# Native iOS Habit Tracking App in Swift

Here's a complete implementation of a native iOS habit tracking app using Swift, SwiftUI, and Core Data for persistence. This includes the main app structure, habit model, views, and data management.

## 1. Project Setup

First, create a new Xcode project:
- Choose "App" template
- Select "SwiftUI" interface
- Name: "HabitTracker"

## 2. Core Data Model Setup

1. Add a new file: `Habit+CoreDataProperties.swift`
2. Configure Core Data entities:
   - `Habit` entity with attributes:
     - `id` (UUID, required)
     - `title` (String, required)
     - `description` (String, optional)
     - `createdAt` (Date, required)
     - `streak` (Int32, required)
     - `lastCompleted` (Date, optional)

## 3. Main App Structure

```swift
// HabitTrackerApp.swift
import SwiftUI

@main
struct HabitTrackerApp: App {
    let persistenceController = PersistenceController.shared

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(\.managedObjectContext, persistenceController.container.viewContext)
        }
    }
}
```

## 4. Persistence Controller

```swift
// Persistence.swift
import CoreData

struct PersistenceController {
    static let shared = PersistenceController()

    let container: NSPersistentContainer

    init(inMemory: Bool = false) {
        container = NSPersistentContainer(name: "HabitTracker")
        if inMemory {
            container.persistentStoreDescriptions.first!.url = URL(fileURLWithPath: "/dev/null")
        }
        container.loadPersistentStores { _, error in
            if let error = error as NSError? {
                fatalError("Unresolved error \(error), \(error.userInfo)")
            }
        }
        container.viewContext.automaticallyMergesChangesFromParent = true
    }
}
```

## 5. Habit Model

```swift
// Habit.swift
import Foundation
import CoreData

@objc(Habit)
public class Habit: NSManagedObject {
    @NSManaged public var id: UUID
    @NSManaged public var title: String
    @NSManaged public var habitDescription: String?
    @NSManaged public var createdAt: Date
    @NSManaged public var streak: Int32
    @NSManaged public var lastCompleted: Date?
}

extension Habit {
    @nonobjc public class func fetchRequest() -> NSFetchRequest<Habit> {
        return NSFetchRequest<Habit>(entityName: "Habit")
    }

    public override func awakeFromInsert() {
        super.awakeFromInsert()
        self.id = UUID()
        self.createdAt = Date()
        self.streak = 0
    }

    func completeToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let lastCompleted = self.lastCompleted {
            let lastCompletedDay = calendar.startOfDay(for: lastCompleted)

            if calendar.isDateInYesterday(lastCompletedDay) {
                // Consecutive day
                self.streak += 1
            } else if !calendar.isDate(lastCompletedDay, inSameDayAs: today) {
                // Not today or yesterday - reset streak
                self.streak = 1
            }
        } else {
            // First completion
            self.streak = 1
        }

        self.lastCompleted = Date()
    }

    func resetStreak() {
        self.streak = 0
        self.lastCompleted = nil
    }
}
```

## 6. View Models

```swift
// HabitViewModel.swift
import Foundation
import CoreData

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    private let context: NSManagedObjectContext

    init(context: NSManagedObjectContext) {
        self.context = context
        fetchHabits()
    }

    func fetchHabits() {
        let request: NSFetchRequest<Habit> = Habit.fetchRequest()
        request.sortDescriptors = [NSSortDescriptor(keyPath: \Habit.createdAt, ascending: false)]

        do {
            habits = try context.fetch(request)
        } catch {
            print("Error fetching habits: \(error)")
        }
    }

    func addHabit(title: String, description: String?) {
        let newHabit = Habit(context: context)
        newHabit.title = title
        newHabit.habitDescription = description

        saveContext()
        fetchHabits()
    }

    func completeHabit(_ habit: Habit) {
        habit.completeToday()
        saveContext()
        fetchHabits()
    }

    func deleteHabit(_ habit: Habit) {
        context.delete(habit)
        saveContext()
        fetchHabits()
    }

    private func saveContext() {
        do {
            try context.save()
        } catch {
            print("Error saving context: \(error)")
        }
    }
}
```

## 7. Main Views

```swift
// ContentView.swift
import SwiftUI

struct ContentView: View {
    @Environment(\.managedObjectContext) private var viewContext
    @StateObject private var habitVM: HabitViewModel
    @State private var showingAddHabit = false

    init() {
        let context = PersistenceController.shared.container.viewContext
        _habitVM = StateObject(wrappedValue: HabitViewModel(context: context))
    }

    var body: some View {
        NavigationStack {
            List {
                ForEach(habitVM.habits, id: \.id) { habit in
                    HabitRow(habit: habit, viewModel: habitVM)
                }
                .onDelete { indices in
                    indices.forEach { index in
                        habitVM.deleteHabit(habitVM.habits[index])
                    }
                }
            }
            .navigationTitle("My Habits")
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button(action: { showingAddHabit = true }) {
                        Image(systemName: "plus")
                    }
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView(viewModel: habitVM)
            }
        }
    }
}

struct HabitRow: View {
    let habit: Habit
    let viewModel: HabitViewModel

    var body: some View {
        HStack {
            VStack(alignment: .leading) {
                Text(habit.title)
                    .font(.headline)
                if let description = habit.habitDescription, !description.isEmpty {
                    Text(description)
                        .font(.subheadline)
                        .foregroundColor(.gray)
                }
            }

            Spacer()

            VStack(alignment: .trailing) {
                Text("Streak: \(habit.streak)")
                    .font(.subheadline)
                    .foregroundColor(.blue)

                if let lastCompleted = habit.lastCompleted {
                    Text("Last: \(lastCompleted, formatter: dateFormatter)")
                        .font(.caption)
                        .foregroundColor(.gray)
                }
            }

            Button(action: {
                viewModel.completeHabit(habit)
            }) {
                Image(systemName: "checkmark.circle.fill")
                    .foregroundColor(.green)
            }
            .buttonStyle(.plain)
        }
    }

    private var dateFormatter: DateFormatter {
        let formatter = DateFormatter()
        formatter.dateStyle = .short
        return formatter
    }
}

struct AddHabitView: View {
    @Environment(\.dismiss) private var dismiss
    @ObservedObject var viewModel: HabitViewModel

    @State private var title = ""
    @State private var description = ""

    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("Habit Details")) {
                    TextField("Title", text: $title)
                    TextField("Description (optional)", text: $description)
                }
            }
            .navigationTitle("Add New Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        if !title.isEmpty {
                            viewModel.addHabit(title: title, description: description.isEmpty ? nil : description)
                            dismiss()
                        }
                    }
                    .disabled(title.isEmpty)
                }
            }
        }
    }
}
```

