### **3. SwiftUI Views**
#### **`ContentView.swift` (Main View)**
```swift
import SwiftUI
import CoreData

struct ContentView: View {
    @Environment(\.managedObjectContext) private var viewContext
    @FetchRequest(
        sortDescriptors: [NSSortDescriptor(keyPath: \Habit.date, ascending: true)],
        animation: .default)
    private var habits: FetchedResults<Habit>

    @State private var newHabitName = ""

    var body: some View {
        NavigationStack {
            VStack {
                // Add new habit
                HStack {
                    TextField("New habit", text: $newHabitName)
                        .textFieldStyle(.roundedBorder)

                    Button(action: addHabit) {
                        Image(systemName: "plus.circle.fill")
                            .font(.title)
                    }
                }
                .padding()

                // List of habits
                List {
                    ForEach(habits) { habit in
                        HStack {
                            Text(habit.name ?? "Unknown")
                            Spacer()
                            Button(action: {
                                toggleHabitCompletion(habit)
                            }) {
                                Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                                    .foregroundColor(habit.isCompleted ? .green : .gray)
                            }
                        }
                    }
                    .onDelete(perform: deleteHabits)
                }
                .listStyle(.plain)
            }
            .navigationTitle("Habit Tracker")
        }
    }

    // MARK: - Functions
    private func addHabit() {
        withAnimation {
            let newHabit = Habit(context: viewContext)
            newHabit.name = newHabitName
            newHabit.isCompleted = false
            newHabit.date = Date()

            do {
                try viewContext.save()
                newHabitName = ""
            } catch {
                let nsError = error as NSError
                fatalError("Unresolved error \(nsError), \(nsError.userInfo)")
            }
        }
    }

    private func toggleHabitCompletion(_ habit: Habit) {
        habit.isCompleted.toggle()
        do {
            try viewContext.save()
        } catch {
            let nsError = error as NSError
            fatalError("Unresolved error \(nsError), \(nsError.userInfo)")
        }
    }

    private func deleteHabits(offsets: IndexSet) {
        withAnimation {
            offsets.map { habits[$0] }.forEach(viewContext.delete)
            do {
                try viewContext.save()
            } catch {
                let nsError = error as NSError
                fatalError("Unresolved error \(nsError), \(nsError.userInfo)")
            }
        }
    }
}

#Preview {
    ContentView().environment(\.managedObjectContext, PersistenceController.preview.container.viewContext)
}
