Here’s a **native iOS habit tracking app** built with **Swift** and **SwiftUI**, featuring:
- A list of habits
- Ability to add, toggle, and delete habits
- Persistence using `UserDefaults` (for simplicity; in production, consider `CoreData` or `SwiftData`)

---

### **1. Define the Habit Model**
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var isCompleted: Bool

    init(id: UUID = UUID(), name: String, isCompleted: Bool = false) {
        self.id = id
        self.name = name
        self.isCompleted = isCompleted
    }
}
```

---

### **2. Create the Habit ViewModel (ObservableObject)**
```swift
import SwiftUI

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    // Load habits from UserDefaults
    init() {
        if let data = UserDefaults.standard.data(forKey: "habits") {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }
        habits = []
    }

    // Save habits to UserDefaults
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    // Add a new habit
    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        saveHabits()
    }

    // Toggle habit completion
    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].isCompleted.toggle()
            saveHabits()
        }
    }

    // Delete a habit
    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }
}
```

