### **3. ViewModel (`HabitViewModel.swift`)**
```swift
import Foundation

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    private let habitsKey = "habits"

    init() {
        loadHabits()
    }

    // Save habits to UserDefaults
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    // Load habits from UserDefaults
    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    // Add a new habit
    func addHabit(name: String, description: String) {
        let newHabit = Habit(name: name, description: description)
        habits.append(newHabit)
        saveHabits()
    }

    // Toggle habit completion
    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].isCompletedToday.toggle()

            // Update streak if completed today
            if habits[index].isCompletedToday {
                let calendar = Calendar.current
                let today = Date()

                if let lastDate = habits[index].lastCompletedDate {
                    let isConsecutiveDay = calendar.isDateInYesterday(lastDate) || calendar.isDateInToday(lastDate)
                    habits[index].streak = isConsecutiveDay ? habits[index].streak + 1 : 1
                } else {
                    habits[index].streak = 1
                }

                habits[index].lastCompletedDate = today
            }

            saveHabits()
        }
    }

    // Delete a habit
    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }
}
```

