import Foundation

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    // Save & Load from UserDefaults
    private let habitsKey = "savedHabits"

    init() {
        loadHabits()
    }

    // MARK: - CRUD Operations
    func addHabit(name: String, description: String) {
        let newHabit = Habit(name: name, description: description)
        habits.append(newHabit)
        saveHabits()
    }

    func deleteHabit(at index: Int) {
        habits.remove(at: index)
        saveHabits()
    }

    func completeHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            // Check if the habit was completed yesterday
            if let lastDate = updatedHabit.lastCompletedDate {
                let calendar = Calendar.current
                if calendar.isDateInYesterday(lastDate) {
                    updatedHabit.streak += 1
                } else if !calendar.isDateInToday(lastDate) {
                    updatedHabit.streak = 1
                }
            } else {
                updatedHabit.streak = 1
            }

            updatedHabit.lastCompletedDate = Date()
            habits[index] = updatedHabit
            saveHabits()
        }
    }

    // MARK: - Persistence
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}
