### **`HabitViewModel.swift` (Handles CRUD Operations)**
```swift
import Foundation
import CoreData

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    private let context = CoreDataManager.shared.context

    init() {
        fetchHabits()
    }

    func fetchHabits() {
        let request: NSFetchRequest<Habit> = Habit.fetchRequest()
        request.sortDescriptors = [NSSortDescriptor(keyPath: \Habit.createdAt, ascending: false)]

        do {
            habits = try context.fetch(request)
        } catch {
            print("Failed to fetch habits: \(error)")
        }
    }

    func addHabit(name: String) {
        let newHabit = Habit(context: context)
        newHabit.name = name
        newHabit.createdAt = Date()

        CoreDataManager.shared.save()
        fetchHabits()
    }

    func deleteHabit(_ habit: Habit) {
        context.delete(habit)
        CoreDataManager.shared.save()
        fetchHabits()
    }

    func toggleHabitCompletion(_ habit: Habit, for date: Date) {
        let calendar = Calendar.current
        let startOfDay = calendar.startOfDay(for: date)

        if let existingLog = habit.logsArray.first(where: {
            calendar.isDate($0.date, inSameDayAs: startOfDay)
        }) {
            existingLog.completed.toggle()
        } else {
            let newLog = HabitLog(context: context)
            newLog.date = startOfDay
            newLog.completed = true
            newLog.habit = habit
        }

        CoreDataManager.shared.save()
        fetchHabits()
    }

    func isHabitCompleted(_ habit: Habit, for date: Date) -> Bool {
        let calendar = Calendar.current
        let startOfDay = calendar.startOfDay(for: date)

        return habit.logsArray.contains { log in
            calendar.isDate(log.date, inSameDayAs: startOfDay) && log.completed
        }
    }
}
```

