            habits[index].isCompletedToday.toggle()

            if habits[index].isCompletedToday {
                habits[index].completionDates.append(Date())
            } else {
                habits[index].completionDates.removeAll { Calendar.current.isDate($0, inSameDayAs: Date()) }
            }

            saveHabits()
        }
    }

    // Delete a habit
    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }
}
