# Minimal Habit Tracker App in Swift + SwiftUI

Here's a complete, minimal working habit tracking app for iOS using SwiftUI. This includes:
- A list of habits
- Ability to add new habits
- Toggle completion for each day
- Persistence using `@AppStorage`

## Complete Code

```swift
import SwiftUI

// MARK: - Data Model
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completionDays: [Date: Bool]

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.completionDays = [:]
    }

    mutating func toggleCompletion(for date: Date) {
        let calendar = Calendar.current
        let components = calendar.dateComponents([.year, .month, .day], from: date)
        if let dateKey = calendar.date(from: components) {
            completionDays[dateKey] = !(completionDays[dateKey] ?? false)
        }
    }

    func isCompleted(on date: Date) -> Bool {
        let calendar = Calendar.current
        let components = calendar.dateComponents([.year, .month, .day], from: date)
        if let dateKey = calendar.date(from: components) {
            return completionDays[dateKey] ?? false
        }
        return false
    }
}

// MARK: - View Models
class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let habitsKey = "habits"

    init() {
        loadHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    func addHabit(name: String) {
        habits.append(Habit(name: name))
    }

    func toggleCompletion(for habit: Habit, on date: Date) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].toggleCompletion(for: date)
        }
    }
}

// MARK: - Views
struct HabitRow: View {
    @ObservedObject var store: HabitStore
    let habit: Habit
    let date: Date

    var body: some View {
        HStack {
            Text(habit.name)
            Spacer()
            Button(action: {
                store.toggleCompletion(for: habit, on: date)
            }) {
                Image(systemName: habit.isCompleted(on: date) ? "checkmark.circle.fill" : "circle")
                    .foregroundColor(habit.isCompleted(on: date) ? .green : .gray)
            }
        }
        .padding(.vertical, 8)
    }
}

struct AddHabitView: View {
    @Environment(\.presentationMode) var presentationMode
    @ObservedObject var store: HabitStore
    @State private var newHabitName = ""

    var body: some View {
        NavigationView {
            Form {
                TextField("Habit name", text: $newHabitName)
                Button("Add Habit") {
                    store.addHabit(name: newHabitName)
                    presentationMode.wrappedValue.dismiss()
                }
                .disabled(newHabitName.isEmpty)
            }
            .navigationTitle("New Habit")
            .navigationBarItems(trailing: Button("Cancel") {
                presentationMode.wrappedValue.dismiss()
            })
        }
    }
}

struct ContentView: View {
    @StateObject private var store = HabitStore()
    @State private var showingAddHabit = false
    private let today = Date()

    var body: some View {
        NavigationView {
            List {
                ForEach(store.habits) { habit in
                    HabitRow(store: store, habit: habit, date: today)
                }
                .onDelete { indices in
                    store.habits.remove(atOffsets: indices)
                }
            }
            .navigationTitle("Habit Tracker")
            .navigationBarItems(trailing: Button(action: {
                showingAddHabit = true
            }) {
                Image(systemName: "plus")
            })
            .sheet(isPresented: $showingAddHabit) {
                AddHabitView(store: store)
            }
        }
    }
}

// MARK: - Preview
struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}
