## **3. ViewModel (`BankViewModel.kt`)**
```kotlin
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class BankViewModel : ViewModel() {
    private val _account = MutableStateFlow<BankAccount?>(null)
    val account: StateFlow<BankAccount?> = _account

    init {
        loadAccountData()
    }

    private fun loadAccountData() {
        viewModelScope.launch {
            // Simulate API call
            _account.value = BankAccount(
                accountNumber = "123456789",
                balance = 5000.0,
                transactions = listOf(
                    Transaction("1", 100.0, "2024-01-15", "Grocery Store"),
                    Transaction("2", 200.0, "2024-01-20", "Electricity Bill")
                )
            )
        }
    }

    fun transferMoney(amount: Double, recipient: String) {
        viewModelScope.launch {
            val currentBalance = _account.value?.balance ?: 0.0
            if (amount <= currentBalance) {
                _account.value = _account.value?.copy(
                    balance = currentBalance - amount,
                    transactions = _account.value?.transactions?.plus(
                        Transaction(
                            id = "3",
                            amount = amount,
                            date = "2024-02-01",
                            description = "Transfer to $recipient"
                        )
                    ) ?: emptyList()
                )
            }
        }
    }
}
```

