### **2. Database Helper (`database_helper.dart`)**
```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._internal();
  factory DatabaseHelper() => _instance;
  DatabaseHelper._internal();

  static Database? _database;

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'surveys.db');

    return await openDatabase(
      path,
      version: 1,
      onCreate: (db, version) async {
        await db.execute('''
          CREATE TABLE surveys (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            answer TEXT NOT NULL,
            isSynced INTEGER DEFAULT 0
          )
        ''');
      },
    );
  }

  // Insert a survey (offline)
  Future<int> insertSurvey(String question, String answer) async {
    final db = await database;
    return await db.insert('surveys', {
      'question': question,
      'answer': answer,
      'isSynced': 0,
    });
  }

  // Get all unsynced surveys
  Future<List<Map<String, dynamic>>> getUnsyncedSurveys() async {
    final db = await database;
    return await db.query('surveys', where: 'isSynced = ?', whereArgs: [0]);
  }

  // Mark surveys as synced
  Future<void> markAsSynced(int id) async {
    final db = await database;
    await db.update('surveys', {'isSynced': 1}, where: 'id = ?', whereArgs: [id]);
  }
}
```

