```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:workmanager/workmanager.dart';
import 'database_helper.dart';

@pragma('vm:entry-point')
void callbackDispatcher() {
  Workmanager().executeTask((task, inputData) async {
    if (task == 'syncSurveys') {
      await _syncSurveys();
    }
    return Future.value(true);
  });
}

Future<void> _syncSurveys() async {
  final dbHelper = DatabaseHelper();
  final unsyncedSurveys = await dbHelper.getUnsyncedSurveys();

  if (unsyncedSurveys.isNotEmpty) {
    // Simulate API call (replace with real HTTP request)
    print('Syncing ${unsyncedSurveys.length} surveys...');

    for (var survey in unsyncedSurveys) {
      // TODO: Replace with actual API call (e.g., using `http` package)
      print('Synced survey: ${survey['question']} -> ${survey['answer']}');
      await dbHelper.markAsSynced(survey['id'] as int);
    }
  }
}

// Initialize background sync
void initBackgroundSync() {
  Workmanager().initialize(callbackDispatcher, isInDebugMode: true);
  Workmanager().registerPeriodicTask(
    'syncSurveys',
    'Sync Surveys',
    frequency: const Duration(minutes: 15),
  );
}

// Check connectivity and trigger sync
Future<void> checkConnectivityAndSync() async {
  final connectivityResult = await Connectivity().checkConnectivity();
  if (connectivityResult != ConnectivityResult.none) {
    await _syncSurveys();
  }
}
