import 'package:http/http.dart' as http;
import 'package:connectivity_plus/connectivity_plus.dart';

class SyncService {
  final DatabaseHelper _dbHelper = DatabaseHelper();

  // Sync unsynced surveys when connected
  Future<void> syncData() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      final unsyncedSurveys = await _dbHelper.getUnsyncedSurveys();
      for (final survey in unsyncedSurveys) {
        try {
          final response = await http.post(
            Uri.parse('https://your-api-endpoint.com/surveys'),
            body: survey,
          );
          if (response.statusCode == 200) {
            await _dbHelper.markAsSynced(survey['id']);
          }
        } catch (e) {
          print('Sync failed: $e');
        }
      }
    }
  }
}
