### **4. Sync Service (`sync_service.dart`)**
```dart
import 'dart:async';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:hive/hive.dart';
import 'package:http/http.dart' as http;
import 'survey_model.dart';

class SyncService {
  final Box<Survey> _surveyBox = Hive.box<Survey>('surveys');
  final String _apiUrl = 'https://your-api-endpoint.com/surveys';

  // Check network and sync unsynced surveys
  Future<void> startSyncListener() async {
    Connectivity().onConnectivityChanged.listen((result) async {
      if (result != ConnectivityResult.none) {
        await _syncUnsyncedSurveys();
      }
    });
  }

  // Sync all unsynced surveys to the server
  Future<void> _syncUnsyncedSurveys() async {
    final unsyncedSurveys = _surveyBox.values.where((s) => !s.isSynced).toList();

    for (final survey in unsyncedSurveys) {
      try {
        final response = await http.post(
          Uri.parse(_apiUrl),
          body: {
            'id': survey.id,
            'title': survey.title,
            'description': survey.description,
            'createdAt': survey.createdAt.toIso8601String(),
          },
        );

        if (response.statusCode == 200) {
          // Mark as synced
          await _surveyBox.put(
            survey.id,
            Survey(
              id: survey.id,
              title: survey.title,
              description: survey.description,
              createdAt: survey.createdAt,
              isSynced: true,
            ),
          );
        }
      } catch (e) {
        print('Sync failed: $e');
      }
    }
  }

  // Fetch surveys from server (optional)
  Future<void> fetchSurveys() async {
    try {
      final response = await http.get(Uri.parse(_apiUrl));
      if (response.statusCode == 200) {
        // Parse and store surveys
      }
    } catch (e) {
      print('Fetch failed: $e');
    }
  }
}
```

