import com.squareup.sqldelight.db.SqlDriver
import com.squareup.sqldelight.runtime.coroutines.asFlow
import com.squareup.sqldelight.runtime.coroutines.mapToList
import kotlinx.coroutines.flow.Flow

interface SurveyDatabase {
    val surveys: Flow<List<Survey>>
    suspend fun insertSurvey(survey: Survey)
    suspend fun updateSurvey(survey: Survey)
    suspend fun deleteSurvey(id: String)
    suspend fun getUnsyncedSurveys(): List<Survey>
}

class SqlDelightSurveyDatabase(driver: SqlDriver) : SurveyDatabase {
    private val database = SurveyDatabase(driver)

    override val surveys: Flow<List<Survey>> = database.surveyQueries
        .selectAll()
        .asFlow()
        .mapToList()

    override suspend fun insertSurvey(survey: Survey) {
        database.surveyQueries.insertSurvey(
            id = survey.id,
            title = survey.title,
            description = survey.description,
            isSynced = survey.isSynced,
            createdAt = survey.createdAt
        )
    }

    override suspend fun updateSurvey(survey: Survey) {
        database.surveyQueries.updateSurvey(
            id = survey.id,
            title = survey.title,
            description = survey.description,
            isSynced = survey.isSynced,
            createdAt = survey.createdAt
        )
    }

    override suspend fun deleteSurvey(id: String) {
        database.surveyQueries.deleteSurvey(id)
    }

    override suspend fun getUnsyncedSurveys(): List<Survey> {
        return database.surveyQueries.selectUnsyncedSurveys().executeAsList()
    }
}
```

#### **`SurveyRepository.kt` (Sync Logic)**
```kotlin
import io.ktor.client.HttpClient
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.http.ContentType
import io.ktor.http.contentType

class SurveyRepository(
    private val database: SurveyDatabase,
    private val httpClient: HttpClient
) {
    // Save survey offline
    suspend fun saveSurvey(survey: Survey) {
        database.insertSurvey(survey)
    }

    // Sync unsynced surveys when reconnected
    suspend fun syncSurveys() {
        val unsyncedSurveys = database.getUnsyncedSurveys()
        unsyncedSurveys.forEach { survey ->
            try {
                httpClient.post("https://api.example.com/surveys") {
                    contentType(ContentType.Application.Json)
                    setBody(survey)
                }
                // Mark as synced
                database.updateSurvey(survey.copy(isSynced = true))
            } catch (e: Exception) {
                // Handle sync failure (retry later)
                println("Sync failed: ${e.message}")
            }
        }
    }
}
```

