class SyncWorker(
    private val context: Context,
    workerParams: WorkerParameters
) : CoroutineWorker(context, workerParams) {

    private val surveyDao = SurveyDatabase.getDatabase(context).surveyDao()
    private val apiService = Retrofit.Builder()
        .baseUrl("https://your-api.com/")
        .build()
        .create(SurveyApiService::class.java)

    override suspend fun doWork(): Result {
        val unsyncedSurveys = surveyDao.getUnsyncedSurveys()
        unsyncedSurveys.forEach { survey ->
            try {
                apiService.syncSurvey(survey)
                surveyDao.markAsSynced(survey.id)
            } catch (e: Exception) {
                Log.e("SyncWorker", "Failed to sync survey", e)
            }
        }
        return Result.success()
    }
}
