### **2.2. Core Data Manager (`CoreDataManager.swift`)**
```swift
import CoreData

class CoreDataManager {
    static let shared = CoreDataManager()

    lazy var persistentContainer: NSPersistentContainer = {
        let container = NSPersistentContainer(name: "SurveyModel")
        container.loadPersistentStores { _, error in
            if let error = error {
                fatalError("Failed to load Core Data: \(error)")
            }
        }
        return container
    }()

    var context: NSManagedObjectContext {
        return persistentContainer.viewContext
    }

    func saveSurvey(question: String, answer: String) {
        let survey = Survey(context: context)
        survey.id = UUID()
        survey.question = question
        survey.answer = answer
        survey.timestamp = Date()
        survey.isSynced = false

        do {
            try context.save()
        } catch {
            print("Failed to save survey: \(error)")
        }
    }

    func fetchUnsyncedSurveys() -> [Survey] {
        let request: NSFetchRequest<Survey> = Survey.fetchRequest()
        request.predicate = NSPredicate(format: "isSynced == %@", NSNumber(value: false))

        do {
            return try context.fetch(request)
        } catch {
            print("Failed to fetch unsynced surveys: \(error)")
            return []
        }
    }

    func markAsSynced(survey: Survey) {
        survey.isSynced = true
        do {
            try context.save()
        } catch {
            print("Failed to mark as synced: \(error)")
        }
    }
}
```

### **2.3. API Service (`SurveyAPI.swift`)**
```swift
import Foundation

struct SurveyAPI {
    static func syncSurvey(survey: Survey, completion: @escaping (Bool) -> Void) {
        guard let url = URL(string: "https://your-api.com/surveys") else { return }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let json: [String: Any] = [
            "id": survey.id.uuidString,
            "question": survey.question,
            "answer": survey.answer,
            "timestamp": survey.timestamp.timeIntervalSince1970
        ]

        request.httpBody = try? JSONSerialization.data(withJSONObject: json)

        URLSession.shared.dataTask(with: request) { _, response, error in
            if let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 {
                completion(true)
            } else {
                completion(false)
            }
        }.resume()
    }
}
```

### **2.4. Background Sync (`BackgroundSync.swift`)**
```swift
import BackgroundTasks

class BackgroundSync {
    static func registerBackgroundSync() {
        BGTaskScheduler.shared.register(forTaskWithIdentifier: "com.your.app.sync", using: nil) { task in
            handleAppRefresh(task: task as! BGAppRefreshTask)
        }
    }

    static func handleAppRefresh(task: BGAppRefreshTask) {
        let queue = OperationQueue()
        queue.maxConcurrentOperationCount = 1

        task.expirationHandler = {
            task.setTaskCompleted(success: false)
        }

        let unsyncedSurveys = CoreDataManager.shared.fetchUnsyncedSurveys()

        for survey in unsyncedSurveys {
            SurveyAPI.syncSurvey(survey: survey) { success in
                if success {
                    CoreDataManager.shared.markAsSynced(survey: survey)
                }
            }
        }

        task.setTaskCompleted(success: true)
    }
}
```

