### **3. Sync Worker (WorkManager for Background Sync)**
#### **SyncWorker.kt (Uploads Pending Surveys)**
```kotlin
class SyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    private val surveyDao = AppDatabase.getDatabase(context).surveyDao()
    private val apiService = RetrofitClient.instance

    override suspend fun doWork(): Result {
        return try {
            val unsyncedSurveys = surveyDao.getUnsyncedSurveys()
            unsyncedSurveys.forEach { survey ->
                val response = apiService.uploadSurvey(survey)
                if (response.isSuccessful) {
                    surveyDao.markAsSynced(survey.id)
                }
            }
            Result.success()
        } catch (e: Exception) {
            Result.retry() // Retry if network fails
        }
    }
}
```

