### **3. Sync Logic (Retrofit + WorkManager)**
#### **API Service (`SurveyApi.kt`)**
```kotlin
interface SurveyApi {
    @POST("surveys")
    suspend fun syncSurveys(@Body surveys: List<Survey>): Response<Unit>
}
```

#### **Sync Worker (`SyncWorker.kt`)**
```kotlin
class SyncWorker(
    private val context: Context,
    workerParams: WorkerParameters
) : CoroutineWorker(context, workerParams) {

    override suspend fun doWork(): Result {
        val dao = AppDatabase.getInstance(context).surveyDao()
        val unsyncedSurveys = dao.getUnsyncedSurveys()

        if (unsyncedSurveys.isEmpty()) return Result.success()

        try {
            val retrofit = Retrofit.Builder()
                .baseUrl("https://your-api.com/")
                .addConverterFactory(GsonConverterFactory.create())
                .build()

            val api = retrofit.create(SurveyApi::class.java)
            api.syncSurveys(unsyncedSurveys)

            // Mark as synced locally
            dao.markAsSynced(unsyncedSurveys.map { it.id })
            return Result.success()
        } catch (e: Exception) {
            return Result.retry() // Retry later
        }
    }
}
```

#### **Trigger Sync on Reconnection (`NetworkMonitor.kt`)**
```kotlin
class NetworkMonitor(private val context: Context) {
    private val connectivityManager = context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager

    fun start() {
        val networkCallback = object : ConnectivityManager.NetworkCallback() {
            override fun onAvailable(network: Network) {
                // Trigger sync when network is available
                val workRequest = OneTimeWorkRequestBuilder<SyncWorker>().build()
                WorkManager.getInstance(context).enqueue(workRequest)
            }
        }

        connectivityManager.registerDefaultNetworkCallback(networkCallback)
    }
}
```

