import 'package:hive/hive.dart';
import 'package:path_provider/path_provider.dart';
import 'package:dio/dio.dart';
import 'package:connectivity_plus/connectivity_plus.dart';

import '../models/survey.dart';

class SurveyService {
  late Box<Survey> _surveyBox;
  final Dio _dio = Dio();

  Future<void> init() async {
    final dir = await getApplicationDocumentsDirectory();
    Hive.init(dir.path);
    Hive.registerAdapter(SurveyAdapter());
    _surveyBox = await Hive.openBox<Survey>('surveys');
  }

  Future<void> addSurvey(Survey survey) async {
    await _surveyBox.put(survey.id, survey);
    _syncIfConnected();
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    return _surveyBox.values.where((s) => !s.isSynced).toList();
  }

  Future<void> _syncIfConnected() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      final unsynced = await getUnsyncedSurveys();
      for (final survey in unsynced) {
        try {
          await _dio.post(
            'https://your-api.com/sync',
            data: {
              'id': survey.id,
              'question': survey.question,
              'answer': survey.answer,
            },
          );
          survey.isSynced = true;
          await survey.save();
        } catch (e) {
          print('Sync failed: $e');
        }
      }
    }
  }
}
```

