class SyncService {
  final DatabaseHelper _dbHelper = DatabaseHelper();

  // Check internet and sync if available
  Future<void> syncIfConnected() async {
    var connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      await _syncSurveys();
    }
  }

  // Sync unsynced surveys to a mock API
  Future<void> _syncSurveys() async {
    final unsyncedSurveys = await _dbHelper.getUnsyncedSurveys();
    for (var survey in unsyncedSurveys) {
      try {
        final response = await http.post(
          Uri.parse('https://example.com/api/surveys'), // Replace with your API
          body: {
            'title': survey['title'],
            'description': survey['description'],
          },
        );
        if (response.statusCode == 200) {
          await _dbHelper.markAsSynced(survey['id']);
        }
      } catch (e) {
        print('Sync failed: $e');
      }
    }
  }
}
