import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase({ name: 'surveys.db', location: 'default' });

export const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        isSynced BOOLEAN DEFAULT 0,
        createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );`
    );
  });
};

export const saveSurvey = (title: string, description: string) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (title, description) VALUES (?, ?)',
        [title, description],
        (_, result) => resolve(result.insertId),
        (_, error) => reject(error)
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE isSynced = 0',
        [],
        (_, result) => resolve(result.rows.raw()),
        (_, error) => reject(error)
      );
    });
  });
};

export const markAsSynced = (id: number) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET isSynced = 1 WHERE id = ?',
        [id],
        () => resolve(true),
        (_, error) => reject(error)
      );
    });
  });
};
```

