import BackgroundFetch from 'react-native-background-fetch';
import { getUnsyncedSurveys, markAsSynced } from './database';

export const setupBackgroundSync = () => {
  BackgroundFetch.configure({
    minimumFetchInterval: 15, // 15 minutes
    stopOnTerminate: false,
    startOnBoot: true,
  }, async (taskId) => {
    try {
      const unsyncedSurveys = await getUnsyncedSurveys();
      if (unsyncedSurveys.length > 0) {
        // Simulate API sync (replace with real API call)
        console.log('Syncing surveys:', unsyncedSurveys);
        await Promise.all(
          unsyncedSurveys.map(async (survey: any) => {
            await markAsSynced(survey.id);
          })
        );
      }
      BackgroundFetch.finish(taskId);
    } catch (error) {
      console.error('Sync failed:', error);
      BackgroundFetch.finish(taskId);
    }
  });
};
