import 'package:hive/hive.dart';
import 'package:http/http.dart' as http;
import '../models/survey.dart';

class SyncService {
  final String _apiUrl = 'https://your-api-endpoint.com/surveys';

  Future<void> syncSurveys() async {
    final box = Hive.box<Survey>('surveys');
    final unsyncedSurveys = box.values.where((s) => !s.isSynced).toList();

    for (final survey in unsyncedSurveys) {
      try {
        final response = await http.post(
          Uri.parse(_apiUrl),
          body: {
            'id': survey.id,
            'question': survey.question,
            'answer': survey.answer,
          },
        );

        if (response.statusCode == 200) {
          survey.isSynced = true;
          await survey.save(); // Update Hive
        }
      } catch (e) {
        print('Sync failed: $e');
      }
    }
  }
}
