      setToken(res.data.token);
      setIsPremium(res.data.premium);
    } catch (err) {
      alert('Registration failed');
    }
  };

  const handleLogin = async () => {
    try {
      const res = await axios.post('http://localhost:5000/login', { username, password });
      setToken(res.data.token);
      setIsPremium(res.data.premium);
    } catch (err) {
      alert('Login failed');
    }
  };

  const handleSendMessage = () => {
    if (socket && newMessage.trim()) {
      socket.emit('sendMessage', { user: username, text: newMessage });
      setNewMessage('');
    }
  };

  const handleUpgradeToPremium = async () => {
    const stripe = await stripePromise;
    const res = await axios.post('http://localhost:5000/create-payment-intent', { amount: 9.99 }, {
      headers: { Authorization: `Bearer ${token}` },
    });

    const { error } = await stripe!.confirmPayment({
      clientSecret: res.data.clientSecret,
      elements: {
        paymentMethod: {
          card: {
            tokenize: 'always',
          },
        },
      },
      confirmParams: {
        return_url: 'http://localhost:3000/success',
      },
    });

    if (error) {
      alert('Payment failed');
    } else {
      setIsPremium(true);
      alert('Upgraded to Premium!');
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      {!token ? (
        <div>
          <h2>Login/Register</h2>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button onClick={handleLogin}>Login</button>
          <button onClick={handleRegister}>Register</button>
        </div>
      ) : (
        <div>
          <h2>Welcome, {username} {isPremium && '💎'}</h2>
          {!isPremium && (
            <button onClick={handleUpgradeToPremium}>Upgrade to Premium ($9.99)</button>
          )}

          <div style={{ marginTop: '20px' }}>
            <h3>Messages</h3>
            <div style={{ height: '300px', overflowY: 'scroll', border: '1px solid #ccc', padding: '10px' }}>
              {messages.map((msg, index) => (
                <div key={index}>
                  <strong>{msg.user}:</strong> {msg.text} <small>({new Date(msg.timestamp).toLocaleTimeString()})</small>
                </div>
              ))}
            </div>
            <input
              type="text"
              placeholder="Type a message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
            />
            <button onClick={handleSendMessage}>Send</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
