      body: JSON.stringify({ id: Date.now().toString(), name }),
    });
    const data = await response.json();
    setUser(data.user);
  };

  const handleSendMessage = async () => {
    if (!user || !input.trim()) return;

    await fetch('http://localhost:5000/api/send-message', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sender: user.name, text: input }),
    });

    // Emit a notification
    socket?.emit('send-notification', { sender: user.name });
    setInput('');
  };

  const handlePurchase = async () => {
    const stripe = await stripePromise;
    if (!stripe) return;

    const response = await fetch('http://localhost:5000/api/create-payment', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: user?.id, amount: 50 }),
    });
    const session = await response.json();

    const result = await stripe.redirectToCheckout({ sessionId: session.id });
    if (result.error) {
      alert(result.error.message);
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      {!user ? (
