  const [username, setUsername] = useState('');
  const [isPremium, setIsPremium] = useState(false);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    newSocket.on('newMessage', (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const sendMessage = () => {
    if (!socket || !newMessage.trim()) return;

    socket.emit('sendMessage', {
      sender: username,
      receiver: 'global', // Simplified for demo
      content: newMessage,
    });
    setNewMessage('');
  };

  const handlePremiumUpgrade = async () => {
    const stripe = await stripePromise;
    const response = await axios.post('http://localhost:5000/api/create-payment-intent', {
      userId: 'user123', // Replace with actual user ID
    });

    const { clientSecret } = response.data;

    if (stripe) {
      const { error } = await stripe.confirmPayment({
        elements: stripe.elements(),
        clientSecret,
        confirmParams: {
          return_url: 'http://localhost:3000/success',
        },
      });

      if (error) {
        console.error('Payment failed:', error);
      } else {
        setIsPremium(true);
        alert('Premium features unlocked!');
      }
    }
  };

  return (
    <div>
      <h1>Social Messaging App</h1>
      <input
        type="text"
        placeholder="Your username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
      />
      <div>
        <input
          type="text"
          placeholder="Type a message..."
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>
      <div>
        <h3>Messages</h3>
        <ul>
          {messages.map((msg, index) => (
            <li key={index}>
              <strong>{msg.sender}:</strong> {msg.content}
            </li>
          ))}
        </ul>
      </div>
      {!isPremium && (
        <button onClick={handlePremiumUpgrade}>Upgrade to Premium ($9.99)</button>
      )}
