```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const admin = require('firebase-admin');
const stripe = require('stripe')('STRIPE_SECRET_KEY');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, { cors: { origin: "*" } });

// Firebase Admin Setup (for FCM)
admin.initializeApp({
  credential: admin.credential.cert(require('./serviceAccountKey.json')),
});

// Store connected users
const users = {};

// Socket.io for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected:', socket.id);

  // User joins with their ID
  socket.on('join', (userId) => {
    users[userId] = socket.id;
    console.log(`User ${userId} joined`);
  });

  // Send a private message
  socket.on('privateMessage', ({ senderId, receiverId, message }) => {
    const receiverSocketId = users[receiverId];
    if (receiverSocketId) {
      io.to(receiverSocketId).emit('newMessage', { senderId, message });
      sendPushNotification(receiverId, `New message from ${senderId}`);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
    // Remove user from active list
    Object.keys(users).forEach((userId) => {
      if (users[userId] === socket.id) delete users[userId];
    });
  });
});

// Send FCM Push Notification
async function sendPushNotification(userId, message) {
  const userDoc = await admin.firestore().collection('users').doc(userId).get();
  const fcmToken = userDoc.data()?.fcmToken;

  if (fcmToken) {
    await admin.messaging().send({
      token: fcmToken,
      notification: { title: 'New Message', body: message },
    });
  }
}

// Stripe Subscription Endpoint
app.post('/create-subscription', async (req, res) => {
  const { userId, paymentMethodId } = req.body;

  const customer = await stripe.customers.create({
    payment_method: paymentMethodId,
    email: 'user@example.com',
  });

  const subscription = await stripe.subscriptions.create({
    customer: customer.id,
    items: [{ price: 'price_123' }], // Replace with your Stripe price ID
    expand: ['latest_invoice.payment_intent'],
  });

  await admin.firestore().collection('subscriptions').doc(userId).set({
    stripeCustomerId: customer.id,
    active: true,
  });

  res.json({ subscriptionId: subscription.id });
});

const PORT = 3000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

