require('dotenv').config();
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const bodyParser = require('body-parser');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Middleware
app.use(express.static(path.join(__dirname, 'public')));
app.use(bodyParser.json());

// Mock database
const users = {
  'user1': { id: 'user1', name: 'Alice', isPremium: false },
  'user2': { id: 'user2', name: 'Bob', isPremium: true }
};

const messages = [];

// Socket.io for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('sendMessage', (data) => {
    const message = {
      id: Date.now(),
      text: data.text,
      sender: users[data.senderId],
      timestamp: new Date()
    };
    messages.push(message);
    io.emit('newMessage', message);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

// API Routes
app.post('/api/login', (req, res) => {
  const { userId } = req.body;
  if (users[userId]) {
    res.json({ success: true, user: users[userId] });
  } else {
    res.status(401).json({ success: false, message: 'Invalid user' });
  }
});

// Stripe Payment Endpoint
app.post('/api/create-payment-intent', async (req, res) => {
  try {
    const paymentIntent = await stripe.paymentIntents.create({
      amount: 999, // $9.99
      currency: 'usd',
      metadata: { userId: req.body.userId }
    });

    res.json({ clientSecret: paymentIntent.client_secret });
  } catch (err) {
    res.status(500).json({ error: err.message });
  });
});

// Webhook for successful payments
app.post('/api/webhook', bodyParser.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'payment_intent.succeeded') {
    const paymentIntent = event.data.object;
    const userId = paymentIntent.metadata.userId;

    if (users[userId]) {
      users[userId].isPremium = true;
      console.log(`User ${userId} upgraded to premium`);
    }
  }

  res.json({ received: true });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

