### **`server.js` (Backend Setup)**
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');
const admin = require('firebase-admin');
const stripe = require('stripe')('YOUR_STRIPE_SECRET_KEY');

const app = express();
app.use(cors());
app.use(express.json());

// Initialize Firebase Admin SDK
admin.initializeApp({
  credential: admin.credential.cert(require('./serviceAccountKey.json')),
});

// Initialize Stripe for in-app purchases
app.post('/create-payment-intent', async (req, res) => {
  const { amount } = req.body;
  try {
    const paymentIntent = await stripe.paymentIntents.create({
      amount,
      currency: 'usd',
    });
    res.json({ clientSecret: paymentIntent.client_secret });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Socket.io for real-time messaging
const server = http.createServer(app);
const io = socketIo(server, {
  cors: { origin: 'http://localhost:5173' },
});

io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  socket.on('sendMessage', async (data) => {
    const { sender, receiver, message } = data;

    // Save message to Firestore
    await admin.firestore().collection('messages').add({
      sender,
      receiver,
      message,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
    });

    // Send real-time notification via FCM
    const receiverToken = await admin.firestore().collection('users').doc(receiver).get();
    if (receiverToken.exists) {
      await admin.messaging().send({
        token: receiverToken.data().fcmToken,
        notification: {
          title: `New message from ${sender}`,
          body: message,
        },
      });
    }

    // Broadcast message to receiver
    io.to(receiver).emit('receiveMessage', { sender, message });
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

