```jsx
import { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import { initializeApp } from 'firebase/app';
import { getAuth, signInWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, collection, addDoc, onSnapshot } from 'firebase/firestore';
import { loadStripe } from '@stripe/stripe-js';

// Firebase Config
const firebaseConfig = {
  apiKey: "YOUR_FIREBASE_API_KEY",
  authDomain: "YOUR_FIREBASE_AUTH_DOMAIN",
  projectId: "YOUR_FIREBASE_PROJECT_ID",
  storageBucket: "YOUR_FIREBASE_STORAGE_BUCKET",
  messagingSenderId: "YOUR_FIREBASE_MESSAGING_SENDER_ID",
  appId: "YOUR_FIREBASE_APP_ID",
};

const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

// Stripe Setup
const stripePromise = loadStripe('YOUR_STRIPE_PUBLISHABLE_KEY');

function App() {
  const [messages, setMessages] = useState([]);
  const [messageInput, setMessageInput] = useState('');
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);

  // Connect to Socket.io
  useEffect(() => {
    const newSocket = io('http://localhost:3000');
    setSocket(newSocket);

    newSocket.on('receiveMessage', (data) => {
      setMessages((prev) => [...prev, data]);
    });

    return () => newSocket.disconnect();
  }, []);

  // Fetch messages from Firestore
  useEffect(() => {
    if (!user) return;

    const unsubscribe = onSnapshot(
      collection(db, 'messages'),
      (snapshot) => {
        const fetchedMessages = snapshot.docs.map((doc) => doc.data());
        setMessages(fetchedMessages);
      }
    );

    return () => unsubscribe();
  }, [user]);

  // Handle login
  const handleLogin = async (email, password) => {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      setUser(userCredential.user);
    } catch (error) {
      console.error('Login failed:', error);
    }
  };

  // Send message
  const sendMessage = () => {
    if (!messageInput.trim() || !user) return;

    socket.emit('sendMessage', {
      sender: user.email,
      receiver: 'receiver@example.com', // Replace with actual receiver
      message: messageInput,
    });

    setMessageInput('');
  };

  // Handle in-app purchase
  const handlePurchase = async (amount) => {
    const stripe = await stripePromise;
    const response = await fetch('http://localhost:3000/create-payment-intent', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount }),
    });
    const { clientSecret } = await response.json();

    const { error } = await stripe.confirmPayment({
      elements: stripe.elements(),
      clientSecret,
    });

    if (error) console.error('Payment failed:', error);
    else alert('Payment successful!');
  };

  return (
    <div>
      {!user ? (
        <div>
          <h1>Login</h1>
          <button onClick={() => handleLogin('user@example.com', 'password123')}>
            Login
          </button>
        </div>
      ) : (
        <div>
          <h1>Messaging App</h1>
          <div>
            {messages.map((msg, index) => (
              <div key={index}>
                <strong>{msg.sender}:</strong> {msg.message}
              </div>
            ))}
          </div>
          <input
            type="text"
            value={messageInput}
            onChange={(e) => setMessageInput(e.target.value)}
            placeholder="Type a message..."
          />
          <button onClick={sendMessage}>Send</button>

          <div>
            <h2>Monetization</h2>
            <button onClick={() => handlePurchase(1000)}>Buy Premium ($10)</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
```

