import React, { useEffect, useState } from 'react';
import { io } from 'socket.io-client';

interface RealTimeDataPoint {
  timestamp: string;
  value: number;
  category: string;
}

const RealTimeData: React.FC = () => {
  const [data, setData] = useState<RealTimeDataPoint[]>([]);

  useEffect(() => {
    const socket = io('http://localhost:5000');

    socket.on('realTimeData', (newData: RealTimeDataPoint) => {
      setData(prev => [...prev, newData].slice(-10)); // Keep last 10 items
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  return (
    <div className="real-time-data">
      <h3>Live Data Stream</h3>
      <ul>
        {data.map((item, index) => (
          <li key={index}>
            {item.timestamp} - {item.category}: {item.value}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default RealTimeData;
```

