import React, { useEffect, useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import { io } from 'socket.io-client';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

interface ChartDataPoint {
  timestamp: string;
  value: number;
}

const DataChart: React.FC = () => {
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);

  useEffect(() => {
    const socket = io('http://localhost:5000');

    socket.on('realTimeData', (newData: ChartDataPoint) => {
      setChartData(prev => [...prev, newData].slice(-20)); // Keep last 20 points
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const data = {
    labels: chartData.map(item => new Date(item.timestamp).toLocaleTimeString()),
    datasets: [
      {
        label: 'Real-Time Values',
        data: chartData.map(item => item.value),
        borderColor: 'rgb(75, 192, 192)',
        tension: 0.1
      }
    ]
  };

  const options = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top' as const,
      },
      title: {
        display: true,
        text: 'Real-Time Data Visualization',
      },
    },
  };

  return (
    <div className="data-chart">
      <Line data={data} options={options} />
    </div>
  );
};

export default DataChart;
```

### `client/src/components/DataForm.tsx`
```tsx
import React from 'react';
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import { io } from 'socket.io-client';

const DataForm: React.FC = () => {
  const socket = io('http://localhost:5000');

  const validationSchema = Yup.object().shape({
    name: Yup.string().required('Name is required'),
    value: Yup.number().required('Value is required').min(0, 'Value must be positive'),
    category: Yup.string().required('Category is required')
  });

  const handleSubmit = (values: any, { resetForm }: any) => {
    const formData = {
      ...values,
      timestamp: new Date().toISOString()
    };
    socket.emit('submitForm', formData);
    resetForm();
  };

  return (
    <div className="data-form">
      <Formik
        initialValues={{ name: '', value: '', category: '' }}
        validationSchema={validationSchema}
        onSubmit={handleSubmit}
      >
        {({ isSubmitting }) => (
          <Form>
            <div className="form-group">
              <label htmlFor="name">Name</label>
              <Field type="text" name="name" />
              <ErrorMessage name="name" component="div" className="error" />
            </div>

            <div className="form-group">
              <label htmlFor="value">Value</label>
              <Field type="number" name="value" />
              <ErrorMessage name="value" component="div" className="error" />
            </div>

            <div className="form-group">
              <label htmlFor="category">Category</label>
              <Field as="select" name="category">
                <option value="">Select a category</option>
                <option value="A">Category A</option>
                <option value="B">Category B</option>
                <option value="C">Category C</option>
              </Field>
              <ErrorMessage name="category" component="div" className="error" />
            </div>

            <button type="submit" disabled={isSubmitting}>
              Submit
            </button>
          </Form>
        )}
      </Formik>
    </div>
  );
};

export default DataForm;
```

