import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import cors from 'cors';

const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Sample data store
let dataPoints: { x: number; y: number }[] = [
  { x: 1, y: 10 },
  { x: 2, y: 20 },
  { x: 3, y: 15 },
  { x: 4, y: 25 },
  { x: 5, y: 30 }
];

// Middleware
app.use(cors());
app.use(express.json());

// API endpoint to get initial data
app.get('/api/data', (req, res) => {
  res.json(dataPoints);
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('Client connected');

  // Send initial data to new client
  socket.emit('initial-data', dataPoints);

  // Handle new data submissions
  socket.on('new-data', (newPoint: { x: number; y: number }) => {
    dataPoints.push(newPoint);

    // Broadcast to all connected clients
    io.emit('update-data', dataPoints);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = 5000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

