  const chartData = {
    labels: dataPoints.map(point => point.x),
    datasets: [
      {
        label: 'Real-Time Data',
        data: dataPoints.map(point => point.y),
        borderColor: 'rgb(75, 192, 192)',
        tension: 0.1,
        fill: false
      }
