  const options = {
    responsive: true,
    scales: {
      x: {
        title: {
          display: true,
          text: 'X Values'
        }
      },
      y: {
        title: {
          display: true,
          text: 'Y Values'
        }
      }
    }
  };

  useEffect(() => {
    if (chartRef.current) {
      chartRef.current.update();
    }
  }, [dataPoints]);

  return (
    <div style={{ width: '80%', margin: '0 auto' }}>
      <Line ref={chartRef} data={chartData} options={options} />
    </div>
  );
};

