### 2. Create `Dashboard.tsx`
```tsx
import React, { useState, useEffect, useRef } from 'react';
import { io, Socket } from 'socket.io-client';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

interface DataPoint {
  timestamp: string;
  value: number;
}

interface FormData {
  name: string;
  email: string;
  message: string;
}

interface FormResponse {
  message: string;
  timestamp: string;
}

const Dashboard: React.FC = () => {
  const [data, setData] = useState<DataPoint[]>([]);
  const [formData, setFormData] = useState<FormData>({
    name: '',
    email: '',
    message: ''
  });
  const [formResponse, setFormResponse] = useState<FormResponse | null>(null);
  const socketRef = useRef<Socket | null>(null);

  // Initialize WebSocket connection
  useEffect(() => {
    socketRef.current = io('http://localhost:4000');

    socketRef.current.on('initial-data', (initialData: DataPoint[]) => {
      setData(initialData);
    });

    socketRef.current.on('data-update', (updatedData: DataPoint[]) => {
      setData(updatedData);
    });

    socketRef.current.on('form-response', (response: FormResponse) => {
      setFormResponse(response);
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
      }
    };
  }, []);

  // Handle form submission
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (socketRef.current) {
      socketRef.current.emit('form-submit', formData);
      setFormData({ name: '', email: '', message: '' });
    }
  };

  // Prepare chart data
  const chartData = {
    labels: data.map(point => new Date(point.timestamp).toLocaleTimeString()),
    datasets: [
      {
        label: 'Real-time Data',
        data: data.map(point => point.value),
        borderColor: 'rgb(75, 192, 192)',
        tension: 0.1,
        fill: false,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top' as const,
      },
      title: {
        display: true,
        text: 'Real-time Data Visualization',
      },
    },
  };

  return (
    <div className="dashboard-container">
      <h1>Interactive Dashboard</h1>

      <div className="chart-container">
        <Line data={chartData} options={chartOptions} />
      </div>

      <div className="form-container">
        <h2>Submit Data</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="name">Name:</label>
            <input
              type="text"
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({...formData, name: e.target.value})}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="email">Email:</label>
            <input
              type="email"
              id="email"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="message">Message:</label>
            <textarea
              id="message"
              value={formData.message}
              onChange={(e) => setFormData({...formData, message: e.target.value})}
              required
            />
          </div>

          <button type="submit">Submit</button>
        </form>

        {formResponse && (
          <div className="form-response">
            <h3>Response:</h3>
            <p>{formResponse.message}</p>
            <p><small>Received at: {new Date(formResponse.timestamp).toLocaleString()}</small></p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
```

