// Initialize Chart.js
const ctx = document.getElementById('realTimeChart').getContext('2d');
const realTimeChart = new Chart(ctx, {
  type: 'line',
  data: {
    labels: [],
    datasets: [{
      label: 'Real-Time Data',
      data: [],
      borderColor: 'rgba(75, 192, 192, 1)',
      tension: 0.1
    }]
  },
  options: {
    responsive: true,
    scales: {
      y: { beginAtZero: true }
    }
  }
});

// Connect to WebSocket
const socket = io('http://localhost:3001');

// Handle real-time updates
socket.on('update', (data) => {
  const { value, timestamp } = data;
  realTimeChart.data.labels.push(timestamp);
  realTimeChart.data.datasets[0].data.push(value);
  realTimeChart.update();
});

// Handle form submissions
document.getElementById('dataForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const name = document.getElementById('nameInput').value;
  const value = document.getElementById('valueInput').value;

  const response = await fetch('http://localhost:3001/submit', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name, value })
  });

  if (response.ok) {
    document.getElementById('nameInput').value = '';
    document.getElementById('valueInput').value = '';
  }
});

// Display form submissions in real-time
socket.on('form-submission', (data) => {
  const submissionsDiv = document.getElementById('submissions');
  const submissionElement = document.createElement('div');
  submissionElement.textContent = `${data.name}: ${data.value}`;
  submissionsDiv.appendChild(submissionElement);
});
