  const [submissions, setSubmissions] = useState([]);
  const socket = io('http://localhost:5000');

  useEffect(() => {
    // Listen for real-time stock updates
    socket.on('stockUpdate', (data) => {
      setStockData(prev => [...prev, data.price]);
    });

    // Listen for new form submissions
    socket.on('newSubmission', (data) => {
      setSubmissions(data);
    });

    return () => socket.disconnect();
  }, []);

  // Chart configuration
  const chartData = {
    labels: stockData.map((_, i) => i),
    datasets: [{
      label: 'Stock Price',
      data: stockData,
      borderColor: 'rgba(75, 192, 192, 1)',
      tension: 0.1,
    }],
  };

  return (
    <div>
      <h2>Real-Time Stock Price</h2>
      <Line data={chartData} />

      <h2>Submissions</h2>
      <ul>
        {submissions.map((sub, i) => (
          <li key={i}>{sub.name} ({sub.email})</li>
        ))}
      </ul>
    </div>
  );
}

export default Dashboard;
