            border: 1px solid #ddd;
            padding: 10px;
            border-radius: 5px;
        }
        .controls {
            display: flex;
            flex-direction: column;
            gap: 10px;
            margin-bottom: 20px;
        }
        button, input, select {
            padding: 8px;
            margin: 5px 0;
        }
    </style>
</head>
<body>
    <h1>Interactive Dashboard</h1>

    <!-- Controls -->
    <div class="controls">
        <label for="dataType">Data Type:</label>
        <select id="dataType">
            <option value="line">Line Chart</option>
            <option value="bar">Bar Chart</option>
            <option value="pie">Pie Chart</option>
        </select>

        <label for="updateInterval">Update Interval (ms):</label>
        <input type="range" id="updateInterval" min="500" max="5000" value="1000">

        <button id="resetBtn">Reset Data</button>
    </div>

    <!-- Dashboard -->
    <div class="dashboard">
        <div class="chart-container">
            <canvas id="dataChart"></canvas>
        </div>
        <div class="chart-container">
            <canvas id="secondaryChart"></canvas>
        </div>
    </div>

    <script>
        // Initialize charts
        const ctx1 = document.getElementById('dataChart').getContext('2d');
        const ctx2 = document.getElementById('secondaryChart').getContext('2d');

        let dataChart, secondaryChart;
        let data = [10, 20, 30, 40, 50];
        let labels = ['Jan', 'Feb', 'Mar', 'Apr', 'May'];

        // Create initial charts
        function initCharts() {
            dataChart = new Chart(ctx1, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Primary Data',
                        data: data,
                        borderColor: 'rgba(75, 192, 192, 1)',
                        backgroundColor: 'rgba(75, 192, 192, 0.2)',
                        tension: 0.1
                    }]
                },
                options: {
                    responsive: true,
                    scales: {
                        y: { beginAtZero: true }
                    }
                }
            });

            secondaryChart = new Chart(ctx2, {
                type: 'bar',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Secondary Data',
                        data: data.map(x => x * 0.8),
                        backgroundColor: 'rgba(153, 102, 255, 0.5)'
                    }]
                },
                options: { responsive: true }
            });
        }

        // Update charts with new data
        function updateCharts() {
            const newData = data.map(x => x + Math.floor(Math.random() * 10) - 5);
            dataChart.data.datasets[0].data = newData;
            secondaryChart.data.datasets[0].data = newData.map(x => x * 0.8);
            dataChart.update();
            secondaryChart.update();
        }

        // Change chart type
        document.getElementById('dataType').addEventListener('change', (e) => {
            dataChart.config.type = e.target.value;
            dataChart.update();
        });

        // Reset data
        document.getElementById('resetBtn').addEventListener('click', () => {
            data = [10, 20, 30, 40, 50];
            updateCharts();
        });

        // Set update interval
        let updateInterval = 1000;
        let intervalId = setInterval(updateCharts, updateInterval);

        document.getElementById('updateInterval').addEventListener('input', (e) => {
            updateInterval = e.target.value;
            clearInterval(intervalId);
            intervalId = setInterval(updateCharts, updateInterval);
        });

        // Initialize
        initCharts();
    </script>
</body>
</html>
```

