  const scripts = document.querySelectorAll("script");
  scripts.forEach((script) => {
    if (script.src && script.src.includes("google-analytics") || script.src.includes("facebook.com/tr")) {
      script.remove();
      console.log(`Removed tracking script: ${script.src}`);
    }
  });
};

// Run on page load
window.addEventListener("load", removeTrackingScripts);
```
