### **4. `content-script.js`**
This script injects into every page and blocks tracking scripts based on the list.

```javascript
// Load tracking domains from a file (or hardcode them)
const trackingDomains = [
  "google-analytics.com",
  "facebook.com",
  "doubleclick.net",
  // Add more domains as needed
];

// Function to check if a URL contains a tracking domain
function isTrackingScript(url) {
  return trackingDomains.some(domain => url.includes(domain));
}

// Block tracking scripts
document.addEventListener("beforescriptexecute", (e) => {
  const scriptSrc = e.target.src || e.target.getAttribute("src");
  if (scriptSrc && isTrackingScript(scriptSrc)) {
    e.preventDefault();
    e.stopPropagation();
    console.log(`Blocked tracking script: ${scriptSrc}`);
  }
});

// Block tracking iframes (optional)
document.addEventListener("beforeload", (e) => {
  if (e.target.tagName === "IFRAME") {
    const iframeSrc = e.target.src || e.target.getAttribute("src");
    if (iframeSrc && isTrackingScript(iframeSrc)) {
      e.preventDefault();
      console.log(`Blocked tracking iframe: ${iframeSrc}`);
    }
  }
});
```

