## 2. `background.js` (Service Worker)
Handles blocking rules and updates the blocklist.

```javascript
// Load the blocklist from assets/blocklist.json
let blocklist = [];

// Fetch the blocklist (simplified example)
fetch(chrome.runtime.getURL('assets/blocklist.json'))
  .then(response => response.json())
  .then(data => {
    blocklist = data;
    updateBlockingRules();
  });

// Update blocking rules using declarativeNetRequest
function updateBlockingRules() {
  const rules = blocklist.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: `*://*.${domain}/*`,
      resourceTypes: ["script", "image", "stylesheet", "xmlhttprequest"]
    }
  }));

  chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: blocklist.map((_, index) => index + 1),
    addRules: rules
  });
}

// Listen for messages from the popup
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === "getBlocklist") {
    sendResponse({ blocklist });
  }
});
```

