```javascript
// Define blocking rules (example: block common trackers)
const blockingRules = [
  {
    "id": 1,
    "priority": 1,
    "action": { "type": "block" },
    "condition": {
      "urlFilter": "*://*.google-analytics.com/*",
      "resourceTypes": ["script", "image", "xmlhttprequest"]
