    }
  }
];

// Register rules when the extension starts
chrome.runtime.onInstalled.addListener(() => {
  chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: blockingRules.map(rule => rule.id),
    addRules: blockingRules
  });
});
```

