### **JavaScript (`heatmap.js`)**
```javascript
// Simulate real-time stock price data (replace with WebSocket in production)
function generateRandomStockData() {
    const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "META", "NVDA", "JPM", "V", "WMT"];
    const data = [];
    const now = new Date();

    for (let i = 0; i < 10; i++) { // 10 time steps
        const time = new Date(now.getTime() - (10 - i) * 60 * 60 * 1000); // Past 10 hours
        for (let j = 0; j < stocks.length; j++) {
            data.push({
                stock: stocks[j],
                time: time,
                price: 100 + Math.random() * 100 // Random price between $100-$200
            });
        }
    }
    return data;
}

// Initialize heatmap
function initHeatmap() {
    const width = 800;
    const height = 500;
    const margin = { top: 50, right: 30, bottom: 50, left: 80 };

    // Create SVG container
    const svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", width + margin.left + margin.right)
        .attr("height", height + margin.top + margin.bottom)
        .append("g")
        .attr("transform", `translate(${margin.left},${margin.top})`);

    // Tooltip
    const tooltip = d3.select("#tooltip");

    // Zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on("zoom", (event) => {
            svg.attr("transform", event.transform);
        });

    svg.call(zoom);

    // Update heatmap with new data
    function updateHeatmap(data) {
        const stocks = [...new Set(data.map(d => d.stock))];
        const times = [...new Set(data.map(d => d.time))].sort((a, b) => a - b);

        // Scales
        const xScale = d3.scaleBand()
            .domain(times.map(t => t.toISOString()))
            .range([0, width])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, height])
            .padding(0.05);

        const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([d3.min(data, d => d.price), d3.max(data, d => d.price)]);

        // Remove old elements
        svg.selectAll("*").remove();

        // Add heatmap cells
        svg.selectAll(".cell")
            .data(data)
            .enter()
            .append("rect")
            .attr("class", "cell")
            .attr("x", d => xScale(d.time.toISOString()))
            .attr("y", d => yScale(d.stock))
            .attr("width", xScale.bandwidth())
            .attr("height", yScale.bandwidth())
            .attr("fill", d => colorScale(d.price))
            .on("mouseover", (event, d) => {
                tooltip.style("visibility", "visible")
                    .html(`Stock: ${d.stock}<br>Time: ${d.time.toLocaleTimeString()}<br>Price: $${d.price.toFixed(2)}`);
