// src/utils/mockData.ts
export interface StockData {
  symbol: string;
  date: string;
  price: number;
}

export const generateMockStockData = (symbols: string[], days: number): StockData[] => {
  const data: StockData[] = [];
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  symbols.forEach((symbol) => {
    for (let i = 0; i < days; i++) {
      const date = new Date(startDate);
      date.setDate(date.getDate() + i);
      const price = 100 + Math.random() * 100; // Random price between $100-$200
      data.push({ symbol, date: date.toISOString().split('T')[0], price });
    }
  });

  return data;
};
