    // Extract unique symbols and dates
    const symbols = Array.from(new Set(data.map(d => d.symbol)));
    const dates = Array.from(new Set(data.map(d => d.date)));

    // Define scales
    const xScale = d3.scaleBand()
      .domain(dates)
      .range([0, width])
      .padding(0.05);

    const yScale = d3.scaleBand()
      .domain(symbols)
      .range([0, height])
      .padding(0.05);

    const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
      .domain([d3.min(data, d => d.price) || 0, d3.max(data, d => d.price) || 100]);

    // Add zoom behavior
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 10])
      .on('zoom', (event) => {
        svg.select('g').attr('transform', event.transform);
      });

    svg.call(zoom);

    // Create heatmap cells
    const cells = svg.append('g')
      .selectAll('rect')
      .data(data)
      .enter()
      .append('rect')
      .attr('x', d => xScale(d.date) || 0)
      .attr('y', d => yScale(d.symbol) || 0)
      .attr('width', xScale.bandwidth())
      .attr('height', yScale.bandwidth())
      .attr('fill', d => colorScale(d.price))
      .on('mouseover', (event, d) => {
        d3.select(event.currentTarget)
          .attr('stroke', 'black')
          .attr('stroke-width', 2);
      })
      .on('mouseout', (event) => {
        d3.select(event.currentTarget)
          .attr('stroke', 'none');
      });

    // Add axes
    svg.append('g')
      .attr('transform', `translate(0, ${height})`)
      .call(d3.axisBottom(xScale).tickFormat(d => new Date(d).toLocaleDateString()));

    svg.append('g')
      .call(d3.axisLeft(yScale));

  }, [data, width, height]);

  return <svg ref={svgRef} />;
};

export default StockHeatmap;
```

