## JavaScript Implementation (`heatmap.js`)

```javascript
// Configuration
const config = {
    container: '#heatmap-container',
    width: 1200,
    height: 600,
    margin: { top: 20, right: 20, bottom: 60, left: 80 },
    timeRange: '1d',
    updateInterval: 5000, // 5 seconds
    maxDataPoints: 1000
};

// Mock data generator
function generateMockData() {
    const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
    const now = new Date();
    const data = [];

    // Generate data for the last 24 hours (for 1d view)
    for (let i = 0; i < config.maxDataPoints; i++) {
        const time = new Date(now - (i * 15 * 60 * 1000)); // 15-minute intervals
        stocks.forEach(stock => {
            // Generate random price change between -5% and +5%
            const change = (Math.random() * 10 - 5) / 100;
            data.push({
                stock,
                time: time.getTime(),
                change: change
            });
        });
    }

    return data;
}

// Main heatmap class
class StockHeatmap {
    constructor() {
        this.data = generateMockData();
        this.svg = null;
        this.xScale = null;
        this.yScale = null;
        this.colorScale = null;
        this.tooltip = null;
        this.zoom = null;
        this.init();
    }

    init() {
        // Set up SVG container
        this.svg = d3.select(config.container)
            .append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Create tooltip
        this.tooltip = d3.select('body')
            .append('div')
            .attr('class', 'tooltip');

        // Set up scales
        this.setupScales();

        // Create axes
        this.createAxes();

        // Create heatmap
        this.createHeatmap();

        // Set up zoom
        this.setupZoom();

        // Set up time range selector
        this.setupTimeRangeSelector();

        // Start real-time updates
        this.startRealTimeUpdates();
    }

    setupScales() {
        // X scale (time)
        const timeExtent = d3.extent(this.data, d => d.time);
        this.xScale = d3.scaleTime()
            .domain(timeExtent)
            .range([config.margin.left, config.width - config.margin.right]);

        // Y scale (stocks)
        const stocks = [...new Set(this.data.map(d => d.stock))];
        this.yScale = d3.scaleBand()
            .domain(stocks)
            .range([config.height - config.margin.bottom, config.margin.top])
            .padding(0.1);

        // Color scale (price change)
        this.colorScale = d3.scaleLinear()
            .domain([-0.05, 0, 0.05]) // -5% to +5%
            .range(['#e74c3c', '#f39c12', '#2ecc71'])
            .clamp(true);
    }

    createAxes() {
        // X axis
        this.svg.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
            .call(d3.axisBottom(this.xScale));

        // Y axis
        this.svg.append('g')
            .attr('class', 'y-axis')
            .attr('transform', `translate(${config.margin.left}, 0)`)
            .call(d3.axisLeft(this.yScale));

        // Axis labels
        this.svg.append('text')
            .attr('class', 'x-axis-label')
            .attr('x', config.width / 2)
            .attr('y', config.height - 10)
            .style('text-anchor', 'middle')
            .text('Time');

        this.svg.append('text')
            .attr('class', 'y-axis-label')
            .attr('transform', 'rotate(-90)')
            .attr('x', -config.height / 2)
            .attr('y', 20)
            .style('text-anchor', 'middle')
            .text('Stock');
    }

    createHeatmap() {
        // Create heatmap cells
        this.svg.selectAll('.heatmap-cell')
            .data(this.data)
            .enter()
            .append('rect')
            .attr('class', 'heatmap-cell')
            .attr('x', d => this.xScale(d.time))
            .attr('y', d => this.yScale(d.stock))
            .attr('width', (config.width - config.margin.left - config.margin.right) / (config.maxDataPoints / 9))
            .attr('height', this.yScale.bandwidth())
            .attr('fill', d => this.colorScale(d.change))
            .on('mouseover', (event, d) => {
                this.tooltip.classed('show', true)
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${new Date(d.time).toLocaleString()}<br>
                        Change: ${(d.change * 100).toFixed(2)}%
                    `)
                    .style('left', `${event.pageX + 10}px`)
                    .style('top', `${event.pageY + 10}px`);
            })
            .on('mouseout', () => {
                this.tooltip.classed('show', false);
            });
    }

    setupZoom() {
        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .translateExtent([
                [config.margin.left, config.margin.top],
                [config.width - config.margin.right, config.height - config.margin.bottom]
            ])
            .on('zoom', (event) => {
                const transform = event.transform;

                // Apply zoom to x-axis
                this.svg.select('.x-axis')
                    .call(d3.axisBottom(this.xScale.scale(transform.rescaleX(this.xScale))));

                // Update heatmap cells
                this.svg.selectAll('.heatmap-cell')
                    .attr('x', d => transform.applyX(this.xScale(d.time)))
                    .attr('width', (config.width - config.margin.left - config.margin.right) /
                          (config.maxDataPoints / 9) / transform.k);
            });

        this.svg.call(this.zoom);
    }

    setupTimeRangeSelector() {
        d3.select('#timeRange').on('change', (event) => {
            config.timeRange = event.target.value;
            this.updateData();
        });
    }

    updateData() {
        // In a real app, this would fetch new data from a server
        // For this demo, we'll just generate new mock data
        this.data = generateMockData();

        // Update scales
        this.setupScales();

        // Update axes
        this.svg.select('.x-axis')
            .transition()
            .duration(500)
            .call(d3.axisBottom(this.xScale));

        this.svg.select('.y-axis')
            .transition()
            .duration(500)
            .call(d3.axisLeft(this.yScale));

        // Update heatmap cells
        const cells = this.svg.selectAll('.heatmap-cell')
            .data(this.data, d => `${d.stock}-${d.time}`);

        // Enter new cells
        cells.enter()
            .append('rect')
            .attr('class', 'heatmap-cell')
            .attr('x', d => this.xScale(d.time))
            .attr('y', d => this.yScale(d.stock))
            .attr('width', (config.width - config.margin.left - config.margin.right) / (config.maxDataPoints / 9))
            .attr('height', this.yScale.bandwidth())
            .attr('fill', d => this.colorScale(d.change))
            .on('mouseover', (event, d) => {
                this.tooltip.classed('show', true)
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${new Date(d.time).toLocaleString()}<br>
                        Change: ${(d.change * 100).toFixed(2)}%
                    `)
                    .style('left', `${event.pageX + 10}px`)
                    .style('top', `${event.pageY + 10}px`);
            })
            .on('mouseout', () => {
                this.tooltip.classed('show', false);
            });

        // Update existing cells
        cells.transition()
            .duration(500)
            .attr('x', d => this.xScale(d.time))
            .attr('y', d => this.yScale(d.stock))
            .attr('fill', d => this.colorScale(d.change));

        // Remove old cells
        cells.exit().remove();
    }

    startRealTimeUpdates() {
        // In a real app, this would connect to a WebSocket or use Server-Sent Events
        // For this demo, we'll simulate updates with setInterval
        setInterval(() => {
            // Generate new data point for each stock
            const now = new Date();
            const newData = [];

            const stocks = [...new Set(this.data.map(d => d.stock))];
            stocks.forEach(stock => {
                const change = (Math.random() * 10 - 5) / 100;
                newData.push({
                    stock,
                    time: now.getTime(),
                    change: change
                });
            });

            // Add new data points
            this.data = [...this.data, ...newData];

            // Remove old data points if we exceed maxDataPoints
            if (this.data.length > config.maxDataPoints * stocks.length) {
                this.data = this.data.slice(stocks.length);
            }

            // Update the visualization
            this.updateData();
        }, config.updateInterval);
    }
}

// Initialize the heatmap when the page loads
document.addEventListener('DOMContentLoaded', () => {
    new StockHeatmap();
});
