```typescript
// Type definitions for our data
interface StockDataPoint {
    timestamp: number;
    price: number;
    volume: number;
}

interface StockData {
    symbol: string;
    data: StockDataPoint[];
}

// Mock WebSocket service for demonstration
class MockWebSocketService {
    private socket: WebSocket | null = null;
    private listeners: ((data: StockData) => void)[] = [];

    connect(symbol: string, timeRange: string): void {
        // In a real app, this would connect to a WebSocket server
        console.log(`Connecting to WebSocket for ${symbol} (${timeRange})`);

        // Simulate real-time data
        this.simulateRealTimeData(symbol);
    }

    onData(callback: (data: StockData) => void): void {
        this.listeners.push(callback);
    }

    private simulateRealTimeData(symbol: string): void {
        const interval = setInterval(() => {
            const now = Date.now();
            const data: StockData = {
                symbol,
                data: Array.from({ length: 10 }, (_, i) => ({
                    timestamp: now - (i * 60 * 1000), // Last 10 minutes
                    price: 100 + Math.random() * 20 - 10, // Random price fluctuation
                    volume: Math.floor(Math.random() * 1000000)
                }))
            };

            this.listeners.forEach(listener => listener(data));
        }, 5000); // Update every 5 seconds

        // Clean up when component unmounts
        return () => clearInterval(interval);
    }
}

// Heatmap visualization class
class StockHeatmap {
    private svg: d3.Selection<SVGSVGElement, unknown, HTMLElement, any>;
    private width: number;
    private height: number;
    private margin = { top: 20, right: 20, bottom: 60, left: 60 };
    private xScale: d3.ScaleTime<number, number>;
    private yScale: d3.ScaleLinear<number, number>;
    private colorScale: d3.ScaleLinear<string, string>;
    private zoom: d3.ZoomBehavior<SVGSVGElement, unknown>;
    private currentData: StockData | null = null;

    constructor(containerId: string) {
        // Set up SVG container
        this.width = document.getElementById(containerId)!.clientWidth - this.margin.left - this.margin.right;
        this.height = 400 - this.margin.top - this.margin.bottom;

        this.svg = d3.select(`#${containerId}`)
            .append("svg")
            .attr("width", this.width + this.margin.left + this.margin.right)
            .attr("height", this.height + this.margin.top + this.margin.bottom)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        // Initialize scales
        this.xScale = d3.scaleTime().range([0, this.width]);
        this.yScale = d3.scaleLinear().range([this.height, 0]);
        this.colorScale = d3.scaleLinear<string>()
            .range(["#f7fbff", "#08306b"])
            .interpolate(d3.interpolateHcl);

        // Set up zoom behavior
        this.zoom = d3.zoom<SVGSVGElement, unknown>()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        // Add legend
        this.createLegend();
    }

    private createLegend(): void {
        const legend = d3.select("#legend");

        const legendData = [
            { color: "#f7fbff", label: "Low" },
            { color: "#08306b", label: "High" }
        ];

        legend.selectAll(".legend-item")
            .data(legendData)
            .enter()
            .append("div")
            .attr("class", "legend-item")
            .html(d => `
                <div class="legend-color" style="background-color: ${d.color};"></div>
                <span>${d.label}</span>
            `);
    }

    private zoomed(event: d3.D3ZoomEvent<SVGSVGElement, unknown>): void {
        if (!this.currentData) return;

        const newXScale = event.transform.rescaleX(this.xScale);
        const newYScale = event.transform.rescaleY(this.yScale);

        // Update axes
        this.svg.selectAll(".x-axis").call(d3.axisBottom(newXScale));
        this.svg.selectAll(".y-axis").call(d3.axisLeft(newYScale));

        // Update heatmap cells
        this.svg.selectAll(".heatmap-cell")
            .attr("x", d => newXScale(new Date(d.timestamp)))
            .attr("y", d => newYScale(d.price))
            .attr("width", this.width / this.currentData.data.length)
            .attr("height", this.height / 10); // Adjust based on your data
    }

    updateData(data: StockData): void {
        this.currentData = data;

        // Update scales
        this.xScale.domain(d3.extent(data.data, d => new Date(d.timestamp)) as [Date, Date]);
        this.yScale.domain([d3.min(data.data, d => d.price)! - 5, d3.max(data.data, d => d.price)! + 5]);
        this.colorScale.domain([d3.min(data.data, d => d.price)!, d3.max(data.data, d => d.price)!]);

        // Draw heatmap
        this.drawHeatmap(data);
    }

    private drawHeatmap(data: StockData): void {
        // Remove previous elements
        this.svg.selectAll(".heatmap-cell").remove();
        this.svg.selectAll(".x-axis").remove();
        this.svg.selectAll(".y-axis").remove();

        // Add X axis
        this.svg.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale));

        // Add Y axis
        this.svg.append("g")
            .attr("class", "y-axis")
            .call(d3.axisLeft(this.yScale));

        // Add heatmap cells
        const cellWidth = this.width / data.data.length;
        const cellHeight = this.height / 10; // Adjust based on your data

        this.svg.selectAll(".heatmap-cell")
            .data(data.data)
            .enter()
            .append("rect")
            .attr("class", "heatmap-cell")
            .attr("x", d => this.xScale(new Date(d.timestamp)))
            .attr("y", d => this.yScale(d.price))
            .attr("width", cellWidth)
            .attr("height", cellHeight)
            .attr("fill", d => this.colorScale(d.price))
            .on("mouseover", (event, d) => {
                d3.select("#tooltip")
                    .style("left", `${event.pageX + 10}px`)
                    .style("top", `${event.pageY + 10}px`)
                    .style("display", "block")
                    .html(`
                        <strong>${data.symbol}</strong><br>
                        Time: ${new Date(d.timestamp).toLocaleTimeString()}<br>
                        Price: $${d.price.toFixed(2)}<br>
                        Volume: ${d.volume.toLocaleString()}
                    `);
            })
            .on("mouseout", () => {
                d3.select("#tooltip").style("display", "none");
            });
    }
}

