// Type definitions for our data
interface StockDataPoint {
    date: string;
    time: string;
    price: number;
    volume: number;
    change: number;
}

interface HeatmapData {
    [date: string]: {
        [time: string]: StockDataPoint;
    };
}

// Main application class
class StockHeatmap {
    private svg: d3.Selection<SVGSVGElement, unknown, null, undefined>;
    private tooltip: d3.Selection<HTMLDivElement, unknown, null, undefined>;
    private data: HeatmapData = {};
    private currentSymbol: string = 'AAPL';
    private socket: WebSocket | null = null;
    private zoom: d3.ZoomBehavior<Element, unknown>;
    private colorScale: d3.ScaleLinear<string, string>;
    private xScale: d3.ScaleBand<string>;
    private yScale: d3.ScaleBand<string>;
    private width: number;
    private height: number;

    constructor() {
        // Initialize dimensions
        this.width = document.getElementById('heatmap')!.clientWidth;
        this.height = document.getElementById('heatmap')!.clientHeight;

        // Create SVG container
        this.svg = d3.select('#heatmap')
            .append('svg')
            .attr('width', this.width)
            .attr('height', this.height);

        // Create tooltip
        this.tooltip = d3.select('body')
            .append('div')
            .attr('class', 'tooltip')
            .style('opacity', 0);

        // Initialize scales
        this.colorScale = d3.scaleLinear<string>()
            .range(['#f7fbff', '#08306b']);

        this.xScale = d3.scaleBand<string>()
            .range([0, this.width])
            .padding(0.01);

        this.yScale = d3.scaleBand<string>()
            .range([0, this.height])
            .padding(0.01);

        // Initialize zoom behavior
        this.zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on('zoom', (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        // Set up event listeners
        this.setupEventListeners();

        // Connect to WebSocket
        this.connectWebSocket();

        // Initial data load
        this.loadInitialData();
    }

    private setupEventListeners(): void {
        // Symbol selection
        d3.select('#symbol-select').on('change', (event) => {
            this.currentSymbol = (event.target as HTMLSelectElement).value;
            this.loadInitialData();
        });

        // Refresh button
        d3.select('#refresh-btn').on('click', () => {
            this.loadInitialData();
        });

        // Window resize
        window.addEventListener('resize', () => {
            this.width = document.getElementById('heatmap')!.clientWidth;
            this.height = document.getElementById('heatmap')!.clientHeight;
            this.svg.attr('width', this.width).attr('height', this.height);
            this.updateScales();
            this.renderHeatmap();
        });
    }

    private connectWebSocket(): void {
        // In a real app, this would connect to your WebSocket server
        // For demo purposes, we'll simulate updates
        this.socket = new WebSocket('wss://demo.piesocket.com/v3/channel_123?api_key=VCXCEuvhGcBDP7XhiJJUDvR1e1D3eiVjgZ9VRiaV&notify_self');

        this.socket.onopen = () => {
            d3.select('#status').text('Connected');
        };

        this.socket.onmessage = (event) => {
            try {
                const update = JSON.parse(event.data);
                this.processUpdate(update);
            } catch (e) {
                console.error('Error parsing WebSocket message:', e);
            }
        };

        this.socket.onclose = () => {
            d3.select('#status').text('Disconnected');
            // Attempt to reconnect after 5 seconds
            setTimeout(() => this.connectWebSocket(), 5000);
        };
    }

    private loadInitialData(): void {
        // In a real app, this would fetch historical data
        // For demo purposes, we'll generate mock data
        this.data = this.generateMockData();

        // Update color scale domain based on data
        const allPrices = Object.values(this.data)
            .flatMap(dateData => Object.values(dateData))
            .map(d => d.price);
        this.colorScale.domain([d3.min(allPrices)!, d3.max(allPrices)!]);

        this.updateScales();
        this.renderHeatmap();
    }

    private generateMockData(): HeatmapData {
        const data: HeatmapData = {};
        const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA'];
        const now = new Date();

        // Generate data for the last 30 days
        for (let day = 0; day < 30; day++) {
            const date = new Date(now);
            date.setDate(now.getDate() - day);
            const dateStr = date.toISOString().split('T')[0];

            data[dateStr] = {};

            // Generate data for each hour of the day
            for (let hour = 0; hour < 24; hour++) {
                const timeStr = `${hour.toString().padStart(2, '0')}:00:00`;

                // Generate random price based on symbol
                let basePrice = 100;
                if (this.currentSymbol === 'AAPL') basePrice = 150;
                if (this.currentSymbol === 'MSFT') basePrice = 250;
                if (this.currentSymbol === 'GOOGL') basePrice = 2000;
                if (this.currentSymbol === 'AMZN') basePrice = 3000;
                if (this.currentSymbol === 'TSLA') basePrice = 150;

                const price = basePrice + (Math.random() * 20 - 10);
                const volume = Math.floor(Math.random() * 1000000);
                const prevPrice = basePrice + (Math.random() * 20 - 10);
                const change = ((price - prevPrice) / prevPrice) * 100;

                data[dateStr][timeStr] = {
                    date: dateStr,
                    time: timeStr,
                    price: parseFloat(price.toFixed(2)),
                    volume,
                    change: parseFloat(change.toFixed(2))
                };
            }
        }

        return data;
    }

    private processUpdate(update: any): void {
        // In a real app, this would process WebSocket updates
        // For demo purposes, we'll just add a random update
        const dates = Object.keys(this.data);
        const randomDate = dates[Math.floor(Math.random() * dates.length)];
        const times = Object.keys(this.data[randomDate]);
        const randomTime = times[Math.floor(Math.random() * times.length)];

        // Generate a new price
        const currentPrice = this.data[randomDate][randomTime].price;
        const newPrice = currentPrice + (Math.random() * 4 - 2);
        const change = ((newPrice - currentPrice) / currentPrice) * 100;

        // Update the data
        this.data[randomDate][randomTime] = {
            ...this.data[randomDate][randomTime],
            price: parseFloat(newPrice.toFixed(2)),
            change: parseFloat(change.toFixed(2))
        };

        // Update the visualization
        this.updateScales();
        this.renderHeatmap();
    }

    private updateScales(): void {
        // Update x and y scales based on current data
        const dates = Object.keys(this.data);
        const times = Object.keys(this.data[dates[0]] || {});

        this.xScale.domain(times).range([0, this.width]);
        this.yScale.domain(dates).range([0, this.height]);
    }

    private renderHeatmap(): void {
        // Clear previous heatmap
        this.svg.selectAll('g').remove();

        // Create a group for the heatmap
        const heatmapGroup = this.svg.append('g');

        // Add rectangles for each data point
        const dates = Object.keys(this.data);
        const times = Object.keys(this.data[dates[0]] || {});

        dates.forEach(date => {
            times.forEach(time => {
                const dataPoint = this.data[date][time];

                heatmapGroup.append('rect')
                    .attr('x', this.xScale(time)!)
                    .attr('y', this.yScale(date)!)
                    .attr('width', this.xScale.bandwidth())
                    .attr('height', this.yScale.bandwidth())
                    .attr('fill', this.colorScale(dataPoint.price))
                    .on('mouseover', (event) => {
                        this.tooltip.transition()
                            .duration(200)
                            .style('opacity', .9);
                        this.tooltip.html(`
                            <strong>${this.currentSymbol}</strong><br>
                            Date: ${date}<br>
                            Time: ${time}<br>
                            Price: $${dataPoint.price.toFixed(2)}<br>
                            Change: ${dataPoint.change.toFixed(2)}%<br>
                            Volume: ${dataPoint.volume.toLocaleString()}
                        `)
                        .style('left', (event.pageX + 10) + 'px')
                        .style('top', (event.pageY - 28) + 'px');
                    })
                    .on('mouseout', () => {
                        this.tooltip.transition()
                            .duration(500)
                            .style('opacity', 0);
                    });
            });
        });

        // Add axes
        this.addAxes();
    }

    private addAxes(): void {
        // X-axis (time)
        this.svg.append('g')
            .attr('class', 'axis axis--x')
            .attr('transform', `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale).tickValues(this.xScale.domain().filter((d, i) => i % 3 === 0)))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        // Y-axis (date)
        this.svg.append('g')
            .attr('class', 'axis axis--y')
            .call(d3.axisLeft(this.yScale).tickValues(this.yScale.domain().filter((d, i) => i % 2 === 0)));
    }

    private zoomed(event: d3.D3ZoomEvent<Element, unknown>): void {
        // Apply zoom transform to the heatmap group
        const transform = event.transform;
        this.svg.selectAll('g').attr('transform', transform);

        // Adjust axis scales
        const newXScale = transform.rescaleX(this.xScale);
        const newYScale = transform.rescaleY(this.yScale);

        // Update axes
        this.svg.select('.axis--x')
            .call(d3.axisBottom(newXScale).tickValues(newXScale.domain().filter((d, i) => i % 3 === 0)))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        this.svg.select('.axis--y')
            .call(d3.axisLeft(newYScale).tickValues(newYScale.domain().filter((d, i) => i % 2 === 0)));
    }
}

