## TypeScript (app.ts)

```typescript
// Define types for our data
interface StockPrice {
    symbol: string;
    timestamp: number;
    price: number;
    change: number;
    volume: number;
}

interface HeatmapData {
    xLabels: string[];
    yLabels: string[];
    data: number[][];
}

// Main application class
class StockHeatmap {
    private svg: d3.Selection<SVGSVGElement, unknown, HTMLElement, any>;
    private tooltip: d3.Selection<HTMLDivElement, unknown, HTMLElement, any>;
    private xScale: d3.ScaleBand<string>;
    private yScale: d3.ScaleBand<string>;
    private colorScale: d3.ScaleSequential<string>;
    private zoom: d3.ZoomBehavior<SVGSVGElement, unknown>;
    private heatmapData: HeatmapData;
    private ws: WebSocket;
    private selectedSymbols: string[] = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'META'];
    private timeRange: string = '1d';

    constructor() {
        // Initialize SVG container
        this.svg = d3.select('#heatmap')
            .append('svg')
            .attr('width', '100%')
            .attr('height', 500);

        // Initialize tooltip
        this.tooltip = d3.select('#tooltip');

        // Initialize scales
        this.xScale = d3.scaleBand();
        this.yScale = d3.scaleBand();
        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([-0.1, 0.1]); // Price change range

        // Initialize zoom behavior
        this.zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on('zoom', (event) => this.zoomed(event));

        // Set up WebSocket connection
        this.setupWebSocket();

        // Set up UI controls
        this.setupControls();

        // Initial data load
        this.loadInitialData();
    }

    private setupWebSocket(): void {
        // In a real app, this would connect to your WebSocket server
        // For demo purposes, we'll simulate real-time updates
        this.ws = new WebSocket('wss://your-websocket-server.com/stocks');

        this.ws.onopen = () => {
            console.log('WebSocket connection established');
            this.ws.send(JSON.stringify({
                action: 'subscribe',
                symbols: this.selectedSymbols,
                timeRange: this.timeRange
            }));
        };

        this.ws.onmessage = (event) => {
            const data: StockPrice[] = JSON.parse(event.data);
            this.updateHeatmap(data);
        };

        this.ws.onclose = () => {
            console.log('WebSocket connection closed');
            // Attempt to reconnect after 5 seconds
            setTimeout(() => this.setupWebSocket(), 5000);
        };
    }

    private setupControls(): void {
        // Time range selector
        d3.select('#timeRange').on('change', (event) => {
            this.timeRange = (event.target as HTMLSelectElement).value;
        });

        // Symbol selector
        d3.select('#symbols').on('change', (event) => {
            const select = event.target as HTMLSelectElement;
            this.selectedSymbols = Array.from(select.selectedOptions)
                .map(option => option.value);
        });

        // Update button
        d3.select('#updateBtn').on('click', () => {
            this.loadInitialData();
            if (this.ws.readyState === WebSocket.OPEN) {
                this.ws.send(JSON.stringify({
                    action: 'subscribe',
                    symbols: this.selectedSymbols,
                    timeRange: this.timeRange
                }));
            }
        });
    }

    private loadInitialData(): void {
        // In a real app, this would fetch historical data from an API
        // For demo purposes, we'll generate mock data
        const now = Date.now();
        const timeInterval = this.getTimeInterval();
        const timestamps = Array.from({length: 24}, (_, i) => now - (24 - i) * timeInterval);

        // Generate mock data
        const mockData: StockPrice[] = [];
        this.selectedSymbols.forEach(symbol => {
            timestamps.forEach(timestamp => {
                const change = (Math.random() - 0.5) * 0.2; // Random change between -0.1 and 0.1
                mockData.push({
                    symbol,
                    timestamp,
                    price: 100 + (Math.random() * 50), // Random price between 100 and 150
                    change,
                    volume: Math.floor(Math.random() * 1000000)
                });
            });
        });

        this.updateHeatmap(mockData);
    }

    private getTimeInterval(): number {
        // Return milliseconds based on selected time range
        switch (this.timeRange) {
            case '1h': return 5 * 60 * 1000; // 5 minutes
            case '4h': return 15 * 60 * 1000; // 15 minutes
            case '1d': return 60 * 60 * 1000; // 1 hour
            case '1w': return 4 * 60 * 60 * 1000; // 4 hours
            case '1m': return 24 * 60 * 60 * 1000; // 1 day
            default: return 60 * 60 * 1000;
        }
    }

    private updateHeatmap(data: StockPrice[]): void {
        // Process data into heatmap format
        const xLabels = [...new Set(data.map(d => new Date(d.timestamp).toLocaleTimeString()))];
        const yLabels = [...new Set(data.map(d => d.symbol))];

        // Create a 2D array for the heatmap values (price changes)
        const heatmapValues: number[][] = yLabels.map(() => new Array(xLabels.length).fill(0));

        data.forEach(d => {
            const xIndex = xLabels.indexOf(new Date(d.timestamp).toLocaleTimeString());
            const yIndex = yLabels.indexOf(d.symbol);
            if (xIndex >= 0 && yIndex >= 0) {
                heatmapValues[yIndex][xIndex] = d.change;
            }
        });

        this.heatmapData = {
            xLabels,
            yLabels,
            data: heatmapValues
        };

        this.renderHeatmap();
    }

    private renderHeatmap(): void {
        // Clear previous content
        this.svg.selectAll('*').remove();

        // Set dimensions
        const margin = { top: 20, right: 20, bottom: 80, left: 80 };
        const width = parseInt(this.svg.style('width')) - margin.left - margin.right;
        const height = parseInt(this.svg.style('height')) - margin.top - margin.bottom;

        // Create main group
        const g = this.svg.append('g')
            .attr('transform', `translate(${margin.left},${margin.top})`);

        // Update scales
        this.xScale.domain(this.heatmapData.xLabels)
            .range([0, width])
            .padding(0.05);

        this.yScale.domain(this.heatmapData.yLabels)
            .range([height, 0])
            .padding(0.05);

        // Create heatmap cells
        const cells = g.selectAll('.cell')
            .data(this.heatmapData.data.flatMap((row, y) =>
                row.map((value, x) => ({
                    x: x,
                    y: y,
                    value: value
                }))
            ))
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => this.xScale(this.heatmapData.xLabels[d.x]) || 0)
            .attr('y', d => this.yScale(this.heatmapData.yLabels[d.y]) || 0)
            .attr('width', this.xScale.bandwidth())
            .attr('height', this.yScale.bandwidth())
            .attr('fill', d => this.colorScale(d.value))
            .on('mouseover', (event, d) => this.showTooltip(event, d))
            .on('mouseout', () => this.hideTooltip());

        // Add axes
        g.append('g')
            .attr('class', 'axis axis--x')
            .attr('transform', `translate(0,${height})`)
            .call(d3.axisBottom(this.xScale))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        g.append('g')
            .attr('class', 'axis axis--y')
            .call(d3.axisLeft(this.yScale));

        // Add zoom behavior
        this.svg.call(this.zoom);

        // Add legend
        this.renderLegend();
    }

    private renderLegend(): void {
        const legend = d3.select('#legend');
        legend.selectAll('*').remove();

        const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([-0.1, 0.1]);

        const legendData = [
            { value: -0.1, label: '-10%' },
            { value: -0.05, label: '-5%' },
            { value: 0, label: '0%' },
            { value: 0.05, label: '+5%' },
            { value: 0.1, label: '+10%' }
        ];

        legend.selectAll('.legend-item')
            .data(legendData)
            .enter()
            .append('div')
            .attr('class', 'legend-item')
            .html(d => `
                <div class="legend-color" style="background-color: ${colorScale(d.value)}"></div>
                <span>${d.label}</span>
            `);
    }

    private zoomed(event: d3.D3ZoomEvent<SVGSVGElement, unknown>): void {
        const transform = event.transform;
        this.svg.select('g').attr('transform', transform);
    }

    private showTooltip(event: MouseEvent, d: { x: number; y: number; value: number }): void {
        const [x, y] = d3.pointer(event);
        const symbol = this.heatmapData.yLabels[d.y];
        const time = this.heatmapData.xLabels[d.x];
        const change = (d.value * 100).toFixed(2);

        this.tooltip.style('visibility', 'visible')
            .style('left', `${x + 10}px`)
            .style('top', `${y - 10}px`)
            .html(`
                <strong>${symbol}</strong><br>
                Time: ${time}<br>
                Change: ${change}%
            `);
    }

    private hideTooltip(): void {
        this.tooltip.style('visibility', 'hidden');
    }
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', () => {
    new StockHeatmap();
});
