### **JavaScript (`app.js`)**
```javascript
// Configuration
const width = 800;
const height = 500;
const margin = { top: 30, right: 30, bottom: 50, left: 50 };
const numStocks = 10; // Number of stocks
const numTimePoints = 50; // Number of time points

// Generate random stock data (simulating real-time updates)
function generateStockData() {
    const stocks = Array.from({ length: numStocks }, (_, i) => `Stock ${i + 1}`);
    const timePoints = Array.from({ length: numTimePoints }, (_, i) => new Date(Date.now() - (numTimePoints - i) * 60000)); // Last 50 minutes

    const data = [];
    for (let i = 0; i < numStocks; i++) {
        for (let j = 0; j < numTimePoints; j++) {
            data.push({
                stock: stocks[i],
                time: timePoints[j],
                price: 100 + Math.random() * 50 // Random price between 100-150
            });
        }
    }
    return { stocks, timePoints, data };
}

// Initialize heatmap
function initHeatmap() {
    const { stocks, timePoints, data } = generateStockData();

    // Create SVG container
    const svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    // Create scales
    const xScale = d3.scaleBand()
        .domain(timePoints.map(d => d.toISOString()))
        .range([margin.left, width - margin.right])
        .padding(0.01);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([margin.top, height - margin.bottom])
        .padding(0.01);

    const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
        .domain([100, 150]); // Price range

    // Create axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => new Date(d).toLocaleTimeString())
        .tickValues(xScale.domain().filter((_, i) => i % 5 === 0)); // Show every 5th time point

    const yAxis = d3.axisLeft(yScale);

    svg.append("g")
        .attr("transform", `translate(0, ${height - margin.bottom})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    svg.append("g")
        .attr("transform", `translate(${margin.left}, 0)`)
        .call(yAxis);

    // Add axis labels
    svg.append("text")
        .attr("x", width / 2)
        .attr("y", height - 5)
        .style("text-anchor", "middle")
        .text("Time");

    svg.append("text")
        .attr("transform", "rotate(-90)")
        .attr("y", 15)
        .attr("x", -height / 2)
        .style("text-anchor", "middle")
        .text("Stock");

    // Add color legend
    const legend = svg.append("g")
        .attr("transform", `translate(${width - margin.right + 10}, ${margin.top})`);

    const legendScale = d3.scaleLinear()
        .domain([100, 150])
        .range([0, 100]);

    const legendAxis = d3.axisRight(legendScale)
        .ticks(5);

    legend.append("g")
        .call(legendAxis);

    legend.selectAll("rect")
        .data(d3.range(100, 151))
        .enter()
        .append("rect")
        .attr("x", 0)
        .attr("y", d => legendScale(d))
        .attr("width", 20)
        .attr("height", 1)
        .attr("fill", d => colorScale(d));

    // Add zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on("zoom", (event) => {
            const newXScale = event.transform.rescaleX(xScale);
            const newYScale = event.transform.rescaleY(yScale);

            svg.selectAll(".heatmap-cell")
                .attr("x", d => newXScale(d.time.toISOString()))
                .attr("y", d => newYScale(d.stock))
                .attr("width", newXScale.bandwidth())
                .attr("height", newYScale.bandwidth());

            svg.select(".x-axis").call(xAxis.scale(newXScale));
            svg.select(".y-axis").call(yAxis.scale(newYScale));
        });

    svg.call(zoom);

    // Draw heatmap cells
    svg.selectAll(".heatmap-cell")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "heatmap-cell")
        .attr("x", d => xScale(d.time.toISOString()))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mouseover", function(event, d) {
            d3.select(this)
                .attr("stroke", "black")
                .attr("stroke-width", 2);

            // Show tooltip
            const tooltip = d3.select("body")
                .append("div")
                .attr("class", "tooltip")
                .style("position", "absolute")
                .style("background", "white")
                .style("padding", "5px")
                .style("border", "1px solid black")
                .style("border-radius", "3px")
                .style("pointer-events", "none")
                .html(`Stock: ${d.stock}<br>Time: ${d.time.toLocaleTimeString()}<br>Price: $${d.price.toFixed(2)}`);

            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        })
        .on("mouseout", function() {
            d3.select(this)
                .attr("stroke", null);

            d3.select(".tooltip").remove();
        });

    // Simulate real-time updates (every 2 seconds)
    setInterval(() => {
        const newData = generateStockData().data;
        svg.selectAll(".heatmap-cell")
            .data(newData)
            .transition()
            .duration(500)
            .attr("fill", d => colorScale(d.price));
    }, 2000);
}

// Initialize the heatmap
initHeatmap();
