### **Code (`index.html`):**
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Stock Price Heatmap</title>
    <script src="https://d3js.org/d3.v7.min.js"></script>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 20px;
            background: #f5f5f5;
        }
        .heatmap-container {
            width: 100%;
            height: 500px;
            border: 1px solid #ddd;
            background: white;
        }
        .axis-label {
            font-size: 12px;
            fill: #555;
        }
        .tooltip {
            position: absolute;
            padding: 8px;
            background: rgba(0, 0, 0, 0.8);
            color: white;
            border-radius: 4px;
            pointer-events: none;
            font-size: 12px;
        }
    </style>
</head>
<body>
    <h2>Stock Price Heatmap (Real-Time)</h2>
    <div class="heatmap-container" id="heatmap"></div>
    <div class="tooltip" id="tooltip"></div>

    <script>
        // Configuration
        const config = {
            width: 800,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 50 },
            numRows: 20,
            numCols: 50,
            updateInterval: 1000, // ms
        };

        // Generate random stock data (simulating real-time updates)
        function generateStockData(rows, cols) {
            const data = [];
            for (let i = 0; i < rows; i++) {
                const row = [];
                for (let j = 0; j < cols; j++) {
                    // Simulate stock price changes (random walk)
                    const change = (Math.random() - 0.5) * 2;
                    row.push(change);
                }
                data.push(row);
            }
            return data;
        }

        // Initialize heatmap
        function initHeatmap() {
            const svg = d3.select("#heatmap")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            const g = svg.append("g")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", (event) => {
                    g.attr("transform", event.transform);
                });

            svg.call(zoom);

            // Add axes
            const xScale = d3.scaleBand()
                .domain(d3.range(config.numCols))
                .range([0, config.width - config.margin.left - config.margin.right]);

            const yScale = d3.scaleBand()
                .domain(d3.range(config.numRows))
                .range([0, config.height - config.margin.top - config.margin.bottom]);

            g.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.top - config.margin.bottom})`)
                .call(d3.axisBottom(xScale).tickFormat(d => `T${d}`))
                .selectAll("text")
                .attr("class", "axis-label");

            g.append("g")
                .attr("class", "y-axis")
                .call(d3.axisLeft(yScale).tickFormat(d => `S${d}`))
                .selectAll("text")
                .attr("class", "axis-label");

            // Add tooltip
            const tooltip = d3.select("#tooltip");

            // Update heatmap data
            function updateHeatmap() {
                const data = generateStockData(config.numRows, config.numCols);

                // Color scale (green = up, red = down)
                const colorScale = d3.scaleLinear()
                    .domain([-1, 0, 1])
                    .range(["#ff4d4d", "#f5f5f5", "#4dff4d"]);

                // Bind data to rectangles
                const cells = g.selectAll(".cell")
                    .data(data.flat());

                cells.enter()
                    .append("rect")
                    .attr("class", "cell")
                    .merge(cells)
                    .attr("x", (d, i) => xScale(i % config.numCols))
                    .attr("y", (d, i) => yScale(Math.floor(i / config.numCols)))
                    .attr("width", xScale.bandwidth())
                    .attr("height", yScale.bandwidth())
                    .attr("fill", d => colorScale(d))
                    .on("mouseover", (event, d) => {
                        tooltip.style("display", "block")
                            .html(`Change: ${d.toFixed(2)}`);
                    })
                    .on("mousemove", (event) => {
                        tooltip.style("left", `${event.pageX + 10}px`)
                            .style("top", `${event.pageY + 10}px`);
                    })
                    .on("mouseout", () => {
                        tooltip.style("display", "none");
                    });

                cells.exit().remove();
            }

            // Initial render
            updateHeatmap();

            // Simulate real-time updates
            setInterval(updateHeatmap, config.updateInterval);
        }

        // Initialize on load
        window.onload = initHeatmap;
    </script>
</body>
</html>
```

