Here's a complete implementation using **TypeScript (frontend)** and **Node.js/Express (backend)** with **Socket.io** for real-time collaboration and **React DnD** for drag-and-drop functionality.

## Backend (Node.js + Express + Socket.io)

### `server.ts`
```typescript
import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import cors from 'cors';

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

app.use(cors());
app.use(express.json());

// In-memory data store (replace with database in production)
interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  description?: string;
}

interface Board {
  id: string;
  name: string;
  tasks: Task[];
}

let boards: Board[] = [
  {
    id: 'board-1',
    name: 'Project Alpha',
    tasks: [
      { id: 'task-1', title: 'Design UI', status: 'todo' },
      { id: 'task-2', title: 'Implement API', status: 'in-progress' },
      { id: 'task-3', title: 'Write tests', status: 'done' }
    ]
  }
];

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  // Send initial data
  socket.emit('initial-data', boards);

  // Handle task updates
  socket.on('update-task', (updatedTask: Task) => {
    boards = boards.map(board => ({
      ...board,
      tasks: board.tasks.map(task =>
        task.id === updatedTask.id ? updatedTask : task
      )
    }));
    io.emit('task-updated', updatedTask);
  });

  // Handle new tasks
  socket.on('add-task', (newTask: Task) => {
    boards = boards.map(board => ({
      ...board,
      tasks: [...board.tasks, newTask]
    }));
    io.emit('task-added', newTask);
  });

  // Handle task deletion
  socket.on('delete-task', (taskId: string) => {
    boards = boards.map(board => ({
      ...board,
      tasks: board.tasks.filter(task => task.id !== taskId)
    }));
    io.emit('task-deleted', taskId);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

