  title: string;
  status: 'todo' | 'in-progress' | 'done';
  description?: string;
}

interface BoardData {
  id: string;
  name: string;
  tasks: Task[];
}

const App: React.FC = () => {
  const [boards, setBoards] = useState<BoardData[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to Socket.io server
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Listen for initial data
    newSocket.on('initial-data', (initialBoards: BoardData[]) => {
      setBoards(initialBoards);
    });

    // Listen for real-time updates
    newSocket.on('task-updated', (updatedTask: Task) => {
      setBoards(prevBoards =>
        prevBoards.map(board => ({
          ...board,
          tasks: board.tasks.map(task =>
            task.id === updatedTask.id ? updatedTask : task
          )
        }))
      );
    });

    newSocket.on('task-added', (newTask: Task) => {
      setBoards(prevBoards =>
        prevBoards.map(board => ({
          ...board,
          tasks: [...board.tasks, newTask]
        }))
      );
    });

    newSocket.on('task-deleted', (taskId: string) => {
      setBoards(prevBoards =>
        prevBoards.map(board => ({
          ...board,
          tasks: board.tasks.filter(task => task.id !== taskId)
        }))
      );
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const handleTaskMove = (taskId: string, newStatus: 'todo' | 'in-progress' | 'done') => {
    if (!socket) return;

    const taskToUpdate = boards.flatMap(board => board.tasks).find(t => t.id === taskId);
    if (taskToUpdate) {
      const updatedTask = { ...taskToUpdate, status: newStatus };
      socket.emit('update-task', updatedTask);
    }
  };

  const handleAddTask = (title: string, description?: string) => {
    if (!socket) return;

    const newTask: Task = {
      id: `task-${Date.now()}`,
      title,
      status: 'todo',
      description
    };
    socket.emit('add-task', newTask);
  };

  const handleDeleteTask = (taskId: string) => {
    if (!socket) return;
    socket.emit('delete-task', taskId);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management Board</h1>
        <TaskForm onAddTask={handleAddTask} />

        <div className="boards-container">
          {boards.map(board => (
            <Board
              key={board.id}
              board={board}
              onTaskMove={handleTaskMove}
              onDeleteTask={handleDeleteTask}
            />
          ))}
        </div>
      </div>
    </DndProvider>
  );
};

export default App;
```

