import React from 'react';
import { useDrop } from 'react-dnd';
import Task from './Task';

interface BoardProps {
  board: {
    id: string;
    name: string;
    tasks: {
      id: string;
      title: string;
      status: 'todo' | 'in-progress' | 'done';
      description?: string;
    }[];
  };
  onTaskMove: (taskId: string, newStatus: 'todo' | 'in-progress' | 'done') => void;
  onDeleteTask: (taskId: string) => void;
}

const Board: React.FC<BoardProps> = ({ board, onTaskMove, onDeleteTask }) => {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: 'TASK',
    drop: (item: { id: string }) => {
      onTaskMove(item.id, board.tasks[0]?.status || 'todo');
    },
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
    }),
  }));

  return (
    <div
      ref={drop}
      className={`board ${isOver ? 'board-drag-over' : ''}`}
    >
      <h2>{board.name}</h2>
      <div className="tasks">
        {board.tasks.map(task => (
          <Task
            key={task.id}
            task={task}
            onDelete={() => onDeleteTask(task.id)}
          />
        ))}
      </div>
    </div>
  );
};

export default Board;
