## **2. Frontend (React + TypeScript + `react-beautiful-dnd`)**
### **`App.tsx`**
```tsx
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable, DropResult } from 'react-beautiful-dnd';
import { io, Socket } from 'socket.io-client';
import './App.css';

interface Task {
  id: string;
  content: string;
}

interface Board {
  id: string;
  title: string;
  tasks: Task[];
}

const App: React.FC = () => {
  const [boards, setBoards] = useState<Board[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to Socket.io server
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Listen for initial data
    newSocket.on('initialData', (initialBoards: Board[]) => {
      setBoards(initialBoards);
    });

    // Listen for real-time updates
    newSocket.on('boardsUpdated', (updatedBoards: Board[]) => {
      setBoards(updatedBoards);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const onDragEnd = (result: DropResult) => {
    if (!result.destination) return;

    const { source, destination } = result;
    const sourceBoard = boards.find(board => board.id === source.droppableId);
    const destBoard = boards.find(board => board.id === destination.droppableId);

    if (!sourceBoard || !destBoard) return;

    // Remove task from source board
    const [movedTask] = sourceBoard.tasks.splice(source.index, 1);

    // Add task to destination board
    destBoard.tasks.splice(destination.index, 0, movedTask);

    const newBoards = [...boards];
    setBoards(newBoards);

    // Emit update to server
    if (socket) {
      socket.emit('updateBoards', newBoards);
    }
  };

  return (
    <div className="app">
      <h1>Project Management Board</h1>
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="boards-container">
          {boards.map((board) => (
            <Droppable key={board.id} droppableId={board.id}>
              {(provided) => (
                <div
                  className="board"
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                >
                  <h2>{board.title}</h2>
                  {board.tasks.map((task, index) => (
                    <Draggable key={task.id} draggableId={task.id} index={index}>
                      {(provided) => (
                        <div
                          className="task"
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                        >
                          {task.content}
                        </div>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default App;
```

