import { BoardState } from './types/types';
import { useTasks } from './hooks/useTasks';
import { DropResult } from 'react-beautiful-dnd';
import { CssBaseline, Container, Typography } from '@mui/material';

const initialData: BoardState = {
  tasks: {},
  columns: {
    'column-1': {
      id: 'column-1',
      title: 'To Do',
      taskIds: []
    },
    'column-2': {
      id: 'column-2',
      title: 'In Progress',
      taskIds: []
    },
    'column-3': {
      id: 'column-3',
      title: 'Done',
      taskIds: []
    }
  },
  columnOrder: ['column-1', 'column-2', 'column-3']
};

export const App: React.FC = () => {
  const { tasks, loading, updateTask } = useTasks();
  const [boardState, setBoardState] = useState<BoardState>(initialData);

  useEffect(() => {
    if (!loading) {
      // Organize tasks into columns
      const newState = {...initialData};
      const tasksMap: {[key: string]: Task} = {};
      const columnTasks: {[key: string]: string[]} = {
        'column-1': [],
        'column-2': [],
        'column-3': []
      };

      tasks.forEach(task => {
        tasksMap[task.id] = task;
        switch(task.status) {
          case 'todo':
            columnTasks['column-1'].push(task.id);
            break;
          case 'in-progress':
            columnTasks['column-2'].push(task.id);
            break;
          case 'done':
            columnTasks['column-3'].push(task.id);
            break;
        }
      });

      newState.tasks = tasksMap;
      newState.columns['column-1'].taskIds = columnTasks['column-1'];
      newState.columns['column-2'].taskIds = columnTasks['column-2'];
      newState.columns['column-3'].taskIds = columnTasks['column-3'];

      setBoardState(newState);
    }
  }, [tasks, loading]);

  const onDragEnd = (result: DropResult) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const start = boardState.columns[source.droppableId];
    const finish = boardState.columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds
      };

      const newState = {
        ...boardState,
        columns: {
          ...boardState.columns,
          [newColumn.id]: newColumn
        }
      };

      setBoardState(newState);
      return;
    }

    // Moving to a different column
    const startTaskIds = Array.from(start.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStart = {
      ...start,
      taskIds: startTaskIds
    };

    const finishTaskIds = Array.from(finish.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinish = {
      ...finish,
      taskIds: finishTaskIds
    };

    const newState = {
      ...boardState,
      columns: {
        ...boardState.columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish
      }
    };

    setBoardState(newState);

    // Update task status in Firebase
    let newStatus: 'todo' | 'in-progress' | 'done';
    switch(destination.droppableId) {
      case 'column-1':
        newStatus = 'todo';
        break;
      case 'column-2':
        newStatus = 'in-progress';
        break;
      case 'column-3':
        newStatus = 'done';
        break;
      default:
        newStatus = 'todo';
    }

    updateTask(draggableId, { status: newStatus });
  };

  if (loading) {
    return <Typography>Loading...</Typography>;
  }

  return (
    <>
      <CssBaseline />
      <Container maxWidth="lg">
        <Typography variant="h3" component="h1" gutterBottom style={{ marginTop: '20px' }}>
          Project Management Board
        </Typography>
        <Board initialData={boardState} onDragEnd={onDragEnd} />
      </Container>
    </>
  );
};
```

