### **2. Frontend (React + TypeScript + React DnD)**
#### **`App.tsx`**
```tsx
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { io, Socket } from 'socket.io-client';
import './App.css';

interface Task {
  id: string;
  title: string;
  status: string;
  columnId: string;
}

interface Column {
  id: string;
  title: string;
}

const columns: Column[] = [
  { id: 'todo', title: 'To Do' },
  { id: 'in-progress', title: 'In Progress' },
  { id: 'done', title: 'Done' },
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to Socket.io server
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Fetch initial tasks
    fetch('http://localhost:5000/api/tasks')
      .then(res => res.json())
      .then(data => setTasks(data));

    // Listen for real-time updates
    newSocket.on('initial-tasks', (initialTasks: Task[]) => {
      setTasks(initialTasks);
    });

    newSocket.on('task-updated', (updatedTask: Task) => {
      setTasks(prevTasks =>
        prevTasks.map(task => (task.id === updatedTask.id ? updatedTask : task))
      );
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const moveTask = (taskId: string, newColumnId: string) => {
    const updatedTask = tasks.find(task => task.id === taskId);
    if (updatedTask) {
      updatedTask.columnId = newColumnId;
      updatedTask.status = newColumnId;
      socket?.emit('update-task', updatedTask);
    }
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management Board</h1>
        <div className="board">
          {columns.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.columnId === column.id)}
              moveTask={moveTask}
            />
          ))}
        </div>
      </div>
    </DndProvider>
  );
};

interface ColumnProps {
  column: Column;
  tasks: Task[];
  moveTask: (taskId: string, newColumnId: string) => void;
}

const Column: React.FC<ColumnProps> = ({ column, tasks, moveTask }) => {
  const [{ isOver }, drop] = useDrop({
    accept: 'TASK',
    drop: (item: { id: string }) => moveTask(item.id, column.id),
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
    }),
  });

  return (
    <div
      ref={drop}
      className={`column ${isOver ? 'column-drag-over' : ''}`}
    >
      <h2>{column.title}</h2>
      {tasks.map(task => (
        <Task key={task.id} task={task} />
      ))}
    </div>
  );
};

interface TaskProps {
  task: Task;
}

const Task: React.FC<TaskProps> = ({ task }) => {
  const [{ isDragging }, drag] = useDrag({
    type: 'TASK',
    item: { id: task.id },
    collect: (monitor) => ({
      isDragging: !!monitor.isDragging(),
    }),
  });

  return (
    <div
      ref={drag}
      className={`task ${isDragging ? 'task-dragging' : ''}`}
    >
      {task.title}
    </div>
  );
};

export default App;
```

