# Browser-Based Project Management App with Drag-and-Drop & Real-Time Collaboration

Here's a complete implementation using **TypeScript (frontend)** and **Node.js + Socket.io (backend)** for real-time collaboration.

## Backend (Node.js + Socket.io)

### `server.ts`
```typescript
import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  position: number;
}

interface BoardState {
  [key: string]: Task[];
}

let boardState: BoardState = {
  'todo': [],
  'in-progress': [],
  'done': []
};

io.on('connection', (socket) => {
  console.log('New client connected');

  // Send current board state to new client
  socket.emit('initial-state', boardState);

  // Handle task updates
  socket.on('update-task', (updatedTask: Task) => {
    const oldStatus = Object.keys(boardState).find(status =>
      boardState[status].some(task => task.id === updatedTask.id)
    );

    if (oldStatus) {
      // Remove from old status
      boardState[oldStatus] = boardState[oldStatus].filter(task => task.id !== updatedTask.id);
    }

    // Add to new status
    if (!boardState[updatedTask.status]) {
      boardState[updatedTask.status] = [];
    }
    boardState[updatedTask.status].push(updatedTask);

    // Broadcast to all clients
    io.emit('task-updated', updatedTask);
  });

  // Handle new tasks
  socket.on('add-task', (newTask: Task) => {
    if (!boardState[newTask.status]) {
      boardState[newTask.status] = [];
    }
    boardState[newTask.status].push(newTask);
    io.emit('task-added', newTask);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

## Frontend (React + TypeScript)

### `App.tsx`
```typescript
import React, { useState, useEffect } from 'react';
import { io, Socket } from 'socket.io-client';
import { DragDropContext, Droppable, Draggable, DropResult } from 'react-beautiful-dnd';
import './App.css';

interface Task {
  id: string;
  title: string;
  status: 'todo' | 'in-progress' | 'done';
  position: number;
}

interface BoardState {
  [key: string]: Task[];
}

const socket: Socket = io('http://localhost:4000');

const App: React.FC = () => {
  const [boardState, setBoardState] = useState<BoardState>({
    'todo': [],
    'in-progress': [],
    'done': []
  });
  const [newTaskTitle, setNewTaskTitle] = useState('');

  useEffect(() => {
    // Initialize with server state
    socket.on('initial-state', (initialState: BoardState) => {
      setBoardState(initialState);
    });

    // Update when tasks are modified
    socket.on('task-updated', (updatedTask: Task) => {
      setBoardState(prevState => {
        const newState = { ...prevState };
        // Remove from old status
        Object.keys(newState).forEach(status => {
          newState[status] = newState[status].filter(task => task.id !== updatedTask.id);
        });
        // Add to new status
        if (!newState[updatedTask.status]) {
          newState[updatedTask.status] = [];
        }
        newState[updatedTask.status].push(updatedTask);
        return newState;
      });
    });

    // Add new tasks
    socket.on('task-added', (newTask: Task) => {
      setBoardState(prevState => {
        const newState = { ...prevState };
        if (!newState[newTask.status]) {
          newState[newTask.status] = [];
        }
        newState[newTask.status].push(newTask);
        return newState;
      });
    });

    return () => {
      socket.off('initial-state');
      socket.off('task-updated');
      socket.off('task-added');
    };
  }, []);

  const handleDragEnd = (result: DropResult) => {
    if (!result.destination) return;

    const { source, destination } = result;
    const sourceStatus = source.droppableId;
    const destStatus = destination.droppableId;

    if (sourceStatus === destStatus && source.index === destination.index) return;

    const updatedTask = {
      ...boardState[sourceStatus][source.index],
      status: destStatus as 'todo' | 'in-progress' | 'done',
      position: destination.index
    };

    socket.emit('update-task', updatedTask);
  };

  const addTask = (status: 'todo' | 'in-progress' | 'done') => {
    if (!newTaskTitle.trim()) return;

    const newTask: Task = {
      id: Date.now().toString(),
      title: newTaskTitle,
      status,
      position: boardState[status].length
    };

    socket.emit('add-task', newTask);
    setNewTaskTitle('');
  };

  return (
    <div className="app">
      <h1>Project Management Board</h1>

      <div className="task-form">
        <input
          type="text"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="Enter task title"
        />
        <button onClick={() => addTask('todo')}>Add Task</button>
      </div>

      <DragDropContext onDragEnd={handleDragEnd}>
        <div className="board">
          {Object.keys(boardState).map((status) => (
            <Droppable key={status} droppableId={status}>
              {(provided) => (
                <div
                  className="column"
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                >
                  <h2>{status.replace('-', ' ')}</h2>
                  {boardState[status].map((task, index) => (
                    <Draggable key={task.id} draggableId={task.id} index={index}>
                      {(provided) => (
                        <div
                          className="task"
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                        >
                          {task.title}
                        </div>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default App;
```

