### 6. Board Component (with Drag-and-Drop)

```typescript
// src/components/Board.tsx
import React, { useState, useEffect } from 'react';
import { useDrop } from 'react-dnd';
import { collection, query, onSnapshot, doc, updateDoc, addDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { Box, Button, TextField, Typography, Paper } from '@mui/material';
import Column from './Column';

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  position: number;
}

interface ColumnData {
  id: string;
  title: string;
  tasks: Task[];
}

const Board: React.FC = () => {
  const [columns, setColumns] = useState<ColumnData[]>([
    { id: 'todo', title: 'To Do', tasks: [] },
    { id: 'in-progress', title: 'In Progress', tasks: [] },
    { id: 'done', title: 'Done', tasks: [] },
  ]);
  const [newTaskTitle, setNewTaskTitle] = useState('');

  useEffect(() => {
    const q = query(collection(db, 'tasks'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasks: Task[] = [];
      querySnapshot.forEach((doc) => {
        tasks.push({ id: doc.id, ...doc.data() } as Task);
      });

      const updatedColumns = columns.map(column => ({
        ...column,
        tasks: tasks.filter(task => task.status === column.id)
          .sort((a, b) => a.position - b.position)
      }));

      setColumns(updatedColumns);
    });

    return () => unsubscribe();
  }, []);

  const handleAddTask = async () => {
    if (!newTaskTitle.trim()) return;

    try {
      await addDoc(collection(db, 'tasks'), {
        title: newTaskTitle,
        description: '',
        status: 'todo',
        position: columns.find(c => c.id === 'todo')?.tasks.length || 0,
      });
      setNewTaskTitle('');
    } catch (error) {
      console.error('Error adding task: ', error);
    }
  };

  const moveTask = async (taskId: string, newStatus: string, newPosition: number) => {
    try {
      const taskRef = doc(db, 'tasks', taskId);
      await updateDoc(taskRef, {
        status: newStatus,
        position: newPosition,
      });
    } catch (error) {
      console.error('Error moving task: ', error);
    }
  };

  const [, drop] = useDrop(() => ({
    accept: 'task',
    drop: (item: { id: string; status: string }, monitor) => {
      const didDrop = monitor.didDrop();
      if (!didDrop) {
        // Task was dropped outside any column
        moveTask(item.id, item.status, columns.find(c => c.id === item.status)?.tasks.length || 0);
      }
    },
  }));

  return (
    <Box sx={{ p: 3, flexGrow: 1 }} ref={drop}>
      <Box sx={{ mb: 3, display: 'flex', gap: 2 }}>
        <TextField
          label="New Task"
          variant="outlined"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          sx={{ flexGrow: 1 }}
        />
        <Button variant="contained" onClick={handleAddTask}>
          Add Task
        </Button>
      </Box>

      <Box sx={{ display: 'flex', gap: 2, overflowX: 'auto', pb: 2 }}>
        {columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            moveTask={moveTask}
          />
        ))}
      </Box>
    </Box>
  );
};

export default Board;
```

