### 8. Task Card Component

```typescript
// src/components/TaskCard.tsx
import React, { useRef } from 'react';
import { useDrag, useDrop } from 'react-dnd';
import { Box, Typography, Paper } from '@mui/material';

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  position: number;
}

interface TaskCardProps {
  task: Task;
  index: number;
  moveTask: (taskId: string, newStatus: string, newPosition: number) => void;
  status: string;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, index, moveTask, status }) => {
  const ref = useRef<HTMLDivElement>(null);

  const [{ isDragging }, drag] = useDrag({
    type: 'task',
    item: { id: task.id, status: task.status },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  const [, drop] = useDrop({
    accept: 'task',
    hover(item: { id: string; status: string }, monitor) {
      if (!ref.current) return;

      const dragIndex = index;
      const hoverIndex = index;

      if (dragIndex === hoverIndex) return;

      const hoverBoundingRect = ref.current?.getBoundingClientRect();
      const hoverMiddleY = (hoverBoundingRect.bottom - hoverBoundingRect.top) / 2;
      const clientOffset = monitor.getClientOffset();
      const hoverClientY = clientOffset!.y - hoverBoundingRect.top;

      if (dragIndex < hoverIndex && hoverClientY < hoverMiddleY) return;
      if (dragIndex > hoverIndex && hoverClientY > hoverMiddleY) return;

      moveTask(item.id, status, hoverIndex);
      item.status = status;
    },
  });

  drag(drop(ref));

  return (
    <Paper
      ref={ref}
      elevation={isDragging ? 5 : 1}
      sx={{
        p: 2,
        cursor: 'move',
        opacity: isDragging ? 0.5 : 1,
        backgroundColor: '#ffffff',
      }}
    >
      <Typography variant="subtitle1" gutterBottom>
        {task.title}
      </Typography>
      {task.description && (
        <Typography variant="body2" color="text.secondary">
          {task.description}
        </Typography>
      )}
    </Paper>
  );
};

export default TaskCard;
```

