### **`src/App.tsx` (Main App)**
```tsx
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { io } from 'socket.io-client';
import { initializeApp } from 'firebase/app';
import { getFirestore, collection, doc, setDoc, onSnapshot } from 'firebase/firestore';

// Firebase Config
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

// Socket.io Connection
const socket = io('http://localhost:3001');

interface Task {
  id: string;
  content: string;
}

interface Column {
  id: string;
  title: string;
  tasks: Task[];
}

const App: React.FC = () => {
  const [columns, setColumns] = useState<Record<string, Column>>({});

  // Load initial data from Firebase
  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, 'boards'), (snapshot) => {
      const data = snapshot.docs[0]?.data();
      if (data) setColumns(data.columns);
    });
    return () => unsubscribe();
  }, []);

  // Handle drag-and-drop
  const onDragEnd = (result: any) => {
    if (!result.destination) return;

    const { source, destination } = result;
    const sourceColumn = columns[source.droppableId];
    const destColumn = columns[destination.droppableId];
    const task = sourceColumn.tasks[source.index];

    // Update locally
    const newColumns = { ...columns };
    newColumns[source.droppableId].tasks.splice(source.index, 1);
    newColumns[destination.droppableId].tasks.splice(destination.index, 0, task);

    setColumns(newColumns);

    // Sync with Firebase & Socket.io
    setDoc(doc(db, 'boards', 'default'), { columns: newColumns });
    socket.emit('update-board', newColumns);
  };

  // Listen for real-time updates
  useEffect(() => {
    socket.on('board-updated', (updatedColumns: Record<string, Column>) => {
      setColumns(updatedColumns);
    });
    return () => socket.off('board-updated');
  }, []);

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div style={{ display: 'flex', padding: '20px' }}>
        {Object.entries(columns).map(([columnId, column]) => (
          <Droppable key={columnId} droppableId={columnId}>
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                style={{
                  margin: '8px',
                  padding: '8px',
                  background: '#f0f0f0',
                  borderRadius: '4px',
                  minWidth: '250px',
                }}
              >
                <h3>{column.title}</h3>
                {column.tasks.map((task, index) => (
                  <Draggable key={task.id} draggableId={task.id} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        style={{
                          padding: '8px',
                          margin: '4px 0',
                          background: 'white',
                          borderRadius: '4px',
                          ...provided.draggableProps.style,
                        }}
                      >
                        {task.content}
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
};

export default App;
```

