import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import Board from './components/Board';
import UserList from './components/UserList';
import { useSocket } from './hooks/useSocket';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<string[]>([]);
  const socket = useSocket();

  useEffect(() => {
    // Fetch initial tasks from Firebase (or API)
    fetch('/api/tasks')
      .then((res) => res.json())
      .then((data) => setTasks(data));

    // Listen for real-time updates
    socket.on('taskUpdated', (updatedTask: Task) => {
      setTasks((prev) => prev.map((task) => (task.id === updatedTask.id ? updatedTask : task)));
    });

    socket.on('userJoined', (username: string) => {
      setUsers((prev) => [...prev, username]);
    });

    return () => {
      socket.off('taskUpdated');
      socket.off('userJoined');
    };
  }, [socket]);

  const handleTaskMove = (taskId: string, newColumn: string) => {
    const updatedTask = { ...tasks.find((t) => t.id === taskId), column: newColumn };
    socket.emit('updateTask', updatedTask);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management Board</h1>
        <UserList users={users} />
        <Board tasks={tasks} onTaskMove={handleTaskMove} />
      </div>
    </DndProvider>
  );
};

export default App;
```

