import express from 'express';
import { Task } from '../models/Task';

const router = express.Router();

let tasks: Task[] = [
  { id: '1', title: 'Task 1', description: 'First task', status: 'todo', position: 0, columnId: '1' },
  { id: '2', title: 'Task 2', description: 'Second task', status: 'in-progress', position: 0, columnId: '2' },
];

router.get('/', (req, res) => {
  res.json(tasks);
});

router.post('/', (req, res) => {
  const newTask: Task = {
    id: Date.now().toString(),
    ...req.body,
  };
  tasks.push(newTask);
  res.status(201).json(newTask);
});

router.put('/:id', (req, res) => {
  const index = tasks.findIndex(t => t.id === req.params.id);
  if (index !== -1) {
    tasks[index] = { ...tasks[index], ...req.body };
    res.json(tasks[index]);
  } else {
    res.status(404).json({ message: 'Task not found' });
  }
});

router.delete('/:id', (req, res) => {
  tasks = tasks.filter(t => t.id !== req.params.id);
  res.status(204).end();
});

export default router;
```

#### `server/src/sockets/taskHandler.ts`
```typescript
import { Server, Socket } from 'socket.io';
import { Task } from '../models/Task';

let tasks: Task[] = [
  { id: '1', title: 'Task 1', description: 'First task', status: 'todo', position: 0, columnId: '1' },
  { id: '2', title: 'Task 2', description: 'Second task', status: 'in-progress', position: 0, columnId: '2' },
];

export const setupTaskSocket = (io: Server) => {
  io.on('connection', (socket: Socket) => {
    console.log('New client connected');

    // Send initial tasks
    socket.emit('initial-tasks', tasks);

    // Handle task updates
    socket.on('update-task', (updatedTask: Task) => {
      const index = tasks.findIndex(t => t.id === updatedTask.id);
      if (index !== -1) {
        tasks[index] = updatedTask;
        io.emit('task-updated', updatedTask);
      }
    });

    // Handle new tasks
    socket.on('create-task', (newTask: Omit<Task, 'id'>) => {
      const task: Task = {
        id: Date.now().toString(),
        ...newTask,
      };
      tasks.push(task);
      io.emit('task-created', task);
    });

    // Handle task deletion
    socket.on('delete-task', (taskId: string) => {
      tasks = tasks.filter(t => t.id !== taskId);
      io.emit('task-deleted', taskId);
    });

    socket.on('disconnect', () => {
      console.log('Client disconnected');
    });
  });
};
```

