```typescript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { io, Socket } from 'socket.io-client';
import { Task } from '../../../server/src/models/Task';

interface SocketContextType {
  socket: Socket | null;
  tasks: Task[];
  updateTask: (task: Task) => void;
  createTask: (task: Omit<Task, 'id'>) => void;
  deleteTask: (taskId: string) => void;
}

const SocketContext = createContext<SocketContextType>({
  socket: null,
  tasks: [],
  updateTask: () => {},
  createTask: () => {},
  deleteTask: () => {},
});

export const SocketProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    const newSocket = io('http://localhost:3000');
    setSocket(newSocket);

    newSocket.on('initial-tasks', (initialTasks: Task[]) => {
      setTasks(initialTasks);
    });

    newSocket.on('task-updated', (updatedTask: Task) => {
      setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
    });

    newSocket.on('task-created', (newTask: Task) => {
      setTasks(prev => [...prev, newTask]);
    });

    newSocket.on('task-deleted', (taskId: string) => {
      setTasks(prev => prev.filter(t => t.id !== taskId));
    });

    return () => {
      newSocket.close();
    };
  }, []);

  const updateTask = (task: Task) => {
    if (socket) {
      socket.emit('update-task', task);
    }
  };

  const createTask = (task: Omit<Task, 'id'>) => {
    if (socket) {
      socket.emit('create-task', task);
    }
  };

  const deleteTask = (taskId: string) => {
    if (socket) {
      socket.emit('delete-task', taskId);
    }
  };

  return (
    <SocketContext.Provider value={{ socket, tasks, updateTask, createTask, deleteTask }}>
      {children}
    </SocketContext.Provider>
  );
};

export const useSocket = () => useContext(SocketContext);
```

