```typescript
import React, { useState } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { Column } from './Column';
import { TaskForm } from './TaskForm';
import { useSocket } from '../context/SocketContext';

const columns = [
  { id: 'todo', title: 'To Do' },
  { id: 'in-progress', title: 'In Progress' },
  { id: 'done', title: 'Done' },
];

export const Board: React.FC = () => {
  const { tasks, updateTask, createTask, deleteTask } = useSocket();
  const [showForm, setShowForm] = useState(false);

  const handleTaskDrop = (taskId: string, newColumnId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (task) {
      updateTask({ ...task, columnId: newColumnId });
    }
  };

  const handleDeleteTask = (taskId: string) => {
    deleteTask(taskId);
  };

  const handleCreateTask = (title: string, description: string) => {
    createTask({
      title,
      description,
      status: 'todo',
      position: 0,
      columnId: 'todo',
    });
    setShowForm(false);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="p-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Project Management Board</h1>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            Add Task
          </button>
        </div>

        {showForm && (
          <TaskForm
            onSubmit={handleCreateTask}
            onCancel={() => setShowForm(false)}
          />
        )}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {columns.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.columnId === column.id)}
              onTaskDrop={handleTaskDrop}
              onDeleteTask={handleDeleteTask}
            />
          ))}
        </div>
      </div>
    </DndProvider>
  );
};
```

