import express from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import { Task } from './types';

const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: 'http://localhost:3000',
    methods: ['GET', 'POST'],
  },
});

let tasks: Task[] = [
  { id: '1', title: 'Task 1', description: 'First task', columnId: 'todo' },
  { id: '2', title: 'Task 2', description: 'Second task', columnId: 'in-progress' },
];

io.on('connection', (socket: Socket) => {
  console.log('User connected:', socket.id);

  // Send initial tasks
  socket.on('getTasks', () => {
    socket.emit('tasksUpdated', tasks);
  });

  // Update tasks and broadcast to all clients
  socket.on('updateTasks', (updatedTasks: Task[]) => {
    tasks = updatedTasks;
    io.emit('tasksUpdated', tasks); // Broadcast to all clients
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

const PORT = 3001;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
