const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// In-memory task storage (replace with a real DB in production)
let tasks: Task[] = [
  { id: '1', title: 'Task 1', column: 'todo' },
  { id: '2', title: 'Task 2', column: 'in-progress' },
];

io.on('connection', (socket) => {
  console.log('User connected:', socket.id);

  // Send initial tasks
  socket.emit('initial-tasks', tasks);

  // Handle task updates
  socket.on('update-task', (updatedTask: Task) => {
    tasks = tasks.map(task => task.id === updatedTask.id ? updatedTask : task);
    io.emit('task-updated', updatedTask);
  });

  // Handle new tasks
  socket.on('add-task', (newTask: Task) => {
    tasks.push(newTask);
    io.emit('task-added', newTask);
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

server.listen(5000, () => {
  console.log('Server running on http://localhost:5000');
});
