```tsx
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { io, Socket } from 'socket.io-client';
import Board from './components/Board';
import { Task } from '../../server/src/types';

const socket: Socket = io('http://localhost:5000');

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    socket.on('initial-tasks', (initialTasks: Task[]) => {
      setTasks(initialTasks);
    });

    socket.on('task-updated', (updatedTask: Task) => {
      setTasks(prevTasks =>
        prevTasks.map(task => task.id === updatedTask.id ? updatedTask : task)
      );
    });

    socket.on('task-added', (newTask: Task) => {
      setTasks(prevTasks => [...prevTasks, newTask]);
    });

    return () => {
      socket.off('initial-tasks');
      socket.off('task-updated');
      socket.off('task-added');
    };
  }, []);

  const moveTask = (taskId: string, newColumn: 'todo' | 'in-progress' | 'done') => {
    const updatedTask = tasks.find(task => task.id === taskId);
    if (updatedTask) {
      updatedTask.column = newColumn;
      socket.emit('update-task', updatedTask);
    }
  };

  const addTask = (title: string) => {
    const newTask: Task = {
      id: Date.now().toString(),
      title,
      column: 'todo',
    };
    socket.emit('add-task', newTask);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management Board</h1>
        <Board tasks={tasks} moveTask={moveTask} addTask={addTask} />
      </div>
    </DndProvider>
  );
};

export default App;
```

