import React from 'react';
import { useDrop } from 'react-dnd';
import Task from './Task';
import TaskForm from './TaskForm';
import { Task as TaskType } from '../../../server/src/types';

interface ColumnProps {
  columnId: string;
  title: string;
  tasks: TaskType[];
  moveTask: (taskId: string, newColumn: 'todo' | 'in-progress' | 'done') => void;
  addTask: (title: string) => void;
}

const Column: React.FC<ColumnProps> = ({ columnId, title, tasks, moveTask, addTask }) => {
  const [{ isOver }, drop] = useDrop({
    accept: 'TASK',
    drop: (item: { id: string }) => moveTask(item.id, columnId as any),
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
    }),
  });

  return (
    <div ref={drop} className={`column ${isOver ? 'drag-over' : ''}`}>
      <h2>{title}</h2>
      {tasks.map(task => (
        <Task key={task.id} task={task} />
      ))}
      {columnId === 'todo' && <TaskForm addTask={addTask} />}
    </div>
  );
};

export default Column;
