### 4. Board Component (`src/components/Board.tsx`)

```typescript
import React, { useState, useEffect } from "react";
import { DragDropContext, Droppable, DropResult } from "react-beautiful-dnd";
import Column from "./Column";
import { db, collection, doc, setDoc, onSnapshot } from "../firebase";
import { Task, Column as ColumnType } from "../types";

const initialData = {
  tasks: {
    "task-1": { id: "task-1", content: "Take out the garbage", columnId: "column-1" },
    "task-2": { id: "task-2", content: "Watch my favorite show", columnId: "column-1" },
    "task-3": { id: "task-3", content: "Charge my phone", columnId: "column-2" },
    "task-4": { id: "task-4", content: "Cook dinner", columnId: "column-2" },
  },
  columns: {
    "column-1": {
      id: "column-1",
      title: "To do",
      taskIds: ["task-1", "task-2"],
    },
    "column-2": {
      id: "column-2",
      title: "In progress",
      taskIds: ["task-3", "task-4"],
    },
  },
  columnOrder: ["column-1", "column-2"],
};

const Board: React.FC = () => {
  const [state, setState] = useState<{
    tasks: Record<string, Task>;
    columns: Record<string, ColumnType>;
    columnOrder: string[];
  }>(initialData);

  useEffect(() => {
    // Initialize Firebase data
    const initFirebase = async () => {
      const boardRef = doc(db, "boards", "main-board");
      await setDoc(boardRef, initialData);
    };

    initFirebase();

    // Set up real-time listener
    const unsubscribe = onSnapshot(doc(db, "boards", "main-board"), (doc) => {
      if (doc.exists()) {
        setState(doc.data() as typeof initialData);
      }
    });

    return () => unsubscribe();
  }, []);

  const onDragEnd = async (result: DropResult) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === "column") {
      const newColumnOrder = Array.from(state.columnOrder);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      const newState = {
        ...state,
        columnOrder: newColumnOrder,
      };

      setState(newState);
      await setDoc(doc(db, "boards", "main-board"), newState);
      return;
    }

    const start = state.columns[source.droppableId];
    const finish = state.columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      const newState = {
        ...state,
        columns: {
          ...state.columns,
          [newColumn.id]: newColumn,
        },
      };

      setState(newState);
      await setDoc(doc(db, "boards", "main-board"), newState);
      return;
    }

    // Moving from one list to another
    const startTaskIds = Array.from(start.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStart = {
      ...start,
      taskIds: startTaskIds,
    };

    const finishTaskIds = Array.from(finish.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinish = {
      ...finish,
      taskIds: finishTaskIds,
    };

    const newState = {
      ...state,
      columns: {
        ...state.columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish,
      },
    };

    setState(newState);
    await setDoc(doc(db, "boards", "main-board"), newState);
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <Droppable droppableId="all-columns" direction="horizontal" type="column">
        {(provided) => (
          <div
            {...provided.droppableProps}
            ref={provided.innerRef}
            style={{
              display: "flex",
              padding: "20px",
              overflowX: "auto",
              height: "100vh",
            }}
          >
            {state.columnOrder.map((columnId, index) => {
              const column = state.columns[columnId];
              const tasks = column.taskIds.map((taskId) => state.tasks[taskId]);

              return (
                <Column
                  key={column.id}
                  column={column}
                  tasks={tasks}
                  index={index}
                />
              );
            })}
            {provided.placeholder}
          </div>
        )}
      </Droppable>
    </DragDropContext>
  );
};

export default Board;
```

