### 8. Custom Hook for Tasks (`src/hooks/useTasks.ts`)

```typescript
import { useState, useEffect } from 'react';
import { db } from '../firebase';
import {
  collection,
  query,
  onSnapshot,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  orderBy
} from 'firebase/firestore';

interface Task {
  id: string;
  content: string;
  columnId: string;
  order: number;
}

interface Column {
  id: string;
  title: string;
}

export const useTasks = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [columns] = useState<Column[]>([
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
  ]);

  // Load tasks from Firestore
  useEffect(() => {
    const q = query(collection(db, 'tasks'), orderBy('order'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const tasksData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as Task));
      setTasks(tasksData);
    });

    return () => unsubscribe();
  }, []);

  const addTask = async (columnId: string, content: string) => {
    const maxOrder = tasks.filter(t => t.columnId === columnId)
      .reduce((max, task) => Math.max(max, task.order), 0);

    await addDoc(collection(db, 'tasks'), {
      content,
      columnId,
      order: maxOrder + 1
    });
  };

  const updateTask = async (taskId: string, content: string) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, { content });
  };

  const deleteTask = async (taskId: string) => {
    const taskRef = doc(db, 'tasks', taskId);
    await deleteDoc(taskRef);
  };

  const moveTask = async (
    sourceColumnId: string,
    destColumnId: string,
    sourceIndex: number,
    destIndex: number
  ) => {
    // Get all tasks in the source and destination columns
    const sourceTasks = tasks.filter(t => t.columnId === sourceColumnId).sort((a, b) => a.order - b.order);
    const destTasks = tasks.filter(t => t.columnId === destColumnId).sort((a, b) => a.order - b.order);

    // Remove from source
    const [movedTask] = sourceTasks.splice(sourceIndex, 1);

    // Insert into destination
    destTasks.splice(destIndex, 0, movedTask);

    // Update columnId and order for all affected tasks
    const batch = [];

    // Update source column tasks
    sourceTasks.forEach((task, index) => {
      batch.push(updateDoc(doc(db, 'tasks', task.id), {
        order: index,
        columnId: sourceColumnId
      }));
    });

    // Update destination column tasks
    destTasks.forEach((task, index) => {
      batch.push(updateDoc(doc(db, 'tasks', task.id), {
        order: index,
        columnId: destColumnId
      }));
    });

    // Update moved task
    batch.push(updateDoc(doc(db, 'tasks', movedTask.id), {
      order: destIndex,
      columnId: destColumnId
    }));

    await Promise.all(batch);
  };

  return { columns, tasks, addTask, updateTask, deleteTask, moveTask };
};
```

