### **1. Core Trading Engine (C++) – Low-Latency Order Matching**
```cpp
#include <iostream>
#include <unordered_map>
#include <queue>
#include <chrono>
#include <thread>
#include <mutex>

struct Order {
    uint64_t orderId;
    double price;
    int quantity;
    bool isBuy;
    std::chrono::high_resolution_clock::time_point timestamp;
};

class OrderBook {
private:
    std::priority_queue<Order, std::vector<Order>, std::function<bool(Order, Order)>> buyOrders;
    std::priority_queue<Order, std::vector<Order>, std::function<bool(Order, Order)>> sellOrders;
    std::mutex mtx;

public:
    OrderBook() {
        // Buy orders sorted by highest price first
        buyOrders = std::priority_queue<Order, std::vector<Order>, std::function<bool(Order, Order)>>(
            [](const Order& a, const Order& b) { return a.price < b.price; }
        );
        // Sell orders sorted by lowest price first
        sellOrders = std::priority_queue<Order, std::vector<Order>, std::function<bool(Order, Order)>>(
            [](const Order& a, const Order& b) { return a.price > b.price; }
        );
    }

    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order.isBuy) {
            buyOrders.push(order);
        } else {
            sellOrders.push(order);
        }
        matchOrders();
    }

    void matchOrders() {
        while (!buyOrders.empty() && !sellOrders.empty()) {
            Order bestBuy = buyOrders.top();
            Order bestSell = sellOrders.top();

            if (bestBuy.price >= bestSell.price) {
                int matchedQty = std::min(bestBuy.quantity, bestSell.quantity);
                std::cout << "Matched: Buy " << bestBuy.orderId << " @ " << bestBuy.price
                          << " with Sell " << bestSell.orderId << " @ " << bestSell.price
                          << " (Qty: " << matchedQty << ")\n";

                bestBuy.quantity -= matchedQty;
                bestSell.quantity -= matchedQty;

                if (bestBuy.quantity == 0) buyOrders.pop();
                if (bestSell.quantity == 0) sellOrders.pop();
            } else {
                break; // No more matches possible
            }
        }
    }
};

int main() {
    OrderBook book;

    // Simulate incoming orders
    book.addOrder({1, 100.5, 10, true, std::chrono::high_resolution_clock::now()});
