### **Code Example: Order Matching Engine**
```rust
use std::collections::BinaryHeap;
use std::sync::{Arc, Mutex};
use std::time::Instant;

// Define Order types
#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
enum OrderType {
    Buy,
    Sell,
}

#[derive(Debug)]
struct Order {
    id: u64,
    price: f64,
    quantity: u64,
    order_type: OrderType,
    timestamp: Instant,
}

// Order book (price-time priority)
struct OrderBook {
    buy_orders: BinaryHeap<Order>,
    sell_orders: BinaryHeap<Order>,
}

impl OrderBook {
    fn new() -> Self {
        OrderBook {
            buy_orders: BinaryHeap::new(),
            sell_orders: BinaryHeap::new(),
        }
    }

    fn add_order(&mut self, order: Order) {
        match order.order_type {
            OrderType::Buy => self.buy_orders.push(order),
            OrderType::Sell => self.sell_orders.push(order),
        }
    }

    fn match_orders(&mut self) -> Vec<(Order, Order)> {
        let mut matches = Vec::new();
        while let (Some(best_buy), Some(best_sell)) = (self.buy_orders.peek(), self.sell_orders.peek()) {
            if best_buy.price >= best_sell.price {
                let buy_order = self.buy_orders.pop().unwrap();
                let sell_order = self.sell_orders.pop().unwrap();
                matches.push((buy_order, sell_order));
            } else {
                break;
            }
        }
        matches
    }
}

// Example usage
fn main() {
    let mut order_book = OrderBook::new();

    order_book.add_order(Order {
        id: 1,
        price: 100.0,
        quantity: 10,
        order_type: OrderType::Buy,
        timestamp: Instant::now(),
    });

    order_book.add_order(Order {
        id: 2,
        price: 99.0,
        quantity: 5,
        order_type: OrderType::Sell,
        timestamp: Instant::now(),
    });

    let matches = order_book.match_orders();
    println!("Matches: {:?}", matches);
}
```

