### **3.1 Order Book (Using `DashMap` for Concurrent Access)**
```rust
use dashmap::DashMap;
use std::sync::Arc;
use std::time::SystemTime;

#[derive(Debug, Clone)]
struct Order {
    id: u64,
    price: f64,
    quantity: u64,
    is_buy: bool,
    timestamp: SystemTime,
}

struct OrderBook {
    bids: Arc<DashMap<f64, Vec<Order>>>,  // price -> orders
    asks: Arc<DashMap<f64, Vec<Order>>>,  // price -> orders
}

impl OrderBook {
    pub fn new() -> Self {
        OrderBook {
            bids: Arc::new(DashMap::new()),
            asks: Arc::new(DashMap::new()),
        }
    }

    pub fn add_order(&self, order: Order) {
        if order.is_buy {
            self.bids.entry(order.price).or_default().push(order);
        } else {
            self.asks.entry(order.price).or_default().push(order);
        }
    }

    pub fn match_orders(&self) -> bool {
        let best_bid = self.bids.iter().next_back();
        let best_ask = self.asks.iter().next();

        if let (Some(bid), Some(ask)) = (best_bid, best_ask) {
            if bid.key() >= ask.key() {
                // Execute trade
                let mut buy_orders = bid.value().clone();
                let mut sell_orders = ask.value().clone();

                let matched_qty = buy_orders[0].quantity.min(sell_orders[0].quantity);
                buy_orders[0].quantity -= matched_qty;
                sell_orders[0].quantity -= matched_qty;

                if buy_orders[0].quantity == 0 {
                    self.bids.remove(bid.key());
                }
                if sell_orders[0].quantity == 0 {
                    self.asks.remove(ask.key());
                }

                return true;
            }
        }
        false
    }
}
