```go
package main

import (
	"fmt"
	"sync"
	"time"
)

type OrderType int

const (
	BUY OrderType = iota
	SELL
)

type Order struct {
	OrderID   int
	Type      OrderType
	Price     float64
	Quantity  int
	Timestamp time.Time
}

type OrderBook struct {
	mu         sync.Mutex
	BuyOrders  map[float64][]Order
	SellOrders map[float64][]Order
}

func NewOrderBook() *OrderBook {
	return &OrderBook{
		BuyOrders:  make(map[float64][]Order),
		SellOrders: make(map[float64][]Order),
	}
}

func (ob *OrderBook) AddOrder(order Order) {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	if order.Type == BUY {
		ob.BuyOrders[order.Price] = append(ob.BuyOrders[order.Price], order)
	} else {
		ob.SellOrders[order.Price] = append(ob.SellOrders[order.Price], order)
	}
}

func (ob *OrderBook) MatchOrders() {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	for buyPrice, buyOrders := range ob.BuyOrders {
		for sellPrice, sellOrders := range ob.SellOrders {
			if buyPrice >= sellPrice {
				fmt.Printf("Trade executed: BUY %.2f SELL %.2f\n", buyPrice, sellPrice)
				ob.BuyOrders[buyPrice] = buyOrders[1:] // Remove matched order
				ob.SellOrders[sellPrice] = sellOrders[1:]
				return
			}
		}
	}
}

func tradingLoop(book *OrderBook) {
	for {
		order := Order{
			OrderID:   1,
			Type:      BUY,
			Price:     100.5,
			Quantity:  10,
			Timestamp: time.Now(),
		}
		book.AddOrder(order)
		book.MatchOrders()
		time.Sleep(10 * time.Millisecond)
	}
}

func main() {
