### **1. Low-Latency Order Matching Engine (C++)**
```cpp
#include <iostream>
#include <unordered_map>
#include <queue>
#include <chrono>
#include <mutex>
#include <atomic>

enum class OrderType { BUY, SELL };
enum class OrderStatus { PENDING, FILLED, CANCELLED };

struct Order {
    uint64_t id;
    OrderType type;
    double price;
    uint64_t quantity;
    OrderStatus status;
    std::chrono::system_clock::time_point timestamp;
};

class OrderBook {
private:
    std::priority_queue<Order*, std::vector<Order*>, decltype([](Order* a, Order* b) {
        return a->price > b->price; // Max-heap for BUY orders
    })> buy_orders;

    std::priority_queue<Order*, std::vector<Order*>, decltype([](Order* a, Order* b) {
        return a->price < b->price; // Min-heap for SELL orders
    })> sell_orders;

    std::unordered_map<uint64_t, Order*> orders;
    std::mutex mtx;

public:
    void addOrder(Order* order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order->type == OrderType::BUY) {
            buy_orders.push(order);
        } else {
            sell_orders.push(order);
        }
        orders[order->id] = order;
    }

    bool matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        while (!buy_orders.empty() && !sell_orders.empty()) {
            Order* buy = buy_orders.top();
            Order* sell = sell_orders.top();

            if (buy->price >= sell->price) {
                uint64_t matched_qty = std::min(buy->quantity, sell->quantity);
                buy->quantity -= matched_qty;
                sell->quantity -= matched_qty;

                if (buy->quantity == 0) {
                    buy->status = OrderStatus::FILLED;
                    buy_orders.pop();
                }
                if (sell->quantity == 0) {
                    sell->status = OrderStatus::FILLED;
                    sell_orders.pop();
                }
                return true;
            } else {
                break; // No more matches possible
            }
        }
        return false;
    }

    Order* getOrder(uint64_t id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = orders.find(id);
        return (it != orders.end()) ? it->second : nullptr;
    }
};

int main() {
    OrderBook book;
    Order buy1{1, OrderType::BUY, 100.0, 10, OrderStatus::PENDING, std::chrono::system_clock::now()};
    Order sell1{2, OrderType::SELL, 99.0, 5, OrderStatus::PENDING, std::chrono::system_clock::now()};

    book.addOrder(&buy1);
    book.addOrder(&sell1);
    book.matchOrders();

    std::cout << "Buy Order Status: " << (buy1.status == OrderStatus::FILLED ? "FILLED" : "PENDING") << std::endl;
    std::cout << "Sell Order Status: " << (sell1.status == OrderStatus::FILLED ? "FILLED" : "PENDING") << std::endl;

    return 0;
}
```

