### **2. REST API Server (Go)**
```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"
)

type Order struct {
	ID        uint64  `json:"id"`
	Type      string   `json:"type"` // "BUY" or "SELL"
	Price     float64 `json:"price"`
	Quantity  uint64  `json:"quantity"`
	Status    string  `json:"status"` // "PENDING", "FILLED", "CANCELLED"
	Timestamp string  `json:"timestamp"`
}

var (
	orders     = make(map[uint64]Order)
	ordersLock sync.Mutex
	nextID     uint64 = 1
)

func main() {
	http.HandleFunc("/orders", handleOrders)
	http.HandleFunc("/orders/", handleOrderByID)
	log.Println("Starting REST API server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func handleOrders(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		getAllOrders(w, r)
	case "POST":
		createOrder(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func getAllOrders(w http.ResponseWriter, r *http.Request) {
	ordersLock.Lock()
	defer ordersLock.Unlock()

	orderList := make([]Order, 0, len(orders))
	for _, order := range orders {
		orderList = append(orderList, order)
	}

	json.NewEncoder(w).Encode(orderList)
}

func createOrder(w http.ResponseWriter, r *http.Request) {
	var order Order
	if err := json.NewDecoder(r.Body).Decode(&order); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	ordersLock.Lock()
	defer ordersLock.Unlock()

	order.ID = nextID
	nextID++
	order.Status = "PENDING"
	orders[order.ID] = order

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(order)
}

func handleOrderByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/orders/"):]
	if id == "" {
		http.Error(w, "Order ID required", http.StatusBadRequest)
		return
	}

	ordersLock.Lock()
	defer ordersLock.Unlock()

	order, exists := orders[id]
	if !exists {
		http.Error(w, "Order not found", http.StatusNotFound)
		return
	}

	json.NewEncoder(w).Encode(order)
}
```

