type PersistentDB struct {
	filename string
	data     map[string]string
}

func NewPersistentDB(filename string) *PersistentDB {
	db := &PersistentDB{
		filename: filename,
		data:     make(map[string]string),
	}
	db.load()
	return db
}

func (db *PersistentDB) Set(key, value string) {
	db.data[key] = value
	db.save()
}

func (db *PersistentDB) Get(key string) string {
	return db.data[key]
}

func (db *PersistentDB) load() {
	file, err := os.ReadFile(db.filename)
	if err != nil {
		if !os.IsNotExist(err) {
			log.Println("Error loading DB:", err)
		}
		return
	}
	json.Unmarshal(file, &db.data)
}

func (db *PersistentDB) save() {
	data, _ := json.Marshal(db.data)
	os.WriteFile(db.filename, data, 0644)
}
