## **2. Core Trading Engine (C++)**
### **File: `trading_engine.cpp`**
```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>

using namespace std;

enum OrderType { BUY, SELL };
enum OrderStatus { PENDING, FILLED, CANCELLED };

struct Order {
    string id;
    OrderType type;
    double price;
    int quantity;
    OrderStatus status;
    chrono::time_point<chrono::high_resolution_clock> timestamp;
};

class OrderBook {
private:
    unordered_map<double, vector<Order>> buy_orders;
    unordered_map<double, vector<Order>> sell_orders;
    mutex mtx;

public:
    void addOrder(Order order) {
        lock_guard<mutex> lock(mtx);
        if (order.type == BUY) {
            buy_orders[order.price].push_back(order);
        } else {
            sell_orders[order.price].push_back(order);
        }
    }

    vector<Order> matchOrders() {
        lock_guard<mutex> lock(mtx);
        vector<Order> matched_orders;

        for (auto& [buy_price, buy_orders_list] : buy_orders) {
            for (auto& [sell_price, sell_orders_list] : sell_orders) {
                if (buy_price >= sell_price) {
                    for (auto& buy_order : buy_orders_list) {
                        for (auto& sell_order : sell_orders_list) {
                            if (buy_order.quantity > 0 && sell_order.quantity > 0) {
                                int matched_qty = min(buy_order.quantity, sell_order.quantity);
                                buy_order.quantity -= matched_qty;
                                sell_order.quantity -= matched_qty;
                                matched_orders.push_back(buy_order);
                                matched_orders.push_back(sell_order);
                            }
                        }
                    }
                }
            }
        }
        return matched_orders;
    }
};

int main() {
    OrderBook order_book;
    Order buy_order{"1", BUY, 100.5, 10, PENDING, chrono::high_resolution_clock::now()};
    Order sell_order{"2", SELL, 100.0, 5, PENDING, chrono::high_resolution_clock::now()};

    order_book.addOrder(buy_order);
    order_book.addOrder(sell_order);

    auto matched_orders = order_book.matchOrders();
    for (const auto& order : matched_orders) {
        cout << "Matched Order: " << order.id << " (Type: " << (order.type == BUY ? "BUY" : "SELL") << ")\n";
    }

    return 0;
}
```
**Key Optimizations:**
- **Lock-free data structures** (if needed for ultra-high throughput)
- **Memory pooling** (to reduce allocations)
- **SIMD optimizations** (if matching large order books)

