use tokio::net::{TcpListener, UdpSocket};
use tokio::sync::mpsc;
use serde::{Deserialize, Serialize};
use flatbuffers::FlatBufferBuilder;

// Define Order Message (FlatBuffers for zero-copy serialization)
#[derive(Serialize, Deserialize)]
struct Order {
    order_id: u64,
    symbol: String,
    side: String, // "buy" or "sell"
    price: f64,
    quantity: f64,
    timestamp: u64,
}

// Async TCP/UDP Server for Order Ingestion
#[tokio::main]
async fn main() {
    let (tx, mut rx) = mpsc::channel(1000); // Buffered channel for orders

    // Start TCP/UDP listener
    let listener = TcpListener::bind("0.0.0.0:5000").await.unwrap();
    println!("Order Gateway running on 0.0.0.0:5000");

    // Spawn order processing task
    tokio::spawn(async move {
        while let Some(order) = rx.recv().await {
            println!("Received order: {:?}", order);
            // Forward to Matching Engine (via channel or gRPC)
        }
    });

    // Accept incoming connections
    loop {
        let (socket, _) = listener.accept().await.unwrap();
        let tx = tx.clone();

        tokio::spawn(async move {
            let mut buf = [0; 1024];
            loop {
                let n = socket.read(&mut buf).await.unwrap();
                if n == 0 {
                    break; // Connection closed
                }

                // Deserialize order (FlatBuffers for zero-copy)
                let order: Order = serde_json::from_slice(&buf[..n]).unwrap();
                tx.send(order).await.unwrap();
            }
        });
    }
}
```

