### **2.2. Matching Engine (Optimized for Speed)**
```rust
use std::collections::BTreeMap;

// Order Book Structure (Bid/Ask Sides)
struct OrderBook {
    bids: BTreeMap<f64, Vec<Order>>, // Price → Orders (sorted descending)
    asks: BTreeMap<f64, Vec<Order>>, // Price → Orders (sorted ascending)
}

impl OrderBook {
    pub fn new() -> Self {
        OrderBook {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    // Match orders (simplified for example)
    pub fn match_orders(&mut self, order: Order) {
        if order.side == "buy" {
            // Match against asks (lowest price first)
            for (price, asks) in self.asks.iter_mut() {
                if *price <= order.price {
                    // Execute trade
                    println!("Matched buy order {} at {}", order.order_id, price);
                    // Remove filled orders
                    asks.retain(|o| o.quantity > 0.0);
                    if asks.is_empty() {
                        self.asks.remove(price);
                    }
                    break;
                }
            }
        } else {
            // Match against bids (highest price first)
            for (price, bids) in self.bids.iter_mut() {
                if *price >= order.price {
                    // Execute trade
                    println!("Matched sell order {} at {}", order.order_id, price);
                    // Remove filled orders
                    bids.retain(|o| o.quantity > 0.0);
                    if bids.is_empty() {
                        self.bids.remove(price);
                    }
                    break;
                }
            }
        }
    }
}
```

