### **Initial Implementation (`oms/main.go`)**
```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
)

// Order structure
type Order struct {
	ID       uint64  `json:"id"`
	Type     string  `json:"type"` // "BUY" or "SELL"
	Price    float64 `json:"price"`
	Quantity uint32  `json:"quantity"`
	Status   string  `json:"status"` // "PENDING", "FILLED", "CANCELLED"
}

// In-memory order store (replace with Redis/PostgreSQL in production)
type OrderStore struct {
	mu     sync.Mutex
	orders map[uint64]Order
}

func NewOrderStore() *OrderStore {
	return &OrderStore{
		orders: make(map[uint64]Order),
	}
}

func (s *OrderStore) AddOrder(order Order) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.orders[order.ID] = order
}

func (s *OrderStore) GetOrder(id uint64) (Order, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	order, exists := s.orders[id]
	return order, exists
}

// HTTP handlers
func (s *OrderStore) handleSubmitOrder(w http.ResponseWriter, r *http.Request) {
	var order Order
	if err := json.NewDecoder(r.Body).Decode(&order); err != nil {
		http.Error(w, "Invalid order data", http.StatusBadRequest)
		return
	}

	s.AddOrder(order)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(order)
}

func (s *OrderStore) handleGetOrder(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "Missing order ID", http.StatusBadRequest)
		return
	}

	order, exists := s.GetOrder(uint64(id))
	if !exists {
		http.Error(w, "Order not found", http.StatusNotFound)
		return
	}

	json.NewEncoder(w).Encode(order)
}

func main() {
	store := NewOrderStore()

	http.HandleFunc("/submit", store.handleSubmitOrder)
	http.HandleFunc("/order", store.handleGetOrder)

	fmt.Println("OMS running on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

