### **Minimal Low-Latency Trading Platform (C++)**
```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <queue>
#include <mutex>
#include <thread>
#include <atomic>
#include <chrono>

// Order Types
enum class OrderType { BUY, SELL };
enum class OrderStatus { PENDING, FILLED, PARTIALLY_FILLED, CANCELLED };

// Order Structure
struct Order {
    uint64_t id;
    OrderType type;
    double price;
    uint32_t quantity;
    OrderStatus status;
    std::chrono::high_resolution_clock::time_point timestamp;

    Order(uint64_t id, OrderType type, double price, uint32_t quantity)
        : id(id), type(type), price(price), quantity(quantity), status(OrderStatus::PENDING),
          timestamp(std::chrono::high_resolution_clock::now()) {}
};

// Order Book (Limit Order Book)
class OrderBook {
private:
    std::priority_queue<std::pair<double, Order*>> buy_orders;  // Max-heap (highest price first)
    std::priority_queue<std::pair<double, Order*>,
                        std::vector<std::pair<double, Order*>>,
                        std::greater<std::pair<double, Order*>>> sell_orders;  // Min-heap (lowest price first)
    std::mutex mtx;

public:
    void addOrder(Order* order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order->type == OrderType::BUY) {
            buy_orders.push({order->price, order});
        } else {
            sell_orders.push({order->price, order});
        }
    }

    void matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        while (!buy_orders.empty() && !sell_orders.empty()) {
            auto best_buy = buy_orders.top();
            auto best_sell = sell_orders.top();

            if (best_buy.first >= best_sell.first) {  // Match condition
                uint32_t matched_qty = std::min(best_buy.second->quantity, best_sell.second->quantity);

                // Update order statuses
                best_buy.second->quantity -= matched_qty;
                best_sell.second->quantity -= matched_qty;

                if (best_buy.second->quantity == 0) {
                    best_buy.second->status = OrderStatus::FILLED;
                    buy_orders.pop();
                } else {
                    best_buy.second->status = OrderStatus::PARTIALLY_FILLED;
                }

                if (best_sell.second->quantity == 0) {
                    best_sell.second->status = OrderStatus::FILLED;
                    sell_orders.pop();
                } else {
                    best_sell.second->status = OrderStatus::PARTIALLY_FILLED;
                }

                std::cout << "Matched: Buy " << best_buy.first << " vs Sell " << best_sell.first
                          << " (Qty: " << matched_qty << ")\n";
            } else {
                break;  // No more matches possible
            }
        }
    }
};

// Simulate a trading engine
int main() {
    OrderBook book;
    std::atomic<uint64_t> order_id{0};

    // Simulate incoming orders (in a real system, this would come from a network)
    std::thread order_generator([&]() {
        while (true) {
            OrderType type = (rand() % 2) ? OrderType::BUY : OrderType::SELL;
            double price = 100.0 + (rand() % 20);  // Random price between 100-120
            uint32_t quantity = 1 + (rand() % 10);  // Random quantity 1-10

            Order* order = new Order(++order_id, type, price, quantity);
            book.addOrder(order);

            std::this_thread::sleep_for(std::chrono::milliseconds(100));  // Simulate latency
        }
    });

    // Matching engine thread
    std::thread matcher([&]() {
        while (true) {
            book.matchOrders();
            std::this_thread::sleep_for(std::chrono::milliseconds(50));  // Matching interval
        }
    });

    order_generator.join();
    matcher.join();

    return 0;
}
```

