#pragma once
#include <unordered_map>
#include <queue>
#include <mutex>
#include <atomic>

enum class OrderType { BUY, SELL };
enum class OrderStatus { PENDING, FILLED, PARTIAL, CANCELLED };

struct Order {
    uint64_t id;
    OrderType type;
    double price;
    uint64_t quantity;
    OrderStatus status;
    std::chrono::high_resolution_clock::time_point timestamp;
};

class OrderBook {
private:
    std::unordered_map<double, std::queue<Order>> buyOrders;  // Price → Orders (FIFO)
    std::unordered_map<double, std::queue<Order>> sellOrders;
    std::mutex mtx;

public:
    void addOrder(const Order& order);
    void matchOrders();
    void cancelOrder(uint64_t orderId);
};
```

#### **1.2 Order Book Implementation (`OrderBook.cpp`)**
```cpp
#include "OrderBook.h"
#include <algorithm>

void OrderBook::addOrder(const Order& order) {
    std::lock_guard<std::mutex> lock(mtx);
    if (order.type == OrderType::BUY) {
        buyOrders[order.price].push(order);
    } else {
        sellOrders[order.price].push(order);
    }
}

void OrderBook::matchOrders() {
    std::lock_guard<std::mutex> lock(mtx);
    auto bestBuy = buyOrders.rbegin();
    auto bestSell = sellOrders.begin();

    while (bestBuy != buyOrders.rend() && bestSell != sellOrders.end()) {
        if (bestBuy->first >= bestSell->first) {
            // Match orders
            auto& buyOrder = bestBuy->second.front();
            auto& sellOrder = bestSell->second.front();

            uint64_t matchedQty = std::min(buyOrder.quantity, sellOrder.quantity);
            buyOrder.quantity -= matchedQty;
            sellOrder.quantity -= matchedQty;

            if (buyOrder.quantity == 0) bestBuy->second.pop();
            if (sellOrder.quantity == 0) bestSell->second.pop();

            if (bestBuy->second.empty()) buyOrders.erase(bestBuy->first);
            if (bestSell->second.empty()) sellOrders.erase(bestSell->first);

            // Log match (in a real system, this would be async)
            std::cout << "Matched: " << matchedQty << " @ " << bestBuy->first << std::endl;
        } else {
            break;
        }
    }
}

void OrderBook::cancelOrder(uint64_t orderId) {
    std::lock_guard<std::mutex> lock(mtx);
    // Implementation omitted for brevity
}
