#### **2.2 TCP Server Implementation (`Server.cpp`)**
```cpp
#include "Server.h"
#include <iostream>

TradingServer::TradingServer(short port)
    : acceptor(ioContext, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port)) {}

void TradingServer::handleConnection(boost::asio::ip::tcp::socket socket) {
    try {
        boost::asio::streambuf buffer;
        boost::asio::read_until(socket, buffer, '\n');

        std::istream is(&buffer);
        std::string orderStr;
        std::getline(is, orderStr);

        // Parse order (simplified for demo)
        Order order;
        order.id = 1;  // Increment in real system
        order.type = OrderType::BUY;
        order.price = 100.0;
        order.quantity = 10;
        order.timestamp = std::chrono::high_resolution_clock::now();

        orderBook.addOrder(order);
        orderBook.matchOrders();

        boost::asio::write(socket, boost::asio::buffer("ACK\n"));
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}

void TradingServer::run() {
    while (true) {
        boost::asio::ip::tcp::socket socket(ioContext);
        acceptor.accept(socket);
        handleConnection(std::move(socket));
    }
}
