```cpp
#include <iostream>
#include <map>
#include <vector>
#include <mutex>
#include <memory>

enum class OrderType { BUY, SELL };
enum class OrderStatus { PENDING, FILLED, PARTIAL, CANCELLED };

struct Order {
    uint64_t id;
    OrderType type;
    double price;
    uint32_t quantity;
    OrderStatus status;
};

class OrderBook {
private:
    std::map<double, std::vector<Order>> buy_orders;  // Sorted by price (highest first)
    std::map<double, std::vector<Order>> sell_orders; // Sorted by price (lowest first)
    std::mutex mtx;

public:
    void add_order(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order.type == OrderType::BUY) {
            buy_orders[order.price].push_back(order);
        } else {
            sell_orders[order.price].push_back(order);
        }
        match_orders();
    }

    void match_orders() {
        while (!buy_orders.empty() && !sell_orders.empty()) {
            auto highest_buy = buy_orders.rbegin();
            auto lowest_sell = sell_orders.begin();

            if (highest_buy->first >= lowest_sell->first) {
                // Match found
                auto& buy_order = highest_buy->second.back();
                auto& sell_order = lowest_sell->second.back();

                uint32_t matched_qty = std::min(buy_order.quantity, sell_order.quantity);
                std::cout << "Matched: " << matched_qty << " @ " << highest_buy->first << std::endl;

                buy_order.quantity -= matched_qty;
                sell_order.quantity -= matched_qty;

                if (buy_order.quantity == 0) highest_buy->second.pop_back();
                if (sell_order.quantity == 0) lowest_sell->second.pop_back();

                if (highest_buy->second.empty()) buy_orders.erase(highest_buy->first);
                if (lowest_sell->second.empty()) sell_orders.erase(lowest_sell->first);
            } else {
                break; // No more matches
            }
        }
    }
};
```

