#### **1.2 TCP Server (Order Submission)**
```cpp
#include <boost/asio.hpp>
#include <thread>

using boost::asio::ip::tcp;

class TradingServer {
private:
    tcp::acceptor acceptor_;
    OrderBook& order_book_;

    void handle_connection(tcp::socket socket) {
        try {
            boost::asio::streambuf buffer;
            boost::asio::read_until(socket, buffer, "\n");

            std::istream is(&buffer);
            std::string line;
            std::getline(is, line);

            // Parse order (simplified: "BUY 100 10.5" or "SELL 50 10.2")
            std::istringstream iss(line);
            std::string type_str;
            double price;
            uint32_t quantity;

            iss >> type_str >> quantity >> price;

            OrderType type = (type_str == "BUY") ? OrderType::BUY : OrderType::SELL;
            Order order{static_cast<uint64_t>(std::rand()), type, price, quantity, OrderStatus::PENDING};

            order_book_.add_order(order);
        } catch (std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }

public:
    TradingServer(boost::asio::io_context& io_context, short port, OrderBook& order_book)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)), order_book_(order_book) {
        start_accept();
    }

    void start_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::thread(&TradingServer::handle_connection, this, std::move(socket)).detach();
                }
                start_accept();
            });
    }
};
```

