```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <atomic>
#include <memory>

// Order Types
enum class OrderType { BUY, SELL };
enum class OrderStatus { PENDING, FILLED, CANCELLED };

// Order Structure
struct Order {
    uint64_t id;
    OrderType type;
    double price;
    uint32_t quantity;
    OrderStatus status;
    std::chrono::high_resolution_clock::time_point timestamp;

    Order(uint64_t id, OrderType type, double price, uint32_t quantity)
        : id(id), type(type), price(price), quantity(quantity), status(OrderStatus::PENDING) {
        timestamp = std::chrono::high_resolution_clock::now();
    }
};

// Order Book (Thread-Safe)
class OrderBook {
private:
    std::unordered_map<double, std::vector<Order>> bids;  // Price -> Orders
    std::unordered_map<double, std::vector<Order>> asks;  // Price -> Orders
    std::mutex mtx;
    std::atomic<uint64_t> nextOrderId{1};

public:
    // Add an order (thread-safe)
    void addOrder(OrderType type, double price, uint32_t quantity) {
        std::lock_guard<std::mutex> lock(mtx);
        Order order(nextOrderId++, type, price, quantity);

        if (type == OrderType::BUY) {
            bids[price].push_back(order);
        } else {
            asks[price].push_back(order);
        }
    }

    // Match orders (simplified)
    void matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& [bidPrice, bidOrders] : bids) {
            for (auto& [askPrice, askOrders] : asks) {
                if (bidPrice >= askPrice) {
                    // Match logic (simplified)
                    for (auto& bid : bidOrders) {
                        for (auto& ask : askOrders) {
                            if (bid.quantity > 0 && ask.quantity > 0) {
                                uint32_t tradeQty = std::min(bid.quantity, ask.quantity);
                                bid.quantity -= tradeQty;
                                ask.quantity -= tradeQty;
                                std::cout << "Trade: " << tradeQty << " @ " << askPrice << std::endl;
                            }
                        }
                    }
                }
            }
        }
    }

    // Print order book (for debugging)
    void printBook() {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << "=== BIDS ===" << std::endl;
        for (const auto& [price, orders] : bids) {
            std::cout << price << ": " << orders.size() << " orders" << std::endl;
        }
        std::cout << "=== ASKS ===" << std::endl;
        for (const auto& [price, orders] : asks) {
            std::cout << price << ": " << orders.size() << " orders" << std::endl;
        }
    }
};

// Simulated Network Layer (UDP/TCP)
class NetworkLayer {
public:
    void sendOrder(const Order& order) {
        // Simulate network latency (1-10 microseconds)
        std::this_thread::sleep_for(std::chrono::microseconds(1 + (rand() % 10)));
        std::cout << "Sent Order ID: " << order.id << " (" << (order.type == OrderType::BUY ? "BUY" : "SELL")
                  << ") Price: " << order.price << " Qty: " << order.quantity << std::endl;
    }
};

// Main Trading Engine
class TradingEngine {
private:
    OrderBook orderBook;
    NetworkLayer network;
    std::atomic<bool> running{true};

public:
    void start() {
        // Simulate incoming orders
        std::thread orderGenerator([this]() {
            while (running) {
                OrderType type = (rand() % 2) ? OrderType::BUY : OrderType::SELL;
                double price = 100.0 + (rand() % 10);  // Random price between 100-110
                uint32_t quantity = 1 + (rand() % 100);  // Random quantity 1-100
                orderBook.addOrder(type, price, quantity);
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });

        // Simulate order matching
        std::thread matcher([this]() {
            while (running) {
                orderBook.matchOrders();
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            }
        });

        // Simulate network traffic
        std::thread networkSim([this]() {
            while (running) {
                // Simulate sending orders to a market maker
                Order order(1, OrderType::BUY, 105.0, 10);
                network.sendOrder(order);
                std::this_thread::sleep_for(std::chrono::milliseconds(20));
            }
        });

        // Print order book periodically
        std::thread printer([this]() {
            while (running) {
                orderBook.printBook();
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });

        // Wait for shutdown
        std::this_thread::sleep_for(std::chrono::seconds(5));
        running = false;

        // Join threads
        orderGenerator.join();
        matcher.join();
        networkSim.join();
        printer.join();
    }
};

int main() {
    TradingEngine engine;
    engine.start();
    return 0;
}
