#### **G. `message_queue.cpp` (Thread-Safe Queue)**
```cpp
#include "message_queue.hpp"

void MessageQueue::push(const Order& order) {
    std::lock_guard<std::mutex> lock(mtx);
    orders.push(order);
    cv.notify_one();
}

Order MessageQueue::pop() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [this] { return !orders.empty(); });
    Order order = orders.front();
    orders.pop();
    return order;
}
```

