use std::{
    sync::{Arc, Mutex},
    thread,
    time::Duration,
};
use tokio::sync::broadcast;
use warp::ws::{Message, WebSocket};
use warp::Filter;

// Market data structure
#[derive(Debug, Clone)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Aggregated stats
#[derive(Debug, Clone)]
struct AggregatedStats {
    symbol: String,
    avg_price: f64,
    min_price: f64,
    max_price: f64,
    count: u64,
}

// Simulate incoming market data
fn simulate_market_data(tx: broadcast::Sender<MarketData>) {
    let symbols = vec!["AAPL", "GOOGL", "MSFT", "AMZN"];
    loop {
        for symbol in &symbols {
            let price = (100.0 + rand::random::<f64>() * 100.0).round();
            let data = MarketData {
                symbol: symbol.to_string(),
                price,
                timestamp: chrono::Utc::now().timestamp() as u64,
            };
            tx.send(data).unwrap();
            thread::sleep(Duration::from_millis(100));
        }
    }
}

// Compute aggregates
fn compute_aggregates(
    mut rx: broadcast::Receiver<MarketData>,
    tx: broadcast::Sender<AggregatedStats>,
) {
    let mut aggregates = std::collections::HashMap::new();

    while let Ok(data) = rx.recv() {
        let entry = aggregates.entry(data.symbol.clone()).or_insert_with(|| {
            AggregatedStats {
                symbol: data.symbol.clone(),
                avg_price: 0.0,
                min_price: f64::MAX,
                max_price: f64::MIN,
                count: 0,
            }
        });

        entry.count += 1;
        entry.avg_price = (entry.avg_price * (entry.count - 1) as f64 + data.price) / entry.count as f64;
        entry.min_price = entry.min_price.min(data.price);
        entry.max_price = entry.max_price.max(data.price);

        tx.send(entry.clone()).unwrap();
    }
}

// WebSocket handler to stream aggregates
async fn handle_websocket(
    ws: WebSocket,
    mut rx: broadcast::Receiver<AggregatedStats>,
) {
    let (mut tx, _) = ws.split();

    while let Ok(stats) = rx.recv().await {
        let json = serde_json::to_string(&stats).unwrap();
        tx.send(Message::text(json)).await.unwrap();
    }
}

