use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    thread,
    time::{Duration, Instant},
};
use tokio::{
    net::{TcpListener, TcpStream},
    sync::broadcast,
};
use tokio_stream::wrappers::BroadcastStream;

// Market data structure
#[derive(Debug, Clone)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: Instant,
}

// Aggregated statistics
#[derive(Debug, Clone)]
struct AggregatedStats {
    symbol: String,
    avg_price: f64,
    min_price: f64,
    max_price: f64,
    count: u64,
}

// Real-time market data processor
struct MarketDataProcessor {
    data_tx: broadcast::Sender<MarketData>,
    stats_tx: broadcast::Sender<AggregatedStats>,
    symbol_stats: Arc<Mutex<HashMap<String, (f64, f64, f64, u64)>>>, // (sum, min, max, count)
}

impl MarketDataProcessor {
    fn new() -> Self {
        let (data_tx, _) = broadcast::channel(100);
        let (stats_tx, _) = broadcast::channel(100);
        let symbol_stats = Arc::new(Mutex::new(HashMap::new()));

        Self {
            data_tx,
            stats_tx,
            symbol_stats,
        }
    }

    // Simulate incoming market data
    async fn simulate_market_data(&self) {
        let symbols = vec!["AAPL", "MSFT", "GOOGL", "AMZN"];
        let mut rng = rand::thread_rng();

        loop {
            let symbol = symbols[rand::random::<usize>() % symbols.len()].to_string();
            let price = (rand::random::<f64>() * 1000.0).round() / 100.0; // Random price (0-1000)
            let data = MarketData {
                symbol: symbol.clone(),
                price,
                timestamp: Instant::now(),
            };

            // Send raw data to subscribers
            self.data_tx.send(data.clone()).unwrap();

            // Update aggregates
            self.update_aggregates(&data).await;

            tokio::time::sleep(Duration::from_millis(100)).await; // Simulate real-time delay
        }
    }

    // Update aggregates (avg, min, max)
    async fn update_aggregates(&self, data: &MarketData) {
        let mut stats = self.symbol_stats.lock().unwrap();
        let entry = stats.entry(data.symbol.clone()).or_insert((0.0, f64::MAX, f64::MIN, 0));

        entry.0 += data.price; // Sum
        entry.1 = entry.1.min(data.price); // Min
        entry.2 = entry.2.max(data.price); // Max
        entry.3 += 1; // Count

        let avg = entry.0 / entry.3 as f64;
        let aggregated_stats = AggregatedStats {
            symbol: data.symbol.clone(),
            avg_price: avg,
            min_price: entry.1,
            max_price: entry.2,
            count: entry.3,
        };

        // Send aggregated stats to subscribers
        self.stats_tx.send(aggregated_stats).unwrap();
    }

    // Start the processor
    async fn run(&self) {
        tokio::spawn(self.simulate_market_data());

        // Start a TCP server to stream stats to subscribers
        let listener = TcpListener::bind("127.0.0.1:8080").await.unwrap();
        println!("Server running on 127.0.0.1:8080");

        loop {
            let (socket, _) = listener.accept().await.unwrap();
            let stats_tx = self.stats_tx.clone();
            tokio::spawn(async move {
                let mut stream = BroadcastStream::new(stats_tx.subscribe());
                while let Ok(Some(stats)) = stream.next().await {
                    let stats_json = serde_json::to_string(&stats).unwrap();
                    socket.writable().await.unwrap();
                    socket.try_write(stats_json.as_bytes()).unwrap();
                }
            });
        }
    }
}

#[tokio::main]
async fn main() {
    let processor = MarketDataProcessor::new();
    processor.run().await;
}
