use std::sync::Arc;
use tokio::sync::broadcast;
use tokio_stream::wrappers::BroadcastStream;
use warp::ws::{Message, WebSocket};
use warp::Filter;
use serde::{Serialize, Deserialize};
use rand::Rng;

// Market data structure
#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Aggregated result
#[derive(Debug, Clone, Serialize, Deserialize)]
struct AggregatedResult {
    symbol: String,
    avg_price: f64,
    min_price: f64,
    max_price: f64,
    window_size: usize,
}

// Simulate incoming market data
async fn generate_market_data(tx: broadcast::Sender<MarketData>) {
    let symbols = vec!["AAPL", "GOOGL", "MSFT", "AMZN"];
    let mut rng = rand::thread_rng();

    loop {
        for &symbol in &symbols {
            let price = rng.gen_range(100.0..500.0);
            let timestamp = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();

            let data = MarketData {
                symbol: symbol.to_string(),
                price,
                timestamp,
            };

            tx.send(data).unwrap();
        }
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
    }
}

// Compute aggregates (moving window)
async fn compute_aggregates(
    mut rx: broadcast::Receiver<MarketData>,
    tx: broadcast::Sender<AggregatedResult>,
) {
    let window_size = 10;
    let mut price_windows: std::collections::HashMap<String, Vec<f64>> = HashMap::new();

    while let Ok(data) = rx.recv().await {
        let symbol = data.symbol.clone();
        let price = data.price;

        // Update window
        let window = price_windows.entry(symbol.clone()).or_default();
        window.push(price);
        if window.len() > window_size {
            window.remove(0);
        }

        // Compute aggregates
        if window.len() == window_size {
            let avg_price = window.iter().sum::<f64>() / window.len() as f64;
            let min_price = *window.iter().min_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();
            let max_price = *window.iter().max_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();

            let result = AggregatedResult {
                symbol,
                avg_price,
                min_price,
                max_price,
                window_size,
            };

            tx.send(result).unwrap();
        }
    }
}

// WebSocket handler
async fn handle_ws_connection(
    ws: WebSocket,
    mut rx: broadcast::Receiver<AggregatedResult>,
) {
    let (mut tx, _) = ws.split();
    while let Ok(result) = rx.recv().await {
        let json = serde_json::to_string(&result).unwrap();
        tx.send(Message::text(json)).await.unwrap();
    }
}

