    let (market_tx, _) = broadcast::channel::<MarketData>(100);
    let (agg_tx, _) = broadcast::channel::<AggregatedResult>(100);

    // Spawn tasks
    tokio::spawn(generate_market_data(market_tx.clone()));
    tokio::spawn(compute_aggregates(market_tx.subscribe(), agg_tx.clone()));

    // WebSocket route
    let agg_rx = agg_tx.subscribe();
    let ws_route = warp::path("ws")
        .and(warp::ws())
        .map(move |ws: warp::ws::Ws| {
            let agg_rx = agg_rx.resubscribe();
            ws.on_upgrade(move |socket| handle_ws_connection(socket, agg_rx))
        });

    // Start server
    println!("Server running on ws://localhost:8080/ws");
    warp::serve(ws_route).run(([127, 0, 0, 1], 8080)).await;
}
