use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use tokio::net::{TcpListener, TcpStream};
use tokio::io::{AsyncWriteExt, AsyncReadExt};
use tokio::sync::broadcast;
use serde::{Serialize, Deserialize};

// Market data structure
#[derive(Debug, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Aggregated statistics
#[derive(Debug, Serialize, Deserialize)]
struct PriceAggregates {
    symbol: String,
    average: f64,
    min: f64,
    max: f64,
    count: u64,
}

// Shared state for market data and subscribers
struct MarketProcessor {
    data: Arc<Mutex<HashMap<String, Vec<f64>>>>,
    tx: broadcast::Sender<PriceAggregates>,
}

impl MarketProcessor {
    fn new() -> Self {
        let (tx, _) = broadcast::channel(100);
        MarketProcessor {
            data: Arc::new(Mutex::new(HashMap::new())),
            tx,
        }
    }

    // Process incoming market data and update aggregates
    fn process_data(&self, data: MarketData) {
        let mut data_map = self.data.lock().unwrap();
        let prices = data_map.entry(data.symbol.clone()).or_insert_with(Vec::new);
        prices.push(data.price);

        // Compute aggregates
        let sum: f64 = prices.iter().sum();
        let avg = sum / prices.len() as f64;
        let min = *prices.iter().min_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();
        let max = *prices.iter().max_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();

        let aggregates = PriceAggregates {
            symbol: data.symbol,
            average: avg,
            min,
            max,
            count: prices.len() as u64,
        };

        // Broadcast to subscribers
        self.tx.send(aggregates).unwrap();
    }
}

// Simulate incoming market data (e.g., from a feed)
async fn simulate_market_data(processor: Arc<MarketProcessor>) {
    let symbols = vec!["AAPL", "MSFT", "GOOGL", "AMZN"];
    let mut rng = rand::thread_rng();

    loop {
        for symbol in &symbols {
            let price = rng.gen_range(100.0..500.0);
            let data = MarketData {
                symbol: symbol.to_string(),
                price,
                timestamp: chrono::Utc::now().timestamp() as u64,
            };
            processor.process_data(data);
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

// Handle client connections (subscribers)
async fn handle_client(mut socket: TcpStream, mut rx: broadcast::Receiver<PriceAggregates>) {
    let mut buf = [0; 1024];
    loop {
        tokio::select! {
            Ok(_) = socket.read(&mut buf) => {
                // Client disconnected
                break;
            }
            Ok(aggregates) = rx.recv() => {
                let json = serde_json::to_string(&aggregates).unwrap();
                socket.write_all(json.as_bytes()).await.unwrap();
                socket.write_all(b"\n").await.unwrap();
            }
        }
    }
}

// Main server to stream aggregates to subscribers
