    let symbols = vec!["AAPL", "GOOGL", "MSFT", "AMZN", "TSLA"];
    let mut rng = rand::thread_rng();

    loop {
        let symbol = symbols[rng.gen_range(0..symbols.len())].to_string();
        let price = rng.gen_range(100.0..500.0);
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let data = MarketData {
            symbol,
            price,
            timestamp,
        };

        tx.send(data).unwrap(); // Broadcast to subscribers
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
    }
}

// Process incoming data and update aggregates
async fn process_data(
    mut rx: broadcast::Receiver<MarketData>,
    aggregates: Aggregates,
) {
    while let Ok(data) = rx.recv().await {
        let mut aggregates = aggregates.lock().unwrap();
        let entry = aggregates.entry(data.symbol.clone()).or_insert_with(|| AggregatedData {
            symbol: data.symbol.clone(),
            avg_price: 0.0,
            min_price: f64::MAX,
            max_price: f64::MIN,
            count: 0,
        });

        entry.count += 1;
        entry.avg_price = (entry.avg_price * (entry.count - 1) as f64 + data.price) / entry.count as f64;
        entry.min_price = entry.min_price.min(data.price);
        entry.max_price = entry.max_price.max(data.price);
    }
}

// WebSocket handler to stream aggregates
async fn handle_ws_connection(
    ws: WebSocket,
    aggregates: Aggregates,
) {
    let (mut tx, _) = ws.split();

    loop {
        let aggregates = aggregates.lock().unwrap();
        let json = serde_json::to_string(&*aggregates).unwrap();
        tx.send(Message::text(json)).await.unwrap();
        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
    }
}

