        for symbol in &symbols {
            let price = rng.gen_range(100.0..500.0);
            let data = MarketData {
                symbol: symbol.to_string(),
                price,
                timestamp: std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_secs(),
            };
