        }
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
    }
}

// --- Price Aggregator ---
async fn compute_aggregates(
    mut rx: broadcast::Receiver<MarketData>,
    tx: broadcast::Sender<PriceAggregate>,
) {
    let mut aggregates = std::collections::HashMap::new();
    let window_size = 10; // Number of prices to aggregate

    while let Ok(data) = rx.recv().await {
        let entry = aggregates.entry(data.symbol.clone()).or_insert_with(|| {
            Vec::with_capacity(window_size)
        });

        entry.push(data.price);
        if entry.len() > window_size {
            entry.remove(0);
        }

        if entry.len() == window_size {
            let avg_price = entry.iter().sum::<f64>() / entry.len() as f64;
            let min_price = *entry.iter().min_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();
            let max_price = *entry.iter().max_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();

            let aggregate = PriceAggregate {
                symbol: data.symbol,
                avg_price,
                min_price,
                max_price,
                window_size,
            };
            tx.send(aggregate).unwrap();
        }
    }
}

// --- WebSocket Server ---
async fn websocket_server(
    addr: &str,
    mut rx: broadcast::Receiver<PriceAggregate>,
) -> Result<(), Box<dyn std::error::Error>> {
    let listener = tokio::net::TcpListener::bind(addr).await?;
    println!("WebSocket server running on ws://{}", addr);

    while let Ok((stream, _)) = listener.accept().await {
        let mut rx = rx.resubscribe();
        tokio::spawn(async move {
            let ws_stream = tokio_tungstenite::accept_async(stream).await.unwrap();
            let (mut write, _) = ws_stream.split();

            while let Ok(aggregate) = rx.recv().await {
                let msg = serde_json::to_string(&aggregate).unwrap();
                write.send(Message::Text(msg)).await.unwrap();
            }
        });
    }
    Ok(())
}

