use std::collections::VecDeque;
use std::sync::Arc;
use tokio::sync::Mutex;
use warp::ws::{Message, WebSocket};
use warp::Filter;

// Market data structure
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Aggregated price data
#[derive(Debug, Clone, serde::Serialize)]
struct PriceAggregate {
    symbol: String,
    average_price: f64,
    window_size: usize,
}

// Shared state for subscribers
type Subscribers = Arc<Mutex<Vec<WebSocket>>>;

// Simulate incoming market data (e.g., from a feed)
async fn generate_market_data() -> MarketData {
    let symbols = vec!["AAPL", "MSFT", "GOOGL", "AMZN"];
    let symbol = symbols[rand::random::<usize>() % symbols.len()].to_string();
    let price = (rand::random::<f64>() * 1000.0).round() / 100.0; // Random price
    let timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();

    MarketData {
        symbol,
        price,
        timestamp,
    }
}

// Compute price aggregates over a sliding window
async fn compute_aggregates(
    data: MarketData,
    window: &mut VecDeque<f64>,
    max_window_size: usize,
) -> Option<PriceAggregate> {
    window.push_back(data.price);
    if window.len() > max_window_size {
        window.pop_front();
    }

    if window.len() == max_window_size {
        let sum: f64 = window.iter().sum();
        let average = sum / window.len() as f64;
        Some(PriceAggregate {
            symbol: data.symbol,
            average_price: average,
            window_size: max_window_size,
        })
    } else {
        None
    }
}

// Handle WebSocket connections
async fn handle_connection(ws: WebSocket, subscribers: Subscribers) {
    let (mut tx, _) = ws.split();
    subscribers.lock().await.push(tx);
}

// Broadcast aggregates to subscribers
async fn broadcast_aggregates(
    subscribers: Subscribers,
    aggregate: PriceAggregate,
) {
    let subscribers = subscribers.lock().await;
    for subscriber in subscribers.iter() {
        let json = serde_json::to_string(&aggregate).unwrap();
        if let Err(e) = subscriber.send(Message::text(json)).await {
            eprintln!("Failed to send to subscriber: {}", e);
        }
    }
}

#[tokio::main]
async fn main() {
    // Shared state for subscribers
    let subscribers = Arc::new(Mutex::new(Vec::new()));

    // WebSocket endpoint for subscribers
    let ws_route = warp::path("ws")
        .and(warp::ws())
        .map(move |ws: warp::ws::Ws| {
            let subscribers = subscribers.clone();
            ws.on_upgrade(move |socket| handle_connection(socket, subscribers))
        });

    // Start WebSocket server
    tokio::spawn(async {
        println!("WebSocket server running on ws://localhost:8080/ws");
        warp::serve(ws_route).run(([127, 0, 0, 1], 8080)).await;
    });

    // Simulate market data and compute aggregates
