    loop {
        let data = generate_market_data().await;
        println!("Received: {:?}", data);

        if let Some(aggregate) = compute_aggregates(data, &mut window, 10).await {
            println!("Aggregate: {:?}", aggregate);
            broadcast_aggregates(subscribers.clone(), aggregate).await;
        }

        tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;
    }
}
