use std::sync::Arc;
use tokio::sync::broadcast;
use dashmap::DashMap;
use serde::{Serialize, Deserialize};
use tokio_tungstenite::tungstenite::protocol::Message;
use futures::{SinkExt, StreamExt};

// --- Data Structures ---
#[derive(Debug, Clone, Serialize, Deserialize)]
struct Trade {
    symbol: String,
    price: f64,
    quantity: u64,
    timestamp: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PriceAggregate {
    symbol: String,
    avg_price: f64,
    min_price: f64,
    max_price: f64,
    volume_weighted_avg: f64,
    total_volume: u64,
}

// --- Mock Market Data Generator ---
async fn mock_market_data(tx: broadcast::Sender<Trade>) {
    let symbols = vec!["AAPL", "MSFT", "GOOG", "AMZN", "TSLA"];
    let mut rng = rand::thread_rng();

    loop {
        let symbol = symbols[rand::random::<usize>() % symbols.len()].to_string();
        let price = (rand::random::<f64>() * 1000.0).round() / 100.0; // Random price (0-1000)
        let quantity = rand::random::<u64>() % 1000 + 1; // Random quantity (1-1000)
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let trade = Trade {
            symbol,
            price,
            quantity,
            timestamp,
        };

        tx.send(trade).unwrap();
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await; // Simulate real-time delay
    }
}

// --- Price Aggregator ---
async fn aggregate_prices(
    mut rx: broadcast::Receiver<Trade>,
    aggregates: Arc<DashMap<String, PriceAggregate>>,
) {
    while let Ok(trade) = rx.recv().await {
        let symbol = trade.symbol.clone();
        let price = trade.price;
        let quantity = trade.quantity;

        aggregates.entry(symbol.clone()).and_modify(|agg| {
            agg.avg_price = (agg.avg_price * agg.total_volume as f64 + price * quantity as f64)
                / (agg.total_volume + quantity) as f64;
            agg.min_price = agg.min_price.min(price);
            agg.max_price = agg.max_price.max(price);
            agg.volume_weighted_avg = (agg.volume_weighted_avg * agg.total_volume as f64
                + price * quantity as f64)
                / (agg.total_volume + quantity) as f64;
            agg.total_volume += quantity;
        }).or_insert(PriceAggregate {
            symbol: symbol.clone(),
            avg_price: price,
            min_price: price,
            max_price: price,
            volume_weighted_avg: price,
            total_volume: quantity,
        });
    }
}

// --- WebSocket Streaming ---
async fn stream_aggregates(
    aggregates: Arc<DashMap<String, PriceAggregate>>,
    addr: &str,
) {
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    println!("WebSocket server listening on {}", addr);

    while let Ok((stream, _)) = listener.accept().await {
        tokio::spawn(async move {
            let ws_stream = tokio_tungstenite::accept_async(stream).await.unwrap();
            let (mut write, _) = ws_stream.split();

            loop {
                let mut aggregates_json = Vec::new();
                for agg in aggregates.iter() {
                    aggregates_json.push(agg.value().clone());
                }

                if let Ok(json) = serde_json::to_string(&aggregates_json) {
                    if let Err(e) = write.send(Message::Text(json)).await {
                        eprintln!("WebSocket error: {}", e);
                        break;
                    }
                }

                tokio::time::sleep(tokio::time::Duration::from_secs(1)).await; // Send updates every second
            }
        });
    }
}

// --- Main Function ---
#[tokio::main]
async fn main() {
    // Shared state for aggregates
    let aggregates = Arc::new(DashMap::new());

    // Broadcast channel for trades
    let (tx, _) = broadcast::channel::<Trade>(100);

