use futures::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::sync::Arc;
use tokio::sync::Mutex;
use tokio_tungstenite::tungstenite::protocol::Message;

// Define a market data event
#[derive(Debug, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Define an aggregate result
#[derive(Debug, Serialize, Deserialize)]
struct PriceAggregate {
    symbol: String,
    average_price: f64,
    window_size: usize,
}

// Shared state for subscribers
type Subscribers = Arc<Mutex<Vec<tokio::sync::mpsc::Sender<PriceAggregate>>>>;

// Simulate incoming market data (e.g., from an exchange)
async fn simulate_market_data(tx: tokio::sync::mpsc::Sender<MarketData>) {
    let symbols = vec!["AAPL", "MSFT", "GOOGL"];
    let mut rng = rand::thread_rng();

    loop {
        let symbol = symbols[rand::random::<usize>() % symbols.len()].to_string();
        let price = (rand::random::<f64>() * 100.0).round() / 10.0; // Random price (0-100)
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        tx.send(MarketData {
            symbol,
            price,
            timestamp,
        })
        .await
        .unwrap();

        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
    }
}

// Compute aggregates (e.g., moving average)
async fn compute_aggregates(
    mut rx: tokio::sync::mpsc::Receiver<MarketData>,
    subscribers: Subscribers,
) {
    let window_size = 5; // Sliding window size
    let mut price_windows: std::collections::HashMap<String, VecDeque<f64>> = HashMap::new();

    while let Some(data) = rx.recv().await {
        let symbol = data.symbol.clone();
        let price = data.price;

        // Update sliding window
        let window = price_windows.entry(symbol.clone()).or_default();
        window.push_back(price);
        if window.len() > window_size {
            window.pop_front();
        }

        // Compute average
        let average_price = window.iter().sum::<f64>() / window.len() as f64;

        // Broadcast to subscribers
        let aggregate = PriceAggregate {
            symbol,
            average_price,
            window_size,
        };

        let mut subscribers = subscribers.lock().await;
        for subscriber in subscribers.iter_mut() {
            subscriber.send(aggregate.clone()).await.unwrap();
        }
    }
}

// Handle WebSocket connections
async fn handle_connection(
    stream: tokio_tungstenite::WebSocketStream<tokio::net::TcpStream>,
    subscribers: Subscribers,
) {
    let (mut ws_tx, mut ws_rx) = stream.split();
    let (tx, mut rx) = tokio::sync::mpsc::channel(100);

    // Add subscriber
    subscribers.lock().await.push(tx);

    // Forward aggregates to WebSocket
    while let Some(aggregate) = rx.recv().await {
        let json = serde_json::to_string(&aggregate).unwrap();
        ws_tx.send(Message::Text(json)).await.unwrap();
    }
}

