struct MarketData {
    symbol: String,
    price: f64,
    timestamp: u64,
}

// Define an aggregate result (e.g., moving average)
#[derive(Debug, Serialize, Deserialize)]
struct AggregateResult {
    symbol: String,
    average_price: f64,
    window_size: usize,
}

// Shared state for subscribers and aggregates
struct SharedState {
    subscribers: Vec<tokio::sync::mpsc::Sender<Message>>,
    price_history: VecDeque<f64>,  // Sliding window for aggregates
    window_size: usize,
}

#[tokio::main]
async fn main() {
    // Initialize shared state
    let shared_state = Arc::new(Mutex::new(SharedState {
        subscribers: Vec::new(),
        price_history: VecDeque::with_capacity(10),  // 10-price window
        window_size: 10,
    }));

    // Spawn a task to simulate incoming market data
    let state_clone = shared_state.clone();
    tokio::spawn(async move {
        simulate_market_data(state_clone).await;
    });

