            price,
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
        };

        // Update price history and compute aggregate
        let mut state = state.lock().await;
        state.price_history.push_back(price);
        if state.price_history.len() > state.window_size {
            state.price_history.pop_front();
        }

        // Compute average price
        let avg_price = state.price_history.iter().sum::<f64>() / state.price_history.len() as f64;
        let aggregate = AggregateResult {
            symbol: data.symbol.clone(),
            average_price: avg_price,
            window_size: state.window_size,
        };

        // Broadcast to all subscribers
        let message = serde_json::to_string(&aggregate).unwrap();
        for subscriber in &state.subscribers {
            let _ = subscriber.send(Message::Text(message.clone())).await;
