    // Shared state for aggregates (thread-safe)
    let state = Arc::new(Mutex::new(SharedState {
        price_history: VecDeque::with_capacity(10),
        window_size: 5,
    }));

    // Spawn a task to simulate incoming market data
    let data_simulator = tokio::spawn(simulate_market_data());

    // Spawn a task to compute aggregates
    let aggregator = tokio::spawn(compute_aggregates(state.clone()));

    // Spawn a WebSocket server to stream results
    let websocket_server = tokio::spawn(start_websocket_server(state.clone()));

    // Wait for all tasks to complete
    tokio::join!(data_simulator, aggregator, websocket_server);
}

// Simulate incoming market data (e.g., from a broker API)
async fn simulate_market_data() {
    let symbols = ["AAPL", "MSFT", "GOOGL"];
    let mut rng = rand::thread_rng();

    loop {
        let symbol = symbols[rand::random::<usize>() % symbols.len()].to_string();
        let price = (rand::random::<f64>() * 100.0).round() / 10.0; // Random price
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let data = MarketData {
            symbol,
            price,
            timestamp,
        };

        // Simulate network delay (e.g., from a broker API)
        tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;

        // In a real system, this would send data to a channel or queue
        println!("Simulated market data: {:?}", data);
    }
}

// Compute moving average aggregates
async fn compute_aggregates(state: Arc<Mutex<SharedState>>) {
    loop {
        // Simulate receiving data (in a real system, this would come from a channel)
        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;

        let mut state = state.lock().await;
        let price = 100.0 + (rand::random::<f64>() * 10.0); // Simulate a new price

        // Update price history
        state.price_history.push_back(price);
        if state.price_history.len() > state.window_size {
            state.price_history.pop_front();
        }

        // Compute moving average
        let sum: f64 = state.price_history.iter().sum();
        let moving_avg = sum / state.price_history.len() as f64;

        let result = AggregateResult {
            symbol: "AAPL".to_string(),
            moving_avg,
            window_size: state.window_size,
        };

        println!("Computed aggregate: {:?}", result);
    }
}

