use futures::{SinkExt, StreamExt};
use rand::Rng;
use std::collections::VecDeque;
use std::sync::Arc;
use tokio::sync::broadcast;
use tokio_tungstenite::tungstenite::protocol::Message;

// Simulate market data (e.g., stock prices)
async fn generate_market_data(tx: broadcast::Sender<f64>) {
    let mut rng = rand::thread_rng();
    loop {
        let price = rng.gen_range(100.0..200.0); // Random price between $100-$200
        tx.send(price).unwrap(); // Broadcast to subscribers
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await; // Simulate real-time delay
    }
}

// Compute aggregates (e.g., moving average)
async fn compute_aggregates(mut rx: broadcast::Receiver<f64>, tx: broadcast::Sender<String>) {
    let window_size = 5; // Sliding window of 5 prices
    let mut window = VecDeque::with_capacity(window_size);

    while let Ok(price) = rx.recv().await {
        window.push_back(price);
        if window.len() > window_size {
            window.pop_front();
        }

        let avg = window.iter().sum::<f64>() / window.len() as f64;
        let result = format!("Average price: {:.2}", avg);
        tx.send(result).unwrap(); // Broadcast aggregated result
    }
}

// Stream results to WebSocket clients
async fn handle_websocket_connection(
    mut stream: tokio_tungstenite::WebSocketStream<tokio::net::TcpStream>,
    mut rx: broadcast::Receiver<String>,
) {
    while let Ok(msg) = rx.recv().await {
        if let Err(e) = stream.send(Message::Text(msg)).await {
            eprintln!("WebSocket error: {}", e);
            break;
        }
    }
}

#[tokio::main]
async fn main() {
    // Create broadcast channels for market data and aggregates
    let (market_tx, _) = broadcast::channel(100);
    let (agg_tx, _) = broadcast::channel(100);

    // Spawn tasks
    tokio::spawn(generate_market_data(market_tx.clone()));
    tokio::spawn(compute_aggregates(market_tx.subscribe(), agg_tx.clone()));

    // Start WebSocket server
    let addr = "127.0.0.1:8080";
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    println!("WebSocket server running on ws://{}", addr);

    while let Ok((stream, _)) = listener.accept().await {
        let agg_rx = agg_tx.subscribe();
        tokio::spawn(handle_websocket_connection(
            tokio_tungstenite::accept_async(stream).await.unwrap(),
            agg_rx,
        ));
    }
}
