use std::sync::Arc;
use std::time::{Instant, Duration};
use tokio::sync::mpsc;
use prometheus::{Histogram, IntCounter, register_histogram, register_int_counter};
use lazy_static::lazy_static;

// Define message structure
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    payload: String,
    timestamp: Instant,
}

// Global metrics (thread-safe)
lazy_static! {
    static ref MESSAGE_COUNTER: IntCounter = register_int_counter!(
        "messages_total",
        "Total number of messages processed"
    ).unwrap();
    static ref LATENCY_HISTOGRAM: Histogram = register_histogram!(
        "message_latency_seconds",
        "Latency of message processing in seconds",
        vec![0.001, 0.005, 0.01, 0.05, 0.1, 0.5, 1.0] // Buckets in seconds
    ).unwrap();
}

// Message producer (simulates high-frequency input)
async fn producer(tx: mpsc::Sender<Message>, rate: u64) {
    let mut id = 0;
    let interval = Duration::from_secs_f64(1.0 / rate as f64);
    loop {
        let now = Instant::now();
        let msg = Message {
            id,
            payload: format!("Message {}", id),
            timestamp: now,
        };
        if tx.send(msg).await.is_err() {
            eprintln!("Receiver dropped!");
            break;
        }
        id += 1;
        tokio::time::sleep(interval).await;
    }
}

// Message processor (routes and measures latency)
async fn processor(mut rx: mpsc::Receiver<Message>) {
    while let Some(msg) = rx.recv().await {
        let latency = msg.timestamp.elapsed().as_secs_f64();
        LATENCY_HISTOGRAM.observe(latency);
        MESSAGE_COUNTER.inc();
        println!("Processed: {:?} (Latency: {:.3}ms)", msg, latency * 1000.0);
    }
}

#[tokio::main]
async fn main() {
    // Configure system
    let (tx, rx) = mpsc::channel::<Message>(10_000); // Buffered channel
    let num_producers = 4; // Simulate multiple producers
    let message_rate_per_producer = 1_000_000; // 1M messages/sec per producer

    // Spawn producers
    for _ in 0..num_producers {
        let tx_clone = tx.clone();
        tokio::spawn(async move {
            producer(tx_clone, message_rate_per_producer).await;
        });
    }

    // Spawn processor
    tokio::spawn(async move {
        processor(rx).await;
    });

    // Keep the system running
    tokio::signal::ctrl_c().await.unwrap();
    println!("Shutting down...");
}
