# High-Frequency Messaging System in Rust

Below is a foundational implementation of a high-performance messaging system in Rust that routes millions of messages per second with built-in latency monitoring. This example uses asynchronous I/O, a lightweight message format, and precise timing for latency tracking.

```rust
use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};
use tokio::{
    net::{TcpListener, TcpStream},
    sync::mpsc,
    time,
};
use bytes::{Bytes, BytesMut};
use futures::{SinkExt, StreamExt};
use tokio_util::codec::{Framed, LengthDelimitedCodec};

// Message structure with metadata for latency tracking
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    payload: Bytes,
    timestamp: Instant,
    route: String,
}

// Latency statistics tracker
#[derive(Debug, Default)]
struct LatencyStats {
    total_messages: u64,
    total_latency: Duration,
    min_latency: Option<Duration>,
    max_latency: Option<Duration>,
}

impl LatencyStats {
    fn record(&mut self, latency: Duration) {
        self.total_messages += 1;
        self.total_latency += latency;

        self.min_latency = Some(
            self.min_latency
                .map(|min| min.min(latency))
                .unwrap_or(latency),
        );

        self.max_latency = Some(
            self.max_latency
                .map(|max| max.max(latency))
                .unwrap_or(latency),
        );
    }

    fn average(&self) -> Duration {
        if self.total_messages == 0 {
            Duration::from_secs(0)
        } else {
            self.total_latency / self.total_messages as u32
        }
    }
}

// Message router that handles distribution
struct MessageRouter {
    routes: Arc<Mutex<HashMap<String, mpsc::Sender<Message>>>>,
    stats: Arc<Mutex<LatencyStats>>,
}

impl MessageRouter {
    fn new() -> Self {
        Self {
            routes: Arc::new(Mutex::new(HashMap::new())),
            stats: Arc::new(Mutex::new(LatencyStats::default())),
        }
    }

    async fn register_route(&self, route: String) -> mpsc::Receiver<Message> {
        let (tx, rx) = mpsc::channel(1024); // Buffered channel for backpressure
        self.routes.lock().unwrap().insert(route, tx);
        rx
    }

    async fn route_message(&self, message: Message) {
        let now = Instant::now();
        let latency = now - message.timestamp;

        // Record latency statistics
        self.stats.lock().unwrap().record(latency);

        // Route the message
        if let Some(sender) = self.routes.lock().unwrap().get(&message.route) {
            if sender.send(message).await.is_err() {
                eprintln!("Failed to send message to route");
            }
        } else {
            eprintln!("No route found for message: {}", message.route);
        }
    }

    fn get_stats(&self) -> LatencyStats {
        self.stats.lock().unwrap().clone()
    }
}

// TCP server that accepts connections and processes messages
async fn run_server(router: Arc<MessageRouter>, addr: &str) {
    let listener = TcpListener::bind(addr).await.unwrap();
    println!("Server listening on {}", addr);

    loop {
        let (stream, _) = listener.accept().await.unwrap();
        let router = router.clone();
        tokio::spawn(async move {
            handle_connection(stream, router).await;
        });
    }
}

// Handle individual TCP connections
async fn handle_connection(stream: TcpStream, router: Arc<MessageRouter>) {
    let mut framed = Framed::new(stream, LengthDelimitedCodec::new());
    let mut message_id = 0;

    while let Some(Ok(bytes)) = framed.next().await {
        message_id += 1;
        let timestamp = Instant::now();

        // Extract route from message (simple format: "route:payload")
        let payload = String::from_utf8_lossy(&bytes);
        let parts: Vec<&str> = payload.splitn(2, ':').collect();

        if parts.len() == 2 {
            let route = parts[0].to_string();
            let payload = Bytes::from(parts[1].as_bytes());

            let message = Message {
                id: message_id,
                payload,
                timestamp,
                route,
            };

            router.route_message(message).await;
        }
    }
}

// Worker that processes messages from a route
async fn run_worker(route: String, mut receiver: mpsc::Receiver<Message>) {
    println!("Worker started for route: {}", route);

    while let Some(message) = receiver.recv().await {
        // Simulate processing time (replace with actual logic)
        time::sleep(Duration::from_micros(10)).await;

        println!(
            "Processed message {} on route {} (latency: {:?})",
            message.id,
            message.route,
            Instant::now() - message.timestamp
        );
    }
}

// Periodically print latency statistics
async fn run_stats_reporter(router: Arc<MessageRouter>) {
    let mut interval = time::interval(Duration::from_secs(5));

    loop {
        interval.tick().await;
        let stats = router.get_stats();
        println!(
            "Latency Stats - Avg: {:?}, Min: {:?}, Max: {:?}, Total: {}",
            stats.average(),
            stats.min_latency.unwrap_or(Duration::from_secs(0)),
            stats.max_latency.unwrap_or(Duration::from_secs(0)),
            stats.total_messages
        );
    }
}

#[tokio::main]
async fn main() {
    let router = Arc::new(MessageRouter::new());

    // Register routes
    let route1 = router.register_route("route1".to_string()).await;
    let route2 = router.register_route("route2".to_string()).await;

    // Spawn workers for each route
    tokio::spawn(run_worker("route1".to_string(), route1));
    tokio::spawn(run_worker("route2".to_string(), route2));

    // Spawn stats reporter
    tokio::spawn(run_stats_reporter(router.clone()));

    // Start server
    run_server(router, "127.0.0.1:8080").await;
}
