use std::time::{Instant, Duration};
use tokio::sync::mpsc;
use tracing::{info, instrument};
use rand::Rng;

// Message structure
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    payload: String,
    timestamp: Instant,
}

// Router that distributes messages to consumers
#[instrument(skip(sender))]
async fn router(
    mut receiver: mpsc::Receiver<Message>,
    consumers: Vec<mpsc::Sender<Message>>,
) {
    let mut rng = rand::thread_rng();
    while let Some(msg) = receiver.recv().await {
        // Randomly select a consumer (round-robin could also be used)
        let consumer_idx = rng.gen_range(0..consumers.len());
        if let Err(e) = consumers[consumer_idx].send(msg).await {
            tracing::error!("Failed to send message: {}", e);
        }
    }
}

// Consumer that processes messages and logs latency
#[instrument(skip(receiver))]
async fn consumer(
    id: usize,
    mut receiver: mpsc::Receiver<Message>,
) {
    while let Some(msg) = receiver.recv().await {
        let latency = msg.timestamp.elapsed().as_micros();
        info!(
            "Consumer {} processed message {} in {} μs",
            id, msg.id, latency
        );
        // Simulate processing delay (optional)
        tokio::time::sleep(Duration::from_micros(10)).await;
    }
}

// Producer that generates test messages
#[instrument(skip(sender))]
async fn producer(sender: mpsc::Sender<Message>, rate: u64) {
    let mut id = 0;
    let interval = Duration::from_secs(1) / rate;
    loop {
        let msg = Message {
            id,
            payload: format!("Test message {}", id),
            timestamp: Instant::now(),
        };
        if let Err(e) = sender.send(msg).await {
            tracing::error!("Failed to send message: {}", e);
            break;
        }
        id += 1;
        tokio::time::sleep(interval).await;
    }
}

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt::init();

    // Configuration
    let num_consumers = 4;
    let message_rate = 1_000_000; // 1M messages per second

    // Create channels
    let (producer_tx, router_rx) = mpsc::channel(1024);
    let mut consumers_tx = Vec::new();
    let mut consumers_rx = Vec::new();

    for i in 0..num_consumers {
        let (tx, rx) = mpsc::channel(1024);
        consumers_tx.push(tx);
        consumers_rx.push(rx);
    }

    // Spawn tasks
    tokio::spawn(producer(producer_tx, message_rate));
    tokio::spawn(router(router_rx, consumers_tx));

    for (i, rx) in consumers_rx.into_iter().enumerate() {
        tokio::spawn(consumer(i, rx));
    }

    // Keep the system running
    tokio::signal::ctrl_c().await.unwrap();
    info!("Shutting down...");
}
