# High-Frequency Messaging System with Latency Monitoring

Below is a Rust-based implementation of a high-performance messaging system that routes millions of messages per second with built-in latency monitoring. This example uses asynchronous I/O with Tokio and implements a simple pub/sub pattern with latency tracking.

```rust
use std::{
    collections::HashMap,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::{
    sync::{mpsc, Mutex},
    time::timeout,
};
use uuid::Uuid;

// Message structure with built-in latency tracking
#[derive(Debug, Clone)]
struct Message {
    id: Uuid,
    payload: Vec<u8>,
    timestamp: Instant,
    latency_metrics: HashMap<String, Duration>,
}

// Topic structure to manage subscribers
struct Topic {
    name: String,
    subscribers: Vec<mpsc::Sender<Message>>,
}

// Message broker that handles routing and latency monitoring
struct MessageBroker {
    topics: Arc<Mutex<HashMap<String, Topic>>>,
    latency_threshold: Duration,
}

impl MessageBroker {
    fn new(latency_threshold: Duration) -> Self {
        MessageBroker {
            topics: Arc::new(Mutex::new(HashMap::new())),
            latency_threshold,
        }
    }

    // Create a new topic
    async fn create_topic(&self, topic_name: &str) {
        let mut topics = self.topics.lock().await;
        if !topics.contains_key(topic_name) {
            topics.insert(
                topic_name.to_string(),
                Topic {
                    name: topic_name.to_string(),
                    subscribers: Vec::new(),
                },
            );
        }
    }

    // Subscribe to a topic
    async fn subscribe(&self, topic_name: &str) -> Option<mpsc::Receiver<Message>> {
        let (tx, rx) = mpsc::channel(1024); // Buffered channel for high throughput

        let mut topics = self.topics.lock().await;
        if let Some(topic) = topics.get_mut(topic_name) {
            topic.subscribers.push(tx);
            Some(rx)
        } else {
            None
        }
    }

    // Publish a message to a topic
    async fn publish(&self, topic_name: &str, payload: Vec<u8>) {
        let message = Message {
            id: Uuid::new_v4(),
            payload,
            timestamp: Instant::now(),
            latency_metrics: HashMap::new(),
        };

        let topics = self.topics.lock().await;
        if let Some(topic) = topics.get(topic_name) {
            // Clone the message for each subscriber
            for subscriber in &topic.subscribers {
                let mut msg = message.clone();
                msg.latency_metrics.insert("broker_received".to_string(), Instant::now() - msg.timestamp);

                // Spawn a task to send the message to avoid blocking
                let tx = subscriber.clone();
                tokio::spawn(async move {
                    if let Err(e) = tx.send(msg).await {
                        eprintln!("Failed to send message: {}", e);
                    }
                });
            }
        }
    }

    // Monitor message latency and alert if exceeding threshold
    async fn monitor_latency(&self, message: &Message) {
        let processing_time = Instant::now() - message.timestamp;
        if processing_time > self.latency_threshold {
            println!(
                "High latency detected for message {}: {:?} (threshold: {:?})",
                message.id, processing_time, self.latency_threshold
            );
            // Here you could add additional alerting logic
        }
    }
}

// Example subscriber task
async fn subscriber_task(
    topic_name: String,
    mut receiver: mpsc::Receiver<Message>,
    broker: Arc<MessageBroker>,
) {
    while let Some(message) = receiver.recv().await {
        // Record when the subscriber received the message
        let mut msg = message.clone();
        msg.latency_metrics.insert("subscriber_received".to_string(), Instant::now() - msg.timestamp);

        // Process the message (simulate work)
        tokio::time::sleep(Duration::from_micros(10)).await;

        // Record when processing completed
        msg.latency_metrics.insert("processing_completed".to_string(), Instant::now() - msg.timestamp);

        // Monitor latency
        broker.monitor_latency(&msg).await;

        println!(
            "Message {} processed with latency metrics: {:?}",
            msg.id, msg.latency_metrics
        );
    }
}

#[tokio::main]
async fn main() {
    // Create a broker with 1ms latency threshold
    let broker = Arc::new(MessageBroker::new(Duration::from_millis(1)));

    // Create a topic
    broker.create_topic("high_freq_topic").await;

    // Create subscribers
    let subscriber1 = broker.subscribe("high_freq_topic").await.unwrap();
    let subscriber2 = broker.subscribe("high_freq_topic").await.unwrap();

    // Spawn subscriber tasks
    tokio::spawn(subscriber_task(
        "high_freq_topic".to_string(),
        subscriber1,
        broker.clone(),
    ));
    tokio::spawn(subscriber_task(
        "high_freq_topic".to_string(),
        subscriber2,
        broker.clone(),
    ));

    // Simulate high message volume
    let mut message_count = 0;
    let start_time = Instant::now();

    loop {
        // Publish messages at a high rate
        for _ in 0..1000 {
            let payload = vec![0u8; 1024]; // 1KB payload
            broker.publish("high_freq_topic", payload).await;
            message_count += 1;
        }

        // Print throughput stats every second
        if start_time.elapsed() >= Duration::from_secs(1) {
            let elapsed = start_time.elapsed().as_secs_f64();
            let throughput = (message_count as f64) / elapsed;
            println!(
                "Throughput: {:.2} messages/sec (total: {})",
                throughput, message_count
            );
            break; // Remove this to run indefinitely
        }

        // Small delay to prevent CPU overload
        tokio::time::sleep(Duration::from_millis(1)).await;
    }
}
```

