use std::net::{TcpListener, TcpStream};
use std::io::{Read, Write};
use std::time::{Instant, SystemTime, UNIX_EPOCH};
use std::thread;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;

// Shared state for latency tracking
#[derive(Debug, Default)]
struct LatencyStats {
    total_messages: u64,
    total_latency_ns: u64,
    max_latency_ns: u64,
    min_latency_ns: u64,
}

impl LatencyStats {
    fn record(&mut self, latency_ns: u64) {
        self.total_messages += 1;
        self.total_latency_ns += latency_ns;
        if latency_ns > self.max_latency_ns {
            self.max_latency_ns = latency_ns;
        }
        if latency_ns < self.min_latency_ns || self.min_latency_ns == 0 {
            self.min_latency_ns = latency_ns;
        }
    }

    fn avg_latency_ns(&self) -> f64 {
        if self.total_messages == 0 {
            0.0
        } else {
            self.total_latency_ns as f64 / self.total_messages as f64
        }
    }
}

// Handle a single client connection
fn handle_client(
    mut stream: TcpStream,
    stats: Arc<Mutex<LatencyStats>>,
) {
    let mut buffer = [0; 1024]; // Adjust buffer size as needed

    loop {
        let start_time = Instant::now();

        match stream.read(&mut buffer) {
            Ok(0) => break, // Connection closed
            Ok(n) => {
                // Simulate message processing (replace with actual routing logic)
                let _ = stream.write_all(&buffer[..n]);

                // Record latency
                let latency_ns = start_time.elapsed().as_nanos() as u64;
                stats.lock().unwrap().record(latency_ns);
            }
            Err(e) => {
                eprintln!("Error reading from stream: {}", e);
                break;
            }
        }
    }
}

// Print latency stats periodically
fn print_stats(stats: Arc<Mutex<LatencyStats>>) {
    loop {
        thread::sleep(std::time::Duration::from_secs(5));
        let stats = stats.lock().unwrap();
        println!(
            "Stats: Total Messages: {}, Avg Latency: {:.2} ns, Max Latency: {} ns, Min Latency: {} ns",
            stats.total_messages,
            stats.avg_latency_ns(),
            stats.max_latency_ns,
            stats.min_latency_ns
        );
    }
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:8080").expect("Failed to bind");
    println!("Server listening on 127.0.0.1:8080");

    let stats = Arc::new(Mutex::new(LatencyStats::default()));

    // Spawn a thread to print stats periodically
    let stats_clone = Arc::clone(&stats);
    thread::spawn(move || print_stats(stats_clone));

    // Accept and handle incoming connections
    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let stats_clone = Arc::clone(&stats);
                thread::spawn(move || handle_client(stream, stats_clone));
            }
            Err(e) => {
                eprintln!("Error accepting connection: {}", e);
            }
        }
    }
}
```

