use std::time::{Duration, Instant};
use tokio::sync::mpsc;
use tracing::{info, instrument};

// Message type
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    payload: String,
    timestamp: Instant,
}

// Worker that processes messages
#[instrument(skip(rx))]
async fn worker(id: usize, mut rx: mpsc::Receiver<Message>) {
    while let Some(msg) = rx.recv().await {
        let latency = msg.timestamp.elapsed().as_micros();
        info!(
            "Worker {} processed message {} in {} µs",
            id, msg.id, latency
        );
    }
}

// Producer that generates messages at high frequency
#[instrument]
async fn producer(tx: mpsc::Sender<Message>, rate: u64) {
    let mut id = 0;
    let interval = Duration::from_secs_f64(1.0 / rate as f64);

    loop {
        let msg = Message {
            id,
            payload: format!("Message {}", id),
            timestamp: Instant::now(),
        };

        if tx.send(msg).await.is_err() {
            break; // Channel closed
        }

        id += 1;
        tokio::time::sleep(interval).await;
    }
}

// Router that distributes messages to workers
#[instrument]
async fn router(mut rx: mpsc::Receiver<Message>, num_workers: usize) {
    let mut workers = Vec::with_capacity(num_workers);
    let mut txs = Vec::with_capacity(num_workers);

    // Spawn workers
    for i in 0..num_workers {
        let (tx, rx) = mpsc::channel(1024); // Buffered channel
        workers.push(tokio::spawn(worker(i, rx)));
        txs.push(tx);
    }

    // Distribute messages round-robin
    let mut next_worker = 0;
    while let Some(msg) = rx.recv().await {
        if txs[next_worker].send(msg).await.is_err() {
            break; // Worker failed
        }
        next_worker = (next_worker + 1) % num_workers;
    }

    // Shutdown workers
    for tx in txs {
        drop(tx); // Close channels
    }
    for worker in workers {
        worker.await.unwrap();
    }
}

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt::init();

    // Config
    let num_workers = 4;  // Number of worker threads
    let msg_rate = 1_000_000;  // Messages per second (simulated)

    // Create channels
    let (tx, rx) = mpsc::channel(1024); // Buffered channel

    // Spawn producer and router
    let producer = tokio::spawn(producer(tx, msg_rate));
