### **Ultra-Low-Latency Packet Filtering & Forwarding (C)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <netinet/if_ether.h>
#include <arpa/inet.h>
#include <pcap.h>
#include <errno.h>

#define MAX_PACKET_SIZE 65536
#define FILTER_RULE_PORT 80  // Example: Forward only HTTP traffic

// Forward a packet using raw sockets
int forward_packet(const u_char *packet, int packet_len, int sockfd) {
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(FILTER_RULE_PORT);  // Forward to port 80
    dest_addr.sin_addr.s_addr = inet_addr("192.168.1.100");  // Destination IP

    if (sendto(sockfd, packet, packet_len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

// Packet handler (filtering logic)
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    int sockfd = *(int *)user_data;

    // Check if it's an IP packet
    struct ethhdr *eth_header = (struct ethhdr *)packet;
    if (ntohs(eth_header->h_proto) != ETH_P_IP) {
        return;  // Not an IP packet
    }

    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));
    if (ip_header->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip_header->ihl * 4);
        if (ntohs(tcp_header->dest) == FILTER_RULE_PORT) {  // Filter: Only forward TCP port 80
            forward_packet(packet, pkthdr->len, sockfd);
        }
    } else if (ip_header->protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip_header->ihl * 4);
        if (ntohs(udp_header->dest) == FILTER_RULE_PORT) {  // Filter: Only forward UDP port 80
            forward_packet(packet, pkthdr->len, sockfd);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open a raw socket for forwarding
    int sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (sockfd < 0) {
        perror("socket creation failed");
        return 1;
    }

    // Open a pcap handle for packet capture
    handle = pcap_open_live(dev, MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Set a BPF filter (optional, but improves performance)
    struct bpf_program fp;
    char filter_exp[] = "tcp or udp";  // Only capture TCP/UDP
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }

    printf("Starting packet capture on %s...\n", dev);
    pcap_loop(handle, 0, packet_handler, (u_char *)&sockfd);

    pcap_close(handle);
    close(sockfd);
    return 0;
}
```

