#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <arpa/inet.h>
#include <linux/if_packet.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <stdbool.h>

// Packet buffer size (adjust based on MTU)
#define BUFFER_SIZE 65536

// Forwarding target (modify as needed)
#define FORWARD_IP "192.168.1.100"
#define FORWARD_PORT 8080

// Filter rules (example: allow TCP port 80, UDP port 53)
bool should_filter(const struct iphdr *ip, const void *transport) {
    if (ip->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp = (struct tcphdr *)transport;
        uint16_t dest_port = ntohs(tcp->dest);
        return (dest_port == 80); // Allow only TCP port 80
    } else if (ip->protocol == IPPROTO_UDP) {
        const struct udphdr *udp = (struct udphdr *)transport;
        uint16_t dest_port = ntohs(udp->dest);
        return (dest_port == 53); // Allow only UDP port 53 (DNS)
    }
    return false; // Drop other protocols
}

// Forward packet to another IP/port
void forward_packet(int sock, const char *dest_ip, uint16_t dest_port, const void *packet, size_t len) {
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(dest_port);
    inet_pton(AF_INET, dest_ip, &dest_addr.sin_addr);

    sendto(sock, packet, len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Create raw socket for packet capture
    int sock_raw = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_raw < 0) {
        perror("socket() failed");
        exit(EXIT_FAILURE);
    }

    // Bind to the specified interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, argv[1], IFNAMSIZ - 1);
    if (ioctl(sock_raw, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl() failed");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sock_raw, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind() failed");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    // Create UDP socket for forwarding
    int sock_udp = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_udp < 0) {
        perror("socket() failed");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    printf("Packet filter & forwarder running on %s...\n", argv[1]);

    uint8_t buffer[BUFFER_SIZE];
    while (true) {
        ssize_t packet_len = recvfrom(sock_raw, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (packet_len < 0) {
            perror("recvfrom() failed");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth = (struct ethhdr *)buffer;
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            continue; // Skip non-IP packets
        }

        // Parse IP header
        struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (ip->version != 4) {
            continue; // Skip non-IPv4 packets
        }

        // Parse transport layer (TCP/UDP)
        void *transport = (void *)(buffer + sizeof(struct ethhdr) + (ip->ihl * 4));

        // Apply filter
        if (should_filter(ip, transport)) {
            printf("Forwarding packet (IP: %s, Proto: %d)\n",
                   inet_ntoa(*(struct in_addr *)&ip->saddr), ip->protocol);
            forward_packet(sock_udp, FORWARD_IP, FORWARD_PORT, buffer, packet_len);
        } else {
            printf("Dropping packet (IP: %s, Proto: %d)\n",
                   inet_ntoa(*(struct in_addr *)&ip->saddr), ip->protocol);
        }
    }

    close(sock_raw);
    close(sock_udp);
    return 0;
}
```

