```c
#include <stdio.h>
#include <stdlib.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_udp.h>
#include <rte_tcp.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8192
#define MBUF_CACHE_SIZE 256

static const struct rte_eth_conf port_conf = {
    .rxmode = {
        .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
    },
};

static struct rte_mempool *mbuf_pool;

// Simple packet filter (allow only UDP/TCP on port 80)
int should_forward(struct rte_mbuf *pkt) {
    struct rte_ether_hdr *eth = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);
    struct rte_ipv4_hdr *ip = (struct rte_ipv4_hdr *)(eth + 1);

    if (ip->next_proto_id == IPPROTO_UDP) {
        struct rte_udp_hdr *udp = (struct rte_udp_hdr *)(ip + 1);
        if (rte_be_to_cpu_16(udp->dst_port) == 80) return 1;
    }
    else if (ip->next_proto_id == IPPROTO_TCP) {
        struct rte_tcp_hdr *tcp = (struct rte_tcp_hdr *)(ip + 1);
        if (rte_be_to_cpu_16(tcp->dst_port) == 80) return 1;
    }
    return 0;
}

int main(int argc, char **argv) {
    int ret;
    uint16_t port_id = 0;

    // Initialize DPDK EAL
    ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    // Create mbuf pool
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS,
        MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (!mbuf_pool) rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Initialize port
    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Cannot configure device: err=%d, port=%u\n", ret, port_id);

    // Setup RX/TX queues
    ret = rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, mbuf_pool);
    if (ret < 0) rte_exit(EXIT_FAILURE, "rx_queue_setup failed: err=%d, port=%u\n", ret, port_id);

    ret = rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL);
    if (ret < 0) rte_exit(EXIT_FAILURE, "tx_queue_setup failed: err=%d, port=%u\n", ret, port_id);

    // Start the port
    ret = rte_eth_dev_start(port_id);
    if (ret < 0) rte_exit(EXIT_FAILURE, "rte_eth_dev_start failed: err=%d, port=%u\n", ret, port_id);

    printf("DPDK packet filter/forwarder running on port %u...\n", port_id);

    struct rte_mbuf *pkts_burst[32];
    while (1) {
        const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, pkts_burst, 32);
        if (unlikely(nb_rx == 0)) continue;

        uint16_t nb_tx = 0;
        for (uint16_t i = 0; i < nb_rx; i++) {
            if (should_forward(pkts_burst[i])) {
                pkts_burst[nb_tx++] = pkts_burst[i];
            } else {
                rte_pktmbuf_free(pkts_burst[i]);
            }
        }

        if (nb_tx > 0) {
            const uint16_t nb_tx_sent = rte_eth_tx_burst(port_id, 0, pkts_burst, nb_tx);
            if (unlikely(nb_tx_sent < nb_tx)) {
                for (uint16_t i = nb_tx_sent; i < nb_tx; i++) {
                    rte_pktmbuf_free(pkts_burst[i]);
                }
            }
        }
    }

    return 0;
}
```

