int should_forward(const u_char *packet, int len) {
    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Check if it's an IPv4 packet
    if (ip_header->version != 4) {
        return 0;
    }

    // Check protocol (UDP or TCP)
    if (ip_header->protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(packet + sizeof(struct ethhdr) + (ip_header->ihl * 4));
        if (ntohs(udp_header->dest) == FILTER_UDP_PORT) {
            return 1; // Forward UDP port 53
        }
    } else if (ip_header->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)(packet + sizeof(struct ethhdr) + (ip_header->ihl * 4));
        if (ntohs(tcp_header->dest) == FILTER_TCP_PORT) {
            return 1; // Forward TCP port 80
        }
    }

    return 0; // Drop by default
}

// Function to forward a packet
void forward_packet(int sockfd, const u_char *packet, int len, const char *dest_ip) {
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = 0; // Let kernel choose port
    inet_pton(AF_INET, dest_ip, &dest_addr.sin_addr);

    // Send the packet
    if (sendto(sockfd, packet, len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto failed");
    }
}

int main() {
    int sockfd;
    struct sockaddr_ll sock_addr;
    u_char buffer[BUFFER_SIZE];
    int len;

