        if (len < 0) {
            perror("recvfrom failed");
            continue;
        }

        // Check if the packet should be forwarded
        if (should_forward(buffer, len)) {
            forward_packet(sockfd, buffer, len, FORWARD_IP);
        }
    }

    close(sockfd);
    return 0;
}
