// Initialize a raw socket for packet capture
int init_raw_socket(const char *ifname) {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket() failed");
        exit(EXIT_FAILURE);
    }

    // Bind to the network interface
