    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (setsockopt(sockfd, SOL_SOCKET, SO_BINDTODEVICE, (void *)&ifr, sizeof(ifr)) < 0) {
        perror("SO_BINDTODEVICE failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    return sockfd;
}

// Check if a packet matches the filter rule
bool should_forward(const u_char *packet, const FilterRule *rule) {
    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Only process IPv4 packets
    if (ip_header->version != 4) {
        return false;
    }

    // Check protocol (UDP or TCP)
    if (ip_header->protocol == IPPROTO_UDP && rule->allow_udp) {
        struct udphdr *udp_header = (struct udphdr *)(packet + sizeof(struct ethhdr) + (ip_header->ihl * 4));
        if (ntohs(udp_header->dest) == rule->allowed_port || ntohs(udp_header->source) == rule->allowed_port) {
            return true;
        }
    } else if (ip_header->protocol == IPPROTO_TCP && rule->allow_tcp) {
        struct tcphdr *tcp_header = (struct tcphdr *)(packet + sizeof(struct ethhdr) + (ip_header->ihl * 4));
        if (ntohs(tcp_header->dest) == rule->allowed_port || ntohs(tcp_header->source) == rule->allowed_port) {
            return true;
        }
    }

    return false;
}

// Forward a packet (simplified: just prints info)
