### **Ultra-Low-Latency Packet Filter & Forwarder (C + AF_XDP)**
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>
#include <xdp/xdp_helpers.h>

// Define XDP program entry point
SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Parse Ethernet header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_DROP; // Invalid packet
    }

    // Check if it's an IPv4 packet (0x0800)
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS; // Not IPv4, forward as-is
    }

    // Parse IPv4 header
    struct iphdr *ip = (struct iphdr *)(eth + 1);
    if ((void *)(ip + 1) > data_end) {
        return XDP_DROP; // Invalid packet
    }

    // Simple filter: Drop ICMP (ping) packets
    if (ip->protocol == IPPROTO_ICMP) {
        return XDP_DROP;
    }

    // Forward UDP packets to a specific destination
    if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)(ip + 1);
        if ((void *)(udp + 1) > data_end) {
            return XDP_DROP;
        }

        // Example: Forward UDP port 53 (DNS) to 192.168.1.100
        if (udp->dest == bpf_htons(53)) {
            ip->daddr = bpf_htonl(0xC0A80164); // 192.168.1.100
            return XDP_TX; // Forward modified packet
        }
    }

    // Default: Pass all other packets
    return XDP_PASS;
}

// License (required for BPF programs)
char _license[] SEC("license") = "GPL";
```

