    {0, 443, IPPROTO_TCP, true},  // Allow HTTPS (TCP 443)
};

// Check if a packet matches any filter rule
bool should_forward(const uint8_t *packet, size_t len) {
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));
    if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        for (int i = 0; i < sizeof(rules) / sizeof(FilterRule); i++) {
            if (rules[i].protocol == IPPROTO_UDP &&
                (rules[i].dst_port == 0 || ntohs(udp->dest) == rules[i].dst_port)) {
                return rules[i].allow;
            }
        }
    } else if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        for (int i = 0; i < sizeof(rules) / sizeof(FilterRule); i++) {
            if (rules[i].protocol == IPPROTO_TCP &&
                (rules[i].dst_port == 0 || ntohs(tcp->dest) == rules[i].dst_port)) {
                return rules[i].allow;
            }
        }
    }
    return false;  // Default: drop
}

// Forward a packet (simplified: just sends it back)
void forward_packet(int sockfd, const uint8_t *packet, size_t len) {
    struct sockaddr_ll dest;
    memset(&dest, 0, sizeof(dest));
    dest.sll_family = AF_PACKET;
    dest.sll_ifindex = if_nametoindex("eth0");  // Replace with your interface
    dest.sll_protocol = htons(ETH_P_ALL);

    if (sendto(sockfd, packet, len, 0, (struct sockaddr *)&dest, sizeof(dest)) < 0) {
        perror("sendto failed");
    }
}

int main() {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    uint8_t buffer[65536];
    ssize_t bytes_read;

    while (true) {
        bytes_read = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);
        if (bytes_read < 0) {
            perror("recvfrom failed");
            continue;
        }

        if (should_forward(buffer, bytes_read)) {
            forward_packet(sockfd, buffer, bytes_read);
        }
    }

    close(sockfd);
    return 0;
}
```

