### **Ultra-Low-Latency Packet Filtering & Forwarding (C + DPDK)**
```c
#include <stdio.h>
#include <stdint.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_udp.h>
#include <rte_tcp.h>
#include <rte_ether.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8192
#define MBUF_CACHE_SIZE 256

static const struct rte_eth_conf port_conf = {
    .rxmode = {
        .mq_mode = ETH_MQ_RX_RSS,
        .max_rx_pkt_len = ETHER_MAX_LEN,
        .split_hdr_size = 0,
    },
    .txmode = {
        .mq_mode = ETH_MQ_TX_NONE,
    },
};

static struct rte_mempool *mbuf_pool;

static inline void
filter_and_forward(struct rte_mbuf *pkt, uint16_t port_id) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);

    // Example: Drop non-IPv4 packets
    if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
        rte_pktmbuf_free(pkt);
        return;
    }

    // Example: Forward IPv4 packets to another port (e.g., port 1)
    uint16_t tx_port = (port_id == 0) ? 1 : 0;
    rte_eth_tx_burst(tx_port, 0, &pkt, 1);
}

static int
init_dpdk(int argc, char **argv) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "EAL init failed\n");

    mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL",
        NUM_MBUFS,
        MBUF_CACHE_SIZE,
        0,
        RTE_MBUF_DEFAULT_BUF_SIZE,
        rte_socket_id()
    );
    if (!mbuf_pool) rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    return 0;
}

static int
init_port(uint16_t port_id) {
    int ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret != 0) rte_exit(EXIT_FAILURE, "Cannot configure port %u\n", port_id);

    ret = rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, mbuf_pool);
    if (ret < 0) rte_exit(EXIT_FAILURE, "RX queue setup failed\n");

    ret = rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL);
    if (ret < 0) rte_exit(EXIT_FAILURE, "TX queue setup failed\n");

    ret = rte_eth_dev_start(port_id);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Cannot start port %u\n", port_id);

    rte_eth_promiscuous_enable(port_id);
    return 0;
}

int
main(int argc, char **argv) {
    if (init_dpdk(argc, argv) < 0) return -1;

    uint16_t nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 2) rte_exit(EXIT_FAILURE, "Need at least 2 ports\n");

    for (uint16_t i = 0; i < nb_ports; i++) {
        if (init_port(i) < 0) return -1;
    }

    printf("Starting packet processing...\n");
    while (1) {
        for (uint16_t i = 0; i < nb_ports; i++) {
            struct rte_mbuf *pkts[32];
            uint16_t nb_rx = rte_eth_rx_burst(i, 0, pkts, 32);

            for (uint16_t j = 0; j < nb_rx; j++) {
                filter_and_forward(pkts[j], i);
            }
        }
    }

    return 0;
}
```

