### **Ultra-Low-Latency Packet Filtering & Forwarding in C**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/if_ether.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <pcap.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <errno.h>

// Packet filter configuration (example: allow only TCP/UDP to 192.168.1.100)
#define TARGET_IP "192.168.1.100"
#define FORWARD_IFACE "eth1"  // Interface to forward packets to

// Forwarding socket
int forward_sock = -1;

// Initialize forwarding socket
int init_forward_socket() {
    forward_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (forward_sock < 0) {
        perror("Failed to create forwarding socket");
        return -1;
    }
    return 0;
}

// Forward packet to another interface
void forward_packet(const u_char *packet, int len) {
    struct sockaddr_ll dest;
    memset(&dest, 0, sizeof(dest));

    // Get interface index
    struct ifreq ifr;
    strncpy(ifr.ifr_name, FORWARD_IFACE, IFNAMSIZ);
    if (ioctl(forward_sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl(SIOCGIFINDEX) failed");
        return;
    }
    dest.sll_ifindex = ifr.ifr_ifindex;

    // Send raw packet
    if (sendto(forward_sock, packet, len, 0, (struct sockaddr*)&dest, sizeof(dest)) < 0) {
        perror("Failed to forward packet");
    }
}

// Packet handler (filter and forward)
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    struct iphdr *ip_header = (struct iphdr*)(packet + sizeof(struct ethhdr));

    // Check if it's an IPv4 packet
    if (ip_header->version != 4) return;

    // Check if destination IP matches our target
    char dest_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(ip_header->daddr), dest_ip, INET_ADDRSTRLEN);

    if (strcmp(dest_ip, TARGET_IP) == 0) {
        printf("Forwarding packet to %s (len=%d)\n", dest_ip, pkthdr->len);
        forward_packet(packet, pkthdr->len);
    }
}

int main(int argc, char *argv[]) {
    char *dev = "eth0";  // Default interface
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Initialize forwarding socket
    if (init_forward_socket() < 0) {
        return EXIT_FAILURE;
    }

    // Open live capture on interface
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Could not open device %s: %s\n", dev, errbuf);
        return EXIT_FAILURE;
    }

    // Set filter to capture only IPv4 traffic
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Could not parse filter: %s\n", pcap_geterr(handle));
        return EXIT_FAILURE;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Could not install filter: %s\n", pcap_geterr(handle));
        return EXIT_FAILURE;
    }

    // Start packet processing loop
    printf("Starting packet capture on %s...\n", dev);
    pcap_loop(handle, 0, packet_handler, NULL);

    // Cleanup
    pcap_close(handle);
    close(forward_sock);
    return EXIT_SUCCESS;
}
```

