### **Ultra-Low-Latency Packet Filter & Forwarder (C)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/if_ether.h>
#include <net/ethernet.h>
#include <netinet/in.h>
#include <linux/if_packet.h>
#include <net/if.h>

#define BUFFER_SIZE 65536
#define ETH_FRAME_LEN 1514

// Basic packet filtering (example: allow only ICMP or TCP)
int should_forward(const struct iphdr *ip_header) {
    // Allow ICMP (1) or TCP (6)
    if (ip_header->protocol == IPPROTO_ICMP || ip_header->protocol == IPPROTO_TCP) {
        return 1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <interface> <destination_IP>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *interface = argv[1];
    const char *dest_ip_str = argv[2];

    // Convert destination IP to binary
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    if (inet_pton(AF_INET, dest_ip_str, &dest_addr.sin_addr) != 1) {
        perror("Invalid destination IP");
        exit(EXIT_FAILURE);
    }

    // Create raw socket for packet capture
    int sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Bind to the specified interface
    struct sockaddr_ll sock_addr;
    memset(&sock_addr, 0, sizeof(sock_addr));
    sock_addr.sll_family = AF_PACKET;
    sock_addr.sll_ifindex = if_nametoindex(interface);
    if (bind(sock_fd, (struct sockaddr *)&sock_addr, sizeof(sock_addr)) < 0) {
        perror("Bind failed");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    printf("Packet forwarder running on %s, forwarding to %s\n", interface, dest_ip_str);

    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll sender_addr;
    socklen_t sender_len = sizeof(sender_addr);

    while (1) {
        ssize_t packet_len = recvfrom(sock_fd, buffer, BUFFER_SIZE, 0,
                                     (struct sockaddr *)&sender_addr, &sender_len);
        if (packet_len < 0) {
            perror("Packet receive failed");
            continue;
        }

        // Extract Ethernet header (optional, if needed)
        struct ethhdr *eth_header = (struct ethhdr *)buffer;
        if (ntohs(eth_header->h_proto) != ETH_P_IP) {
            continue; // Skip non-IP packets
        }

        // Extract IP header
        struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (ip_header->version != 4) {
            continue; // Skip non-IPv4 packets
        }

        // Check if packet should be forwarded
        if (should_forward(ip_header)) {
            // Modify destination IP (forwarding logic)
            ip_header->daddr = dest_addr.sin_addr.s_addr;

            // Recalculate checksum (simplified, real-world needs proper checksumming)
            ip_header->check = 0;
            ip_header->check = in_cksum((unsigned short *)ip_header, sizeof(struct iphdr));

            // Send the modified packet
            if (sendto(sock_fd, buffer, packet_len, 0,
                      (struct sockaddr *)&sender_addr, sender_len) < 0) {
                perror("Packet send failed");
            } else {
                printf("Forwarded packet from %s to %s\n",
                       inet_ntoa(*(struct in_addr *)&ip_header->saddr),
                       dest_ip_str);
            }
        }
    }

    close(sock_fd);
    return 0;
}

// Simple checksum function (for IPv4 header)
unsigned short in_cksum(unsigned short *buf, int len) {
    unsigned long sum = 0;
    while (len > 1) {
        sum += *buf++;
        len -= 2;
    }
    if (len == 1) {
        sum += *(unsigned char *)buf;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return (unsigned short)(~sum);
}
```

