```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/ip_icmp.h>
#include <netinet/tcp.h>
#include <net/ethernet.h>
#include <linux/if_packet.h>
#include <net/if.h>

// Define packet buffer size (adjust based on MTU)
#define BUFFER_SIZE 65536

// Function to filter packets (allow only ICMP or TCP)
int should_forward(const u_char *packet) {
    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Check if it's an IPv4 packet
    if (ip_header->version != 4) {
        return 0;
    }

    // Allow ICMP (protocol 1) or TCP (protocol 6)
    if (ip_header->protocol == IPPROTO_ICMP || ip_header->protocol == IPPROTO_TCP) {
        return 1;
    }

    return 0;
}

// Function to forward a packet
void forward_packet(int sockfd, const u_char *packet, int packet_len, struct sockaddr_ll *dest_addr) {
    if (sendto(sockfd, packet, packet_len, 0, (struct sockaddr *)dest_addr, sizeof(*dest_addr)) < 0) {
        perror("sendto failed");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <interface> <destination_IP>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *interface = argv[1];
    const char *dest_ip = argv[2];

    // Create raw socket for packet capture
    int sock_raw = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_raw < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Create raw socket for forwarding
    int sock_forward = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (sock_forward < 0) {
        perror("forwarding socket creation failed");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    // Set socket options to allow IP header manipulation
    int one = 1;
    if (setsockopt(sock_forward, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        perror("setsockopt failed");
        close(sock_raw);
        close(sock_forward);
        exit(EXIT_FAILURE);
    }

    // Set up destination address for forwarding
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_addr.s_addr = inet_addr(dest_ip);

    // Set up packet socket for forwarding (needed for raw packet sending)
    struct sockaddr_ll packet_dest_addr;
    memset(&packet_dest_addr, 0, sizeof(packet_dest_addr));
    packet_dest_addr.sll_family = AF_PACKET;
    packet_dest_addr.sll_ifindex = if_nametoindex(interface);
    packet_dest_addr.sll_protocol = htons(ETH_P_ALL);

    printf("Starting low-latency forwarder on %s, forwarding to %s...\n", interface, dest_ip);

    u_char buffer[BUFFER_SIZE];
    while (1) {
        // Receive a packet
        int packet_len = recvfrom(sock_raw, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (packet_len < 0) {
            perror("recvfrom failed");
            continue;
        }

        // Check if the packet should be forwarded
        if (should_forward(buffer)) {
            forward_packet(sock_forward, buffer, packet_len, (struct sockaddr_ll *)&packet_dest_addr);
        }
    }

    close(sock_raw);
    close(sock_forward);
    return 0;
}
