#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Simple IP filter (allow only TCP to port 80)
int should_forward(struct rte_mbuf *pkt) {
    struct rte_ether_hdr *eth = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);
    if (eth->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) return 0;

    struct rte_ipv4_hdr *ip = (struct rte_ipv4_hdr *)(eth + 1);
    if (ip->next_proto_id != IPPROTO_TCP) return 0;

    struct rte_tcp_hdr *tcp = (struct rte_tcp_hdr *)(ip + 1);
    if (rte_be_to_cpu_16(tcp->dst_port) == 80) return 1;
    return 0;
}

int main(int argc, char **argv) {
    // Initialize DPDK
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "EAL init failed\n");

    // Configure port 0
    uint16_t port_id = 0;
    struct rte_eth_conf port_conf = {0};
    ret = rte_eth_dev_configure(port_id, 1, 1, &port_conf);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Port config failed\n");

    // Set up RX/TX queues
    ret = rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, NULL);
    if (ret < 0) rte_exit(EXIT_FAILURE, "RX queue setup failed\n");

    ret = rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL);
    if (ret < 0) rte_exit(EXIT_FAILURE, "TX queue setup failed\n");

    // Start port
    ret = rte_eth_dev_start(port_id);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Port start failed\n");

    // Main loop: receive, filter, forward
    struct rte_mbuf *pkts_burst[32];
    while (1) {
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, pkts_burst, 32);
        if (nb_rx > 0) {
            for (int i = 0; i < nb_rx; i++) {
                if (should_forward(pkts_burst[i])) {
                    printf("Forwarding packet (size: %d bytes)\n", pkts_burst[i]->pkt_len);
                    // In a real app, forward to another port here
                }
                rte_pktmbuf_free(pkts_burst[i]);
            }
        }
    }

    return 0;
}
