### **Code: Ultra-Low-Latency Packet Filter & Forwarder (C)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <arpa/inet.h>
#include <linux/if_packet.h>
#include <net/if.h>

#define BUFFER_SIZE 65536

// Simple IP packet filter (allow/deny based on source/destination IP)
int should_forward(struct iphdr *ip_header) {
    // Example: Allow only packets from 192.168.1.100
    uint32_t allowed_ip = inet_addr("192.168.1.100");
    return (ip_header->saddr == allowed_ip);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_interface> <output_interface>\n", argv[0]);
        return 1;
    }

    // Create raw socket for packet capture
    int sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_fd < 0) {
        perror("socket");
        return 1;
    }

    // Bind to input interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(argv[1]);
    if (bind(sock_fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sock_fd);
        return 1;
    }

    // Open output interface for forwarding
    int out_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (out_fd < 0) {
        perror("socket");
        close(sock_fd);
        return 1;
    }

    // Set output interface
    struct sockaddr_ll out_sll;
    memset(&out_sll, 0, sizeof(out_sll));
    out_sll.sll_family = AF_PACKET;
    out_sll.sll_ifindex = if_nametoindex(argv[2]);

    printf("Forwarding packets from %s to %s...\n", argv[1], argv[2]);

    char buffer[BUFFER_SIZE];
    while (1) {
        ssize_t bytes_read = recv(sock_fd, buffer, BUFFER_SIZE, 0);
        if (bytes_read < 0) {
            perror("recv");
            break;
        }

        // Parse Ethernet header
        struct ethhdr *eth_header = (struct ethhdr *)buffer;
        if (ntohs(eth_header->h_proto) != ETH_P_IP) {
            continue; // Skip non-IP packets
        }

        // Parse IP header
        struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (should_forward(ip_header)) {
            // Forward the packet
            if (sendto(out_fd, buffer, bytes_read, 0, (struct sockaddr *)&out_sll, sizeof(out_sll)) < 0) {
                perror("sendto");
            }
        }
    }

    close(sock_fd);
    close(out_fd);
    return 0;
}
```

