### **1. Basic Version (Raw Sockets)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/if_ether.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <linux/if_packet.h>

#define BUFFER_SIZE 65536

// Packet filter: Allow only packets from a specific source IP
int filter_packet(const u_char *packet, const char *allowed_src_ip) {
    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));
    char src_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(ip_header->saddr), src_ip, INET_ADDRSTRLEN);

    if (strcmp(src_ip, allowed_src_ip) == 0) {
        return 1; // Allow packet
    }
    return 0; // Drop packet
}

// Forward packet to a destination IP
void forward_packet(int sockfd, const u_char *packet, int packet_len, const char *dest_ip, int dest_port) {
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(dest_port);
    inet_pton(AF_INET, dest_ip, &dest_addr.sin_addr);

    sendto(sockfd, packet, packet_len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
}

int main() {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set interface (e.g., "eth0")
    struct ifreq ifr;
    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ);
    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("Interface error");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);
    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("Bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Packet capture started. Press Ctrl+C to stop.\n");

    u_char buffer[BUFFER_SIZE];
    const char *allowed_src_ip = "192.168.1.100"; // Example: Allow only this IP
    const char *dest_ip = "192.168.1.200";        // Forward to this IP
    int dest_port = 9000;                          // Forward to this port

    while (1) {
        int packet_len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (packet_len < 0) {
            perror("Packet receive failed");
            continue;
        }

        if (filter_packet(buffer, allowed_src_ip)) {
            forward_packet(sockfd, buffer, packet_len, dest_ip, dest_port);
            printf("Forwarded packet from %s to %s:%d\n", allowed_src_ip, dest_ip, dest_port);
        }
    }

    close(sockfd);
    return 0;
}
```

