#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define MAX_LOG_SIZE (10 * 1024 * 1024)  // 10MB max log size
#define ROTATE_COUNT 5                   // Keep 5 rotated logs
#define ROTATE_INTERVAL 3600             // Rotate every hour (3600 sec)

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        keep_running = 0;
    }
}

void rotate_log(const char *log_path) {
    char rotated_path[256];
    struct stat st;

    // Check if log exists and is too large
    if (stat(log_path, &st) == -1 || st.st_size < MAX_LOG_SIZE) {
        return;
    }

    // Close and rename old logs (e.g., log.1, log.2, etc.)
    for (int i = ROTATE_COUNT - 1; i >= 0; i--) {
        if (i == 0) {
            snprintf(rotated_path, sizeof(rotated_path), "%s.%d", log_path, i + 1);
        } else {
            snprintf(rotated_path, sizeof(rotated_path), "%s.%d", log_path, i);
        }

        if (i == 0) {
            rename(log_path, rotated_path);
        } else if (access(rotated_path, F_OK) != -1) {
            char next_path[256];
            snprintf(next_path, sizeof(next_path), "%s.%d", log_path, i + 1);
            rename(rotated_path, next_path);
        }
    }

    // Truncate the current log
    int fd = open(log_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Failed to truncate log");
    } else {
        close(fd);
    }
}

void monitor_log(const char *log_path) {
    time_t last_rotate = time(NULL);

    while (keep_running) {
        time_t now = time(NULL);

        // Rotate if time interval elapsed or log is too large
        if (now - last_rotate >= ROTATE_INTERVAL) {
            rotate_log(log_path);
            last_rotate = now;
        }

        sleep(1);  // Reduce CPU usage
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting log rotation daemon for: %s\n", log_path);
    monitor_log(log_path);

    printf("Shutting down...\n");
    return 0;
}
```

