use std::fs::{File, OpenOptions};
use std::io::{self, Read, Write, Seek, SeekFrom};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};
use std::env;
use std::process;

const MAX_LOG_SIZE: u64 = 1024 * 1024; // 1MB (adjust as needed)
const MAX_LOG_AGE_SECS: u64 = 86400;  // 24 hours (adjust as needed)
const BUFFER_SIZE: usize = 4096;      // 4KB read/write buffer

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <log_file_path>", args[0]);
        process::exit(1);
    }

    let log_path = PathBuf::from(&args[1]);
    if !log_path.exists() {
        eprintln!("Log file does not exist: {}", log_path.display());
        process::exit(1);
    }

    if let Err(e) = rotate_log(&log_path) {
        eprintln!("Error rotating log: {}", e);
        process::exit(1);
    }
}

fn rotate_log(log_path: &Path) -> io::Result<()> {
    let metadata = log_path.metadata()?;
    let file_size = metadata.len();
    let modified_time = metadata.modified()?.duration_since(UNIX_EPOCH).unwrap().as_secs();

    let current_time = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();

    // Check if rotation is needed (size or age)
    if file_size >= MAX_LOG_SIZE || (current_time - modified_time) >= MAX_LOG_AGE_SECS {
        let rotated_path = generate_rotated_path(log_path)?;
        rename_and_truncate(log_path, &rotated_path)?;
    }

    Ok(())
}

fn generate_rotated_path(original_path: &Path) -> io::Result<PathBuf> {
    let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
    let mut rotated_path = original_path.to_path_buf();
    rotated_path.set_extension(format!("{}.{}", timestamp, rotated_path.extension().unwrap_or_default().to_str().unwrap_or("log")));
    Ok(rotated_path)
}

fn rename_and_truncate(original_path: &Path, rotated_path: &Path) -> io::Result<()> {
    // Rename the old log (atomic operation)
    std::fs::rename(original_path, rotated_path)?;

    // Create a new empty log file
    OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(original_path)?;

    Ok(())
}
```

