### **`logrotate.c`**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>

#define MAX_LOG_SIZE (10 * 1024 * 1024)  // 10MB per log file
#define LOG_DIR "./logs/"
#define BASE_LOG_NAME "app.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void rotate_log(const char *log_path) {
    struct stat st;
    if (stat(log_path, &st) == -1 || st.st_size < MAX_LOG_SIZE) {
        return;  // No rotation needed
    }

    // Generate a new log filename with timestamp
    time_t now = time(NULL);
    char new_log_path[256];
    snprintf(new_log_path, sizeof(new_log_path), "%s%s.%ld", LOG_DIR, BASE_LOG_NAME, now);

    // Rename the current log
    if (rename(log_path, new_log_path) == -1) {
        perror("Failed to rotate log");
    }
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);  // Parent exits

    // Child continues
    umask(0);
    setsid();

    // Redirect stdin/stdout/stderr to /dev/null
    freopen("/dev/null", "r", stdin);
    freopen("/dev/null", "w", stdout);
    freopen("/dev/null", "w", stderr);
}

int main() {
    daemonize();

    // Set up signal handler for graceful shutdown
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Ensure log directory exists
    mkdir(LOG_DIR, 0755);

    char log_path[256];
    snprintf(log_path, sizeof(log_path), "%s%s", LOG_DIR, BASE_LOG_NAME);

    while (keep_running) {
        rotate_log(log_path);
        sleep(60);  // Check every minute
    }

    return EXIT_SUCCESS;
}
```

