        eprintln!("ERROR: Memory limit exceeded! Current: {} bytes, Max: {} bytes",
            current_usage, max_memory_bytes);
        process::abort(); // Forceful exit to prevent OOM
    }
}

/// Tracks memory allocations (simplified for demo).
fn track_allocation(size: usize) {
    MEMORY_USAGE.fetch_add(size, Ordering::Relaxed);
}

/// Tracks memory deallocations (simplified for demo).
fn track_deallocation(size: usize) {
    MEMORY_USAGE.fetch_sub(size, Ordering::Relaxed);
}

/// Rotates logs by moving old files to a backup directory.
fn rotate_logs(
    log_dir: &Path,
    backup_dir: &Path,
    max_log_size_bytes: usize,
    max_retention_days: u64,
) -> io::Result<()> {
    // Ensure backup directory exists
    fs::create_dir_all(backup_dir)?;

    // Get current timestamp for log rotation
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();

    // Iterate over log files
    for entry in fs::read_dir(log_dir)? {
        let entry = entry?;
        let path = entry.path();
        let metadata = fs::metadata(&path)?;

        // Skip directories
        if metadata.is_dir() {
            continue;
        }

        // Check if log is too large
        if metadata.len() > max_log_size_bytes as u64 {
            let backup_path = backup_dir.join(format!(
                "{}_{}.log",
                path.file_stem().unwrap().to_string_lossy(),
                now
            ));

            // Move log to backup directory
            fs::rename(&path, &backup_path)?;
            println!("Rotated log: {} → {}", path.display(), backup_path.display());
        }

        // Delete old backups (simplified retention)
        if let Ok(modified_time) = metadata.modified() {
            let age_days = (now - modified_time.duration_since(UNIX_EPOCH).unwrap().as_secs()) / 86400;
            if age_days > max_retention_days {
                fs::remove_file(&path)?;
                println!("Deleted old log: {}", path.display());
            }
        }
    }

    Ok(())
}

/// Writes a log message to a file while tracking memory.
fn write_log(log_file: &mut File, message: &str) -> io::Result<()> {
    let bytes_written = message.as_bytes().len();
    track_allocation(bytes_written);

    log_file.write_all(message.as_bytes())?;
    log_file.write_all(b"\n")?;

    Ok(())
}

fn main() {
    // Configuration
    let log_dir = PathBuf::from("./logs");
    let backup_dir = PathBuf::from("./logs_backup");
    let max_log_size_bytes = 1024 * 1024; // 1MB per log
    let max_retention_days = 7; // Delete logs older than 7 days
    let max_memory_bytes = 1024 * 1024 * 10; // 10MB memory limit

    // Ensure log directory exists
    fs::create_dir_all(&log_dir).expect("Failed to create log directory");

    // Open (or create) the active log file
    let mut log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_dir.join("app.log"))
        .expect("Failed to open log file");

    // Simulate log rotation and writing
    for i in 0..100 {
        let message = format!("Log entry #{}", i);
        write_log(&mut log_file, &message).expect("Failed to write log");

        // Check memory usage
        check_memory_limit(max_memory_bytes);

        // Rotate logs every 10 entries (for demo)
