### **`log_rotator.c`** (Memory-Constrained Log Rotation Daemon)
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

#define MAX_LOG_SIZE (1024 * 1024)  // 1MB rotation threshold
#define BUFFER_SIZE 4096            // Read/write buffer size

void rotate_log(const char *log_path) {
    char rotated_path[256];
    snprintf(rotated_path, sizeof(rotated_path), "%s.%ld", log_path, time(NULL));

    // Open source and destination files
    int src_fd = open(log_path, O_RDONLY);
    if (src_fd < 0) {
        perror("Failed to open log file");
        return;
    }

    int dst_fd = open(rotated_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dst_fd < 0) {
        perror("Failed to create rotated log");
        close(src_fd);
        return;
    }

    // Copy data in chunks
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    while ((bytes_read = read(src_fd, buffer, BUFFER_SIZE)) > 0) {
        if (write(dst_fd, buffer, bytes_read) != bytes_read) {
            perror("Failed to write to rotated log");
            break;
        }
    }

    // Cleanup
    close(src_fd);
    close(dst_fd);

    // Truncate the original log
    if (truncate(log_path, 0) != 0) {
        perror("Failed to truncate log");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_path = argv[1];
    struct stat st;

    while (1) {
        if (stat(log_path, &st) == 0 && st.st_size >= MAX_LOG_SIZE) {
            rotate_log(log_path);
        }
        sleep(1);  // Check every second (adjust as needed)
    }

    return EXIT_SUCCESS;
}
```

