#define MAX_LOG_SIZE (1024 * 1024)  // 1MB max log size (adjust as needed)
#define MAX_BACKUPS 5               // Keep up to 5 rotated logs

void rotate_log(const char *log_path) {
    char backup_path[256];
    struct stat st;

    // Check if log exists and exceeds size limit
    if (stat(log_path, &st) == 0 && st.st_size >= MAX_LOG_SIZE) {
        // Delete oldest backup if we have too many
        for (int i = MAX_BACKUPS - 1; i >= 0; i--) {
            snprintf(backup_path, sizeof(backup_path), "%s.%d", log_path, i);
            if (i == MAX_BACKUPS - 1) {
                remove(backup_path);  // Delete the oldest backup
            } else if (access(backup_path, F_OK) == 0) {
                char next_backup[256];
                snprintf(next_backup, sizeof(next_backup), "%s.%d", log_path, i + 1);
                rename(backup_path, next_backup);  // Shift backups up
            }
        }

        // Rotate current log to .1
        snprintf(backup_path, sizeof(backup_path), "%s.1", log_path);
        rename(log_path, backup_path);

        // Reopen log file (truncated)
        FILE *log_file = fopen(log_path, "w");
        if (log_file) {
            fclose(log_file);
        }
    }
}

