### **`logrotate.c`**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <time.h>

#define MAX_LOG_SIZE (1024 * 1024)  // 1MB size limit
#define MAX_PATH_LEN 256

void rotate_log(const char *log_path) {
    char rotated_path[MAX_PATH_LEN];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    // Generate rotated filename (e.g., "app.log.2024-05-20_14-30-00")
    snprintf(rotated_path, MAX_PATH_LEN, "%s.%04d-%02d-%02d_%02d-%02d-%02d",
             log_path, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
             tm->tm_hour, tm->tm_min, tm->tm_sec);

    // Rename the log file
    if (rename(log_path, rotated_path) != 0) {
        perror("Failed to rotate log");
        return;
    }

    // Recreate the log file (empty)
    FILE *new_log = fopen(log_path, "w");
    if (!new_log) {
        perror("Failed to recreate log file");
        return;
    }
    fclose(new_log);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    struct stat st;

    while (1) {
        if (stat(log_path, &st) != 0) {
            perror("Failed to check log file");
            sleep(1);
            continue;
        }

        if (st.st_size >= MAX_LOG_SIZE) {
            rotate_log(log_path);
        }

        sleep(1);  // Check every second (adjust as needed)
    }

    return 0;
}
```

---

### **Key Features:**
1. **Memory Efficiency:**
   - No dynamic memory allocation (only stack buffers).
   - Uses `stat()` to check file size without loading the file into memory.
   - Minimal I/O operations (only renames and recreates the log file).

2. **Log Rotation Logic:**
   - Rotates logs when they exceed `MAX_LOG_SIZE` (1MB by default).
   - Appends a timestamp to the rotated filename (e.g., `app.log.2024-05-20_14-30-00`).

3. **Strict Constraints:**
   - No external dependencies (pure C).
   - Runs in a loop with minimal CPU usage (sleeps between checks).

