use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::path::Path;
use std::time::SystemTime;

/// Rotates a log file if it exceeds `max_size_bytes`.
/// Returns `Ok(())` on success, or an error if rotation fails.
fn rotate_log(log_path: &str, max_size_bytes: u64) -> io::Result<()> {
    let path = Path::new(log_path);

    // Check if the log file exists and exceeds the size limit.
    if path.exists() {
        let metadata = std::fs::metadata(log_path)?;
        if metadata.len() >= max_size_bytes {
            // Generate a new filename with a timestamp.
            let timestamp = SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)?
                .as_secs();
            let rotated_path = format!("{}.{}.rotated", log_path, timestamp);

            // Rename the old log file.
            std::fs::rename(log_path, &rotated_path)?;
            println!("Rotated log: {} → {}", log_path, rotated_path);
        }
    }

    // Ensure the log file exists (create if it doesn't).
    OpenOptions::new()
        .create(true)
        .write(true)
        .append(true)
        .open(log_path)?;

    Ok(())
}

/// Writes a log message to the file.
fn write_log(log_path: &str, message: &str) -> io::Result<()> {
    let mut file = OpenOptions::new()
        .write(true)
        .append(true)
        .open(log_path)?;
    writeln!(file, "{}", message)?;
    Ok(())
}

fn main() -> io::Result<()> {
    const LOG_FILE: &str = "app.log";
    const MAX_LOG_SIZE: u64 = 1024 * 1024; // 1MB

    // Rotate the log if needed.
    rotate_log(LOG_FILE, MAX_LOG_SIZE)?;

    // Write a test log message.
    write_log(LOG_FILE, "This is a test log entry.")?;

    println!("Log written successfully.");
    Ok(())
}
```

