use std::fs;
use std::process::Command;
use std::thread;
use std::time::{Duration, Instant};
use sysinfo::{System, SystemExt, CpuExt, DiskExt, NetworkExt};
use log::{info, error, LevelFilter};
use simple_logger::SimpleLogger;

fn main() {
    // Initialize logging
    SimpleLogger::new()
        .with_level(LevelFilter::Info)
        .init()
        .unwrap();

    info!("Starting sysmon daemon...");

    // Configuration
    let poll_interval = Duration::from_secs(5); // Check every 5 seconds
    let log_file = "/var/log/sysmon.log";

    // Create log file if it doesn't exist
    if !fs::metadata(log_file).is_ok() {
        fs::File::create(log_file).expect("Failed to create log file");
    }

    // Main monitoring loop
    loop {
        let start_time = Instant::now();

        // Get system metrics
        let mut sys = System::new_all();
        sys.refresh_all();

        // Log CPU usage
        let cpu_usage = sys.global_cpu_info().cpu_usage();
        info!("CPU Usage: {:.2}%", cpu_usage);

        // Log Memory usage
        let total_mem = sys.total_memory() as f64 / (1024.0 * 1024.0 * 1024.0); // GB
        let used_mem = sys.used_memory() as f64 / (1024.0 * 1024.0 * 1024.0); // GB
        info!("Memory: {:.2}GB / {:.2}GB ({:.2}% used)", used_mem, total_mem, (used_mem / total_mem) * 100.0);

        // Log Disk usage
        for disk in sys.disks() {
            let total_space = disk.total_space() as f64 / (1024.0 * 1024.0 * 1024.0); // GB
            let available_space = disk.available_space() as f64 / (1024.0 * 1024.0 * 1024.0); // GB
            info!(
                "Disk {}: {:.2}GB / {:.2}GB ({:.2}% free)",
                disk.name().to_string_lossy(),
                available_space,
                total_space,
                (available_space / total_space) * 100.0
            );
        }

        // Log Network usage
        let networks = sys.networks();
        for (interface, data) in networks {
            info!(
                "Network {}: Received: {:.2}MB, Transmitted: {:.2}MB",
                interface,
                data.received() as f64 / (1024.0 * 1024.0),
                data.transmitted() as f64 / (1024.0 * 1024.0)
            );
        }

        // Log process count
        info!("Running Processes: {}", sys.processes().len());

        // Sleep until next poll
        let elapsed = start_time.elapsed();
        if elapsed < poll_interval {
            thread::sleep(poll_interval - elapsed);
        }
    }
}
```

