### **System Resource Monitor Daemon (`sysmon`)**
```rust
use std::fs;
use std::io::{self, Write};
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
struct SystemMetrics {
    cpu_usage: f64,
    memory_used: u64,
    memory_total: u64,
    disk_usage: f64,
    network_rx: u64,
    network_tx: u64,
    timestamp: Instant,
}

impl SystemMetrics {
    fn new() -> Self {
        SystemMetrics {
            cpu_usage: 0.0,
            memory_used: 0,
            memory_total: 0,
            disk_usage: 0.0,
            network_rx: 0,
            network_tx: 0,
            timestamp: Instant::now(),
        }
    }

    fn collect(&mut self) {
        // CPU Usage (Linux-specific, requires /proc/stat)
        if let Ok(cpu_stats) = fs::read_to_string("/proc/stat") {
            let lines: Vec<&str> = cpu_stats.lines().collect();
            if let Some(cpu_line) = lines.get(0) {
                let parts: Vec<&str> = cpu_line.split_whitespace().collect();
                if parts.len() >= 5 {
                    let user = parts[1].parse::<u64>().unwrap_or(0);
                    let nice = parts[2].parse::<u64>().unwrap_or(0);
                    let system = parts[3].parse::<u64>().unwrap_or(0);
                    let idle = parts[4].parse::<u64>().unwrap_or(0);
                    let total = user + nice + system + idle;
                    self.cpu_usage = 100.0 - (idle as f64 / total as f64 * 100.0);
                }
            }
        }

        // Memory Usage (Linux-specific, requires /proc/meminfo)
        if let Ok(mem_info) = fs::read_to_string("/proc/meminfo") {
            let lines: Vec<&str> = mem_info.lines().collect();
            for line in lines {
                if line.starts_with("MemTotal:") {
                    self.memory_total = line.split_whitespace().nth(1).unwrap_or("0").parse().unwrap_or(0);
                } else if line.starts_with("MemAvailable:") {
                    self.memory_used = self.memory_total - line.split_whitespace().nth(1).unwrap_or("0").parse().unwrap_or(0);
                }
            }
        }

        // Disk Usage (Linux-specific, requires `df`)
        if let Ok(output) = Command::new("df").arg("-h").arg("/").output() {
            if let Ok(df_output) = String::from_utf8(output.stdout) {
                let lines: Vec<&str> = df_output.lines().collect();
                if let Some(disk_line) = lines.get(1) {
                    let parts: Vec<&str> = disk_line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        self.disk_usage = parts[4].trim_end_matches('%').parse().unwrap_or(0.0);
                    }
                }
            }
        }

        // Network Stats (Linux-specific, requires /proc/net/dev)
        if let Ok(net_stats) = fs::read_to_string("/proc/net/dev") {
            let lines: Vec<&str> = net_stats.lines().collect();
            for line in lines {
                if line.contains("eth0") || line.contains("wlan0") {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 10 {
                        self.network_rx = parts[1].parse().unwrap_or(0);
                        self.network_tx = parts[9].parse().unwrap_or(0);
                    }
                }
            }
        }

        self.timestamp = Instant::now();
    }
}

fn log_metrics(metrics: &SystemMetrics) {
    println!(
        "[{}] CPU: {:.2}% | Memory: {}MB/{}MB | Disk: {:.2}% | Network: RX={} TX={}",
        metrics.timestamp.elapsed().as_secs(),
        metrics.cpu_usage,
        metrics.memory_used / 1024,
        metrics.memory_total / 1024,
        metrics.disk_usage,
        metrics.network_rx,
        metrics.network_tx
    );
}

fn main() {
    let metrics = Arc::new(Mutex::new(SystemMetrics::new()));
    let metrics_clone = Arc::clone(&metrics);

    // Spawn a thread to collect metrics every 5 seconds
    thread::spawn(move || loop {
        {
            let mut metrics = metrics_clone.lock().unwrap();
            metrics.collect();
            log_metrics(&metrics);
        }
        thread::sleep(Duration::from_secs(5));
    });

    // Main thread: Keep the daemon running
    println!("System Monitor Daemon started. Press Ctrl+C to exit.");
    loop {
        thread::sleep(Duration::from_secs(1));
    }
}
```

