### **System Resource Monitor Daemon (`sysmon.c`)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/sysinfo.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define DAEMON_NAME "sysmon"
#define LOG_FILE "/var/log/sysmon.log"
#define PID_FILE "/var/run/sysmon.pid"
#define INTERVAL 5 // Check every 5 seconds

// Function to write PID to file
void write_pid() {
    FILE *pid_file = fopen(PID_FILE, "w");
    if (pid_file) {
        fprintf(pid_file, "%d", getpid());
        fclose(pid_file);
    }
}

// Function to log system stats
void log_system_stats() {
    struct sysinfo info;
    struct rusage usage;
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (sysinfo(&info) != 0) {
        perror("sysinfo failed");
        return;
    }

    if (getrusage(RUSAGE_SELF, &usage) != 0) {
        perror("getrusage failed");
        return;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log, "[%s] System Stats:\n", timestamp);
    fprintf(log, "  - Uptime: %ld days, %ld:%02ld:%02ld\n",
            info.uptime / 86400,
            (info.uptime % 86400) / 3600,
            (info.uptime % 3600) / 60,
            info.uptime % 60);
    fprintf(log, "  - Load Avg (1/5/15 min): %.2f, %.2f, %.2f\n",
            info.loads[0] / 65536.0,
            info.loads[1] / 65536.0,
            info.loads[2] / 65536.0);
    fprintf(log, "  - Total RAM: %lu MB, Free: %lu MB\n",
            info.totalram / 1024 / 1024,
            info.freeram / 1024 / 1024);
    fprintf(log, "  - CPU Usage: %.2f%%\n",
            (double)(usage.ru_utime.tv_sec + usage.ru_stime.tv_sec) / (double)info.uptime * 100);
    fclose(log);
}

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        remove(PID_FILE);
        exit(0);
    }
}

int main() {
    // Fork the process to run in the background
    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Create a new session and detach from terminal
    if (setsid() < 0) {
        perror("setsid failed");
        exit(EXIT_FAILURE);
    }

    // Change working directory to root
    if (chdir("/") < 0) {
        perror("chdir failed");
        exit(EXIT_FAILURE);
    }

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Write PID to file
    write_pid();

    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Main daemon loop
    while (1) {
        log_system_stats();
        sleep(INTERVAL);
    }

    return 0;
}
```

