#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/sysinfo.h>
#include <sys/statvfs.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>

#define LOG_FILE "/var/log/sysmon.log"
#define MAX_CPU_USAGE 90.0  // Threshold for CPU alert
#define MAX_MEM_USAGE 85.0  // Threshold for memory alert

// Global variables
volatile sig_atomic_t keep_running = 1;

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        keep_running = 0;
    }
}

// Log system events to a file
void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s\n", time_str, message);
    fclose(log_file);
}

// Get CPU usage (simplified)
float get_cpu_usage() {
    static unsigned long long last_total = 0, last_idle = 0;
    FILE *stat_file = fopen("/proc/stat", "r");
    if (!stat_file) {
        perror("Failed to read /proc/stat");
        return 0.0;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    fscanf(stat_file, "cpu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
    fclose(stat_file);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long long diff_total = total - last_total;
    unsigned long long diff_idle = idle - last_idle;

    last_total = total;
    last_idle = idle;

    if (diff_total == 0) return 0.0;
    return (1.0 - (float)diff_idle / diff_total) * 100.0;
}

// Get memory usage
float get_memory_usage() {
    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        perror("Failed to get system info");
        return 0.0;
    }
    return ((float)(info.totalram - info.freeram) / info.totalram) * 100.0;
}

// Get disk usage
float get_disk_usage(const char *path) {
    struct statvfs stat;
    if (statvfs(path, &stat) != 0) {
        perror("Failed to get disk stats");
        return 0.0;
    }
    return ((float)(stat.f_blocks - stat.f_bfree) / stat.f_blocks) * 100.0;
}

// Monitor system resources
void monitor_system() {
    while (keep_running) {
        float cpu = get_cpu_usage();
        float mem = get_memory_usage();
        float disk = get_disk_usage("/");

        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "CPU: %.2f%%, Memory: %.2f%%, Disk: %.2f%%", cpu, mem, disk);
        log_event(log_msg);

        if (cpu > MAX_CPU_USAGE) {
            snprintf(log_msg, sizeof(log_msg), "WARNING: High CPU usage (%.2f%%)", cpu);
            log_event(log_msg);
        }

        if (mem > MAX_MEM_USAGE) {
            snprintf(log_msg, sizeof(log_msg), "WARNING: High memory usage (%.2f%%)", mem);
            log_event(log_msg);
        }

        sleep(5); // Check every 5 seconds
    }
}

int main() {
    // Daemonize the process
    pid_t pid = fork();
    if (pid < 0) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits

    // Child continues as daemon
    umask(0);
    setsid();

    // Redirect stdin, stdout, stderr to /dev/null
    int fd = open("/dev/null", O_RDWR);
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    close(fd);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("System monitoring daemon started");

    monitor_system();

    log_event("System monitoring daemon stopped");
    return EXIT_SUCCESS;
}
