### **Code Implementation (`main.rs`)**
```rust
use std::{
    fs::File,
    io::{self, Write},
    process::{Command, Stdio},
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    thread,
    time::{Duration, Instant},
};
use sysinfo::{ProcessExt, System, SystemExt};

#[derive(Debug, Clone)]
struct Config {
    log_file: Option<String>,
    cpu_threshold: f32,       // Max allowed CPU usage per process (%)
    memory_threshold: u64,     // Max allowed memory per process (MB)
    check_interval: u64,       // Seconds between checks
}

impl Default for Config {
    fn default() -> Self {
        Config {
            log_file: Some("system_monitor.log".to_string()),
            cpu_threshold: 80.0,  // 80% CPU usage
            memory_threshold: 2048, // 2GB RAM
            check_interval: 5,      // 5 seconds
        }
    }
}

fn log_message(config: &Config, message: &str) {
    let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    let log_entry = format!("[{}] {}\n", timestamp, message);

    // Print to stdout
    println!("{}", log_entry);

    // Write to log file if specified
    if let Some(log_file) = &config.log_file {
        if let Ok(mut file) = File::options().append(true).create(true).open(log_file) {
            let _ = file.write_all(log_entry.as_bytes());
        }
    }
}

fn monitor_system(config: &Config, running: Arc<AtomicBool>) {
    let mut system = System::new_all();
    let mut last_check = Instant::now();

    while running.load(Ordering::Relaxed) {
        if last_check.elapsed() >= Duration::from_secs(config.check_interval) {
            system.refresh_all();

            // Log system-wide stats
            log_message(
                config,
                &format!(
                    "System: CPU: {:.2}%, RAM: {:.2}GB/{:.2}GB, Disk: {:.2}GB/{:.2}GB",
                    system.global_cpu_info().cpu_usage(),
                    system.used_memory() as f64 / 1024.0 / 1024.0 / 1024.0,
                    system.total_memory() as f64 / 1024.0 / 1024.0 / 1024.0,
                    system.used_swap() as f64 / 1024.0 / 1024.0 / 1024.0,
                    system.total_swap() as f64 / 1024.0 / 1024.0 / 1024.0,
                ),
            );

            // Check each process
            for (pid, process) in system.processes() {
                let cpu_usage = process.cpu_usage();
                let memory_usage = process.memory() / 1024 / 1024; // MB

                if cpu_usage > config.cpu_threshold {
                    log_message(
                        config,
                        &format!(
                            "WARNING: Process {} ({}) using {:.2}% CPU (threshold: {:.2}%)",
                            pid,
                            process.name(),
                            cpu_usage,
                            config.cpu_threshold
                        ),
                    );
                    // Optional: Kill the process (uncomment to enable)
                    // kill_process(pid.as_u32());
                }

                if memory_usage > config.memory_threshold {
                    log_message(
                        config,
                        &format!(
                            "WARNING: Process {} ({}) using {}MB RAM (threshold: {}MB)",
                            pid,
                            process.name(),
                            memory_usage,
                            config.memory_threshold
                        ),
                    );
                    // Optional: Kill the process (uncomment to enable)
                    // kill_process(pid.as_u32());
                }
            }

            last_check = Instant::now();
        }

        thread::sleep(Duration::from_millis(100));
    }
}

fn kill_process(pid: u32) {
    if let Err(e) = Command::new("kill").arg(pid.to_string()).status() {
        eprintln!("Failed to kill process {}: {}", pid, e);
    }
}

fn main() {
    let config = Config::default();
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    // Handle Ctrl+C (SIGINT)
    ctrlc::set_handler(move || {
        r.store(false, Ordering::Relaxed);
        println!("Shutting down gracefully...");
    })
    .expect("Error setting Ctrl-C handler");

    log_message(&config, "System monitor started.");
    monitor_system(&config, running);
    log_message(&config, "System monitor stopped.");
}
```

