```rust
use std::fs::{File, OpenOptions};
use std::io::{Write, BufWriter};
use std::process::{Command, exit};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};
use sysinfo::{System, SystemExt, ProcessExt, CpuExt, DiskExt, NetworkExt};

static RUNNING: AtomicBool = AtomicBool::new(true);

fn handle_signal() {
    ctrlc::set_handler(move || {
        println!("\nShutting down gracefully...");
        RUNNING.store(false, Ordering::SeqCst);
    }).expect("Failed to set Ctrl-C handler");
}

fn log_resource_usage(system: &mut System, log_file: &mut BufWriter<File>) {
    system.refresh_all();

    // CPU Usage
    let cpu_usage = system.global_cpu_info().cpu_usage();
    writeln!(log_file, "CPU Usage: {:.2}%", cpu_usage).unwrap();

    // Memory Usage
    let total_mem = system.total_memory() as f64 / (1024 * 1024 * 1024); // GB
    let used_mem = system.used_memory() as f64 / (1024 * 1024 * 1024); // GB
    writeln!(log_file, "Memory: {:.2}GB / {:.2}GB ({:.2}%)",
        used_mem, total_mem, (used_mem / total_mem) * 100.0).unwrap();

    // Disk Usage
    for disk in system.disks() {
        let total = disk.total_space() as f64 / (1024 * 1024 * 1024); // GB
        let free = disk.available_space() as f64 / (1024 * 1024 * 1024); // GB
        writeln!(log_file, "Disk {}: {:.2}GB free / {:.2}GB total ({:.2}%)",
            disk.name().to_string_lossy(),
            free, total, (free / total) * 100.0).unwrap();
    }

    // Network Usage
    for (interface, data) in system.networks() {
        writeln!(log_file, "Network {}: {} bytes received, {} bytes sent",
            interface, data.received(), data.transmitted()).unwrap();
    }

    writeln!(log_file, "---").unwrap();
}

fn kill_process(pid: u32) -> Result<(), String> {
    if let Ok(mut process) = sysinfo::Process::new(pid) {
        if process.kill() {
            Ok(())
        } else {
            Err(format!("Failed to kill process {}", pid))
        }
    } else {
        Err(format!("Process {} not found", pid))
    }
}

fn main() {
    handle_signal();

    // Open log file
    let log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open("sysmon.log")
        .expect("Failed to open log file");
    let mut log_writer = BufWriter::new(log_file);

    let mut system = System::new_all();
    let interval = Duration::from_secs(5); // Check every 5 seconds

    println!("System Monitor Daemon started. Logging to sysmon.log");
    println!("Press Ctrl+C to exit.");

    while RUNNING.load(Ordering::SeqCst) {
        let start = Instant::now();
        log_resource_usage(&mut system, &mut log_writer);
        log_writer.flush().unwrap();

        // Sleep for remaining interval time
        let elapsed = start.elapsed();
        if elapsed < interval {
            thread::sleep(interval - elapsed);
        }
    }

    println!("Daemon stopped.");
}
