use clap::Parser;
use log::{info, warn, error};
use serde::{Serialize, Deserialize};
use std::time::Duration;
use sysinfo::{System, SystemExt, CpuExt, DiskExt, NetworkExt};
use tokio::time;

// Configurable settings
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// Interval between checks (seconds)
    #[arg(short, long, default_value_t = 5)]
    interval: u64,

    /// Log format (json or plain)
    #[arg(short, long, default_value = "plain")]
    log_format: String,

    /// Enable CPU throttling (experimental)
    #[arg(short, long, action)]
    throttle_cpu: bool,
}

// System metrics data structure
#[derive(Serialize, Deserialize, Debug)]
struct SystemMetrics {
    timestamp: String,
    cpu_usage: f32,
    memory_used: u64,
    memory_total: u64,
    disk_usage: Vec<DiskUsage>,
    network_rx: u64,
    network_tx: u64,
}

#[derive(Serialize, Deserialize, Debug)]
struct DiskUsage {
    name: String,
    total: u64,
    used: u64,
}

#[tokio::main]
async fn main() {
    // Initialize logging
    env_logger::init();
    let args = Args::parse();

    info!("Starting sysmon daemon...");
    info!("Monitoring interval: {}s", args.interval);

    let mut sys = System::new_all();
    let mut prev_network_rx = 0;
    let mut prev_network_tx = 0;

    // Main monitoring loop
    loop {
        sys.refresh_all();

        // Collect CPU usage
        let cpu_usage = sys.global_cpu_info().cpu_usage();

        // Collect memory usage
        let memory_used = sys.used_memory();
        let memory_total = sys.total_memory();

        // Collect disk usage
        let disk_usage = sys.disks()
            .iter()
            .map(|disk| DiskUsage {
                name: disk.name().to_string_lossy().into_owned(),
                total: disk.total_space(),
                used: disk.total_space() - disk.available_space(),
            })
            .collect::<Vec<_>>();

        // Collect network stats (delta since last check)
        let network_rx = sys.networks().values().map(|net| net.received()).sum::<u64>() - prev_network_rx;
        let network_tx = sys.networks().values().map(|net| net.transmitted()).sum::<u64>() - prev_network_tx;
        prev_network_rx = sys.networks().values().map(|net| net.received()).sum();
        prev_network_tx = sys.networks().values().map(|net| net.transmitted()).sum();

        // Build metrics
        let metrics = SystemMetrics {
            timestamp: chrono::Utc::now().to_rfc3339(),
            cpu_usage,
            memory_used,
            memory_total,
            disk_usage,
            network_rx,
            network_tx,
        };

        // Log metrics
        match args.log_format.as_str() {
            "json" => info!("{}", serde_json::to_string(&metrics).unwrap()),
            _ => {
                info!("CPU: {:.1}%", cpu_usage);
                info!("Memory: {}MB / {}MB", memory_used / 1024 / 1024, memory_total / 1024 / 1024);
                info!("Network: RX {}KB, TX {}KB", network_rx / 1024, network_tx / 1024);
            }
        }

        // Optional: Throttle CPU (simplified example)
        if args.throttle_cpu && cpu_usage > 80.0 {
            warn!("High CPU usage detected! Consider throttling.");
        }

        // Wait for next interval
        time::sleep(Duration::from_secs(args.interval)).await;
    }
}
