use std::{
    fs::File,
    io::{self, Write},
    process,
    sync::mpsc,
    thread,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, ProcessExt, System, SystemExt};

// Configuration for the daemon
struct Config {
    log_file: Option<String>,      // Path to log file (None for stdout)
    poll_interval: Duration,       // How often to check system stats
    max_cpu_usage: Option<f32>,    // Optional: Max allowed CPU usage (%)
    max_memory_usage: Option<u64>, // Optional: Max allowed memory (MB)
}

impl Default for Config {
    fn default() -> Self {
        Config {
            log_file: Some("system_monitor.log".to_string()),
            poll_interval: Duration::from_secs(5),
            max_cpu_usage: Some(80.0),      // 80% CPU limit
            max_memory_usage: Some(8000),  // 8GB RAM limit
        }
    }
}

// Main monitoring loop
fn monitor_system(config: Config, tx: mpsc::Sender<String>) -> io::Result<()> {
    let mut system = System::new_all();
    let mut log_file = config.log_file.map(|path| File::create(path).unwrap());

    loop {
        system.refresh_all();

        // Get CPU usage
        let cpu_usage = system.global_cpu_info().cpu_usage();
        let cpu_load = format!("CPU Usage: {:.2}%", cpu_usage);

        // Get memory usage
        let total_memory = system.total_memory() / (1024 * 1024); // Convert to MB
        let used_memory = system.used_memory() / (1024 * 1024);
        let memory_load = format!(
            "Memory Usage: {} MB / {} MB ({:.2}%)",
            used_memory,
            total_memory,
            (used_memory as f32 / total_memory as f32) * 100.0
        );

        // Get disk usage (example: first disk)
        let disks = system.disks();
        let disk_usage = if !disks.is_empty() {
            let disk = &disks[0];
            format!(
                "Disk Usage: {} / {} ({:.2}%)",
                disk.available_space() / (1024 * 1024 * 1024), // GB
                disk.total_space() / (1024 * 1024 * 1024),
                (disk.available_space() as f32 / disk.total_space() as f32) * 100.0
            )
        } else {
            "No disks found".to_string()
        };

        // Get network stats (example: first network interface)
        let networks = system.networks();
        let network_stats = if !networks.is_empty() {
            let net = networks.values().next().unwrap();
            format!(
                "Network: {} MB in, {} MB out",
                net.received() / (1024 * 1024),
                net.transmitted() / (1024 * 1024)
            )
        } else {
            "No network interfaces found".to_string()
        };

        // Log to file or stdout
        let log_entry = format!(
            "[{}]\n{}\n{}\n{}\n{}\n\n",
            Instant::now(),
            cpu_load,
            memory_load,
            disk_usage,
            network_stats
        );

        if let Some(file) = &mut log_file {
            file.write_all(log_entry.as_bytes())?;
        } else {
            print!("{}", log_entry);
        }

        // Send metrics to main thread (optional)
        tx.send(log_entry).unwrap();

        // Check resource limits (optional)
        if let Some(max_cpu) = config.max_cpu_usage {
            if cpu_usage > max_cpu {
                eprintln!("WARNING: CPU usage exceeds {}%!", max_cpu);
            }
        }

        if let Some(max_mem) = config.max_memory_usage {
            if used_memory > max_mem {
                eprintln!("WARNING: Memory usage exceeds {} MB!", max_mem);
            }
        }

        thread::sleep(config.poll_interval);
    }
}

fn main() -> io::Result<()> {
    let config = Config::default();
    let (tx, rx) = mpsc::channel();

    // Spawn monitoring thread
    let monitor_thread = thread::spawn(move || {
        if let Err(e) = monitor_system(config, tx) {
            eprintln!("Monitoring error: {}", e);
            process::exit(1);
        }
    });

    // Main thread can receive logs (optional)
    for log_entry in rx {
        println!("Received log: {}", log_entry);
    }

    monitor_thread.join().unwrap();
    Ok(())
}
