use std::{
    fs::File,
    io::Write,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, ProcessExt, System, SystemExt};
use tokio::{
    signal::unix::{signal, SignalKind},
    sync::Mutex,
    time,
};
use log::{error, info, warn};
use clap::Parser;
use serde::{Deserialize, Serialize};

/// Configuration for the daemon
#[derive(Debug, Serialize, Deserialize)]
struct Config {
    log_file: Option<PathBuf>,
    poll_interval_secs: u64,
    cpu_threshold_percent: Option<f32>,
    memory_threshold_percent: Option<f32>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            log_file: Some(PathBuf::from("sysmon.log")),
            poll_interval_secs: 5,
            cpu_threshold_percent: Some(90.0),
            memory_threshold_percent: Some(85.0),
        }
    }
}

/// CLI arguments
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(short, long, default_value = "config.toml")]
    config: PathBuf,
}

#[tokio::main]
async fn main() {
    // Initialize logging
    simple_logger::init_with_level(log::Level::Info).unwrap();

    // Parse CLI args
    let args = Args::parse();

    // Load config (or use defaults)
    let config = match std::fs::read_to_string(&args.config) {
        Ok(content) => toml::from_str(&content).unwrap_or_else(|e| {
            warn!("Failed to parse config: {}. Using defaults.", e);
            Config::default()
        }),
        Err(_) => {
            warn!("Config file not found. Using defaults.");
            Config::default()
        }
    };

    info!("Starting sysmon-daemon with config: {:?}", config);

    // Shared system state
    let system = Arc::new(Mutex::new(System::new_all()));

    // Log file (if specified)
    let log_file = config.log_file.map(|path| {
        File::create(path).expect("Failed to create log file")
    });

    // Spawn monitoring task
    let monitor_handle = tokio::spawn({
        let system = system.clone();
        async move {
            let mut interval = time::interval(Duration::from_secs(config.poll_interval_secs));
            loop {
                interval.tick().await;
                monitor_system(&system, &config, &log_file).await;
            }
        }
    });

    // Handle shutdown signals
    let mut sigterm = signal(SignalKind::terminate()).unwrap();
    let mut sigint = signal(SignalKind::interrupt()).unwrap();

    tokio::select! {
        _ = sigterm.recv() => info!("Received SIGTERM, shutting down..."),
        _ = sigint.recv() => info!("Received SIGINT, shutting down..."),
    }

    // Cleanup
    monitor_handle.abort();
    info!("Daemon stopped.");
}

/// Monitor system resources and log metrics
async fn monitor_system(
    system: &Arc<Mutex<System>>,
    config: &Config,
    log_file: &Option<File>,
) {
    let mut sys = system.lock().await;
    sys.refresh_all();

    // CPU usage
    let cpu_usage = sys.global_cpu_info().cpu_usage();
    if let Some(threshold) = config.cpu_threshold_percent {
        if cpu_usage > threshold {
            warn!("High CPU usage: {:.2}% (Threshold: {:.2}%)", cpu_usage, threshold);
        }
    }

    // Memory usage
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_percent = (used_mem as f32 / total_mem as f32) * 100.0;
    if let Some(threshold) = config.memory_threshold_percent {
        if mem_percent > threshold {
            warn!(
                "High memory usage: {:.2}% (Threshold: {:.2}%)",
                mem_percent, threshold
            );
        }
    }

    // Disk usage (example: first disk)
    if let Some(disk) = sys.disks().first() {
        let disk_usage = disk.available_space() as f64 / disk.total_space() as f64 * 100.0;
        info!("Disk usage: {:.2}% free", disk_usage);
    }

    // Network stats
    for (interface, data) in sys.networks() {
        info!(
            "Network {}: {:.2} KB/s in, {:.2} KB/s out",
            interface,
            data.received() as f64 / 1024.0,
            data.transmitted() as f64 / 1024.0
        );
    }

    // Log to file if specified
    if let Some(file) = log_file {
        let log_entry = format!(
            "CPU: {:.2}%, Mem: {:.2}%, Time: {:?}\n",
            cpu_usage,
            mem_percent,
            Instant::now()
        );
        if let Err(e) = file.write_all(log_entry.as_bytes()) {
            error!("Failed to write to log file: {}", e);
        }
    }
}
