const POLL_INTERVAL_SECS: u64 = 5; // Check every 5 seconds

fn main() -> io::Result<()> {
    // Initialize logging
    let mut log_file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(LOG_FILE)?;

