        // Refresh system stats
        system.refresh_all();

        // Log CPU usage
        let cpu_usage = system.global_cpu_info().cpu_usage();
        writeln!(
            &mut log_file,
            "[{}] CPU Usage: {:.2}%",
            chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
