        )?;

        // Log Memory usage
        let total_memory = system.total_memory() as f64 / (1024 * 1024 * 1024); // GB
        let used_memory = system.used_memory() as f64 / (1024 * 1024 * 1024); // GB
        writeln!(
            &mut log_file,
            "[{}] Memory: {:.2}GB / {:.2}GB ({:.2}% used)",
            chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
            used_memory,
            total_memory,
            (used_memory / total_memory) * 100.0
        )?;

        // Log Disk usage (example: first disk)
        if let Some(disk) = system.disks().first() {
            let total_disk = disk.total_space() as f64 / (1024 * 1024 * 1024); // GB
            let free_disk = disk.available_space() as f64 / (1024 * 1024 * 1024); // GB
            writeln!(
                &mut log_file,
                "[{}] Disk: {:.2}GB free / {:.2}GB total ({:.2}% free)",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                free_disk,
                total_disk,
                (free_disk / total_disk) * 100.0
            )?;
        }

        // Flush logs to disk
        log_file.flush()?;

        // Sleep until next poll
        let elapsed = start_time.elapsed();
        if elapsed < Duration::from_secs(POLL_INTERVAL_SECS) {
            thread::sleep(Duration::from_secs(POLL_INTERVAL_SECS) - elapsed);
        }
    }
}
