### **Code (`main.rs`)**
```rust
use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};
use signal_hook::{consts::SIGTERM, consts::SIGINT, iterator::Signals};

fn main() -> io::Result<()> {
    // Set up signal handling for graceful shutdown
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    // Spawn a thread to handle signals
    thread::spawn(move || {
        let mut signals = Signals::new(&[SIGTERM, SIGINT]).unwrap();
        for _ in signals.forever() {
            r.store(false, Ordering::SeqCst);
            break;
        }
    });

    // Open log file (append mode)
    let mut log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open("system_monitor.log")?;

    println!("System Monitor Daemon started. Logging to system_monitor.log");

    // Main monitoring loop
    while running.load(Ordering::SeqCst) {
        let start_time = Instant::now();

        // Get CPU usage
        let cpu_usage = get_cpu_usage().unwrap_or(0.0);

        // Get memory usage
        let mem_usage = get_memory_usage().unwrap_or(0.0);

        // Get disk usage (for root partition)
        let disk_usage = get_disk_usage("/").unwrap_or(0.0);

        // Log metrics
        let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        let log_entry = format!(
            "[{}] CPU: {:.2}%, Memory: {:.2}%, Disk (/): {:.2}%\n",
            timestamp, cpu_usage, mem_usage, disk_usage
        );

        log_file.write_all(log_entry.as_bytes())?;
        log_file.flush()?;

        // Sleep for 5 seconds (adjust as needed)
        let elapsed = start_time.elapsed();
        if elapsed < Duration::from_secs(5) {
            thread::sleep(Duration::from_secs(5) - elapsed);
        }
    }

    println!("System Monitor Daemon shutting down gracefully.");
    Ok(())
}

/// Get CPU usage percentage (Linux only)
fn get_cpu_usage() -> io::Result<f64> {
    let output = Command::new("cat")
        .arg("/proc/stat")
        .output()?;

    let stat = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stat.lines().collect();

    if lines.len() < 1 {
        return Ok(0.0);
    }

    let parts: Vec<&str> = lines[0].split_whitespace().collect();
    if parts.len() < 5 {
        return Ok(0.0);
    }

    let user = parts[1].parse::<u64>().unwrap_or(0);
    let nice = parts[2].parse::<u64>().unwrap_or(0);
    let system = parts[3].parse::<u64>().unwrap_or(0);
    let idle = parts[4].parse::<u64>().unwrap_or(0);

    let total = user + nice + system + idle;
    let idle_percentage = (idle as f64 / total as f64) * 100.0;

    Ok(100.0 - idle_percentage)
}

/// Get memory usage percentage (Linux only)
fn get_memory_usage() -> io::Result<f64> {
    let output = Command::new("cat")
        .arg("/proc/meminfo")
        .output()?;

    let meminfo = String::from_utf8_lossy(&output.stdout);
    let mut total_mem = 0;
    let mut free_mem = 0;

    for line in meminfo.lines() {
        if line.starts_with("MemTotal:") {
            total_mem = line.split_whitespace().nth(1).unwrap_or("0").parse::<u64>().unwrap_or(0);
        } else if line.starts_with("MemFree:") {
            free_mem = line.split_whitespace().nth(1).unwrap_or("0").parse::<u64>().unwrap_or(0);
        }
    }

    if total_mem == 0 {
        return Ok(0.0);
    }

    let used_mem = total_mem - free_mem;
    Ok((used_mem as f64 / total_mem as f64) * 100.0)
}

/// Get disk usage percentage for a given path
fn get_disk_usage(path: &str) -> io::Result<f64> {
    let output = Command::new("df")
        .arg("-h")
        .arg(path)
        .output()?;

    let df_output = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = df_output.lines().collect();

    if lines.len() < 2 {
        return Ok(0.0);
    }

    let parts: Vec<&str> = lines[1].split_whitespace().collect();
    if parts.len() < 5 {
        return Ok(0.0);
    }

    let used = parts[2].trim_end_matches('%').parse::<f64>().unwrap_or(0.0);
    Ok(used)
}
