use std::fs::File;
use std::io::Write;
use std::process;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};

// Global flag for graceful shutdown
static RUNNING: AtomicBool = AtomicBool::new(true);

fn handle_signal() {
    // Handle SIGTERM/SIGINT for graceful shutdown
    ctrlc::set_handler(|| {
        println!("Received shutdown signal. Exiting...");
        RUNNING.store(false, Ordering::SeqCst);
    })
    .expect("Failed to set Ctrl-C handler");
}

fn log_metrics(system: &System, log_file: &mut File) {
    // CPU Usage
    let cpu_usage = system.global_cpu_info().cpu_usage();
    writeln!(log_file, "CPU Usage: {:.2}%", cpu_usage).unwrap();

    // Memory Usage
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let memory_percent = (used_memory as f64 / total_memory as f64) * 100.0;
    writeln!(
        log_file,
        "Memory Usage: {:.2}% ({} MB / {} MB)",
        memory_percent,
        used_memory / 1024 / 1024,
        total_memory / 1024 / 1024
    )
    .unwrap();

    // Disk Usage (first disk)
    if let Some(disk) = system.disks().first() {
        let total_space = disk.total_space();
        let available_space = disk.available_space();
        let used_space = total_space - available_space;
        let disk_percent = (used_space as f64 / total_space as f64) * 100.0;
        writeln!(
            log_file,
            "Disk Usage: {:.2}% ({} GB / {} GB)",
            disk_percent,
            used_space / 1024 / 1024 / 1024,
            total_space / 1024 / 1024 / 1024
        )
        .unwrap();
    }

    writeln!(log_file, "---").unwrap();
    log_file.flush().unwrap();
}

fn main() {
    // Initialize system monitoring
    let mut system = System::new_all();
    system.refresh_all();

    // Open log file (or use stdout)
    let mut log_file = File::create("system_monitor.log").expect("Failed to create log file");

    // Handle signals for graceful shutdown
    handle_signal();

    println!("System monitoring daemon started. Logging to system_monitor.log");

    // Main monitoring loop
    while RUNNING.load(Ordering::SeqCst) {
        system.refresh_all();
        log_metrics(&system, &mut log_file);
        thread::sleep(Duration::from_secs(5)); // Adjust interval as needed
    }

    println!("Daemon shutting down...");
}
