### **Code (`main.rs`)**
```rust
use std::fs::OpenOptions;
use std::io::Write;
use std::process;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use sysinfo::{System, SystemExt};
use daemonize::Daemonize;

// Global flag to control daemon shutdown
static RUNNING: AtomicBool = AtomicBool::new(true);

// Handle signals (SIGTERM, SIGINT)
fn handle_signals() {
    let running = Arc::new(RUNNING);
    ctrlc::set_handler(move || {
        eprintln!("Received shutdown signal. Exiting...");
        running.store(false, Ordering::SeqCst);
    }).expect("Failed to set Ctrl-C handler");
}

// Log system metrics to a file
fn log_system_metrics(log_file: &str) -> std::io::Result<()> {
    let mut sys = System::new_all();
    sys.refresh_all();

    let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let disk_usage = sys.disks().iter().map(|d| d.total_space()).sum::<u64>();

    let log_entry = format!(
        "[{}] CPU: {:.2}%, Memory: {} MB / {} MB, Disk: {} GB\n",
        timestamp,
        cpu_usage,
        used_memory / (1024 * 1024),
        total_memory / (1024 * 1024),
        disk_usage / (1024 * 1024 * 1024)
    );

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_file)?;

    file.write_all(log_entry.as_bytes())?;
    Ok(())
}

// Main daemon loop
fn run_daemon(log_file: &str, interval_secs: u64) {
    while RUNNING.load(Ordering::SeqCst) {
        if let Err(e) = log_system_metrics(log_file) {
            eprintln!("Failed to log metrics: {}", e);
        }
        thread::sleep(Duration::from_secs(interval_secs));
    }
}

fn main() {
    // Daemon configuration
    let daemonize = Daemonize::new()
        .pid_file("/tmp/system_monitor.pid")
        .chown_pid_file(true)
        .working_directory("/tmp")
        .umask(0o777)
        .privileged_action(|| {
            println!("Starting system monitor daemon...");
        });

    // Start daemon
    match daemonize.start() {
        Ok(_) => {
            handle_signals();
            run_daemon("/tmp/system_monitor.log", 5); // Log every 5 seconds
        }
        Err(e) => {
            eprintln!("Failed to start daemon: {}", e);
            process::exit(1);
        }
    }
}
