### **Code Implementation (`main.rs`)**
```rust
use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr};
use std::sync::Arc;
use std::time::{Duration, Instant};

use pnet::datalink::{self, Channel::Ethernet, DataLinkReceiver, NetworkInterface};
use pnet::packet::ethernet::{EthernetPacket, EtherTypes};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use tokio::sync::Mutex;
use tokio::time;

// Define a flow key (5-tuple)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8, // TCP=6, UDP=17
}

// Flow statistics
#[derive(Debug, Default, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// Shared state for flow tracking
struct FlowAnalyzer {
    flows: HashMap<FlowKey, FlowStats>,
    active_flows: u64,
    total_packets: u64,
    total_bytes: u64,
}

impl FlowAnalyzer {
    fn new() -> Self {
        Self {
            flows: HashMap::new(),
            active_flows: 0,
            total_packets: 0,
            total_bytes: 0,
        }
    }

    fn process_packet(&mut self, packet: &[u8]) {
        if let Some(ethernet) = EthernetPacket::new(packet) {
            match ethernet.get_ethertype() {
                EtherTypes::Ipv4 => {
                    if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                        let src_ip = ipv4.get_source();
                        let dst_ip = ipv4.get_destination();
                        let protocol = ipv4.get_next_level_protocol();

                        match protocol {
                            IpNextHeaderProtocols::Tcp => {
                                if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                    let key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port: tcp.get_source(),
                                        dst_port: tcp.get_destination(),
                                        protocol: 6, // TCP
                                    };
                                    self.update_flow(&key, ipv4.packet().len() as u64);
                                }
                            }
                            IpNextHeaderProtocols::Udp => {
                                if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                    let key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port: udp.get_source(),
                                        dst_port: udp.get_destination(),
                                        protocol: 17, // UDP
                                    };
                                    self.update_flow(&key, ipv4.packet().len() as u64);
                                }
                            }
                            _ => {} // Ignore other protocols
                        }
                    }
                }
                _ => {} // Ignore non-IPv4 packets
            }
        }
    }

    fn update_flow(&mut self, key: &FlowKey, bytes: u64) {
        let now = Instant::now();
        self.flows
            .entry(key.clone())
            .and_modify(|flow| {
                flow.packets += 1;
                flow.bytes += bytes;
                flow.last_seen = now;
            })
            .or_insert_with(|| FlowStats {
                packets: 1,
                bytes,
                first_seen: now,
                last_seen: now,
            });
        self.total_packets += 1;
        self.total_bytes += bytes;
    }

    fn expire_flows(&mut self, timeout: Duration) {
        let now = Instant::now();
        self.flows.retain(|_, flow| {
            if now.duration_since(flow.last_seen) < timeout {
                true
            } else {
                self.active_flows -= 1;
                false
            }
        });
    }
}

#[tokio::main]
async fn main() {
    // Select the network interface (e.g., "eth0")
    let interface_name = "eth0";
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == interface_name)
        .expect("Interface not found");

    // Create a channel for packet capture
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Failed to create channel: {}", e),
    };

    // Initialize flow analyzer
    let analyzer = Arc::new(Mutex::new(FlowAnalyzer::new()));

    // Spawn a task to periodically print stats
    let analyzer_clone = analyzer.clone();
    tokio::spawn(async move {
        let mut interval = time::interval(Duration::from_secs(5));
        loop {
            interval.tick().await;
            let analyzer = analyzer_clone.lock().await;
            println!(
                "Active Flows: {}, Total Packets: {}, Total Bytes: {}",
                analyzer.active_flows, analyzer.total_packets, analyzer.total_bytes
            );
        }
    });

    // Main packet processing loop
    loop {
        match rx.next() {
            Ok(packet) => {
                let analyzer = analyzer.clone();
                tokio::spawn(async move {
                    let mut analyzer = analyzer.lock().await;
                    analyzer.process_packet(&packet);
                    analyzer.expire_flows(Duration::from_secs(30)); // Expire flows after 30s
                });
            }
            Err(e) => eprintln!("Error receiving packet: {}", e),
        }
    }
}
