    fn process_packet(&mut self, src_ip: Ipv4Addr, dst_ip: Ipv4Addr, src_port: u16, dst_port: u16, protocol: u8, packet_len: usize) {
        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            protocol,
        };

        let now = Instant::now();
        self.flows.entry(key).and_modify(|stats| {
            stats.packets += 1;
            stats.bytes += packet_len as u64;
            stats.last_seen = now;
        }).or_insert(FlowStats {
            packets: 1,
            bytes: packet_len as u64,
            last_seen: now,
        });
    }

    fn print_active_flows(&self) {
        println!("\n=== Active Flows ===");
        for (key, stats) in &self.flows {
            println!(
                "Flow: {:?} -> {:?}:{}:{} (Proto: {}) | Packets: {} | Bytes: {}",
                key.src_ip, key.dst_ip, key.src_port, key.dst_port, key.protocol, stats.packets, stats.bytes
            );
        }
    }

    fn cleanup_old_flows(&mut self, timeout: Duration) {
        let now = Instant::now();
        self.flows.retain(|_, stats| now.duration_since(stats.last_seen) < timeout);
    }
}

fn main() {
    // Initialize flow analyzer
    let analyzer = Arc::new(Mutex::new(FlowAnalyzer::new()));

    // Get available network device
    let device = Device::list()
        .expect("Failed to list network devices")
        .first()
        .expect("No network devices found")
        .clone();

    // Open pcap capture (non-blocking mode)
    let mut cap = Capture::from_device(device)
        .expect("Failed to open capture device")
        .immediate_mode(true)
        .open()
        .expect("Failed to open capture");

    // Set BPF filter to capture only TCP/UDP (optional)
    cap.filter("tcp or udp", true)
        .expect("Failed to set BPF filter");

    // Spawn worker threads (one per CPU core)
    let num_threads = num_cpus::get();
    let analyzer_clone = Arc::clone(&analyzer);

    for _ in 0..num_threads {
        let analyzer_thread = Arc::clone(&analyzer_clone);
        thread::spawn(move || {
            loop {
                // Process packets in batches
                let mut batch = Vec::with_capacity(1000);
                for _ in 0..1000 {
                    if let Ok(packet) = cap.next_packet() {
                        batch.push(packet);
                    }
                }

                // Parse and update flows
                let mut analyzer = analyzer_thread.lock().unwrap();
                for packet in batch {
                    // Simplified parsing (real code would use a proper parser like `etherparse`)
                    if packet.len() >= 20 { // Minimum IP header size
                        let src_ip = Ipv4Addr::new(packet[12], packet[13], packet[14], packet[15]);
                        let dst_ip = Ipv4Addr::new(packet[16], packet[17], packet[18], packet[19]);
                        let protocol = packet[9];
                        let src_port = if packet.len() >= 34 { u16::from_be_bytes([packet[20], packet[21]]) } else { 0 };
                        let dst_port = if packet.len() >= 34 { u16::from_be_bytes([packet[22], packet[23]]) } else { 0 };

                        analyzer.process_packet(src_ip, dst_ip, src_port, dst_port, protocol, packet.len());
                    }
                }
            }
        });
    }

    // Periodically print and cleanup flows
    loop {
        thread::sleep(Duration::from_secs(5));
        let mut analyzer = analyzer.lock().unwrap();
        analyzer.print_active_flows();
        analyzer.cleanup_old_flows(Duration::from_secs(30)); // Remove inactive flows after 30s
    }
}
