use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::{ethernet::EthernetPacket, ip::IpNextHeaderProtocol, ipv4::Ipv4Packet, tcp::TcpPacket, udp::UdpPacket, Packet};
use rayon::prelude::*;
use std::thread;

// Flow key (5-tuple: src_ip, dst_ip, src_port, dst_port, protocol)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8, // TCP=6, UDP=17
}

// Flow statistics
#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    last_seen: Instant,
}

// Main flow tracker
struct FlowTracker {
    flows: Arc<Mutex<HashMap<FlowKey, FlowStats>>>,
    expiration_time: Duration,
}

impl FlowTracker {
    fn new(expiration_time: Duration) -> Self {
        Self {
            flows: Arc::new(Mutex::new(HashMap::new())),
            expiration_time,
        }
    }

    // Process a single packet and update flow stats
    fn process_packet(&self, packet: &[u8]) {
        let ethernet = match EthernetPacket::new(packet) {
            Some(p) => p,
            None => return,
        };

        let ipv4 = match Ipv4Packet::new(ethernet.payload()) {
            Some(p) => p,
            None => return,
        };

        let src_ip = IpAddr::V4(ipv4.get_source());
        let dst_ip = IpAddr::V4(ipv4.get_destination());

        match ipv4.get_next_level_protocol() {
            IpNextHeaderProtocol::Tcp => {
                if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: tcp.get_source(),
                        dst_port: tcp.get_destination(),
                        protocol: 6, // TCP
                    };
                    self.update_flow(&key, ipv4.packet().len() as u64);
                }
            }
            IpNextHeaderProtocol::Udp => {
                if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port: udp.get_source(),
                        dst_port: udp.get_destination(),
                        protocol: 17, // UDP
                    };
                    self.update_flow(&key, ipv4.packet().len() as u64);
                }
            }
            _ => {} // Ignore non-TCP/UDP
        }
    }

    // Update flow stats (thread-safe)
    fn update_flow(&self, key: &FlowKey, bytes: u64) {
        let mut flows = self.flows.lock().unwrap();
        let entry = flows.entry(key.clone()).or_insert(FlowStats {
            packets: 0,
            bytes: 0,
            last_seen: Instant::now(),
        });
        entry.packets += 1;
        entry.bytes += bytes;
        entry.last_seen = Instant::now();
    }

    // Expire old flows (run periodically)
    fn expire_flows(&self) {
        let now = Instant::now();
        let mut flows = self.flows.lock().unwrap();
        flows.retain(|_, stats| now - stats.last_seen < self.expiration_time);
    }

    // Get active flows (for reporting)
    fn get_active_flows(&self) -> Vec<(FlowKey, FlowStats)> {
        let flows = self.flows.lock().unwrap();
        flows.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
    }
}

fn main() {
    // Initialize flow tracker (expire flows after 10 seconds)
    let tracker = Arc::new(FlowTracker::new(Duration::from_secs(10)));

    // Spawn a thread to periodically expire old flows
    let tracker_clone = tracker.clone();
    thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(1));
        tracker_clone.expire_flows();
    });

    // Get the default network interface
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback())
        .expect("No suitable network interface found");

