            println!("--- Current Flows ---");
            for (key, stats) in flows.iter() {
                println!(
                    "Flow: {:?} | Packets: {} | Bytes: {} | Duration: {:?}",
                    key,
                    stats.packets,
                    stats.bytes,
                    stats.last_seen.duration_since(stats.start_time)
                );
            }
            println!("---------------------");
        }
    });

    // Open a network interface (e.g., "eth0")
    let interface_name = "eth0".to_string();
    let interface = pnet::datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == interface_name)
        .expect("Interface not found");

    let (_, mut rx) = pnet::datalink::channel(&interface, Default::default())
        .expect("Failed to create channel");

    loop {
        match rx.next() {
            Ok(packet) => {
                // Parse Ethernet frame
                let eth_packet = EthernetPacket::new(packet).expect("Failed to parse Ethernet packet");

                // Handle IPv4 packets
                if eth_packet.get_ethertype() == pnet::packet::ethernet::EtherTypes::Ipv4 {
                    if let Some(ipv4_packet) = Ipv4Packet::new(eth_packet.payload()) {
                        let src_ip = ipv4_packet.get_source();
                        let dst_ip = ipv4_packet.get_destination();
                        let protocol = ipv4_packet.get_next_level_protocol();

                        // Handle TCP/UDP flows
                        match protocol {
                            IpNextHeaderProtocol::Tcp => {
                                if let Some(tcp_packet) = TcpPacket::new(ipv4_packet.payload()) {
                                    let src_port = tcp_packet.get_source();
                                    let dst_port = tcp_packet.get_destination();
                                    let key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port,
                                        dst_port,
                                        protocol,
                                    };
                                    let payload_len = tcp_packet.payload().len() as u64;

                                    update_flow(&flows, key, payload_len);
                                }
                            }
                            IpNextHeaderProtocol::Udp => {
                                if let Some(udp_packet) = UdpPacket::new(ipv4_packet.payload()) {
                                    let src_port = udp_packet.get_source();
                                    let dst_port = udp_packet.get_destination();
                                    let key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port,
                                        dst_port,
                                        protocol,
                                    };
                                    let payload_len = udp_packet.payload().len() as u64;

                                    update_flow(&flows, key, payload_len);
                                }
                            }
                            _ => {} // Ignore other protocols
                        }
                    }
                }
            }
            Err(e) => eprintln!("Error receiving packet: {}", e),
        }
    }
}

fn update_flow(flows: &Arc<Mutex<HashMap<FlowKey, FlowStats>>>, key: FlowKey, payload_len: u64) {
    let mut flows = flows.lock().unwrap();
    let now = Instant::now();

    if let Some(stats) = flows.get_mut(&key) {
        stats.packets += 1;
        stats.bytes += payload_len;
        stats.last_seen = now;
    } else {
        flows.insert(
            key,
            FlowStats {
                packets: 1,
                bytes: payload_len,
                start_time: now,
                last_seen: now,
            },
        );
    }
}
