use tokio::time::interval;
use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::ethernet::{EthernetPacket, EtherTypes};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;

// Define a flow key (src_ip, dst_ip, src_port, dst_port, protocol)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: IpNextHeaderProtocols,
}

// Define flow statistics
#[derive(Debug, Default)]
struct FlowStats {
    packets: u64,
    bytes: u64,
}

// Main flow analyser struct
struct FlowAnalyser {
    flows: HashMap<FlowKey, FlowStats>,
}

impl FlowAnalyser {
    fn new() -> Self {
        Self {
            flows: HashMap::new(),
        }
    }

    // Process a single packet and update flow stats
    fn process_packet(&mut self, packet: &[u8]) {
        if let Some(ethernet) = EthernetPacket::new(packet) {
            match ethernet.get_ethertype() {
                EtherTypes::Ipv4 => {
                    if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                        let src_ip = ipv4.get_source();
                        let dst_ip = ipv4.get_destination();
                        let protocol = ipv4.get_next_level_protocol();

                        match protocol {
                            IpNextHeaderProtocols::Tcp => {
                                if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                    let flow_key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port: tcp.get_source(),
                                        dst_port: tcp.get_destination(),
                                        protocol,
                                    };
                                    self.update_flow(&flow_key, ipv4.packet().len() as u64);
                                }
                            }
                            IpNextHeaderProtocols::Udp => {
                                if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                    let flow_key = FlowKey {
                                        src_ip,
                                        dst_ip,
                                        src_port: udp.get_source(),
                                        dst_port: udp.get_destination(),
                                        protocol,
                                    };
                                    self.update_flow(&flow_key, ipv4.packet().len() as u64);
                                }
                            }
                            _ => {} // Ignore other protocols (ICMP, etc.)
                        }
                    }
                }
                _ => {} // Ignore non-IPv4 packets
            }
        }
    }

    // Update flow statistics
    fn update_flow(&mut self, key: &FlowKey, bytes: u64) {
        let entry = self.flows.entry(key.clone()).or_default();
        entry.packets += 1;
        entry.bytes += bytes;
    }

    // Print aggregated flow stats
    fn print_stats(&self) {
        println!("=== Flow Statistics ===");
        for (key, stats) in &self.flows {
            println!(
                "Flow: {:?} -> {:?}:{}:{} | Packets: {} | Bytes: {}",
                key.src_ip, key.dst_ip, key.src_port, key.dst_port, stats.packets, stats.bytes
            );
        }
    }
}

