use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use pcap::{Active, Capture, Device};
use tokio::sync::mpsc;
use tokio::time;

// Define a flow key (5-tuple)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8, // TCP=6, UDP=17, etc.
}

// Define flow statistics
#[derive(Debug, Default)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize packet capture
    let device = Device::lookup()?.expect("No network device found");
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .snaplen(65535)
        .timeout(500)
        .open()?;

    // Channel for async packet processing
    let (tx, mut rx) = mpsc::channel::<Vec<u8>>(1024);

    // Shared flow storage (thread-safe)
    let flows: Arc<Mutex<HashMap<FlowKey, FlowStats>>> = Arc::new(Mutex::new(HashMap::new()));

    // Spawn packet capture thread
    tokio::spawn(async move {
        loop {
            match cap.next_packet() {
                Ok(packet) => {
                    let _ = tx.send(packet.data.to_vec()).await;
                }
                Err(e) => eprintln!("Packet capture error: {}", e),
            }
        }
    });

    // Spawn flow processing thread
    let flows_clone = flows.clone();
    tokio::spawn(async move {
        while let Some(packet) = rx.recv().await {
            if let Some((flow_key, packet_len)) = parse_packet(&packet) {
                let mut flows = flows_clone.lock().unwrap();
                let entry = flows.entry(flow_key).or_default();
                entry.packets += 1;
                entry.bytes += packet_len as u64;
                entry.last_seen = Instant::now();
            }
        }
    });

    // Periodically print flow stats
    let print_interval = time::interval(Duration::from_secs(5));
    tokio::spawn(async move {
        loop {
            print_interval.tick().await;
            let flows = flows.lock().unwrap();
            println!("Active Flows: {}", flows.len());
            for (key, stats) in flows.iter() {
                println!(
                    "Flow: {:?}, Packets: {}, Bytes: {}, Duration: {:?}",
                    key,
                    stats.packets,
                    stats.bytes,
                    stats.last_seen.duration_since(stats.first_seen)
                );
            }
        }
    });

    // Keep the program running
    tokio::signal::ctrl_c().await?;
    Ok(())
}

// Parse a packet and extract flow key
fn parse_packet(packet: &[u8]) -> Option<(FlowKey, usize)> {
    // Simplified parsing (real implementation would use a proper parser like `etherparse`)
    if packet.len() < 20 {
        return None;
    }

    // Extract IPv4 header (simplified)
    let version = (packet[0] >> 4) & 0xF;
    if version != 4 {
        return None; // Only IPv4 for simplicity
    }

    let src_ip = Ipv4Addr::new(packet[12], packet[13], packet[14], packet[15]);
    let dst_ip = Ipv4Addr::new(packet[16], packet[17], packet[18], packet[19]);

    // Extract TCP/UDP ports (simplified)
    let protocol = packet[9];
    let src_port = if packet.len() >= 34 {
        u16::from_be_bytes([packet[20], packet[21]])
    } else {
        0
    };
    let dst_port = if packet.len() >= 34 {
        u16::from_be_bytes([packet[22], packet[23]])
    } else {
        0
    };

    let flow_key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol,
    };

    Some((flow_key, packet.len()))
}
