### **Code Implementation (`main.rs`)**
```rust
use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use crossbeam::channel::{bounded, Receiver, Sender};
use pnet::datalink::{Channel::Ethernet, Config, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::{IpNextHeaderProtocol, IpNextHeaderProtocols};
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;

// Define a flow key (5-tuple)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: IpNextHeaderProtocol,
}

// Define flow statistics
#[derive(Debug, Default)]
struct FlowStats {
    packets: AtomicU64,
    bytes: AtomicU64,
    first_seen: Instant,
    last_seen: Instant,
}

// Main flow analyser struct
struct FlowAnalyser {
    flows: HashMap<FlowKey, FlowStats>,
    packet_rx: Receiver<(Vec<u8>, Instant)>,
    flow_tx: Sender<(FlowKey, FlowStats)>,
}

impl FlowAnalyser {
    fn new(interface: &NetworkInterface) -> Self {
        let (packet_tx, packet_rx) = bounded::<(Vec<u8>, Instant)>(1024);
        let (flow_tx, flow_rx) = bounded::<(FlowKey, FlowStats)>(1024);

        // Spawn packet capture thread
        std::thread::spawn({
            let interface = interface.clone();
            move || {
                let (_, mut rx) = match pnet::datalink::channel(&interface, Config::default()) {
                    Ok(Ethernet(tx, rx)) => (tx, rx),
                    Ok(_) => panic!("Unsupported channel type"),
                    Err(e) => panic!("Failed to create channel: {}", e),
                };

                loop {
                    match rx.next() {
                        Ok(packet) => {
                            let timestamp = Instant::now();
                            packet_tx.send((packet.to_vec(), timestamp)).unwrap();
                        }
                        Err(e) => eprintln!("Packet capture error: {}", e),
                    }
                }
            }
        });

        // Spawn flow processing thread
        std::thread::spawn({
            let mut flows = HashMap::new();
            move || {
                while let Ok((packet_data, timestamp)) = packet_rx.recv() {
                    if let Some(ethernet) = EthernetPacket::new(&packet_data) {
                        match ethernet.get_ethertype() {
                            EtherTypes::Ipv4 => {
                                if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                                    process_ip_packet(
                                        &mut flows,
                                        &flow_tx,
                                        ipv4.get_source(),
                                        ipv4.get_destination(),
                                        ipv4.get_next_level_protocol(),
                                        ipv4.payload(),
                                        timestamp,
                                    );
                                }
                            }
                            EtherTypes::Ipv6 => {
                                if let Some(ipv6) = Ipv6Packet::new(ethernet.payload()) {
                                    process_ip_packet(
                                        &mut flows,
                                        &flow_tx,
                                        ipv6.get_source(),
                                        ipv6.get_destination(),
                                        ipv6.get_next_header(),
                                        ipv6.payload(),
                                        timestamp,
                                    );
                                }
                            }
                            _ => continue,
                        }
                    }
                }
            }
        });

        // Spawn flow reporting thread (prints every 5 seconds)
        std::thread::spawn(move || {
            loop {
                std::thread::sleep(Duration::from_secs(5));
                let mut flows = HashMap::new();
                while let Ok((key, stats)) = flow_rx.try_recv() {
                    flows.insert(key, stats);
                }
                println!("Active flows: {}", flows.len());
                for (key, stats) in flows {
                    println!(
                        "Flow: {:?}, Packets: {}, Bytes: {}",
                        key,
                        stats.packets.load(Ordering::Relaxed),
                        stats.bytes.load(Ordering::Relaxed)
                    );
                }
            }
        });

        FlowAnalyser {
            flows: HashMap::new(),
            packet_rx,
            flow_tx,
        }
    }
}

// Process an IP packet and update flows
fn process_ip_packet(
    flows: &mut HashMap<FlowKey, FlowStats>,
    flow_tx: &Sender<(FlowKey, FlowStats)>,
    src_ip: IpAddr,
    dst_ip: IpAddr,
    protocol: IpNextHeaderProtocol,
    payload: &[u8],
    timestamp: Instant,
) {
    let (src_port, dst_port) = match protocol {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(payload) {
                (tcp.get_source(), tcp.get_destination())
            } else {
                return;
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(payload) {
                (udp.get_source(), udp.get_destination())
            } else {
                return;
            }
        }
        _ => return, // Only TCP/UDP for now
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol,
    };

    let stats = flows.entry(key.clone()).or_insert_with(|| FlowStats {
        packets: AtomicU64::new(0),
        bytes: AtomicU64::new(0),
        first_seen: timestamp,
        last_seen: timestamp,
    });

    stats.packets.fetch_add(1, Ordering::Relaxed);
    stats.bytes.fetch_add(payload.len() as u64, Ordering::Relaxed);
    stats.last_seen = timestamp;

    // Send flow update for reporting
    flow_tx.send((key, stats.clone())).unwrap();
}

fn main() {
    // Get the default network interface
    let interface = pnet::datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback())
        .expect("No suitable network interface found");

    println!("Monitoring interface: {}", interface.name);

    // Start the flow analyser
    let _analyser = FlowAnalyser::new(&interface);

    // Keep the main thread alive
    loop {
        std::thread::park();
    }
}
