use pcap::{Device, Capture};
use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr};
use std::time::{Instant, Duration};
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;

// Define a flow key (5-tuple)
#[derive(Hash, Eq, PartialEq, Debug, Clone)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

// Flow statistics
struct FlowStats {
    packets: AtomicU64,
    bytes: AtomicU64,
    last_seen: Instant,
}

fn main() {
    // Get the default network device
    let device = Device::lookup().expect("No default device found");
    println!("Using device: {}", device.name);

    // Open a live capture with a 100MB buffer
    let mut cap = Capture::from_device(device)
        .expect("Failed to open capture")
        .immediate_mode(true)  // Reduce latency
        .open()
        .expect("Failed to open capture");

    // Set a BPF filter to capture only IPv4 traffic (optional)
    cap.filter("ip", true).expect("Failed to set BPF filter");

    // Flow storage (thread-safe)
    let flows: HashMap<FlowKey, FlowStats> = HashMap::new();
    let mut flows = std::sync::Arc::new(std::sync::Mutex::new(flows));

    // Spawn a thread to print flow stats periodically
    let flows_clone = flows.clone();
    thread::spawn(move || {
        loop {
            thread::sleep(Duration::from_secs(5));
            let flows = flows_clone.lock().unwrap();
            println!("\n--- Active Flows ---");
            for (key, stats) in flows.iter() {
                println!(
                    "Flow: {:?} -> {:?}:{}:{} (Proto: {}) | Packets: {} | Bytes: {}",
                    key.src_ip,
                    key.dst_ip,
                    key.src_port,
                    key.dst_port,
                    key.protocol,
                    stats.packets.load(Ordering::Relaxed),
                    stats.bytes.load(Ordering::Relaxed),
                );
            }
        }
    });

    // Process packets in a loop
    while let Ok(packet) = cap.next_packet() {
        let now = Instant::now();

        // Parse Ethernet header (simplified)
        if packet.data.len() < 14 {
            continue;
        }

        // Parse IPv4 header (simplified)
        let ip_header_offset = 14;
        if packet.data.len() < ip_header_offset + 20 {
            continue;
        }

        let protocol = packet.data[ip_header_offset + 9];
        let src_ip = Ipv4Addr::new(
            packet.data[ip_header_offset + 12],
            packet.data[ip_header_offset + 13],
            packet.data[ip_header_offset + 14],
            packet.data[ip_header_offset + 15],
        );
        let dst_ip = Ipv4Addr::new(
            packet.data[ip_header_offset + 16],
            packet.data[ip_header_offset + 17],
            packet.data[ip_header_offset + 18],
            packet.data[ip_header_offset + 19],
        );

        // Parse TCP/UDP ports (simplified)
        let src_port = if protocol == 6 || protocol == 17 {
            u16::from_be_bytes([packet.data[ip_header_offset + 20], packet.data[ip_header_offset + 21]])
        } else {
            0
        };
        let dst_port = if protocol == 6 || protocol == 17 {
            u16::from_be_bytes([packet.data[ip_header_offset + 22], packet.data[ip_header_offset + 23]])
        } else {
            0
        };

        // Create flow key
        let flow_key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            protocol,
        };

        // Update flow stats
        let mut flows = flows.lock().unwrap();
        let flow_stats = flows.entry(flow_key).or_insert(FlowStats {
            packets: AtomicU64::new(0),
            bytes: AtomicU64::new(0),
            last_seen: now,
        });

        flow_stats.packets.fetch_add(1, Ordering::Relaxed);
        flow_stats.bytes.fetch_add(packet.data.len() as u64, Ordering::Relaxed);
        flow_stats.last_seen = now;
    }
}
```

