use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::ethernet::EthernetPacket;
use pnet::packet::ip::IpNextHeaderProtocol;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use tokio::sync::Mutex;
use tokio::time;

// Define a flow key (src_ip, dst_ip, src_port, dst_port, protocol)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: IpNextHeaderProtocol,
}

// Flow statistics (packets, bytes, start/end time)
#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    start_time: Instant,
    end_time: Instant,
}

#[tokio::main]
async fn main() {
    // Select the default network interface
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback())
        .expect("No suitable network interface found");

    println!("Listening on: {}", interface.name);

    // Create a channel for packet capture
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error creating channel: {}", e),
    };

    // Shared flow storage (thread-safe)
    let flows: Arc<Mutex<HashMap<FlowKey, FlowStats>>> = Arc::new(Mutex::new(HashMap::new()));

    // Spawn a task to periodically print flow stats
    let flows_clone = flows.clone();
    tokio::spawn(async move {
        let mut interval = time::interval(Duration::from_secs(5));
        loop {
            interval.tick().await;
            let flows = flows_clone.lock().await;
            println!("\n--- Current Flow Stats ---");
            for (key, stats) in flows.iter() {
                println!(
                    "Flow: {:?} | Packets: {} | Bytes: {} | Duration: {:?}",
                    key,
                    stats.packets,
                    stats.bytes,
                    stats.end_time.duration_since(stats.start_time)
                );
            }
        }
    });

    // Process packets in a loop
    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(ethernet) = EthernetPacket::new(packet) {
                    if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                        let src_ip = IpAddr::V4(ipv4.get_source());
                        let dst_ip = IpAddr::V4(ipv4.get_destination());
                        let protocol = ipv4.get_next_level_protocol();

                        // Extract transport-layer ports (TCP/UDP)
                        let (src_port, dst_port) = match protocol {
                            IpNextHeaderProtocol::Tcp => {
                                if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                    (tcp.get_source(), tcp.get_destination())
                                } else {
                                    continue;
                                }
                            }
                            IpNextHeaderProtocol::Udp => {
                                if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                    (udp.get_source(), udp.get_destination())
                                } else {
                                    continue;
                                }
                            }
                            _ => continue, // Skip non-TCP/UDP traffic
                        };

                        // Create a flow key
                        let key = FlowKey {
                            src_ip,
                            dst_ip,
                            src_port,
                            dst_port,
                            protocol,
                        };

                        // Update flow stats
                        let mut flows = flows.lock().await;
                        let now = Instant::now();
                        if let Some(stats) = flows.get_mut(&key) {
                            stats.packets += 1;
                            stats.bytes += ipv4.packet().len() as u64;
                            stats.end_time = now;
                        } else {
                            flows.insert(
                                key,
                                FlowStats {
                                    packets: 1,
                                    bytes: ipv4.packet().len() as u64,
                                    start_time: now,
                                    end_time: now,
                                },
                            );
                        }
                    }
                }
            }
            Err(e) => eprintln!("Error reading packet: {}", e),
        }
    }
}
```

