use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::{Duration, Instant};

use pcap::{Active, Capture, Device};
use tokio::sync::Mutex;
use tokio::time;

// Define a flow key (src_ip, dst_ip, src_port, dst_port)
#[derive(Debug, Hash, PartialEq, Eq, Clone)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
}

// Define a flow record (bytes, packets, timestamp)
#[derive(Debug, Clone)]
struct FlowRecord {
    bytes: u64,
    packets: u64,
    last_seen: Instant,
}

#[tokio::main]
async fn main() {
    // Initialize packet capture (use a real interface, e.g., "eth0")
    let device = Device::list()
        .expect("Failed to list network devices")
        .into_iter()
        .next()
        .expect("No network device found");

    let mut cap = Capture::from_device(device)
        .expect("Failed to open capture device")
        .immediate_mode(true)
        .open()
        .expect("Failed to open capture");

    // Set a BPF filter to capture only IPv4 traffic (optional but recommended)
    cap.filter("ip", true)
        .expect("Failed to set BPF filter");

    // Shared state for flow aggregation (thread-safe)
    let flows = Arc::new(Mutex::new(HashMap::new()));

    // Spawn a background task to periodically log flows
    let flows_clone = flows.clone();
    tokio::spawn(async move {
        let mut interval = time::interval(Duration::from_secs(5));
        loop {
            interval.tick().await;
            let mut flows = flows_clone.lock().await;
            println!("--- Flow Summary (Last 5s) ---");
            for (key, record) in flows.iter() {
                println!(
                    "Flow: {:?} -> {:?}:{}:{} | Bytes: {} | Packets: {}",
                    key.src_ip, key.dst_ip, key.src_port, key.dst_port, record.bytes, record.packets
                );
            }
            flows.clear(); // Reset for next interval
        }
    });

    // Main packet processing loop
    while let Ok(packet) = cap.next_packet() {
        if let Some(ethernet) = etherparse::EthernetSlice::from_slice(&packet) {
            if let Ok(ipv4) = ethernet.ip() {
                if let etherparse::IpTraffic::Tcp(tcp) = ipv4.payload() {
                    let src_ip = ipv4.source_addr();
                    let dst_ip = ipv4.destination_addr();
                    let src_port = tcp.source_port();
                    let dst_port = tcp.destination_port();
                    let packet_len = packet.len() as u64;

                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port,
                        dst_port,
                    };

                    let mut flows = flows.lock().await;
                    let record = flows.entry(key).or_insert(FlowRecord {
                        bytes: 0,
                        packets: 0,
                        last_seen: Instant::now(),
                    });

                    record.bytes += packet_len;
                    record.packets += 1;
                    record.last_seen = Instant::now();
                }
            }
        }
    }
}
```

