### **Code: `flow_analyzer.rs`**
```rust
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EthernetPacket, EtherTypes};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// Flow structure to track connections
#[derive(Debug, Clone)]
struct Flow {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    protocol: String,
    packets: u64,
    bytes: u64,
    start_time: Instant,
}

// Main function to process packets
fn process_packets(interface: &str, flow_map: Arc<Mutex<HashMap<String, Flow>>>) {
    // Open the network interface
    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == interface)
        .expect("Interface not found");

    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error opening interface: {}", e),
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                // Parse Ethernet frame
                let eth_packet = EthernetPacket::new(packet).unwrap();
                if eth_packet.get_ethertype() != EtherTypes::Ipv4 {
                    continue; // Skip non-IPv4 packets
                }

                // Parse IPv4 packet
                let ipv4_packet = Ipv4Packet::new(eth_packet.payload()).unwrap();
                let src_ip = ipv4_packet.get_source().to_string();
                let dst_ip = ipv4_packet.get_destination().to_string();
                let protocol = match ipv4_packet.get_next_level_protocol() {
                    IpNextHeaderProtocols::Tcp => "TCP",
                    IpNextHeaderProtocols::Udp => "UDP",
                    _ => "OTHER",
                };

                // Parse transport layer (TCP/UDP)
                let (src_port, dst_port) = match protocol {
                    "TCP" => {
                        let tcp_packet = TcpPacket::new(ipv4_packet.payload()).unwrap();
                        (tcp_packet.get_source(), tcp_packet.get_destination())
                    }
                    "UDP" => {
                        let udp_packet = UdpPacket::new(ipv4_packet.payload()).unwrap();
                        (udp_packet.get_source(), udp_packet.get_destination())
                    }
                    _ => (0, 0), // Skip non-TCP/UDP
                };

                // Skip if no port info (e.g., ICMP)
                if src_port == 0 || dst_port == 0 {
                    continue;
                }

                // Create a unique flow key (src_ip:src_port-dst_ip:dst_port)
                let flow_key = format!("{}:{}-{}:{}", src_ip, src_port, dst_ip, dst_port);

                // Update flow stats
                let mut flows = flow_map.lock().unwrap();
                let entry = flows.entry(flow_key.clone()).or_insert_with(|| Flow {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    protocol: protocol.to_string(),
                    packets: 0,
                    bytes: 0,
                    start_time: Instant::now(),
                });

                entry.packets += 1;
                entry.bytes += ipv4_packet.get_total_length() as u64;
            }
            Err(e) => eprintln!("Error reading packet: {}", e),
        }
    }
}

// Log flows periodically
fn log_flows(flow_map: Arc<Mutex<HashMap<String, Flow>>>) {
    loop {
        thread::sleep(Duration::from_secs(5)); // Log every 5 seconds
        let flows = flow_map.lock().unwrap();

        println!("--- Flow Summary ---");
        for (key, flow) in flows.iter() {
            let duration = flow.start_time.elapsed().as_secs_f64();
            let bps = (flow.bytes as f64 / duration) as u64;
            println!(
                "Flow: {} | Packets: {} | Bytes: {} | BPS: {} | Duration: {:.2}s",
                key, flow.packets, flow.bytes, bps, duration
            );
        }
    }
}

fn main() {
    let interface = "eth0"; // Replace with your interface (e.g., "en0" on macOS)
    let flow_map: Arc<Mutex<HashMap<String, Flow>>> = Arc::new(Mutex::new(HashMap::new()));

    // Spawn packet processing thread
    let flow_map_clone = Arc::clone(&flow_map);
    thread::spawn(move || process_packets(interface, flow_map_clone));

    // Spawn logging thread
    let flow_map_clone = Arc::clone(&flow_map);
    thread::spawn(move || log_flows(flow_map_clone));

    // Keep main thread alive
    loop {
        thread::sleep(Duration::from_secs(1));
    }
}
