        .expect("No suitable network interface found");

    println!("Monitoring interface: {}", interface.name);

    // Create a channel for packet capture
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error creating datalink channel: {}", e),
    };

    // Shared flow statistics (thread-safe)
    let flow_stats = Arc::new(Mutex::new(HashMap::new()));

    // Spawn a worker thread to process packets
    let flow_stats_clone = Arc::clone(&flow_stats);
    thread::spawn(move || {
        loop {
            match rx.next() {
                Ok(packet) => process_packet(&packet, &flow_stats_clone),
                Err(e) => eprintln!("Error receiving packet: {}", e),
            }
        }
    });

    // Periodically print flow statistics
    loop {
        thread::sleep(Duration::from_secs(5));
        let stats = flow_stats.lock().unwrap();
        println!("\n=== Current Flow Statistics ===");
        for (key, stat) in stats.iter() {
            println!(
                "Flow: {:?}, Packets: {}, Bytes: {}, Duration: {:?}",
                key,
                stat.packets,
                stat.bytes,
                stat.last_seen.duration_since(stat.first_seen)
            );
        }
    }
}

fn process_packet(packet: &[u8], flow_stats: &Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    // Parse Ethernet frame
    let ethernet = match EthernetPacket::new(packet) {
        Some(p) => p,
        None => return,
    };

    // Parse IPv4 packet
    let ipv4 = match Ipv4Packet::new(ethernet.payload()) {
        Some(p) => p,
        None => return,
    };

    // Extract source and destination IPs
    let src_ip = ipv4.get_source().to_string();
    let dst_ip = ipv4.get_destination().to_string();

    // Extract transport layer info (TCP/UDP)
    let (src_port, dst_port, protocol) = match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = match TcpPacket::new(ipv4.payload()) {
                Some(p) => p,
                None => return,
            };
            (tcp.get_source(), tcp.get_destination(), "TCP".to_string())
        }
        IpNextHeaderProtocols::Udp => {
            let udp = match UdpPacket::new(ipv4.payload()) {
                Some(p) => p,
                None => return,
            };
            (udp.get_source(), udp.get_destination(), "UDP".to_string())
        }
        _ => return, // Ignore non-TCP/UDP traffic
    };

    // Create a flow key
    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol,
    };

    // Update flow statistics
    let mut stats = flow_stats.lock().unwrap();
    let now = Instant::now();
    let entry = stats.entry(key).or_insert(FlowStats {
        packets: 0,
        bytes: 0,
        first_seen: now,
        last_seen: now,
    });

    entry.packets += 1;
    entry.bytes += ipv4.get_total_length() as u64;
    entry.last_seen = now;
}
```

---

### **How It Works:**
1. **Packet Capture:**
   - Uses `pnet` to capture Ethernet frames.
   - Extracts **IPv4 packets** and **TCP/UDP flows**.

2. **Flow Aggregation:**
   - Each flow is identified by `(src_ip, dst_ip, src_port, dst_port, protocol)`.
   - Tracks **packet count**, **byte count**, and **duration**.

3. **Multi-Threaded Processing:**
   - A **worker thread** processes packets in real-time.
   - The **main thread** periodically prints statistics.

4. **Performance Optimizations:**
   - **No unnecessary allocations** (reuses `FlowKey` and `FlowStats`).
   - **Lock-free updates** (using `Arc<Mutex<HashMap>>` for thread safety).

