Below is a **minimal working version** of a **high-performance network flow analyser** in **Rust** (the best choice for safety and performance). This example captures **IPv4 traffic**, extracts **source/destination IPs and ports**, and aggregates **flow statistics** (packets/bytes per flow).

### **Key Features**
- Uses **`pnet`** for packet capture (efficient, low-level networking).
- Uses **`tokio`** for async I/O (handles high-speed traffic without blocking).
- Aggregates **flow statistics** (packets, bytes) in a **concurrent-safe** way.
- **Minimal dependencies** for maximum performance.

---

### **Code: `main.rs`**
```rust
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EthernetPacket, EtherTypes};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use tokio::runtime::Runtime;

// Flow key: (src_ip, dst_ip, src_port, dst_port, protocol)
type FlowKey = (Ipv4Addr, Ipv4Addr, u16, u16, u8);

// Flow statistics: (packets, bytes)
type FlowStats = (u64, u64);

#[tokio::main]
async fn main() {
    // Shared flow map (thread-safe)
    let flow_map: Arc<Mutex<HashMap<FlowKey, FlowStats>>> = Arc::new(Mutex::new(HashMap::new()));

    // Get the default network interface
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback())
        .expect("No suitable network interface found");

    // Create a channel for packet capture
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error creating datalink channel: {}", e),
    };

    println!("Monitoring traffic on {}...", interface.name);

    // Spawn a task to process packets
    tokio::spawn(async move {
        loop {
            match rx.next() {
                Ok(packet) => {
                    if let Some(ethernet) = EthernetPacket::new(packet) {
                        process_packet(ethernet, Arc::clone(&flow_map));
                    }
                }
                Err(e) => eprintln!("Error receiving packet: {}", e),
            }
        }
    });

    // Print flow stats periodically
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(std::time::Duration::from_secs(5)).await;
            print_flow_stats(&flow_map);
        }
    });

    // Keep the runtime alive
    Runtime::new().unwrap().block_on(async {
        tokio::signal::ctrl_c().await.unwrap();
        println!("Shutting down...");
    });
}

// Process a single packet and update flow stats
fn process_packet(ethernet: EthernetPacket, flow_map: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    match ethernet.get_ethertype() {
        EtherTypes::Ipv4 => {
            if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                let src_ip = ipv4.get_source();
                let dst_ip = ipv4.get_destination();
                let protocol = ipv4.get_next_level_protocol();

                match protocol {
                    IpNextHeaderProtocols::Tcp => {
                        if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                            let src_port = tcp.get_source();
                            let dst_port = tcp.get_destination();
                            let flow_key = (src_ip, dst_ip, src_port, dst_port, 6); // 6 = TCP

                            update_flow_stats(&flow_map, flow_key, ipv4.packet().len() as u64);
                        }
                    }
                    IpNextHeaderProtocols::Udp => {
                        if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                            let src_port = udp.get_source();
                            let dst_port = udp.get_destination();
                            let flow_key = (src_ip, dst_ip, src_port, dst_port, 17); // 17 = UDP

                            update_flow_stats(&flow_map, flow_key, ipv4.packet().len() as u64);
                        }
                    }
                    _ => {} // Ignore other protocols
                }
            }
        }
        _ => {} // Ignore non-IPv4 packets
    }
}

// Update flow statistics (thread-safe)
fn update_flow_stats(
    flow_map: &Arc<Mutex<HashMap<FlowKey, FlowStats>>>,
    flow_key: FlowKey,
    bytes: u64,
) {
    let mut map = flow_map.lock().unwrap();
    let entry = map.entry(flow_key).or_insert((0, 0));
    entry.0 += 1; // Increment packet count
    entry.1 += bytes; // Add bytes
}

// Print flow statistics
fn print_flow_stats(flow_map: &Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    let map = flow_map.lock().unwrap();
    println!("\n=== Flow Statistics ===");
    for (key, stats) in map.iter() {
        let (src_ip, dst_ip, src_port, dst_port, proto) = key;
        let (packets, bytes) = stats;
        println!(
            "Flow: {}:{} -> {}:{} ({}) | Packets: {} | Bytes: {}",
            src_ip, src_port, dst_ip, dst_port, proto, packets, bytes
        );
    }
}
```

