Here’s a **C-based firmware example** for a microcontroller (e.g., STM32, AVR, or ESP32) that reads data from an **analog sensor (e.g., temperature sensor)** and processes it. This example assumes an **ADC (Analog-to-Digital Converter)** and a simple moving average filter for noise reduction.

### **Firmware Code (C)**
```c
#include <stdint.h>
#include <stdio.h>

// Define microcontroller-specific ADC and GPIO functions (example for STM32 HAL)
#ifdef STM32
#include "stm32f4xx_hal.h"
ADC_HandleTypeDef hadc1;
#endif

// Define microcontroller-specific ADC and GPIO functions (example for AVR)
#ifdef AVR
#include <avr/io.h>
#include <util/delay.h>
#endif

// Define microcontroller-specific ADC and GPIO functions (example for ESP32)
#ifdef ESP32
#include "driver/adc.h"
#include "esp_log.h"
#endif

// Constants
#define SAMPLE_SIZE 10  // Number of samples for moving average
#define ADC_MAX_VALUE 4095  // 12-bit ADC (adjust based on your MCU)

// Global variables
uint16_t adc_samples[SAMPLE_SIZE] = {0};
uint8_t sample_index = 0;
float filtered_value = 0.0;

// Function to initialize ADC (example for STM32 HAL)
void ADC_Init(void) {
#ifdef STM32
    __HAL_RCC_ADC1_CLK_ENABLE();
    hadc1.Instance = ADC1;
    hadc1.Init.ClockPrescaler = ADC_CLOCK_SYNC_PCLK_DIV4;
    hadc1.Init.Resolution = ADC_RESOLUTION_12B;
    hadc1.Init.ScanConvMode = DISABLE;
    hadc1.Init.ContinuousConvMode = ENABLE;
    hadc1.Init.DiscontinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConvEdge = ADC_EXTERNALTRIGCONVEDGE_NONE;
    hadc1.Init.ExternalTrigConv = ADC_SOFTWARE_START;
    hadc1.Init.DataAlign = ADC_DATAALIGN_RIGHT;
    hadc1.Init.NbrOfConversion = 1;
    hadc1.Init.DMAContinuousRequests = DISABLE;
    hadc1.Init.EOCSelection = ADC_EOC_SINGLE_CONV;
    HAL_ADC_Init(&hadc1);
#endif

#ifdef AVR
    ADMUX = (1 << REFS0);  // AVCC as reference
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);  // Enable ADC, prescaler=128
#endif

#ifdef ESP32
    adc1_config_width(ADC_WIDTH_BIT_12);
    adc1_config_channel_atten(ADC1_CHANNEL_0, ADC_ATTEN_DB_11);
#endif
}

// Function to read ADC value (example for STM32 HAL)
uint16_t Read_ADC(void) {
#ifdef STM32
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, 10);
    return HAL_ADC_GetValue(&hadc1);
#endif

#ifdef AVR
    ADCSRA |= (1 << ADSC);  // Start conversion
    while (ADCSRA & (1 << ADSC));  // Wait for conversion
    return ADC;
#endif

#ifdef ESP32
    return adc1_get_raw(ADC1_CHANNEL_0);
#endif
}

// Simple moving average filter
float Process_Sensor_Data(uint16_t raw_value) {
    static float sum = 0.0;

    // Remove oldest sample from sum
    sum -= adc_samples[sample_index];

    // Store new sample
    adc_samples[sample_index] = raw_value;
    sum += raw_value;

    // Update index (circular buffer)
    sample_index = (sample_index + 1) % SAMPLE_SIZE;

    // Calculate average
    filtered_value = sum / SAMPLE_SIZE;

    return filtered_value;
}

// Main function
int main(void) {
    // Initialize hardware
    ADC_Init();

    while (1) {
        // Read raw ADC value
        uint16_t raw_value = Read_ADC();

        // Process data (moving average)
        float processed_value = Process_Sensor_Data(raw_value);

        // Convert to voltage (example for 3.3V ADC)
        float voltage = (processed_value / ADC_MAX_VALUE) * 3.3;

        // Print or transmit data (example for STM32 UART)
        #ifdef STM32
        printf("Raw: %d, Filtered: %.2f, Voltage: %.2fV\n", raw_value, processed_value, voltage);
        #endif

        // Delay (adjust based on sampling rate)
        #ifdef AVR
        _delay_ms(100);
        #endif

        #ifdef ESP32
        vTaskDelay(100 / portTICK_PERIOD_MS);
        #endif
    }

    return 0;
}
```

