// Read temperature from sensor
float readTemperature(void) {
    float temp = 0.0f;

#ifdef USE_ANALOG_SENSOR
    // LM35: 10mV per °C, 3.3V ADC reference
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, 10);
    uint32_t adcValue = HAL_ADC_GetValue(&hadc1);
    temp = (adcValue * 3.3f / 4095.0f) * 100.0f;  // Convert to °C
#endif

#ifdef USE_DIGITAL_SENSOR
    // DS18B20: Digital temperature sensor
    uint8_t scratchpad[9];
    if (OneWire_Reset(ONE_WIRE_PIN) == 0) {
        OneWire_WriteByte(ONE_WIRE_PIN, 0xCC);  // Skip ROM
        OneWire_WriteByte(ONE_WIRE_PIN, 0x44);  // Start conversion
        HAL_Delay(800);  // Wait for conversion

        OneWire_Reset(ONE_WIRE_PIN);
        OneWire_WriteByte(ONE_WIRE_PIN, 0xCC);  // Skip ROM
        OneWire_WriteByte(ONE_WIRE_PIN, 0xBE);  // Read scratchpad

        for (int i = 0; i < 9; i++) {
            scratchpad[i] = OneWire_ReadByte(ONE_WIRE_PIN);
        }

        int16_t rawTemp = (scratchpad[1] << 8) | scratchpad[0];
        temp = rawTemp / 16.0f;  // Convert to °C
    }
#endif

    return temp;
}

// Process and log temperature data
void processData(float temp) {
    char buffer[50];
    snprintf(buffer, sizeof(buffer), "Temperature: %.2f°C\r\n", temp);
    HAL_UART_Transmit(&huart2, (uint8_t*)buffer, strlen(buffer), HAL_MAX_DELAY);

    // Example: Trigger an alarm if temp > 30°C
    if (temp > 30.0f) {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);  // Turn on LED
    } else {
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET);
    }
}

