    static float sum = 0.0;

    // Subtract oldest data point
    sum -= sensor_data[data_index];

    // Store new data
    sensor_data[data_index] = new_data;
    sum += new_data;

    // Update index (circular buffer)
    data_index = (data_index + 1) % MOVING_AVG_SIZE;

    // Return average
    return sum / MOVING_AVG_SIZE;
