        HAL_ADC_Start(&hadc1);  // Start ADC conversion
        HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
        uint16_t rawValue = HAL_ADC_GetValue(&hadc1);

        // Store in buffer and compute moving average
        adcBuffer[sampleIndex] = rawValue;
        sampleIndex = (sampleIndex + 1) % SENSOR_SAMPLES;
        filteredValue = MovingAverageFilter(adcBuffer, SENSOR_SAMPLES);

        // Process data (e.g., convert to temperature)
        ProcessSensorData();

        // Delay for next reading (e.g., 100ms)
        HAL_Delay(100);
    }
