### **Code Implementation**
```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <chrono>
#include <cmath>
#include <vector>

// --- Shared Data (Thread-Safe) ---
struct RobotState {
    double x = 0.0;       // Position (x)
    double y = 0.0;       // Position (y)
    double theta = 0.0;    // Orientation (yaw)
    double v_left = 0.0;   // Left wheel speed (rad/s)
    double v_right = 0.0;  // Right wheel speed (rad/s)
    std::mutex mtx;        // Mutex for thread safety
};

// --- Kalman Filter for Sensor Fusion ---
class KalmanFilter {
private:
    // State: [x, y, theta, v_left, v_right]
    Eigen::VectorXd x;      // State estimate
    Eigen::MatrixXd P;      // State covariance
    Eigen::MatrixXd Q;      // Process noise
    Eigen::MatrixXd R;      // Measurement noise
    Eigen::MatrixXd F;      // State transition
    Eigen::MatrixXd H;      // Measurement model

public:
    KalmanFilter() {
        x = Eigen::VectorXd::Zero(5);
        P = Eigen::MatrixXd::Identity(5, 5);
        Q = Eigen::MatrixXd::Identity(5, 5) * 0.1;
        R = Eigen::MatrixXd::Identity(3, 3) * 0.5;  // IMU + Encoder noise
        F = Eigen::MatrixXd::Identity(5, 5);
        H = Eigen::MatrixXd::Zero(3, 5);
        H(0, 0) = 1.0;  // x
        H(1, 1) = 1.0;  // y
        H(2, 2) = 1.0;  // theta
    }

    void predict(double dt) {
        F(0, 3) = dt * cos(x(2));  // x += v_left * cos(theta) * dt
        F(1, 3) = dt * sin(x(2));  // y += v_left * sin(theta) * dt
        F(0, 4) = dt * cos(x(2));  // x += v_right * cos(theta) * dt
        F(1, 4) = dt * sin(x(2));  // y += v_right * sin(theta) * dt
        x = F * x;
        P = F * P * F.transpose() + Q;
    }

    void update(const Eigen::VectorXd& z) {
        Eigen::MatrixXd S = H * P * H.transpose() + R;
        Eigen::MatrixXd K = P * H.transpose() * S.inverse();
        x = x + K * (z - H * x);
        P = (Eigen::MatrixXd::Identity(5, 5) - K * H) * P;
    }

    Eigen::VectorXd getState() const { return x; }
};

// --- PID Controller for Motor Control ---
class PIDController {
private:
    double Kp, Ki, Kd;
    double prev_error = 0.0;
    double integral = 0.0;

public:
    PIDController(double Kp, double Ki, double Kd) : Kp(Kp), Ki(Ki), Kd(Kd) {}

    double compute(double setpoint, double measured, double dt) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return Kp * error + Ki * integral + Kd * derivative;
    }
};

// --- Simulated Sensor Data ---
struct SensorData {
    double encoder_left = 0.0;   // Left wheel encoder (rad)
    double encoder_right = 0.0;  // Right wheel encoder (rad)
    double imu_yaw = 0.0;        // IMU yaw (rad)
};

// --- Control Loop Thread ---
void controlLoop(RobotState& state, KalmanFilter& kf, PIDController& pid_left, PIDController& pid_right) {
    const double dt = 0.01;  // 10ms control loop
    const double wheel_radius = 0.1;  // 10cm wheel radius
    const double wheel_base = 0.3;    // 30cm wheelbase

    while (true) {
        // --- Sensor Fusion (Kalman Filter) ---
        SensorData sensor_data;
        // Simulate sensor readings (replace with real sensor data)
        sensor_data.encoder_left += state.v_left * dt;
        sensor_data.encoder_right += state.v_right * dt;
        sensor_data.imu_yaw = state.theta + 0.01 * (rand() % 10 - 5);  // Add noise

        // Predict step
        kf.predict(dt);

        // Update step (IMU + Encoder fusion)
        Eigen::VectorXd z(3);
        z << state.x, state.y, sensor_data.imu_yaw;
        kf.update(z);

        // Update robot state
        Eigen::VectorXd fused_state = kf.getState();
        {
            std::lock_guard<std::mutex> lock(state.mtx);
            state.x = fused_state(0);
            state.y = fused_state(1);
            state.theta = fused_state(2);
        }

        // --- Motor Control (PID) ---
        double target_v_left = 1.0;  // Desired left wheel speed (rad/s)
        double target_v_right = 1.0; // Desired right wheel speed (rad/s)

        double control_left = pid_left.compute(target_v_left, state.v_left, dt);
        double control_right = pid_right.compute(target_v_right, state.v_right, dt);

        // Simulate motor response (replace with real motor control)
        {
            std::lock_guard<std::mutex> lock(state.mtx);
            state.v_left += control_left * dt;
            state.v_right += control_right * dt;
        }

        // Print state (for debugging)
        std::cout << "State: x=" << state.x << ", y=" << state.y << ", theta=" << state.theta << std::endl;

        // Sleep to maintain loop rate
        std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(dt * 1000)));
    }
}

int main() {
    RobotState state;
    KalmanFilter kf;
    PIDController pid_left(1.0, 0.1, 0.01);  // Kp, Ki, Kd for left wheel
    PIDController pid_right(1.0, 0.1, 0.01); // Kp, Ki, Kd for right wheel

    // Start control loop in a separate thread
    std::thread control_thread(controlLoop, std::ref(state), std::ref(kf), std::ref(pid_left), std::ref(pid_right));

    // Main thread can do other tasks (e.g., logging, user input)
    while (true) {
