    float left_speed, right_speed;     // Desired speeds (rad/s)
    float timestamp;                   // Seconds since boot
};

// PID Controller
class PIDController {
private:
    float Kp, Ki, Kd;
    float prev_error, integral;
    float output_min, output_max;

public:
    PIDController(float kp, float ki, float kd, float min_out, float max_out)
        : Kp(kp), Ki(ki), Kd(kd), prev_error(0), integral(0),
          output_min(min_out), output_max(max_out) {}

    float compute(float setpoint, float measured, float dt) {
        float error = setpoint - measured;
        integral += error * dt;
        float derivative = (error - prev_error) / dt;
        prev_error = error;

        float output = Kp * error + Ki * integral + Kd * derivative;
        return std::clamp(output, output_min, output_max);
    }
};

// Robot Control Loop
class RobotController {
private:
    IMUData imu_data;
    EncoderData encoder_data;
    MotorCommand motor_cmd;
    std::mutex data_mutex;
    std::atomic<bool> running;

    // PID Controllers for left and right motors
    PIDController left_pid;
    PIDController right_pid;

    // Sensor Fusion (Complementary Filter)
    float fused_angle;  // Fused orientation (rad)
    float fused_angular_velocity;  // Fused angular velocity (rad/s)

public:
    RobotController()
        : left_pid(1.0, 0.1, 0.01, -1.0, 1.0),
          right_pid(1.0, 0.1, 0.01, -1.0, 1.0),
          fused_angle(0), fused_angular_velocity(0), running(false) {}

    // Update sensor data (called by sensor threads)
    void updateIMU(const IMUData& data) {
        std::lock_guard<std::mutex> lock(data_mutex);
        imu_data = data;
    }

    void updateEncoders(const EncoderData& data) {
        std::lock_guard<std::mutex> lock(data_mutex);
        encoder_data = data;
    }

    // Sensor Fusion (Complementary Filter)
    void fuseSensors(float alpha = 0.98) {
        std::lock_guard<std::mutex> lock(data_mutex);

        // Simple complementary filter for angle estimation
        float dt = imu_data.timestamp - encoder_data.timestamp;
        if (dt <= 0) return;

        // Gyro integration (predicted angle)
        float gyro_angle = fused_angle + imu_data.gyro_z * dt;

        // Encoder-based angle (measured angle)
        float encoder_angle = (encoder_data.left_ticks + encoder_data.right_ticks) / 2.0f;

        // Fuse data
        fused_angle = alpha * gyro_angle + (1.0f - alpha) * encoder_angle;
        fused_angular_velocity = imu_data.gyro_z;  // Use gyro for angular velocity
    }

    // Motor Control Loop
    void controlLoop() {
        running = true;
        auto last_time = std::chrono::steady_clock::now();

        while (running) {
            auto current_time = std::chrono::steady_clock::now();
            float dt = std::chrono::duration<float>(current_time - last_time).count();
            last_time = current_time;

            // Sensor Fusion
            fuseSensors();

            // PID Control for Motors
            float left_setpoint = motor_cmd.left_speed;
            float right_setpoint = motor_cmd.right_speed;

            float left_feedback = encoder_data.left_ticks;  // Simplified (replace with actual speed)
            float right_feedback = encoder_data.right_ticks;

            float left_output = left_pid.compute(left_setpoint, left_feedback, dt);
            float right_output = right_pid.compute(right_setpoint, right_feedback, dt);

            // Apply motor commands (simplified)
            std::cout << "Left Motor: " << left_output << ", Right Motor: " << right_output << std::endl;

            // Sleep to maintain loop rate (e.g., 100Hz)
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    // Set desired motor speeds
    void setMotorSpeeds(float left, float right) {
        std::lock_guard<std::mutex> lock(data_mutex);
        motor_cmd.left_speed = left;
        motor_cmd.right_speed = right;
        motor_cmd.timestamp = std::chrono::duration<float>(
            std::chrono::steady_clock::now().time_since_epoch()
        ).count();
    }

    // Stop the control loop
    void stop() {
        running = false;
    }
};

