// ===== Sensor Fusion (Kalman Filter) =====
class KalmanFilter {
private:
    double x, P, Q, R; // State, covariance, process noise, measurement noise

public:
    KalmanFilter(double initial_state, double process_noise, double measurement_noise)
        : x(initial_state), P(1.0), Q(process_noise), R(measurement_noise) {}

    void update(double measurement) {
        // Prediction step
        P += Q;

        // Update step
        double K = P / (P + R); // Kalman gain
        x += K * (measurement - x);
        P *= (1 - K);
    }

