// PID Controller Class
class PIDController {
public:
    PIDController(double kp, double ki, double kd, double max_output)
        : kp_(kp), ki_(ki), kd_(kd), max_output_(max_output) {}

    double compute(double setpoint, double measured_value, double dt) {
        double error = setpoint - measured_value;
        integral_ += error * dt;
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = std::clamp(output, -max_output_, max_output_);
        return output;
    }

private:
    double kp_, ki_, kd_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
    double max_output_;
};

