            "/imu/data", 10, std::bind(&RobotController::imu_callback, this, std::placeholders::_1));
        encoder_sub_ = this->create_subscription<std_msgs::msg::Float64>(
            "/wheel_velocity", 10, std::bind(&RobotController::encoder_callback, this, std::placeholders::_1));
        cmd_vel_sub_ = this->create_subscription<geometry_msgs::msg::Twist>(
            "/cmd_vel", 10, std::bind(&RobotController::cmd_vel_callback, this, std::placeholders::_1));

        // Publishers
        odom_pub_ = this->create_publisher<nav_msgs::msg::Odometry>("/odom", 10);
        motor_pub_ = this->create_publisher<std_msgs::msg::Float64>("/motor_command", 10);

        // PID Controllers (left and right wheels)
        left_pid_ = std::make_unique<PIDController>(1.0, 0.1, 0.01, 10.0);
        right_pid_ = std::make_unique<PIDController>(1.0, 0.1, 0.01, 10.0);

        // Control loop timer (100Hz)
        timer_ = this->create_wall_timer(
            std::chrono::milliseconds(10),
            std::bind(&RobotController::control_loop, this));
    }

private:
    // Callbacks
    void imu_callback(const sensor_msgs::msg::Imu::SharedPtr msg) {
        imu_data_ = *msg;
    }

    void encoder_callback(const std_msgs::msg::Float64::SharedPtr msg) {
        wheel_velocity_ = msg->data;
    }

    void cmd_vel_callback(const geometry_msgs::msg::Twist::SharedPtr msg) {
        target_linear_vel_ = msg->linear.x;
        target_angular_vel_ = msg->angular.z;
    }

    // Control Loop (100Hz)
    void control_loop() {
        // Sensor Fusion (IMU + Encoder)
        double fused_velocity = 0.5 * wheel_velocity_ + 0.5 * imu_data_.angular_velocity.z;

        // Compute wheel velocities (differential drive)
        double left_vel = target_linear_vel_ - (target_angular_vel_ * wheel_separation_ / 2.0);
        double right_vel = target_linear_vel_ + (target_angular_vel_ * wheel_separation_ / 2.0);

        // PID Control
        double left_motor_cmd = left_pid_->compute(left_vel, fused_velocity, 0.01);
        double right_motor_cmd = right_pid_->compute(right_vel, fused_velocity, 0.01);

        // Publish motor commands
        auto motor_msg = std_msgs::msg::Float64();
        motor_msg.data = left_motor_cmd;  // Simplified (real implementation would send to each motor)
        motor_pub_->publish(motor_msg);

        // Publish odometry (simplified)
        auto odom_msg = nav_msgs::msg::Odometry();
        odom_msg.header.stamp = this->now();
        odom_msg.twist.twist.linear.x = target_linear_vel_;
        odom_msg.twist.twist.angular.z = target_angular_vel_;
        odom_pub_->publish(odom_msg);
    }

    // ROS Components
    rclcpp::Subscription<sensor_msgs::msg::Imu>::SharedPtr imu_sub_;
    rclcpp::Subscription<std_msgs::msg::Float64>::SharedPtr encoder_sub_;
    rclcpp::Subscription<geometry_msgs::msg::Twist>::SharedPtr cmd_vel_sub_;
    rclcpp::Publisher<nav_msgs::msg::Odometry>::SharedPtr odom_pub_;
    rclcpp::Publisher<std_msgs::msg::Float64>::SharedPtr motor_pub_;
    rclcpp::TimerBase::SharedPtr timer_;

    // Robot Parameters
    double wheel_separation_ = 0.3;  // meters (distance between wheels)
