// Sensor Fusion: Update robot pose using IMU and encoders
void RobotController::updateSensors(const IMUData& imu, const EncoderData& encoders) {
    // Calculate wheel speeds from encoders (m/s)
    double left_wheel_speed = (encoders.left_encoder_ticks / encoder_ticks_per_rev) *
                             (2 * M_PI * wheel_radius) / dt;
    double right_wheel_speed = (encoders.right_encoder_ticks / encoder_ticks_per_rev) *
                              (2 * M_PI * wheel_radius) / dt;

    // Robot velocity (differential drive kinematics)
    double linear_velocity = (left_wheel_speed + right_wheel_speed) / 2.0;
    double angular_velocity = (right_wheel_speed - left_wheel_speed) / wheel_base;

    // Update pose using IMU and encoder data (simplified)
    robot_x += linear_velocity * cos(robot_theta) * dt;
    robot_y += linear_velocity * sin(robot_theta) * dt;
    robot_theta += angular_velocity * dt;

    // Optional: Apply IMU correction (e.g., for drift)
    robot_theta += imu.angular_velocity * dt;
}

// Motor Control: Compute PWM commands for differential drive
MotorCommand RobotController::computeMotorCommands(double target_speed, double target_turn) {
    MotorCommand cmd;

    // Simple proportional control (PID could be added)
    cmd.left_motor_speed = target_speed - target_turn;
    cmd.right_motor_speed = target_speed + target_turn;

    // Clamp to valid PWM range (-1.0 to 1.0)
    cmd.left_motor_speed = std::max(-1.0, std::min(1.0, cmd.left_motor_speed));
    cmd.right_motor_speed = std::max(-1.0, std::min(1.0, cmd.right_motor_speed));

    return cmd;
}

// Main Control Loop (Fixed time step)
void RobotController::runControlLoop(double dt) {
    while (true) {
        auto current_time = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> elapsed = current_time - last_time;

        if (elapsed.count() >= dt) {
            last_time = current_time;

            // Read sensors (simulated here)
            IMUData imu = {0.1, 0.0};  // Example: 0.1 rad/s angular velocity
            EncoderData encoders = {10.0, 10.0};  // Example: 10 encoder ticks

            // Update robot state
            updateSensors(imu, encoders);

            // Compute motor commands (e.g., move forward at 0.5 m/s)
