```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <Eigen/Dense>
#include <boost/asio.hpp>

// Simulated sensor data
struct IMUData {
    double angular_velocity;  // rad/s
    double linear_acceleration; // m/s²
};

struct EncoderData {
    double left_wheel_speed;   // rad/s
    double right_wheel_speed; // rad/s
};

// Kalman Filter for IMU Fusion
class IMUKalmanFilter {
private:
    Eigen::Matrix2d A;  // State transition matrix
    Eigen::Matrix2d H;  // Observation matrix
    Eigen::Matrix2d Q;  // Process noise covariance
    Eigen::Matrix2d R;  // Measurement noise covariance
    Eigen::Matrix2d P;  // Estimate covariance
    Eigen::Vector2d x;  // State vector [angular_velocity, linear_acceleration]

public:
    IMUKalmanFilter() {
        A << 1, 0, 0, 1;  // Identity (no dynamics)
        H << 1, 0, 0, 1;  // Direct observation
        Q << 0.1, 0, 0, 0.1;  // Process noise
        R << 0.5, 0, 0, 0.5;  // Measurement noise
        P << 1, 0, 0, 1;      // Initial covariance
        x << 0, 0;           // Initial state
    }

    void predict() {
        x = A * x;
        P = A * P * A.transpose() + Q;
    }

    void update(const IMUData& imu) {
        Eigen::Vector2d z(imu.angular_velocity, imu.linear_acceleration);
        Eigen::Vector2d y = z - H * x;
        Eigen::Matrix2d S = H * P * H.transpose() + R;
        Eigen::Matrix2d K = P * H.transpose() * S.inverse();

        x = x + K * y;
        P = (Eigen::Matrix2d::Identity() - K * H) * P;
    }

    Eigen::Vector2d getState() const { return x; }
};

// PID Controller for Motor Speed
class PIDController {
private:
    double Kp, Ki, Kd;
    double prev_error, integral;
    double dt;

public:
    PIDController(double Kp, double Ki, double Kd, double dt)
        : Kp(Kp), Ki(Ki), Kd(Kd), prev_error(0), integral(0), dt(dt) {}

    double compute(double setpoint, double measured) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;

        return Kp * error + Ki * integral + Kd * derivative;
    }
};

// Simulated Robot Control Loop
class RobotControlLoop {
private:
    IMUKalmanFilter imu_filter;
    PIDController left_pid, right_pid;
    boost::asio::steady_timer timer;
    double target_speed;  // rad/s

public:
    RobotControlLoop(boost::asio::io_context& io, double Kp, double Ki, double Kd, double dt)
        : left_pid(Kp, Ki, Kd, dt), right_pid(Kp, Ki, Kd, dt), timer(io), target_speed(1.0) {}

    void run() {
        timer.expires_after(std::chrono::milliseconds(10));  // 100Hz control loop
        timer.async_wait([this](const boost::system::error_code&) {
            controlStep();
            run();  // Recursive loop
        });
    }

    void controlStep() {
        // Simulate sensor readings
        IMUData imu = {0.1, 9.8};  // Simulated IMU data
        EncoderData encoders = {0.9, 1.1};  // Simulated encoder data

        // Sensor Fusion (Kalman Filter)
        imu_filter.predict();
        imu_filter.update(imu);
        auto fused_state = imu_filter.getState();

        // Motor Control (PID)
        double left_control = left_pid.compute(target_speed, encoders.left_wheel_speed);
        double right_control = right_pid.compute(target_speed, encoders.right_wheel_speed);

        // Apply motor commands (simulated)
        std::cout << "IMU Fused: [" << fused_state[0] << ", " << fused_state[1] << "] | "
                  << "Motor Control: [" << left_control << ", " << right_control << "]" << std::endl;

        // Adjust target speed (simulated)
        target_speed += 0.01;  // Ramp up for testing
    }
};

int main() {
    boost::asio::io_context io;
    RobotControlLoop robot(io, 1.0, 0.1, 0.01, 0.01);  // Kp, Ki, Kd, dt
    robot.run();
    io.run();  // Start the event loop
    return 0;
}
