// Kalman Filter for Sensor Fusion (IMU + Encoders)
class KalmanFilter {
private:
    Eigen::Matrix2d A, H, Q, R, P;
    Eigen::Vector2d x;

public:
    KalmanFilter() {
        // State transition matrix (constant velocity model)
        A << 1, 0.1, 0, 1;
        // Measurement matrix (only position is measured)
        H << 1, 0, 0, 1;
        // Process noise covariance (tune based on system)
        Q << 0.1, 0, 0, 0.1;
        // Measurement noise covariance (tune based on sensors)
        R << 0.5, 0, 0, 0.5;
        // Initial state covariance
        P << 1, 0, 0, 1;
        // Initial state (position, velocity)
        x << 0, 0;
    }

    void predict() {
        x = A * x;
        P = A * P * A.transpose() + Q;
    }

    void update(double measurement) {
        Eigen::Vector2d y = Eigen::Vector2d(measurement, 0) - H * x;
        Eigen::Matrix2d S = H * P * H.transpose() + R;
        Eigen::Matrix2d K = P * H.transpose() * S.inverse();
        x = x + K * y;
        P = (Eigen::Matrix2d::Identity() - K * H) * P;
    }

    double getPosition() { return x(0); }
    double getVelocity() { return x(1); }
};

