class SensorFusion {
public:
    double fuseIMUAndEncoder(const IMUData& imu, const EncoderData& encoder) {
        // Simple complementary filter (weighted average)
        const double alpha = 0.9; // IMU weight
        return alpha * imu.angular_velocity + (1 - alpha) * encoder.velocity;
