    // IMU Callback (Sensor Fusion)
    void imu_callback(const sensor_msgs::msg::Imu::SharedPtr msg) {
        // Extract yaw and yaw rate from IMU
        tf2::Quaternion q(
            msg->orientation.x,
            msg->orientation.y,
            msg->orientation.z,
            msg->orientation.w);

        tf2::Matrix3x3 m(q);
        double roll, pitch;
        m.getRPY(roll, pitch, yaw_);

        yaw_rate_ = msg->angular_velocity.z;  // Yaw rate (rad/s)
    }

    // Command Velocity Callback (Twist to Wheel Velocities)
    void cmd_vel_callback(const geometry_msgs::msg::Twist::SharedPtr msg) {
        // Convert Twist (linear & angular velocity) to wheel velocities
        double linear_vel = msg->linear.x;
        double angular_vel = msg->angular.z;

        left_vel_cmd_ = linear_vel - (angular_vel * wheel_base_ / 2.0);
        right_vel_cmd_ = linear_vel + (angular_vel * wheel_base_ / 2.0);

        // Convert to wheel speeds (rad/s)
        left_vel_cmd_ /= wheel_radius_;
        right_vel_cmd_ /= wheel_radius_;
    }

    // Control Loop (PID + Motor Control)
    void control_loop() {
        rclcpp::Rate loop_rate(50);  // 50Hz control loop

        while (rclcpp::ok()) {
            // Get current wheel speeds (from encoders, simulated here)
            double left_vel_actual = left_vel_cmd_;  // Replace with encoder feedback
            double right_vel_actual = right_vel_cmd_; // Replace with encoder feedback

            // Compute PID outputs
            double left_pwm = left_pid_.compute(left_vel_cmd_, left_vel_actual, 0.02);  // 0.02s = 50Hz
            double right_pwm = right_pid_.compute(right_vel_cmd_, right_vel_actual, 0.02);

            // Send PWM to motors (simulated here)
            RCLCPP_INFO(this->get_logger(),
                "Left PWM: %.2f, Right PWM: %.2f", left_pwm, right_pwm);

            // Publish Odometry (for ROS navigation)
            nav_msgs::msg::Odometry odom;
            odom.header.stamp = this->now();
            odom.header.frame_id = "odom";
            odom.child_frame_id = "base_link";

            // Update pose (simplified, replace with actual odometry)
            odom.pose.pose.position.x += (left_vel_actual + right_vel_actual) * wheel_radius_ * 0.02 / 2.0;
            odom.pose.pose.orientation = tf2::toMsg(tf2::Quaternion(tf2::Vector3(0, 0, 1), yaw_));

            odom_pub_->publish(odom);

            rclcpp::spin_some(this->get_node_base_interface());
            loop_rate.sleep();
        }
    }
};

int main(int argc, char **argv) {
    rclcpp::init(argc, argv);
    auto node = std::make_shared<RobotController>();
    node->control_loop();
    rclcpp::shutdown();
