#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/imu.hpp>
#include <nav_msgs/msg/odometry.hpp>
#include <geometry_msgs/msg/twist.hpp>
#include <std_msgs/msg/float64_multi_array.hpp>

// PID Controller for Motor Velocity
class PIDController {
private:
    double kp, ki, kd;
    double prev_error, integral;
public:
    PIDController(double kp, double ki, double kd) : kp(kp), ki(ki), kd(kd), prev_error(0), integral(0) {}

    double compute(double setpoint, double measured) {
        double error = setpoint - measured;
        integral += error;
        double derivative = error - prev_error;
        prev_error = error;
        return kp * error + ki * integral + kd * derivative;
    }
};

class RobotControlNode : public rclcpp::Node {
private:
    // Publishers & Subscribers
    rclcpp::Publisher<geometry_msgs::msg::Twist>::SharedPtr motor_cmd_pub_;
    rclcpp::Subscription<sensor_msgs::msg::Imu>::SharedPtr imu_sub_;
    rclcpp::Subscription<std_msgs::msg::Float64MultiArray>::SharedPtr encoder_sub_;

    // PID Controllers (left & right wheels)
    PIDController left_pid_{0.5, 0.1, 0.01};
    PIDController right_pid_{0.5, 0.1, 0.01};

    // Sensor Data
    double imu_yaw_{0.0};
    double left_wheel_vel_{0.0}, right_wheel_vel_{0.0};

public:
    RobotControlNode() : Node("robot_control_node") {
        // Publishers
        motor_cmd_pub_ = this->create_publisher<geometry_msgs::msg::Twist>("/cmd_vel", 10);

        // Subscribers
        imu_sub_ = this->create_subscription<sensor_msgs::msg::Imu>(
            "/imu/data", 10,
            [this](const sensor_msgs::msg::Imu::SharedPtr msg) {
                imu_yaw_ = msg->orientation.z; // Simplified yaw extraction
            });

        encoder_sub_ = this->create_subscription<std_msgs::msg::Float64MultiArray>(
            "/wheel_encoders", 10,
            [this](const std_msgs::msg::Float64MultiArray::SharedPtr msg) {
                left_wheel_vel_ = msg->data[0];
                right_wheel_vel_ = msg->data[1];
            });

        // Control Loop (100Hz)
        auto timer_callback = [this]() {
            // Desired velocities (e.g., from a higher-level planner)
            double left_setpoint = 1.0;  // m/s
            double right_setpoint = 1.0; // m/s

            // Compute PID outputs
            double left_cmd = left_pid_.compute(left_setpoint, left_wheel_vel_);
            double right_cmd = right_pid_.compute(right_setpoint, right_wheel_vel_);

            // Publish motor commands
            auto motor_cmd = geometry_msgs::msg::Twist();
            motor_cmd.linear.x = (left_cmd + right_cmd) / 2.0; // Linear velocity
            motor_cmd.angular.z = (right_cmd - left_cmd) / 0.3; // Angular velocity (wheelbase = 0.3m)
            motor_cmd_pub_->publish(motor_cmd);
        };

        rclcpp::WallRate loop_rate(100); // 100Hz control loop
        while (rclcpp::ok()) {
            timer_callback();
            rclcpp::spin_some(this->get_node_base_interface());
            loop_rate.sleep();
        }
    }
};

int main(int argc, char **argv) {
    rclcpp::init(argc, argv);
    auto node = std::make_shared<RobotControlNode>();
    rclcpp::spin(node);
    rclcpp::shutdown();
    return 0;
}
