constexpr double WHEEL_BASE = 0.2;     // meters (distance between wheels)
constexpr double MAX_SPEED = 1.0;      // m/s
constexpr double PID_KP = 0.5;         // Proportional gain
constexpr double PID_KI = 0.1;         // Integral gain
constexpr double PID_KD = 0.05;        // Derivative gain

class RobotController : public rclcpp::Node {
public:
    RobotController() : Node("robot_controller") {
        // Subscribers
        imu_sub_ = this->create_subscription<sensor_msgs::msg::IMU>(
            "/imu/data", 10, std::bind(&RobotController::imu_callback, this, std::placeholders::_1));

        odom_sub_ = this->create_subscription<nav_msgs::msg::Odometry>(
            "/odom", 10, std::bind(&RobotController::odom_callback, this, std::placeholders::_1));

        // Publisher for motor commands
        cmd_vel_pub_ = this->create_publisher<geometry_msgs::msg::Twist>("/cmd_vel", 10);

        // Timer for control loop (100Hz)
        control_timer_ = this->create_wall_timer(
            std::chrono::milliseconds(10),
            std::bind(&RobotController::control_loop, this));
    }

private:
    // Sensor callbacks
    void imu_callback(const sensor_msgs::msg::IMU::SharedPtr msg) {
        current_yaw_ = msg->orientation.z;  // Simplified yaw extraction
    }

    void odom_callback(const nav_msgs::msg::Odometry::SharedPtr msg) {
        current_x_ = msg->pose.pose.position.x;
        current_y_ = msg->pose.pose.position.y;
    }

    // PID Controller for motor control
    void control_loop() {
        // Example: Move forward at 0.5 m/s
        double target_speed = 0.5;
        double error = target_speed - current_speed_;

        // Simple PID control
        integral_error_ += error;
        double derivative_error = error - prev_error_;
        double control_output = PID_KP * error + PID_KI * integral_error_ + PID_KD * derivative_error;
        prev_error_ = error;

        // Publish motor commands (simplified)
        auto cmd_vel = geometry_msgs::msg::Twist();
        cmd_vel.linear.x = std::min(MAX_SPEED, control_output);  // Clamp speed
        cmd_vel.angular.z = 0.0;  // No turning in this example
        cmd_vel_pub_->publish(cmd_vel);
    }

    // ROS2 components
    rclcpp::Subscription<sensor_msgs::msg::IMU>::SharedPtr imu_sub_;
    rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odom_sub_;
    rclcpp::Publisher<geometry_msgs::msg::Twist>::SharedPtr cmd_vel_pub_;
    rclcpp::TimerBase::SharedPtr control_timer_;

    // State variables
    double current_x_ = 0.0, current_y_ = 0.0, current_yaw_ = 0.0;
    double current_speed_ = 0.0;
    double integral_error_ = 0.0, prev_error_ = 0.0;
};

int main(int argc, char **argv) {
    rclcpp::init(argc, argv);
    auto node = std::make_shared<RobotController>();
