### **2. Core Code: Anomaly Detection Pipeline**
```rust
use embedded_hal::blocking::i2c::{Write, WriteRead};
use ndarray::{Array1, ArrayView1};
use statrs::statistics::{Statistics, Mean, Variance};

// Define a simple I2C accelerometer driver (e.g., MPU6050)
struct Accelerometer<I2C> {
    i2c: I2C,
    addr: u8,
}

impl<I2C, E> Accelerometer<I2C>
where
    I2C: Write<Error = E> + WriteRead<Error = E>,
{
    pub fn new(i2c: I2C, addr: u8) -> Self {
        Self { i2c, addr }
    }

    // Read raw accelerometer data (x, y, z)
    pub fn read_accel(&mut self) -> Result<(i16, i16, i16), E> {
        let mut data = [0u8; 6];
        self.i2c.write_read(self.addr, &[0x3B], &mut data)?; // Example register for MPU6050
        let x = i16::from_be_bytes([data[0], data[1]]);
        let y = i16::from_be_bytes([data[2], data[3]]);
        let z = i16::from_be_bytes([data[4], data[5]]);
        Ok((x, y, z))
    }
}

// Anomaly detection using Z-score (simple statistical method)
fn detect_anomaly(data: ArrayView1<f32>, threshold: f32) -> bool {
    let mean = data.mean();
    let std_dev = data.std_dev();
    let z_scores = data.map(|&x| (x - mean) / std_dev);
    z_scores.iter().any(|&z| z.abs() > threshold)
}

fn main() -> ! {
    // Initialize I2C (example for STM32)
    let i2c = /* Initialize I2C peripheral */;
    let mut accel = Accelerometer::new(i2c, 0x68); // MPU6050 default address

    // Buffer for storing recent accelerometer readings
    let mut buffer = Array1::zeros(10); // Sliding window of 10 samples
    let mut index = 0;
    let anomaly_threshold = 3.0; // Z-score threshold for anomaly

    loop {
        // Read accelerometer data
        if let Ok((x, y, z)) = accel.read_accel() {
            // Compute magnitude (Euclidean norm)
            let magnitude = ((x as f32).powi(2) + (y as f32).powi(2) + (z as f32).powi(2)).sqrt();

            // Update sliding window
            buffer[index] = magnitude;
            index = (index + 1) % buffer.len();

            // Detect anomaly if enough data is available
            if index == 0 { // After filling the buffer
                if detect_anomaly(buffer.view(), anomaly_threshold) {
                    // Handle anomaly (e.g., log, trigger alarm)
                    println!("Anomaly detected!");
                }
            }
        }

        // Small delay (adjust based on sensor sampling rate)
        cortex_m::asm::delay(1_000_000);
    }
}
```

