#include <stdio.h>
#include <stdbool.h>
#include <math.h>

// Configuration
#define WINDOW_SIZE 5          // Moving average window size
#define ANOMALY_THRESHOLD 1.5  // Threshold for anomaly detection (adjust based on sensor characteristics)

// Simulated accelerometer data (replace with real sensor readings)
float simulate_accelerometer() {
    // Simulate random accelerometer data (e.g., from a real sensor)
    // In practice, this would read from an I2C/SPI interface
    return (float)(rand() % 100) / 10.0;  // Random value between 0.0 and 10.0
}

// Moving average filter to smooth the data
float moving_average(float *window, int window_size, float new_value) {
    static float sum = 0.0;
    static int count = 0;

    // Remove the oldest value from the sum
    if (count >= window_size) {
        sum -= window[count % window_size];
    } else {
        count++;
    }

    // Add the new value to the sum
    sum += new_value;
    window[count % window_size] = new_value;

    // Return the average
    return sum / (count < window_size ? count : window_size);
}

// Detect anomalies based on a threshold
bool detect_anomaly(float value, float threshold) {
    return fabs(value) > threshold;
}

int main() {
    float window[WINDOW_SIZE] = {0};
    float raw_value, smoothed_value;
    bool anomaly_detected;

    printf("Starting accelerometer anomaly detection...\n");

    while (1) {
        // Simulate reading from the accelerometer
        raw_value = simulate_accelerometer();

        // Apply moving average filter
        smoothed_value = moving_average(window, WINDOW_SIZE, raw_value);

        // Detect anomalies
        anomaly_detected = detect_anomaly(smoothed_value, ANOMALY_THRESHOLD);

        // Log results
        printf("Raw: %.2f, Smoothed: %.2f, Anomaly: %s\n",
               raw_value, smoothed_value, anomaly_detected ? "YES" : "NO");

        // Simulate delay (replace with real-time loop in practice)
        // In an embedded system, this would be replaced with a proper delay or interrupt-driven loop
        for (volatile int i = 0; i < 1000000; i++);  // Simulate processing delay
    }

    return 0;
}
