```c
#include "stm32f4xx_hal.h"
#include <math.h>
#include <stdbool.h>

// Define accelerometer registers (example for LIS3DH)
#define ACCEL_ADDR          0x18 << 1  // I2C address (shifted for HAL)
#define ACCEL_OUT_X_L      0x28        // X-axis LSB
#define ACCEL_OUT_X_H      0x29        // X-axis MSB
#define ACCEL_OUT_Y_L      0x2A        // Y-axis LSB
#define ACCEL_OUT_Y_H      0x2B        // Y-axis MSB
#define ACCEL_OUT_Z_L      0x2C        // Z-axis LSB
#define ACCEL_OUT_Z_H      0x2D        // Z-axis MSB

// Anomaly detection parameters
#define WINDOW_SIZE        10          // Moving average window
#define THRESHOLD          2.0f        // Anomaly threshold (adjust based on calibration)

// Global variables
float accel_data[3];                  // X, Y, Z acceleration
float moving_avg[3] = {0};            // Moving average buffer
float sum[3] = {0};                   // Sum for moving average
int sample_count = 0;                  // Sample counter

// I2C handle (configured in CubeMX)
extern I2C_HandleTypeDef hi2c1;

// Function to read accelerometer data
bool read_accelerometer(float *x, float *y, float *z) {
    uint8_t data[6];
    if (HAL_I2C_Mem_Read(&hi2c1, ACCEL_ADDR, ACCEL_OUT_X_L, 1, data, 6, HAL_MAX_DELAY) != HAL_OK) {
        return false;  // Read failed
    }

    // Convert raw data to g-force (assuming ±2g range, 10-bit resolution)
    *x = (int16_t)((data[1] << 8) | data[0]) / 256.0f;
    *y = (int16_t)((data[3] << 8) | data[2]) / 256.0f;
    *z = (int16_t)((data[5] << 8) | data[4]) / 256.0f;

    return true;
}

// Function to detect anomalies
bool detect_anomaly(float x, float y, float z) {
    // Update moving average
    for (int i = 0; i < 3; i++) {
        sum[i] += (i == 0) ? x : (i == 1) ? y : z;
        if (sample_count >= WINDOW_SIZE) {
            sum[i] -= moving_avg[i];
        }
        moving_avg[i] = sum[i] / ((sample_count < WINDOW_SIZE) ? (sample_count + 1) : WINDOW_SIZE);
    }

    // Check if current value deviates from moving average
    float deviation = fabs(x - moving_avg[0]) + fabs(y - moving_avg[1]) + fabs(z - moving_avg[2]);
    if (deviation > THRESHOLD) {
        return true;  // Anomaly detected
    }

    sample_count++;
    return false;
}

// Main processing loop
void process_accelerometer_data() {
    if (read_accelerometer(&accel_data[0], &accel_data[1], &accel_data[2])) {
        if (detect_anomaly(accel_data[0], accel_data[1], accel_data[2])) {
            // Anomaly detected! (e.g., blink LED or send alert)
            HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);  // Example: Toggle LED
            printf("Anomaly detected! X: %.2f, Y: %.2f, Z: %.2f\n", accel_data[0], accel_data[1], accel_data[2]);
        }
    } else {
        printf("Accelerometer read failed!\n");
    }
}

// Example main loop (called periodically)
void main_loop() {
    while (1) {
        process_accelerometer_data();
        HAL_Delay(100);  // Adjust sampling rate as needed
    }
}
```

