### Code (`main.rs`)
```rust
use std::time::{Duration, Instant};
use rand::Rng; // For simulation; replace with actual sensor reading in practice

// Simulated accelerometer data (x, y, z axes)
#[derive(Debug, Clone, Copy)]
struct AccelerometerData {
    x: f32,
    y: f32,
    z: f32,
    timestamp: Instant,
}

// Anomaly detection using Z-score
struct AnomalyDetector {
    window_size: usize,
    threshold: f32, // Z-score threshold (e.g., 3.0 for 99.7% confidence)
    history: Vec<f32>, // Rolling window of magnitudes
}

impl AnomalyDetector {
    fn new(window_size: usize, threshold: f32) -> Self {
        Self {
            window_size,
            threshold,
            history: Vec::with_capacity(window_size),
        }
    }

    // Calculate magnitude of acceleration vector
    fn magnitude(&self, data: &AccelerometerData) -> f32 {
        (data.x.powi(2) + data.y.powi(2) + data.z.powi(2)).sqrt()
    }

    // Update rolling window and detect anomalies
    fn detect_anomaly(&mut self, data: &AccelerometerData) -> bool {
        let mag = self.magnitude(data);

        // Update rolling window
        if self.history.len() >= self.window_size {
            self.history.remove(0); // Remove oldest sample
        }
        self.history.push(mag);

        // Skip detection if not enough data
        if self.history.len() < self.window_size {
            return false;
        }

        // Calculate mean and standard deviation
        let mean: f32 = self.history.iter().sum::<f32>() / self.history.len() as f32;
        let variance: f32 = self.history.iter()
            .map(|&x| (x - mean).powi(2))
            .sum::<f32>() / self.history.len() as f32;
        let std_dev = variance.sqrt();

        // Z-score anomaly detection
        let z_score = (mag - mean) / std_dev;
        z_score.abs() > self.threshold
    }
}

fn main() {
    // Simulate accelerometer data (replace with real sensor reading)
    let mut rng = rand::thread_rng();
    let mut detector = AnomalyDetector::new(10, 3.0); // Window size = 10, threshold = 3.0

    loop {
        // Simulate sensor reading (replace with actual I2C/SPI/ADC code)
        let data = AccelerometerData {
            x: rng.gen_range(-1.0..1.0),
            y: rng.gen_range(-1.0..1.0),
            z: rng.gen_range(-1.0..1.0),
            timestamp: Instant::now(),
        };

        // Detect anomaly
        if detector.detect_anomaly(&data) {
            println!(
                "ANOMALY DETECTED at {:?}: (x={:.2}, y={:.2}, z={:.2})",
                data.timestamp, data.x, data.y, data.z
            );
        }

        // Simulate real-time processing delay
        std::thread::sleep(Duration::from_millis(100));
    }
}
```

