class AnomalyDetector {
private:
    size_t window_size;
    float threshold;
    std::vector<float> history;

public:
    AnomalyDetector(size_t window_size, float threshold)
        : window_size(window_size), threshold(threshold) {}

    float magnitude(const AccelerometerData& data) {
        return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

