```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

// Simulated accelerometer data (x, y, z axes)
typedef struct {
    float x, y, z;
} AccelerometerData;

// Simple moving average filter
void moving_average_filter(AccelerometerData *data, int window_size) {
    static AccelerometerData buffer[10]; // Fixed-size buffer
    static int count = 0;

    buffer[count % window_size] = *data;
    count++;

    float sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < window_size; i++) {
        sum_x += buffer[i].x;
        sum_y += buffer[i].y;
        sum_z += buffer[i].z;
    }

    data->x = sum_x / window_size;
    data->y = sum_y / window_size;
    data->z = sum_z / window_size;
}

// Detect anomalies using a simple threshold
bool detect_anomaly(AccelerometerData *data, float threshold) {
    float magnitude = sqrt(data->x * data->x + data->y * data->y + data->z * data->z);
    return (magnitude > threshold);
}

int main() {
    // Simulate accelerometer data
    AccelerometerData data = {0.5, 0.3, 0.1};

    // Preprocess
    moving_average_filter(&data, 3);

    // Detect anomaly
    float threshold = 1.2; // Adjust based on calibration
    if (detect_anomaly(&data, threshold)) {
        printf("Anomaly detected! Magnitude: %.2f\n", sqrt(data.x*data.x + data.y*data.y + data.z*data.z));
    } else {
        printf("Normal operation.\n");
    }

    return 0;
}
```

