    SystemClock_Config();
    initAccelerometer();

    // Create FreeRTOS queue for accelerometer data
    xAccelDataQueue = xQueueCreate(10, sizeof(float32_t) * 3);  // 10 samples, 3 axes

    // Create tasks
    xTaskCreate(vTaskAccelRead, "AccelRead", 256, NULL, 2, NULL);
    xTaskCreate(vTaskProcessData, "ProcessData", 512, NULL, 1, NULL);

    // Start scheduler
    vTaskStartScheduler();

    while (1) {}  // Should never reach here
}

