void vTaskAccelRead(void *pvParameters) {
    float32_t accelData[3];  // x, y, z axes

    while (1) {
        // Read accelerometer (simulated or via HAL_I2C/SPI)
        // Example: HAL_I2C_Mem_Read(&hi2c1, LSM6DS3_ADDR, LSM6DS3_OUTX_L_XL, 1, (uint8_t*)accelData, 6, 100);

        // Simulate accelerometer data (replace with real sensor read)
        accelData[0] = (float32_t)(rand() % 100) / 10.0f;  // x-axis
        accelData[1] = (float32_t)(rand() % 100) / 10.0f;  // y-axis
        accelData[2] = (float32_t)(rand() % 100) / 10.0f;  // z-axis

        // Send to processing task
        xQueueSend(xAccelDataQueue, accelData, portMAX_DELAY);

        vTaskDelay(pdMS_TO_TICKS(10));  // 10ms delay (~100Hz)
    }
}

// --- Task: Process Data & Detect Anomalies ---
void vTaskProcessData(void *pvParameters) {
    float32_t accelData[3];
    float32_t mean[3] = {0}, variance[3] = {0}, stddev[3] = {0};
    uint32_t sampleCount = 0;

    while (1) {
        if (xQueueReceive(xAccelDataQueue, accelData, portMAX_DELAY) == pdTRUE) {
            // Update sliding window buffer
            for (int i = 0; i < 3; i++) {
                accelBuffer[i][sampleCount % WINDOW_SIZE] = accelData[i];
            }

            // Compute mean and variance (for anomaly detection)
            if (sampleCount >= WINDOW_SIZE) {
                arm_mean_f32(accelBuffer[0], WINDOW_SIZE, &mean[0]);
                arm_mean_f32(accelBuffer[1], WINDOW_SIZE, &mean[1]);
                arm_mean_f32(accelBuffer[2], WINDOW_SIZE, &mean[2]);

                arm_var_f32(accelBuffer[0], WINDOW_SIZE, &variance[0]);
                arm_var_f32(accelBuffer[1], WINDOW_SIZE, &variance[1]);
                arm_var_f32(accelBuffer[2], WINDOW_SIZE, &variance[2]);

                stddev[0] = sqrtf(variance[0]);
                stddev[1] = sqrtf(variance[1]);
                stddev[2] = sqrtf(variance[2]);

                // Check for anomalies (Z-score > threshold)
                for (int i = 0; i < 3; i++) {
                    float32_t zScore = computeZScore(accelData[i], mean[i], stddev[i]);
                    if (fabsf(zScore) > ANOMALY_THRESHOLD) {
                        // Anomaly detected! (e.g., trigger LED, log event)
                        HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);  // Example: Toggle LED
                    }
                }
            }

            sampleCount++;
        }
    }
}

// --- Helper: Compute Z-Score ---
float32_t computeZScore(float32_t value, float32_t mean, float32_t stddev) {
    if (stddev == 0) return 0;  // Avoid division by zero
    return (value - mean) / stddev;
}

// --- Helper: Low-Pass Filter (Optional) ---
void applyLowPassFilter(float32_t *data, uint32_t length) {
    // Example: Simple moving average filter
    float32_t sum = 0;
    for (uint32_t i = 0; i < length; i++) {
        sum += data[i];
    }
    float32_t avg = sum / length;
    for (uint32_t i = 0; i < length; i++) {
        data[i] = avg;  // Overwrite with filtered value
    }
}
