typedef struct {
    float x, y, z;  // Acceleration in g-force (m/s²)
} AccelerometerData;

// Moving average filter for smoothing
float movingAverage(float *window, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += window[i];
    }
    return sum / size;
}

// Compute magnitude of acceleration vector (Euclidean norm)
float computeMagnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Detect anomalies using a simple threshold-based approach
