    float x, y, z;
} AccelerometerData;

// Moving average filter (simple low-pass filter)
#define WINDOW_SIZE 5
float moving_avg_filter(float *window, float new_val) {
    static float sum = 0;
    static int count = 0;

    if (count < WINDOW_SIZE) {
        sum += new_val;
        count++;
    } else {
        sum = sum - window[0] + new_val;
        for (int i = 0; i < WINDOW_SIZE - 1; i++) {
            window[i] = window[i + 1];
        }
    }
    window[WINDOW_SIZE - 1] = new_val;
    return sum / WINDOW_SIZE;
}

// Threshold-based anomaly detection
