### **Code (`anomaly_detection.c`)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

// Simulated accelerometer data (X, Y, Z axes)
typedef struct {
    float x;
    float y;
    float z;
} AccelerometerData;

// Compute mean of an array
float compute_mean(float *data, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Compute standard deviation
float compute_stddev(float *data, int size, float mean) {
    float sum_sq = 0.0f;
    for (int i = 0; i < size; i++) {
        sum_sq += (data[i] - mean) * (data[i] - mean);
    }
    return sqrt(sum_sq / size);
}

// Detect anomalies using Z-score (threshold = 3.0)
bool is_anomaly(float value, float mean, float stddev) {
    float z_score = fabs(value - mean) / stddev;
    return (z_score > 3.0f); // Adjust threshold as needed
}

int main() {
    // Simulated accelerometer data (100 samples)
    AccelerometerData data[100];
    for (int i = 0; i < 100; i++) {
        data[i].x = 0.0f + (rand() % 100) / 100.0f; // Random noise
        data[i].y = 0.0f + (rand() % 100) / 100.0f;
        data[i].z = 9.8f + (rand() % 100) / 100.0f; // Gravity + noise
    }

    // Introduce an anomaly (e.g., sudden spike)
    data[50].x = 5.0f; // Anomalous spike

    // Compute baseline statistics (first 50 samples)
    float x_mean = compute_mean((float[]){data[0].x, data[1].x, ..., data[49].x}, 50);
    float x_stddev = compute_stddev((float[]){data[0].x, data[1].x, ..., data[49].x}, 50, x_mean);

    // Detect anomalies in real-time
    for (int i = 0; i < 100; i++) {
        if (is_anomaly(data[i].x, x_mean, x_stddev)) {
            printf("Anomaly detected at sample %d: X=%.2f (Z-score > 3.0)\n", i, data[i].x);
        }
    }

    return 0;
}
```

---

### **Explanation:**
1. **Simulated Data:**
   - Generates random accelerometer readings (X, Y, Z) with slight noise.
   - Introduces an artificial anomaly at sample 50 (`data[50].x = 5.0f`).

2. **Baseline Calculation:**
   - Computes mean and standard deviation for the first 50 samples (assumed to be normal).

3. **Anomaly Detection:**
   - Uses **Z-score** (distance from mean in standard deviations).
   - If `|Z-score| > 3.0`, it flags the sample as anomalous.

4. **Real-Time Processing:**
   - Runs in a loop, simulating continuous sensor data processing.

