### **Minimal Embedded Anomaly Detection Pipeline (C)**
```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

// Simulated accelerometer data (replace with real I2C/SPI reads)
typedef struct {
    float x, y, z;  // Acceleration in m/s²
} AccelerometerData;

// Simple moving average filter (for noise reduction)
typedef struct {
    float buffer[5];  // Small buffer for moving average
    uint8_t index;
    float sum;
} MovingAverageFilter;

// Initialize moving average filter
void initMovingAverage(MovingAverageFilter *filter) {
    filter->index = 0;
    filter->sum = 0.0f;
    for (uint8_t i = 0; i < 5; i++) {
        filter->buffer[i] = 0.0f;
    }
}

// Update moving average filter and return filtered value
float updateMovingAverage(MovingAverageFilter *filter, float new_value) {
    filter->sum -= filter->buffer[filter->index];  // Remove oldest value
    filter->buffer[filter->index] = new_value;     // Add new value
    filter->sum += new_value;                       // Update sum
    filter->index = (filter->index + 1) % 5;         // Circular buffer
    return filter->sum / 5.0f;                      // Return average
}

// Compute magnitude of acceleration (Euclidean norm)
float computeMagnitude(const AccelerometerData *data) {
    return sqrtf(data->x * data->x + data->y * data->y + data->z * data->z);
}

// Threshold-based anomaly detection
bool detectAnomaly(float magnitude, float threshold) {
    return (magnitude > threshold);
}

// Main processing loop (simulated)
int main() {
    // Simulated accelerometer data (replace with real sensor reads)
    AccelerometerData accel_data = {0.1f, 0.2f, 9.8f};  // Example: x=0.1, y=0.2, z=9.8 (gravity)

    // Initialize moving average filter
    MovingAverageFilter x_filter, y_filter, z_filter;
    initMovingAverage(&x_filter);
    initMovingAverage(&y_filter);
    initMovingAverage(&z_filter);

    // Threshold for anomaly detection (adjust based on calibration)
    const float ANOMALY_THRESHOLD = 10.5f;  // m/s² (e.g., sudden impact)

    while (1) {
        // Read accelerometer data (simulated)
        // In real code: accel_data = read_accelerometer();

        // Apply moving average filter
        float filtered_x = updateMovingAverage(&x_filter, accel_data.x);
        float filtered_y = updateMovingAverage(&y_filter, accel_data.y);
        float filtered_z = updateMovingAverage(&z_filter, accel_data.z);

        // Compute magnitude of filtered acceleration
        AccelerometerData filtered_data = {filtered_x, filtered_y, filtered_z};
        float magnitude = computeMagnitude(&filtered_data);

        // Detect anomaly
        if (detectAnomaly(magnitude, ANOMALY_THRESHOLD)) {
            // Anomaly detected! (e.g., trigger LED, send alert)
            // In real code: trigger_alarm();
        }

        // Delay for next reading (simulated)
        // In real code: delay_ms(10);
    }

    return 0;
}
```

