#include <stdint.h>
#include <math.h>
#include <stdio.h>

// Simulated accelerometer data (replace with real I2C/SPI reads)
typedef struct {
    float x, y, z;  // Accelerometer readings (g-force)
} AccelerometerData;

// Moving average filter (simple low-pass filter)
void computeMovingAverage(float *window, int windowSize, float newValue, float *avg) {
    static float sum = 0.0;
    static int count = 0;

    if (count < windowSize) {
        sum += newValue;
        count++;
    } else {
        sum = sum - window[0] + newValue;
        for (int i = 0; i < windowSize - 1; i++) {
            window[i] = window[i + 1];
        }
        window[windowSize - 1] = newValue;
    }
    *avg = sum / count;
}

// Detect anomalies using variance threshold
int detectAnomaly(float *window, int windowSize, float threshold) {
    float avg = 0.0;
    float variance = 0.0;

    // Compute mean
    for (int i = 0; i < windowSize; i++) {
        avg += window[i];
    }
    avg /= windowSize;

    // Compute variance
    for (int i = 0; i < windowSize; i++) {
        variance += pow(window[i] - avg, 2);
    }
    variance /= windowSize;

    return (variance > threshold) ? 1 : 0;  // 1 = anomaly detected
}

int main() {
    // Simulated accelerometer data (replace with real sensor reads)
    AccelerometerData accelData[] = {
        {0.1, 0.2, 0.3}, {0.15, 0.25, 0.35}, {0.2, 0.3, 0.4},
        {0.1, 0.2, 0.3}, {0.15, 0.25, 0.35}, {0.2, 0.3, 0.4},
        {0.1, 0.2, 0.3}, {0.15, 0.25, 0.35}, {0.2, 0.3, 0.4},
        {10.0, 10.0, 10.0}  // Anomalous spike
    };

    const int WINDOW_SIZE = 5;
    float xWindow[WINDOW_SIZE] = {0};
    float yWindow[WINDOW_SIZE] = {0};
    float zWindow[WINDOW_SIZE] = {0};
    float xAvg, yAvg, zAvg;
    const float ANOMALY_THRESHOLD = 0.1;  // Adjust based on sensor noise

    for (int i = 0; i < sizeof(accelData) / sizeof(accelData[0]); i++) {
        // Update moving average windows
        computeMovingAverage(xWindow, WINDOW_SIZE, accelData[i].x, &xAvg);
        computeMovingAverage(yWindow, WINDOW_SIZE, accelData[i].y, &yAvg);
        computeMovingAverage(zWindow, WINDOW_SIZE, accelData[i].z, &zAvg);

        // Check for anomalies in any axis
        int anomalyDetected = 0;
        if (detectAnomaly(xWindow, WINDOW_SIZE, ANOMALY_THRESHOLD) ||
            detectAnomaly(yWindow, WINDOW_SIZE, ANOMALY_THRESHOLD) ||
            detectAnomaly(zWindow, WINDOW_SIZE, ANOMALY_THRESHOLD)) {
            anomalyDetected = 1;
        }

        // Output results (replace with LED/buzzer alert in real hardware)
        printf("Sample %d: X=%.2f, Y=%.2f, Z=%.2f | Anomaly: %s\n",
               i, accelData[i].x, accelData[i].y, accelData[i].z,
               anomalyDetected ? "DETECTED" : "NONE");
    }

    return 0;
}
