#include <stdint.h>
#include <stdbool.h>
#include "stm32f4xx_hal.h"  // STM32 HAL library (adjust for your MCU)

// Accelerometer I2C/SPI configuration
#define ACCEL_ADDR 0x6A     // LSM6DS3 default I2C address
#define ACCEL_REG_CTRL1_XL 0x10  // Accelerometer control register
#define ACCEL_REG_OUT_X_L 0x28   // X-axis low byte

// Threshold for anomaly detection (adjust based on sensor sensitivity)
#define ANOMALY_THRESHOLD 2.0f  // g-force (e.g., sudden impact)

// Global variables
I2C_HandleTypeDef hi2c1;  // I2C handle (adjust for your setup)
float accel_data[3];      // X, Y, Z axes (in g-force)

// Initialize accelerometer
void Accel_Init(void) {
    uint8_t ctrl_reg = 0x60;  // Enable accelerometer (1.66 kHz, ±2g)
    HAL_I2C_Mem_Write(&hi2c1, ACCEL_ADDR, ACCEL_REG_CTRL1_XL, 1, &ctrl_reg, 1, HAL_MAX_DELAY);
}

// Read accelerometer data (X, Y, Z)
void Accel_Read(float *data) {
    uint8_t raw_data[6];
    HAL_I2C_Mem_Read(&hi2c1, ACCEL_ADDR, ACCEL_REG_OUT_X_L, 1, raw_data, 6, HAL_MAX_DELAY);

    // Convert raw data to g-force (adjust scaling factor based on sensor)
    data[0] = (int16_t)(raw_data[1] << 8 | raw_data[0]) * 0.000061f;  // X-axis
    data[1] = (int16_t)(raw_data[3] << 8 | raw_data[2]) * 0.000061f;  // Y-axis
    data[2] = (int16_t)(raw_data[5] << 8 | raw_data[4]) * 0.000061f;  // Z-axis
}

// Detect anomaly (simple threshold-based)
bool Detect_Anomaly(float *data) {
    // Calculate magnitude (Euclidean norm)
    float magnitude = sqrtf(data[0] * data[0] + data[1] * data[1] + data[2] * data[2]);

    // Check if magnitude exceeds threshold
    if (magnitude > ANOMALY_THRESHOLD) {
        return true;  // Anomaly detected
    }
    return false;
}

// Main loop
int main(void) {
    HAL_Init();         // Initialize HAL
    SystemClock_Config();  // Configure clock (adjust for your MCU)

    // Initialize I2C (adjust pins for your setup)
    hi2c1.Instance = I2C1;
    hi2c1.Init.ClockSpeed = 400000;  // 400 kHz
    HAL_I2C_Init(&hi2c1);

    Accel_Init();  // Initialize accelerometer

    while (1) {
        Accel_Read(accel_data);  // Read accelerometer data

        if (Detect_Anomaly(accel_data)) {
            // Anomaly detected! (e.g., blink LED or send UART message)
            HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);  // Toggle LED (adjust pin)
            HAL_Delay(100);  // Debounce delay
        }

        HAL_Delay(10);  // Sampling rate (100 Hz)
    }
}
```

