```rust
use std::time::Duration;
use std::thread;

fn read_sensor() -> f32 {
    // Simulate noisy sensor data
    static mut SIMULATED_TEMP: f32 = 25.0;
    unsafe {
        SIMULATED_TEMP += (rand::random::<f32>() * 10.0 - 5.0) * 0.1;
        SIMULATED_TEMP
    }
}

fn filter_sensor_data(new_sample: f32) -> f32 {
    static mut BUFFER: [f32; 3] = [0.0; 3];
    static mut INDEX: usize = 0;
    static mut INITIALIZED: bool = false;

    unsafe {
        if !INITIALIZED {
            BUFFER.fill(new_sample);
            INITIALIZED = true;
        }

        BUFFER[*INDEX] = new_sample;
        *INDEX = (*INDEX + 1) % 3;

        BUFFER.iter().sum::<f32>() / 3.0
    }
}

fn control_actuator(state: bool) {
    println!("Actuator: {}", if state { "ON" } else { "OFF" });
}

fn main() {
    const THRESHOLD: f32 = 30.0;

    loop {
        let raw_temp = read_sensor();
        println!("Raw Sensor: {:.2}°C", raw_temp);

        let filtered_temp = filter_sensor_data(raw_temp);
        println!("Filtered: {:.2}°C", filtered_temp);

        control_actuator(filtered_temp > THRESHOLD);

        thread::sleep(Duration::from_millis(100)); // Simulate delay
    }
}
