// Constants
const float SCALE = 30.0f; // Box2D to SFML scale
const float GRAVITY = 9.8f;
const float PLAYER_SPEED = 5.0f;
const float JUMP_FORCE = 10.0f;

// Player class
class Player {
public:
    b2Body* body;
    sf::Sprite sprite;
    sf::Texture texture;
    sf::IntRect currentFrame;
    int animationFrame = 0;
    float animationTimer = 0.0f;
    bool isJumping = false;

    Player(b2World& world, float x, float y) {
        // Load texture (replace with your sprite sheet)
        if (!texture.loadFromFile("player.png")) {
            std::cerr << "Failed to load player texture!" << std::endl;
        }
        sprite.setTexture(texture);
        sprite.setTextureRect(sf::IntRect(0, 0, 32, 32)); // Adjust based on sprite sheet
        sprite.setOrigin(16, 16); // Center origin

        // Box2D body setup
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(x / SCALE, y / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape shape;
        shape.SetAsBox(16.0f / SCALE, 16.0f / SCALE); // Half-width, half-height

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &shape;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.2f;
        body->CreateFixture(&fixtureDef);
    }

    void update(float deltaTime) {
        // Update sprite position from physics
        sprite.setPosition(
            body->GetPosition().x * SCALE,
            body->GetPosition().y * SCALE
        );

        // Simple animation (idle/walk)
        animationTimer += deltaTime;
        if (animationTimer > 0.1f) {
            animationFrame = (animationFrame + 1) % 4; // 4 frames in sprite sheet
            sprite.setTextureRect(sf::IntRect(animationFrame * 32, 0, 32, 32));
            animationTimer = 0.0f;
        }
    }

    void jump() {
        if (!isJumping) {
            body->ApplyLinearImpulse(b2Vec2(0, -JUMP_FORCE), body->GetWorldCenter(), true);
            isJumping = true;
        }
    }
};

// Ground class
class Ground {
public:
    b2Body* body;
    sf::RectangleShape shape;

    Ground(b2World& world, float x, float y, float width, float height) {
        // SFML shape
        shape.setSize(sf::Vector2f(width, height));
        shape.setPosition(x, y);
        shape.setFillColor(sf::Color::Green);

        // Box2D body
        b2BodyDef bodyDef;
        bodyDef.type = b2_staticBody;
        bodyDef.position.Set((x + width / 2) / SCALE, (y + height / 2) / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape boxShape;
        boxShape.SetAsBox(width / 2 / SCALE, height / 2 / SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &boxShape;
        body->CreateFixture(&fixtureDef);
    }
};

int main() {
    // SFML setup
    sf::RenderWindow window(sf::VideoMode(800, 600), "2D Platformer");
    window.setFramerateLimit(60);

    // Box2D world
    b2Vec2 gravity(0.0f, GRAVITY);
    b2World world(gravity);

    // Create player
    Player player(world, 100.0f, 300.0f);

    // Create ground
    Ground ground(world, 0.0f, 500.0f, 800.0f, 50.0f);

    // Game loop
    sf::Clock clock;
    while (window.isOpen()) {
        float deltaTime = clock.restart().asSeconds();

        // Event handling
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
            if (event.type == sf::Event::KeyPressed) {
                if (event.key.code == sf::Keyboard::Space) {
                    player.jump();
                }
