### **2. Code (`main.cpp`)**
```cpp
#include <SFML/Graphics.hpp>
#include <Box2D/Box2D.h>
#include <vector>
#include <cmath>

// Constants
const float SCALE = 30.0f; // Box2D to SFML scale
const float GRAVITY = 9.8f;
const float PLAYER_SPEED = 5.0f;
const float JUMP_FORCE = 10.0f;

// Player class
class Player {
public:
    sf::Sprite sprite;
    b2Body* body;
    sf::Texture texture;
    sf::IntRect currentFrame;
    int animationFrame = 0;
    float animationTimer = 0.0f;
    bool facingRight = true;

    Player(b2World& world, float x, float y) {
        // Load sprite sheet (replace with your own)
        if (!texture.loadFromFile("player_spritesheet.png")) {
            // Fallback: Create a colored rectangle if texture fails
            sf::RectangleShape rect(sf::Vector2f(32, 32));
            rect.setFillColor(sf::Color::Green);
            texture.create(32, 32);
            texture.update(rect);
        }

        sprite.setTexture(texture);
        currentFrame = sf::IntRect(0, 0, 32, 32); // First frame
        sprite.setTextureRect(currentFrame);
        sprite.setOrigin(16, 16); // Center origin

        // Box2D body setup
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(x / SCALE, y / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape shape;
        shape.SetAsBox(16 / SCALE, 16 / SCALE); // Half-width, half-height

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &shape;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.2f;
        body->CreateFixture(&fixtureDef);
    }

    void update(float deltaTime) {
        // Update sprite position from physics
        sprite.setPosition(
            body->GetPosition().x * SCALE,
            body->GetPosition().y * SCALE
        );

        // Simple animation (cycle frames)
        animationTimer += deltaTime;
        if (animationTimer > 0.1f) {
            animationTimer = 0.0f;
            animationFrame = (animationFrame + 1) % 4; // 4 frames
            currentFrame.left = animationFrame * 32;
            sprite.setTextureRect(currentFrame);
        }

        // Flip sprite if moving left
        if (body->GetLinearVelocity().x < -0.1f) {
            sprite.setScale(-1, 1);
            facingRight = false;
        } else if (body->GetLinearVelocity().x > 0.1f) {
            sprite.setScale(1, 1);
            facingRight = true;
        }
    }

    void jump() {
        // Check if grounded (simple raycast down)
        b2Vec2 start = body->GetPosition();
        b2Vec2 end = start + b2Vec2(0, 0.2f); // Small downward ray

        b2RayCastInput input;
        input.p1 = start;
        input.p2 = end;
        input.maxFraction = 1.0f;

        // If no ground, don't jump
        if (!body->GetWorld()->RayCast(nullptr, input)) {
            body->ApplyLinearImpulse(b2Vec2(0, -JUMP_FORCE), body->GetWorldCenter(), true);
        }
    }
};

int main() {
