    window.setFramerateLimit(60);

    // Box2D world
    b2Vec2 gravity(0.0f, GRAVITY);
    b2World world(gravity);

    // Create player
    Player player(world, 400, 300);

    // Create ground (static platform)
    b2BodyDef groundDef;
    groundDef.position.Set(400 / SCALE, 500 / SCALE);
    b2Body* ground = world.CreateBody(&groundDef);

    b2PolygonShape groundShape;
    groundShape.SetAsBox(400 / SCALE, 20 / SCALE);
    ground->CreateFixture(&groundShape, 0.0f);

    // Game loop
    sf::Clock clock;
    while (window.isOpen()) {
        float deltaTime = clock.restart().asSeconds();

        // Handle events
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
            if (event.type == sf::Event::KeyPressed) {
                if (event.key.code == sf::Keyboard::Space) {
                    player.jump();
                }
            }
        }

        // Player movement
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Left)) {
            player.body->ApplyForceToCenter(b2Vec2(-PLAYER_SPEED, 0), true);
        }
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Right)) {
            player.body->ApplyForceToCenter(b2Vec2(PLAYER_SPEED, 0), true);
        }

        // Update physics
        world.Step(deltaTime, 8, 3);

        // Update player
        player.update(deltaTime);

        // Render
        window.clear(sf::Color::Black);

        // Draw ground
        sf::RectangleShape groundRect(sf::Vector2f(800, 40));
        groundRect.setPosition(0, 500);
        groundRect.setFillColor(sf::Color::Blue);
        window.draw(groundRect);

        // Draw player
        window.draw(player.sprite);

        window.display();
    }

    return 0;
}
