### **2. Main Game Code (`main.cpp`)**
```cpp
#include <SFML/Graphics.hpp>
#include <Box2D/Box2D.h>
#include <vector>
#include <iostream>

// Constants
const float SCALE = 30.0f; // Box2D to SFML scaling factor
const float GRAVITY = 9.8f;
const float PLAYER_SPEED = 5.0f;
const float JUMP_FORCE = 7.0f;

// Player class
class Player {
public:
    sf::Sprite sprite;
    b2Body* body;
    sf::Texture texture;
    sf::IntRect currentFrame;
    int animationFrame = 0;
    float animationTimer = 0.0f;
    bool isJumping = false;

    Player(b2World& world, float x, float y) {
        // Load player texture (replace with your sprite sheet)
        if (!texture.loadFromFile("player.png")) {
            std::cerr << "Failed to load player texture!" << std::endl;
        }
        sprite.setTexture(texture);
        sprite.setTextureRect(sf::IntRect(0, 0, 32, 32)); // Adjust based on sprite sheet
        sprite.setOrigin(16, 16); // Center origin

        // Box2D body setup
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(x / SCALE, y / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape shape;
        shape.SetAsBox(10.0f / SCALE, 16.0f / SCALE); // Half-width, half-height

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &shape;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.2f;
        body->CreateFixture(&fixtureDef);
    }

    void update(float deltaTime) {
        // Update sprite position from physics
        b2Vec2 position = body->GetPosition();
        sprite.setPosition(position.x * SCALE, position.y * SCALE);

        // Simple animation (walking)
        if (body->GetLinearVelocity().x != 0) {
            animationTimer += deltaTime;
            if (animationTimer > 0.1f) { // Frame delay
                animationFrame = (animationFrame + 1) % 4; // 4 frames in sprite sheet
                sprite.setTextureRect(sf::IntRect(animationFrame * 32, 0, 32, 32));
                animationTimer = 0.0f;
            }
        }
    }

    void jump() {
        if (!isJumping) {
            body->ApplyLinearImpulse(b2Vec2(0, -JUMP_FORCE), body->GetWorldCenter(), true);
            isJumping = true;
        }
    }
};

// Platform class
class Platform {
public:
    sf::RectangleShape shape;
    b2Body* body;

    Platform(b2World& world, float x, float y, float width, float height) {
        shape.setSize(sf::Vector2f(width, height));
        shape.setFillColor(sf::Color::Green);
        shape.setPosition(x, y);

        b2BodyDef bodyDef;
        bodyDef.position.Set((x + width / 2) / SCALE, (y + height / 2) / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape shape;
        shape.SetAsBox(width / 2 / SCALE, height / 2 / SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &shape;
        fixtureDef.density = 0.0f; // Static
        body->CreateFixture(&fixtureDef);
    }
};

int main() {
    // SFML setup
    sf::RenderWindow window(sf::VideoMode(800, 600), "2D Platformer");
    window.setFramerateLimit(60);

    // Box2D setup
    b2Vec2 gravity(0.0f, GRAVITY);
    b2World world(gravity);

    // Create player
    Player player(world, 100.0f, 300.0f);

    // Create platforms
    std::vector<Platform> platforms;
    platforms.emplace_back(world, 0, 550, 800, 50); // Ground
    platforms.emplace_back(world, 200, 400, 200, 20); // Floating platform

    // Game loop
    sf::Clock clock;
    while (window.isOpen()) {
        float deltaTime = clock.restart().asSeconds();

        // Handle events
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
            if (event.type == sf::Event::KeyPressed) {
                if (event.key.code == sf::Keyboard::Space) {
                    player.jump();
                }
            }
        }

        // Player movement
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Left)) {
            player.body->SetLinearVelocity(b2Vec2(-PLAYER_SPEED, player.body->GetLinearVelocity().y));
        } else if (sf::Keyboard::isKeyPressed(sf::Keyboard::Right)) {
            player.body->SetLinearVelocity(b2Vec2(PLAYER_SPEED, player.body->GetLinearVelocity().y));
        } else {
            player.body->SetLinearVelocity(b2Vec2(0, player.body->GetLinearVelocity().y));
        }

        // Update physics
        world.Step(deltaTime, 8, 3);

        // Update player
        player.update(deltaTime);

        // Render
        window.clear(sf::Color::Black);
        window.draw(player.sprite);
        for (const auto& platform : platforms) {
            window.draw(platform.shape);
        }
        window.display();
    }

    return 0;
}
```

