// Player class
class Player {
public:
    sf::Sprite sprite;
    b2Body* body;
    sf::Texture texture;
    sf::IntRect currentFrame;
    float frameTime = 0.1f;
    float elapsedTime = 0.0f;

    Player(b2World& world, float x, float y) {
        // Load sprite
        texture.loadFromFile("player.png"); // Replace with your sprite sheet
        sprite.setTexture(texture);
        sprite.setTextureRect(sf::IntRect(0, 0, 32, 32)); // First frame
        sprite.setOrigin(16, 16); // Center origin

        // Box2D body setup
        b2BodyDef bodyDef;
        bodyDef.type = b2_dynamicBody;
        bodyDef.position.Set(x / SCALE, y / SCALE);
        body = world.CreateBody(&bodyDef);

        b2PolygonShape shape;
        shape.SetAsBox(10.0f / SCALE, 16.0f / SCALE); // Player hitbox

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &shape;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.2f;
        body->CreateFixture(&fixtureDef);
    }

    void update(float deltaTime) {
        // Update sprite position from physics
        sprite.setPosition(
            body->GetPosition().x * SCALE,
            body->GetPosition().y * SCALE
        );

        // Simple animation (flip sprite if moving left)
        if (body->GetLinearVelocity().x < -0.1f) {
            sprite.setScale(-1, 1); // Flip left
        } else if (body->GetLinearVelocity().x > 0.1f) {
            sprite.setScale(1, 1); // Flip right
        }

        // Frame animation (simplified)
        elapsedTime += deltaTime;
        if (elapsedTime >= frameTime) {
            elapsedTime = 0;
            currentFrame.left += 32; // Move to next frame
            if (currentFrame.left >= 96) currentFrame.left = 0; // Loop
            sprite.setTextureRect(currentFrame);
        }
    }
};

int main() {
    // SFML setup
    sf::RenderWindow window(sf::VideoMode(800, 600), "2D Platformer");
    window.setFramerateLimit(60);

    // Box2D world setup
    b2Vec2 gravity(0.0f, GRAVITY);
    b2World world(gravity);

    // Create player
    Player player(world, 100, 100);

    // Create ground (static platform)
    b2BodyDef groundDef;
    groundDef.position.Set(400 / SCALE, 500 / SCALE);
    b2Body* ground = world.CreateBody(&groundDef);

    b2PolygonShape groundShape;
    groundShape.SetAsBox(400 / SCALE, 20 / SCALE);
    ground->CreateFixture(&groundShape, 0.0f);

    // Game loop
    sf::Clock clock;
    while (window.isOpen()) {
        float deltaTime = clock.restart().asSeconds();

        // Handle events
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
        }

        // Player movement
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Left)) {
            player.body->ApplyLinearImpulse(b2Vec2(-5.0f, 0), player.body->GetWorldCenter(), true);
        }
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Right)) {
            player.body->ApplyLinearImpulse(b2Vec2(5.0f, 0), player.body->GetWorldCenter(), true);
        }
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::Space) && player.body->GetLinearVelocity().y == 0) {
