Below is an example of a **custom physics plugin** for a game engine, written in **C++** (the most common choice for high-performance plugins). This example demonstrates a simple **rigid body physics system** that can be integrated into engines like **Unreal Engine** or **Unity** (via native plugins).

---

### **1. Basic Physics Plugin Structure (C++)**
This example includes:
- A `RigidBody` class for basic physics simulation.
- A `PhysicsWorld` class to manage physics objects.
- A simple **Euler integration** method for movement.

```cpp
#include <vector>
#include <cmath>
#include <iostream>

// Simple 3D Vector class
struct Vector3 {
    float x, y, z;

    Vector3(float x = 0.0f, float y = 0.0f, float z = 0.0f) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        if (mag > 0.0f) {
            return *this * (1.0f / mag);
        }
        return Vector3(0.0f, 0.0f, 0.0f);
    }
};

// RigidBody class (basic physics object)
class RigidBody {
public:
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;

    RigidBody(float x = 0.0f, float y = 0.0f, float z = 0.0f, float mass = 1.0f)
        : position(x, y, z), velocity(0.0f, 0.0f, 0.0f), acceleration(0.0f, 0.0f, 0.0f), mass(mass) {}

    void applyForce(const Vector3& force) {
        acceleration = force * (1.0f / mass);
    }

    void update(float deltaTime) {
        velocity = velocity + (acceleration * deltaTime);
        position = position + (velocity * deltaTime);
        acceleration = Vector3(0.0f, 0.0f, 0.0f); // Reset acceleration after applying
    }
};

// PhysicsWorld class (manages all physics objects)
class PhysicsWorld {
private:
    std::vector<RigidBody*> bodies;
    Vector3 gravity;

public:
    PhysicsWorld(const Vector3& gravity = Vector3(0.0f, -9.81f, 0.0f)) : gravity(gravity) {}

    void addBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void update(float deltaTime) {
        for (auto body : bodies) {
            body->applyForce(gravity * body->mass); // Apply gravity
            body->update(deltaTime);
        }
    }

    void debugPrint() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            std::cout << "Body " << i << ": Position (" << bodies[i]->position.x << ", "
                      << bodies[i]->position.y << ", " << bodies[i]->position.z << ")\n";
        }
    }
};

// Example usage
int main() {
    PhysicsWorld world(Vector3(0.0f, -9.81f, 0.0f)); // Earth-like gravity

    RigidBody ball(0.0f, 10.0f, 0.0f, 1.0f); // Start at y=10, mass=1
    world.addBody(&ball);

    // Simulate for 5 seconds with 0.016s steps (60 FPS)
    for (int i = 0; i < 300; ++i) {
        world.update(0.016f);
    }

    world.debugPrint(); // Should show ball falling to y=0
    return 0;
}
```

