#pragma once

#include <glm/glm.hpp> // For vector math (replace with engine's math library if needed)

class RigidBody {
public:
    RigidBody(float mass, const glm::vec3& position, const glm::vec3& velocity = glm::vec3(0.0f))
        : mass(mass), position(position), velocity(velocity), acceleration(glm::vec3(0.0f)) {}

    void ApplyForce(const glm::vec3& force) {
        acceleration += force / mass;
    }

    void Update(float deltaTime) {
        velocity += acceleration * deltaTime;
        position += velocity * deltaTime;
        acceleration = glm::vec3(0.0f); // Reset acceleration after each frame
    }

    // Simple AABB collision detection (for demonstration)
    bool CheckCollision(const RigidBody& other) const {
        // Assuming a simple box shape (min/max bounds)
        glm::vec3 thisMin = position - glm::vec3(0.5f); // Half-extent
        glm::vec3 thisMax = position + glm::vec3(0.5f);
        glm::vec3 otherMin = other.position - glm::vec3(0.5f);
        glm::vec3 otherMax = other.position + glm::vec3(0.5f);

        return (thisMin.x <= otherMax.x && thisMax.x >= otherMin.x) &&
               (thisMin.y <= otherMax.y && thisMax.y >= otherMin.y) &&
               (thisMin.z <= otherMax.z && thisMax.z >= otherMin.z);
    }

    glm::vec3 position;
    glm::vec3 velocity;
    glm::vec3 acceleration;
    float mass;
};
