        // Apply gravity (optional)
        for (auto body : bodies) {
            body->ApplyForce(glm::vec3(0.0f, -9.8f, 0.0f) * body->mass);
        }

        // Update positions
        for (auto body : bodies) {
            body->Update(deltaTime);
        }

        // Simple collision response (elastic collision)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                if (bodies[i]->CheckCollision(*bodies[j])) {
                    // Simple bounce (elastic collision)
                    glm::vec3 normal = glm::normalize(bodies[j]->position - bodies[i]->position);
                    bodies[i]->velocity = glm::reflect(bodies[i]->velocity, normal);
                    bodies[j]->velocity = glm::reflect(bodies[j]->velocity, normal);
                }
            }
        }
    }

private:
    std::vector<RigidBody*> bodies;
};
