### **1. Plugin Structure (C++)**
#### **Header File (`CustomPhysicsPlugin.h`)**
```cpp
#pragma once

#include <vector>
#include <memory>

namespace CustomPhysics {

    // Basic 3D vector for position/velocity
    struct Vector3 {
        float x, y, z;
        Vector3(float x = 0.0f, float y = 0.0f, float z = 0.0f) : x(x), y(y), z(z) {}
    };

    // Rigid body properties
    struct RigidBody {
        Vector3 position;
        Vector3 velocity;
        float mass;
        float radius; // For sphere collision

        RigidBody(Vector3 pos, float m, float r)
            : position(pos), velocity(0.0f, 0.0f, 0.0f), mass(m), radius(r) {}
    };

    // Simple physics world
    class PhysicsWorld {
    private:
        std::vector<std::shared_ptr<RigidBody>> bodies;
        float gravity = -9.81f; // Earth gravity (m/s²)
        float timeStep = 1.0f / 60.0f; // Fixed timestep (60 FPS)

    public:
        // Add a rigid body to the world
        void AddBody(std::shared_ptr<RigidBody> body) {
            bodies.push_back(body);
        }

        // Apply gravity and update positions
        void Update() {
            for (auto& body : bodies) {
                // Apply gravity
                body->velocity.y += gravity * timeStep;

                // Update position
                body->position.x += body->velocity.x * timeStep;
                body->position.y += body->velocity.y * timeStep;
                body->position.z += body->velocity.z * timeStep;

                // Simple ground collision (y = 0)
                if (body->position.y < body->radius) {
                    body->position.y = body->radius;
                    body->velocity.y = -body->velocity.y * 0.8f; // Bounce with damping
                }
            }

            // Check for collisions between bodies
            for (size_t i = 0; i < bodies.size(); ++i) {
                for (size_t j = i + 1; j < bodies.size(); ++j) {
                    CheckCollision(bodies[i], bodies[j]);
                }
            }
        }

        // Simple sphere-sphere collision
        void CheckCollision(std::shared_ptr<RigidBody> a, std::shared_ptr<RigidBody> b) {
            Vector3 delta = {
                b->position.x - a->position.x,
                b->position.y - a->position.y,
                b->position.z - a->position.z
            };
            float distanceSquared = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            float minDistance = a->radius + b->radius;

            if (distanceSquared < minDistance * minDistance) {
                // Simple elastic collision response
                float distance = sqrt(distanceSquared);
                Vector3 normal = { delta.x / distance, delta.y / distance, delta.z / distance };

                // Relative velocity
                Vector3 relativeVelocity = {
                    b->velocity.x - a->velocity.x,
                    b->velocity.y - a->velocity.y,
                    b->velocity.z - a->velocity.z
                };
                float velocityAlongNormal = relativeVelocity.x * normal.x +
                                           relativeVelocity.y * normal.y +
                                           relativeVelocity.z * normal.z;

                if (velocityAlongNormal > 0) return; // Already moving apart

                // Calculate impulse scalar
                float restitution = 0.8f; // Bounciness
                float j = -(1 + restitution) * velocityAlongNormal;
                j /= (1 / a->mass) + (1 / b->mass);

                // Apply impulse
                Vector3 impulse = { normal.x * j, normal.y * j, normal.z * j };
                a->velocity.x -= impulse.x / a->mass;
                a->velocity.y -= impulse.y / a->mass;
                a->velocity.z -= impulse.z / a->mass;
                b->velocity.x += impulse.x / b->mass;
                b->velocity.y += impulse.y / b->mass;
                b->velocity.z += impulse.z / b->mass;
            }
        }
    };
}
```

