```cpp
#include <vector>
#include <cmath>
#include <iostream>

// --- Physics Constants ---
constexpr float GRAVITY = 9.81f;
constexpr float TIME_STEP = 1.0f / 60.0f; // 60 FPS

// --- Vector3 Helper Class ---
struct Vector3 {
    float x, y, z;

    Vector3(float x = 0.0f, float y = 0.0f, float z = 0.0f) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        if (mag > 0.0f) {
            return Vector3(x / mag, y / mag, z / mag);
        }
        return Vector3(0.0f, 0.0f, 0.0f);
    }
};

// --- RigidBody Class ---
class RigidBody {
public:
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;

    RigidBody(float x = 0.0f, float y = 0.0f, float z = 0.0f, float m = 1.0f)
        : position(x, y, z), velocity(0.0f, 0.0f, 0.0f), acceleration(0.0f, 0.0f, 0.0f), mass(m) {}

    void applyForce(const Vector3& force) {
        acceleration = force * (1.0f / mass);
    }

    void update(float deltaTime) {
        velocity = velocity + acceleration * deltaTime;
        position = position + velocity * deltaTime;
        acceleration = Vector3(0.0f, 0.0f, 0.0f); // Reset acceleration
    }
};

// --- PhysicsWorld Class ---
class PhysicsWorld {
private:
    std::vector<RigidBody*> bodies;

public:
    void addBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void update() {
        for (auto body : bodies) {
            // Apply gravity
            body->applyForce(Vector3(0.0f, -GRAVITY * body->mass, 0.0f));
            // Update physics
            body->update(TIME_STEP);
        }
    }

    void printBodies() const {
        for (const auto body : bodies) {
            std::cout << "Position: (" << body->position.x << ", " << body->position.y << ", " << body->position.z << ")\n";
        }
    }
};

// --- Example Usage ---
int main() {
    PhysicsWorld world;

    // Create a rigid body
    RigidBody* ball = new RigidBody(0.0f, 10.0f, 0.0f, 1.0f);
    world.addBody(ball);

    // Simulate physics for 5 seconds
    for (int i = 0; i < 300; ++i) { // 300 steps at 60 FPS = 5 seconds
        world.update();
    }

    // Print final position
    world.printBodies();

    delete ball;
    return 0;
}
