```cpp
#include <vector>
#include <cmath>
#include <iostream>

// --- Physics Types ---
struct Vector3 {
    float x, y, z;
    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
    Vector3 operator+(const Vector3& other) const { return Vector3(x + other.x, y + other.y, z + other.z); }
    Vector3 operator*(float scalar) const { return Vector3(x * scalar, y * scalar, z * scalar); }
};

struct AABB {
    Vector3 min, max;
    AABB(const Vector3& min, const Vector3& max) : min(min), max(max) {}
    bool intersects(const AABB& other) const {
        return (min.x <= other.max.x && max.x >= other.min.x) &&
               (min.y <= other.max.y && max.y >= other.min.y) &&
               (min.z <= other.max.z && max.z >= other.min.z);
    }
};

// --- Rigid Body ---
class RigidBody {
public:
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;
    AABB bounds;

    RigidBody(const Vector3& pos, const Vector3& vel, float m, const AABB& b)
        : position(pos), velocity(vel), mass(m), bounds(b) {}

    void applyForce(const Vector3& force) {
        acceleration = force * (1.0f / mass);
    }

    void update(float deltaTime) {
        velocity = velocity + acceleration * deltaTime;
        position = position + velocity * deltaTime;
        bounds = AABB(position + bounds.min, position + bounds.max);
    }
};

// --- Physics World ---
class PhysicsWorld {
private:
    std::vector<RigidBody*> bodies;
    float gravity = -9.81f;

public:
    void addBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void update(float deltaTime) {
        // Apply gravity
        for (auto body : bodies) {
            body->applyForce(Vector3(0, gravity * body->mass, 0));
        }

        // Update positions
        for (auto body : bodies) {
            body->update(deltaTime);
        }

        // Simple collision detection (AABB)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                if (bodies[i]->bounds.intersects(bodies[j]->bounds)) {
                    std::cout << "Collision detected between body " << i << " and " << j << std::endl;
                    // Simple bounce (elastic collision)
                    bodies[i]->velocity.y *= -0.5f;
                    bodies[j]->velocity.y *= -0.5f;
                }
            }
        }
    }
};

// --- Example Usage ---
int main() {
    PhysicsWorld world;

    // Create two rigid bodies
    RigidBody body1(Vector3(0, 10, 0), Vector3(0, 0, 0), 1.0f, AABB(Vector3(-1, -1, -1), Vector3(1, 1, 1)));
    RigidBody body2(Vector3(0, 5, 0), Vector3(0, 0, 0), 1.0f, AABB(Vector3(-1, -1, -1), Vector3(1, 1, 1)));

    world.addBody(&body1);
    world.addBody(&body2);

    // Simulate for 5 seconds
    for (int i = 0; i < 100; ++i) {
        world.update(0.05f); // 50ms per step
    }

    return 0;
}
