#include "CustomPhysicsPlugin.h"

void UCustomPhysicsPlugin::InitializePhysics()
{
    UE_LOG(LogTemp, Log, TEXT("Custom Physics Plugin Initialized"));
}

void UCustomPhysicsPlugin::UpdatePhysics(float DeltaTime)
{
    for (auto& Elem : PhysicsObjects)
    {
        AActor* Actor = Elem.Key;
        FPhysicsObject& PhysicsObj = Elem.Value;

        // Simple Euler integration for physics update
        PhysicsObj.Velocity += PhysicsObj.Acceleration * DeltaTime;
        PhysicsObj.Position += PhysicsObj.Velocity * DeltaTime;

        // Apply to the actor (if it has a root component)
        if (Actor && Actor->GetRootComponent())
        {
            Actor->GetRootComponent()->SetWorldLocation(PhysicsObj.Position);
        }
    }
}

void UCustomPhysicsPlugin::ApplyForce(FVector Force, AActor* TargetActor)
{
    if (PhysicsObjects.Contains(TargetActor))
    {
        FPhysicsObject& PhysicsObj = PhysicsObjects[TargetActor];
        PhysicsObj.Acceleration += Force / PhysicsObj.Mass;
    }
}

FVector UCustomPhysicsPlugin::GetVelocity(AActor* TargetActor)
{
    if (PhysicsObjects.Contains(TargetActor))
    {
        return PhysicsObjects[TargetActor].Velocity;
    }
    return FVector::ZeroVector;
}
