```cpp
#include "MyRigidBody.h"

UMyRigidBody::UMyRigidBody()
{
    Velocity = FVector::ZeroVector;
}

void UMyRigidBody::ApplyForce(const FVector& Force)
{
    if (bIsStatic) return;
    Velocity += Force / Mass;
}

void UMyRigidBody::UpdatePhysics(float DeltaTime)
{
    if (bIsStatic) return;

    // Simple Euler integration for movement
    FVector Position = GetOuter()->GetActorLocation();
    Position += Velocity * DeltaTime;
    GetOuter()->SetActorLocation(Position);

    // Apply gravity (optional)
    ApplyForce(FVector(0.0f, 0.0f, -9.8f * Mass));
}
