### **Code: Real-Time Physics Simulation with Bullet Physics**
```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>

// Bullet Physics Engine
#include <btBulletDynamicsCommon.h>

// Constants
const float TIME_STEP = 1.0f / 60.0f; // 60 FPS
const int MAX_SUB_STEPS = 5;           // Prevents simulation from lagging

// Physics World Setup
btDefaultCollisionConfiguration* collisionConfig;
btCollisionDispatcher* dispatcher;
btBroadphaseInterface* broadphase;
btSequentialImpulseConstraintSolver* solver;
btDiscreteDynamicsWorld* dynamicsWorld;

// Rigid Bodies
btRigidBody* groundBody;
btRigidBody* dynamicBox;

// Initialize Physics World
void initPhysics() {
    // Collision configuration
    collisionConfig = new btDefaultCollisionConfiguration();
    dispatcher = new btCollisionDispatcher(collisionConfig);
    broadphase = new btDbvtBroadphase();
    solver = new btSequentialImpulseConstraintSolver();

    // Create dynamics world
    dynamicsWorld = new btDiscreteDynamicsWorld(
        dispatcher, broadphase, solver, collisionConfig
    );
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity
}

// Create a Rigid Body (Ground Plane)
void createGround() {
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);

    btDefaultMotionState* groundMotionState = new btDefaultMotionState(
        btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0))
    );

    btRigidBody::btRigidBodyConstructionInfo groundRigidBodyCI(
        0, groundMotionState, groundShape, btVector3(0, 0, 0)
    );

    groundBody = new btRigidBody(groundRigidBodyCI);
    dynamicsWorld->addRigidBody(groundBody);
}

// Create a Dynamic Box
void createDynamicBox() {
    btCollisionShape* boxShape = new btBoxShape(btVector3(1, 1, 1));

    btDefaultMotionState* boxMotionState = new btDefaultMotionState(
        btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, 10, 0))
    );

    btScalar mass = 1.0f;
    btVector3 inertia(0, 0, 0);
    boxShape->calculateLocalInertia(mass, inertia);

    btRigidBody::btRigidBodyConstructionInfo boxRigidBodyCI(
        mass, boxMotionState, boxShape, inertia
    );

    dynamicBox = new btRigidBody(boxRigidBodyCI);
    dynamicsWorld->addRigidBody(dynamicBox);
}

// Main Simulation Loop
void runSimulation() {
    auto previousTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float frameTime = std::chrono::duration<float>(currentTime - previousTime).count();
        previousTime = currentTime;

        accumulator += frameTime;

        // Fixed timestep update
        while (accumulator >= TIME_STEP) {
            dynamicsWorld->stepSimulation(TIME_STEP, MAX_SUB_STEPS, TIME_STEP);
            accumulator -= TIME_STEP;
        }

        // Get box position (for rendering/debugging)
        btTransform trans;
        dynamicBox->getMotionState()->getWorldTransform(trans);
        btVector3 pos = trans.getOrigin();

        // Print position (replace with rendering logic)
        std::cout << "Box Position: (" << pos.x() << ", " << pos.y() << ", " << pos.z() << ")\n";

        // Sleep to cap at ~60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }
}

int main() {
    initPhysics();
    createGround();
    createDynamicBox();
    runSimulation();

    // Cleanup (omitted for brevity)
    return 0;
}
```

