### **2. Minimal Physics Simulation Code**
```cpp
#include <btBulletDynamicsCommon.h>
#include <iostream>
#include <chrono>
#include <thread>

// Constants
const float TIME_STEP = 1.0f / 60.0f; // 60 FPS
const int MAX_SUB_STEPS = 5;          // For stability

// Physics world setup
btDefaultCollisionConfiguration* collisionConfig;
btCollisionDispatcher* dispatcher;
btBroadphaseInterface* broadphase;
btSequentialImpulseConstraintSolver* solver;
btDiscreteDynamicsWorld* dynamicsWorld;

// Create a simple rigid body (a box)
btRigidBody* createRigidBody(float mass, const btTransform& startTransform, btCollisionShape* shape) {
    btVector3 localInertia(0, 0, 0);
    if (mass != 0.0f) {
        shape->calculateLocalInertia(mass, localInertia);
    }

    btDefaultMotionState* motionState = new btDefaultMotionState(startTransform);
    btRigidBody::btRigidBodyConstructionInfo rbInfo(mass, motionState, shape, localInertia);
    btRigidBody* body = new btRigidBody(rbInfo);

    dynamicsWorld->addRigidBody(body);
    return body;
}

int main() {
    // Initialize Bullet Physics
    collisionConfig = new btDefaultCollisionConfiguration();
    dispatcher = new btCollisionDispatcher(collisionConfig);
    broadphase = new btDbvtBroadphase();
    solver = new btSequentialImpulseConstraintSolver();
    dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, broadphase, solver, collisionConfig);
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity

    // Create a ground plane (static rigid body)
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);
    btTransform groundTransform;
    groundTransform.setIdentity();
    groundTransform.setOrigin(btVector3(0, -1, 0));
    createRigidBody(0.0f, groundTransform, groundShape);

    // Create a dynamic box (mass = 1kg)
    btCollisionShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
    btTransform boxTransform;
    boxTransform.setIdentity();
    boxTransform.setOrigin(btVector3(0, 10, 0));
    btRigidBody* boxBody = createRigidBody(1.0f, boxTransform, boxShape);

    // Game loop with fixed timestep
    auto lastTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(currentTime - lastTime).count();
        lastTime = currentTime;

        accumulator += deltaTime;

        // Fixed timestep update
        while (accumulator >= TIME_STEP) {
            dynamicsWorld->stepSimulation(TIME_STEP, MAX_SUB_STEPS, TIME_STEP);
            accumulator -= TIME_STEP;
        }

        // Get box position and print (for demo purposes)
        btTransform trans;
        boxBody->getMotionState()->getWorldTransform(trans);
        std::cout << "Box position: ("
                  << trans.getOrigin().getX() << ", "
                  << trans.getOrigin().getY() << ", "
                  << trans.getOrigin().getZ() << ")\n";

        // Sleep to limit frame rate (optional)
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    // Cleanup (not reached in this example)
    delete dynamicsWorld;
    delete solver;
    delete broadphase;
    delete dispatcher;
    delete collisionConfig;

    return 0;
}
```

