### **Minimal Rigid Body Physics Simulation (C++ with Bullet Physics)**
```cpp
#include <iostream>
#include <btBulletDynamicsCommon.h> // Bullet Physics

// Simple rigid body simulation with a falling box
int main() {
    // Initialize Bullet Physics world
    btDefaultCollisionConfiguration* collisionConfig = new btDefaultCollisionConfiguration();
    btCollisionDispatcher* dispatcher = new btCollisionDispatcher(collisionConfig);
    btBroadphaseInterface* broadphase = new btDbvtBroadphase();
    btSequentialImpulseConstraintSolver* solver = new btSequentialImpulseConstraintSolver();
    btDiscreteDynamicsWorld* dynamicsWorld = new btDiscreteDynamicsWorld(
        dispatcher, broadphase, solver, collisionConfig
    );
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity

    // Create a ground plane (static rigid body)
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);
    btDefaultMotionState* groundMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0)));
    btRigidBody::btRigidBodyConstructionInfo groundRigidBodyCI(0, groundMotionState, groundShape, btVector3(0, 0, 0));
    btRigidBody* groundRigidBody = new btRigidBody(groundRigidBodyCI);
    dynamicsWorld->addRigidBody(groundRigidBody);

    // Create a dynamic box (falling rigid body)
    btCollisionShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
    btDefaultMotionState* boxMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, 10, 0)));
    btScalar mass = 1.0f;
    btVector3 boxInertia(0, 0, 0);
    boxShape->calculateLocalInertia(mass, boxInertia);
    btRigidBody::btRigidBodyConstructionInfo boxRigidBodyCI(mass, boxMotionState, boxShape, boxInertia);
    btRigidBody* boxRigidBody = new btRigidBody(boxRigidBodyCI);
    dynamicsWorld->addRigidBody(boxRigidBody);

    // Simulation loop (60 FPS)
    const float timeStep = 1.0f / 60.0f;
    for (int i = 0; i < 300; ++i) { // Simulate for 5 seconds (300 steps at 60 FPS)
        dynamicsWorld->stepSimulation(timeStep, 10); // Step physics

        // Get box position
        btTransform trans;
        boxRigidBody->getMotionState()->getWorldTransform(trans);
        std::cout << "Box position: (" << trans.getOrigin().getX() << ", "
                  << trans.getOrigin().getY() << ", "
                  << trans.getOrigin().getZ() << ")" << std::endl;
    }

    // Cleanup
    dynamicsWorld->removeRigidBody(boxRigidBody);
    dynamicsWorld->removeRigidBody(groundRigidBody);
    delete boxRigidBody->getMotionState();
    delete groundRigidBody->getMotionState();
    delete boxShape;
    delete groundShape;
    delete dynamicsWorld;
    delete solver;
    delete broadphase;
    delete dispatcher;
    delete collisionConfig;

    return 0;
}
```

