Here’s a **minimal working example** of a real-time physics simulation using **C++** with **Bullet Physics** (a popular rigid-body dynamics engine). This example demonstrates:
- A simple 3D scene with a ground plane and a falling box.
- Fixed timestep physics updates (for stability).
- Frame-rate independent movement (to avoid jitter).

---

### **Minimal C++ Physics Simulation (Bullet Physics)**
#### **Prerequisites**
- Install **Bullet Physics** (e.g., via `vcpkg` or download from [bulletphysics.org](https://pybullet.org/wordpress/)).
- A C++ compiler (GCC, Clang, or MSVC).

#### **Code (`main.cpp`)**
```cpp
#include <btBulletDynamicsCommon.h>
#include <iostream>
#include <chrono>

// Physics world setup
btDefaultCollisionConfiguration* collisionConfig;
btCollisionDispatcher* dispatcher;
btBroadphaseInterface* broadphase;
btSequentialImpulseConstraintSolver* solver;
btDiscreteDynamicsWorld* dynamicsWorld;

// Create a rigid body (box)
btRigidBody* createBox(btScalar mass, const btVector3& halfExtents, const btVector3& position) {
    btCollisionShape* boxShape = new btBoxShape(halfExtents);
    btTransform startTransform;
    startTransform.setIdentity();
    startTransform.setOrigin(position);

    btVector3 localInertia(0, 0, 0);
    if (mass != 0.0f) {
        boxShape->calculateLocalInertia(mass, localInertia);
    }

    btDefaultMotionState* motionState = new btDefaultMotionState(startTransform);
    btRigidBody::btRigidBodyConstructionInfo rbInfo(mass, motionState, boxShape, localInertia);
    return new btRigidBody(rbInfo);
}

int main() {
    // Initialize Bullet Physics
    collisionConfig = new btDefaultCollisionConfiguration();
    dispatcher = new btCollisionDispatcher(collisionConfig);
    broadphase = new btDbvtBroadphase();
    solver = new btSequentialImpulseConstraintSolver();
    dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, broadphase, solver, collisionConfig);
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0)); // Earth gravity

    // Create ground plane (static)
    btCollisionShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);
    btDefaultMotionState* groundMotionState = new btDefaultMotionState(btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0)));
    btRigidBody::btRigidBodyConstructionInfo groundRbInfo(0, groundMotionState, groundShape, btVector3(0, 0, 0));
    btRigidBody* groundRigidBody = new btRigidBody(groundRbInfo);
    dynamicsWorld->addRigidBody(groundRigidBody);

    // Create a falling box (dynamic)
    btRigidBody* box = createBox(1.0f, btVector3(1, 1, 1), btVector3(0, 10, 0));
    dynamicsWorld->addRigidBody(box);

    // Simulation loop
    const float fixedTimeStep = 1.0f / 60.0f; // 60 FPS physics timestep
    float accumulator = 0.0f;
    auto lastTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Fixed timestep physics update
        accumulator += deltaTime;
        while (accumulator >= fixedTimeStep) {
            dynamicsWorld->stepSimulation(fixedTimeStep, 10); // Max substeps = 10
            accumulator -= fixedTimeStep;
        }

        // Get box position (for demo purposes)
        btTransform trans;
        box->getMotionState()->getWorldTransform(trans);
        std::cout << "Box position: (" << trans.getOrigin().getX() << ", "
                  << trans.getOrigin().getY() << ", "
                  << trans.getOrigin().getZ() << ")\n";

        // Exit after 10 seconds (for demo)
        if (trans.getOrigin().getY() < -5.0f) {
            std::cout << "Box fell below ground. Exiting.\n";
            break;
        }
    }

    // Cleanup
    dynamicsWorld->removeRigidBody(box);
    delete box->getMotionState();
    delete box->getCollisionShape();
    delete box;

    dynamicsWorld->removeRigidBody(groundRigidBody);
    delete groundRigidBody->getMotionState();
    delete groundRigidBody->getCollisionShape();
    delete groundRigidBody;

    delete dynamicsWorld;
    delete solver;
    delete broadphase;
    delete dispatcher;
    delete collisionConfig;

    return 0;
}
```

---

### **Key Features**
1. **Fixed Timestep Physics**
   - Uses `stepSimulation(fixedTimeStep, maxSubSteps)` to ensure stable physics updates.
   - Prevents jitter by decoupling physics from rendering.

2. **Frame-Rate Independent Movement**
   - Uses `accumulator` to handle variable frame times while maintaining a consistent physics rate.

3. **Rigid Body Dynamics**
   - A static ground plane and a dynamic falling box.
   - Gravity and collision response are handled by Bullet.

4. **Cleanup**
   - Properly deletes Bullet objects to avoid memory leaks.

---

### **How to Run**
1. Compile with:
   ```sh
   g++ main.cpp -lBulletDynamics -lBulletCollision -lLinearMath -o physics_sim
   ```
2. Run:
   ```sh
   ./physics_sim
   ```
3. The box will fall, and its position will be printed until it hits the ground.

