// Payment represents a financial transaction.
type Payment struct {
	ID          string
	Amount      float64
	Currency    string
	Sender      string
	Receiver    string
	Timestamp   time.Time
	Status      string // "pending", "completed", "failed", "fraudulent"
	Description string
}

// PaymentService handles payment processing.
type PaymentService struct {
	mu          sync.Mutex
	transactions map[string]Payment
	fraudRules   []FraudRule
}

// FraudRule defines a rule for detecting fraud.
type FraudRule func(Payment) bool

// NewPaymentService initializes a new payment service.
func NewPaymentService() *PaymentService {
	return &PaymentService{
		transactions: make(map[string]Payment),
		fraudRules: []FraudRule{
			IsLargeTransaction,
			IsUnusualLocation,
		},
	}
}

// ProcessPayment validates and processes a payment.
func (ps *PaymentService) ProcessPayment(ctx context.Context, payment Payment) error {
	ps.mu.Lock()
	defer ps.mu.Unlock()

	// Generate a unique transaction ID
	payment.ID = generateTransactionID(payment)
	payment.Timestamp = time.Now()
	payment.Status = "pending"

	// Check for fraud
	if ps.isFraudulent(payment) {
		payment.Status = "fraudulent"
		ps.transactions[payment.ID] = payment
		return errors.New("fraudulent transaction detected")
	}

	// Simulate payment processing (e.g., calling a bank API)
	time.Sleep(2 * time.Second) // Simulate network delay

	payment.Status = "completed"
	ps.transactions[payment.ID] = payment

	return nil
}

// GetTransaction retrieves a transaction by ID.
func (ps *PaymentService) GetTransaction(id string) (Payment, bool) {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	tx, exists := ps.transactions[id]
	return tx, exists
}

// isFraudulent checks if a payment violates any fraud rules.
func (ps *PaymentService) isFraudulent(payment Payment) bool {
	for _, rule := range ps.fraudRules {
		if rule(payment) {
			return true
		}
	}
	return false
}

// generateTransactionID creates a unique ID for a transaction.
func generateTransactionID(payment Payment) string {
	hash := sha256.Sum256([]byte(fmt.Sprintf(
		"%s-%s-%f-%s-%d",
		payment.Sender,
		payment.Receiver,
		payment.Amount,
		payment.Currency,
		time.Now().UnixNano(),
	)))
	return hex.EncodeToString(hash[:])
}

// Fraud Detection Rules
func IsLargeTransaction(payment Payment) bool {
	return payment.Amount > 10000 // Example: Flag transactions over $10,000
}

func IsUnusualLocation(payment Payment) bool {
	// In a real system, this would compare sender location with known fraud patterns.
	return false // Simplified for example
