```rust
use sqlx::{PgPool, postgres::PgPoolOptions};
use uuid::Uuid;
use crate::models::{PaymentRecord, PaymentRequest};

pub async fn establish_connection(database_url: &str) -> Result<PgPool, sqlx::Error> {
    PgPoolOptions::new()
        .max_connections(10)
        .connect(database_url)
        .await
}

pub async fn create_payment(
    pool: &PgPool,
    payment: &PaymentRequest,
) -> Result<PaymentRecord, sqlx::Error> {
    let payment_id = Uuid::new_v4();
    let status = "PROCESSING".to_string();

    let record = sqlx::query_as!(
        PaymentRecord,
        r#"
        INSERT INTO payments (id, amount, currency, source_account, destination_account, status)
        VALUES ($1, $2, $3, $4, $5, $6)
        RETURNING *
        "#,
        payment_id,
        payment.amount,
        payment.currency,
        payment.source_account,
        payment.destination_account,
        status
    )
    .fetch_one(pool)
    .await?;

    Ok(record)
}

pub async fn update_payment_status(
    pool: &PgPool,
    payment_id: Uuid,
    status: &str,
) -> Result<(), sqlx::Error> {
    sqlx::query!(
        r#"UPDATE payments SET status = $1 WHERE id = $2"#,
        status,
        payment_id
    )
    .execute(pool)
    .await?;

    Ok(())
}
```

