```rust
use actix_web::{web, HttpResponse, Responder};
use sqlx::PgPool;
use uuid::Uuid;
use crate::models::{PaymentRequest, PaymentResponse};
use crate::database::{create_payment, update_payment_status};

pub async fn process_payment(
    pool: web::Data<PgPool>,
    payment: web::Json<PaymentRequest>,
) -> impl Responder {
    let payment_record = match create_payment(&pool, &payment).await {
        Ok(record) => record,
        Err(e) => {
            log::error!("Failed to create payment: {}", e);
            return HttpResponse::InternalServerError().json("Payment processing failed");
        }
    };

    // Simulate payment processing (e.g., call a bank API)
    tokio::spawn(async move {
        // Simulate async processing (e.g., fraud check, bank transfer)
        tokio::time::sleep(std::time::Duration::from_secs(2)).await;

        let status = if payment.amount > 0.0 { "COMPLETED" } else { "FAILED" };

        if let Err(e) = update_payment_status(&pool, payment_record.id, status).await {
            log::error!("Failed to update payment status: {}", e);
        }
    });

    HttpResponse::Ok().json(PaymentResponse {
        payment_id: payment_record.id,
        status: payment_record.status,
        timestamp: payment_record.created_at.to_string(),
    })
}

pub async fn get_payment_status(
    pool: web::Data<PgPool>,
    payment_id: web::Path<Uuid>,
) -> impl Responder {
    let record = match sqlx::query_as!(
        crate::models::PaymentRecord,
        r#"SELECT * FROM payments WHERE id = $1"#,
        payment_id.into_inner()
    )
    .fetch_optional(&*pool)
    .await
    {
        Ok(Some(record)) => record,
        Ok(None) => return HttpResponse::NotFound().json("Payment not found"),
        Err(e) => {
            log::error!("Database error: {}", e);
            return HttpResponse::InternalServerError().json("Failed to fetch payment");
        }
    };

    HttpResponse::Ok().json(PaymentResponse {
        payment_id: record.id,
        status: record.status,
        timestamp: record.created_at.to_string(),
    })
}
