use crate::models::{Transaction, TransactionStatus, Account};
use uuid::Uuid;
use chrono::Utc;

pub struct TransactionService;

impl TransactionService {
    pub fn create_transaction(account_id: Uuid, amount: f64, currency: String) -> Transaction {
        Transaction {
            id: Uuid::new_v4(),
            account_id,
            amount,
            currency,
            status: TransactionStatus::Pending,
            timestamp: Utc::now(),
            fraud_flag: false,
        }
    }

    pub fn process_transaction(transaction: &mut Transaction, account: &mut Account) -> Result<(), String> {
        if account.is_frozen {
            return Err("Account is frozen".to_string());
        }

        if account.balance < transaction.amount {
            transaction.status = TransactionStatus::Failed;
            return Err("Insufficient funds".to_string());
        }

        account.balance -= transaction.amount;
        transaction.status = TransactionStatus::Completed;
        Ok(())
    }
}
```

