use actix_web::{web, App, HttpServer, Responder, HttpResponse};
use serde_json::json;
use uuid::Uuid;
use crate::models::{Transaction, Account};
use crate::services::{TransactionService, FraudDetector};

async fn create_transaction(
    account_id: web::Path<Uuid>,
    transaction_data: web::Json<TransactionRequest>,
) -> impl Responder {
    let mut account = Account {
        id: *account_id,
        balance: 1000.0,  // Mock balance
        currency: "USD".to_string(),
        is_frozen: false,
    };

    let mut transaction = TransactionService::create_transaction(
        *account_id,
        transaction_data.amount,
        transaction_data.currency.clone(),
    );

    if FraudDetector::check_fraud(&mut transaction) {
        return HttpResponse::BadRequest().json(json!({
            "error": "Fraud detected",
            "transaction_id": transaction.id,
        }));
    }

    if let Err(e) = TransactionService::process_transaction(&mut transaction, &mut account) {
        return HttpResponse::BadRequest().json(json!({ "error": e }));
    }

    HttpResponse::Ok().json(transaction)
}

