		// Process payment (delegated to core engine)
		paymentID, err := ProcessPayment(req)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}

		c.JSON(http.StatusOK, gin.H{"payment_id": paymentID})
