### **B. Payment Service (`internal/core/services/payment_service.go`)**
```go
package services

import (
    "errors"
    "payment-service/internal/core/models"
    "payment-service/internal/core/repositories"
)

type PaymentService struct {
    accountRepo repositories.AccountRepository
    txRepo      repositories.TransactionRepository
}

func NewPaymentService(
    accountRepo repositories.AccountRepository,
    txRepo repositories.TransactionRepository,
) *PaymentService {
    return &PaymentService{
        accountRepo: accountRepo,
        txRepo:      txRepo,
    }
}

// ProcessTransaction handles deposits, withdrawals, and transfers
func (s *PaymentService) ProcessTransaction(tx *models.Transaction) error {
    // Validate accounts
    fromAccount, err := s.accountRepo.GetAccount(tx.FromAccount)
    if err != nil {
        return errors.New("invalid source account")
    }
    toAccount, err := s.accountRepo.GetAccount(tx.ToAccount)
    if err != nil {
        return errors.New("invalid destination account")
    }

    // Check account status
    if fromAccount.Status != "active" || toAccount.Status != "active" {
        return errors.New("account is not active")
    }

    // Check sufficient balance (for withdrawals/transfers)
    if tx.Type == "withdrawal" || tx.Type == "transfer" {
        if fromAccount.Balance < tx.Amount {
            return errors.New("insufficient funds")
        }
    }

    // Update balances
    if tx.Type == "deposit" {
        fromAccount.Balance += tx.Amount
    } else if tx.Type == "withdrawal" {
        fromAccount.Balance -= tx.Amount
    } else if tx.Type == "transfer" {
        fromAccount.Balance -= tx.Amount
        toAccount.Balance += tx.Amount
    }

    // Save changes
    if err := s.accountRepo.UpdateAccount(fromAccount); err != nil {
        return err
    }
    if tx.Type == "transfer" {
        if err := s.accountRepo.UpdateAccount(toAccount); err != nil {
            return err
        }
    }

    // Record transaction
    tx.Status = "completed"
    return s.txRepo.SaveTransaction(tx)
}
```

