use std::sync::Arc;
use tokio::sync::Mutex;
use crate::models::{Payment, TransactionStatus};
use crate::services::{PaymentService, FraudDetectionService};
use crate::errors::PaymentError;

pub struct PaymentProcessingService {
    payment_service: Arc<Mutex<PaymentService>>,
    fraud_detection: Arc<Mutex<FraudDetectionService>>,
}

impl PaymentProcessingService {
    pub fn new() -> Self {
        Self {
            payment_service: Arc::new(Mutex::new(PaymentService::new())),
            fraud_detection: Arc::new(Mutex::new(FraudDetectionService::new())),
        }
    }

    pub async fn process_payment(&self, payment: Payment) -> Result<TransactionStatus, PaymentError> {
        // Step 1: Validate payment
        if !payment.is_valid() {
            return Err(PaymentError::InvalidPayment);
        }

        // Step 2: Check for fraud
        let is_fraudulent = self.fraud_detection.lock().await.check_fraud(&payment).await?;
        if is_fraudulent {
            return Err(PaymentError::FraudDetected);
        }

        // Step 3: Process payment
        let transaction = self.payment_service.lock().await.process(payment).await?;

        Ok(transaction.status)
    }
}
```

