package com.finance.paymentservice.service;

import com.finance.paymentservice.dto.PaymentRequest;
import com.finance.paymentservice.dto.PaymentResponse;
import com.finance.paymentservice.exception.InvalidPaymentException;
import com.finance.paymentservice.model.Payment;
import com.finance.paymentservice.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;

    public PaymentService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public PaymentResponse processPayment(PaymentRequest request) {
        // Validate payment details
        if (!isValidCardNumber(request.getCardNumber())) {
            throw new InvalidPaymentException("Invalid card number");
        }
        if (!isValidCVV(request.getCvv())) {
            throw new InvalidPaymentException("Invalid CVV");
        }

        // Create and save payment
        Payment payment = new Payment();
        payment.setTransactionId(UUID.randomUUID().toString());
        payment.setAmount(request.getAmount());
        payment.setCardNumber(maskCardNumber(request.getCardNumber()));
        payment.setStatus("SUCCESS");
        payment.setTimestamp(LocalDateTime.now());

        paymentRepository.save(payment);

        // Return response
        return new PaymentResponse(
            payment.getTransactionId(),
            payment.getStatus(),
            payment.getTimestamp()
        );
    }

    private boolean isValidCardNumber(String cardNumber) {
        return cardNumber != null && cardNumber.matches("\\d{16}");
    }

    private boolean isValidCVV(String cvv) {
        return cvv != null && cvv.matches("\\d{3,4}");
    }

    private String maskCardNumber(String cardNumber) {
        return "****-****-****-" + cardNumber.substring(12);
    }
}
```

