package com.example.paymentservice.service;

import com.example.paymentservice.model.Payment;
import com.example.paymentservice.repository.PaymentRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
public class PaymentService {

    @Autowired
    private PaymentRepository paymentRepository;

    @Transactional
    public Payment processPayment(Payment payment) {
        payment.setStatus("PENDING");
        payment.setCreatedAt(LocalDateTime.now());

        // Simulate payment processing (e.g., call a bank API)
        boolean isSuccess = simulateBankTransaction(payment);

        if (isSuccess) {
            payment.setStatus("COMPLETED");
        } else {
            payment.setStatus("FAILED");
        }

        return paymentRepository.save(payment);
    }

    private boolean simulateBankTransaction(Payment payment) {
        // In a real system, this would call a bank API or external service
        return payment.getAmount().compareTo(BigDecimal.ZERO) > 0;
    }
}
