import axios from "axios";
import { IntegrationResponse, Order } from "../types";

export class CorporateSystemClient {
  private readonly baseUrl: string;

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }

  async submitOrder(order: Order): Promise<IntegrationResponse<Order>> {
    try {
      const response = await axios.post(`${this.baseUrl}/orders`, order, {
        headers: { "Content-Type": "application/json" },
      });
      return { success: true, data: response.data };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    }
  }

  async fetchUser(userId: string): Promise<IntegrationResponse<CorporateUser>> {
    try {
      const response = await axios.get(`${this.baseUrl}/users/${userId}`);
      return { success: true, data: response.data };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    }
  }
}
```

