```typescript
import { Order, CorporateUser } from "../types";
import { CorporateSystemClient } from "../integrations/corporateSystemClient";
import { validateOrder } from "../validation";

export class OrderService {
  private readonly corporateClient: CorporateSystemClient;

  constructor(corporateClient: CorporateSystemClient) {
    this.corporateClient = corporateClient;
  }

  async processOrder(orderData: unknown): Promise<Order> {
    // Validate input
    const order = validateOrder(orderData);

    // Check if user exists in corporate system
    const userResponse = await this.corporateClient.fetchUser(order.userId);
    if (!userResponse.success) {
      throw new Error(`User not found: ${userResponse.error}`);
    }

    // Submit order to corporate system
    const orderResponse = await this.corporateClient.submitOrder(order);
    if (!orderResponse.success) {
      throw new Error(`Order submission failed: ${orderResponse.error}`);
    }

    return orderResponse.data!;
  }
}
```

