import express, { Request, Response, NextFunction } from "express";
import { OrderService } from "./services/orderService";
import { CorporateSystemClient } from "./integrations/corporateSystemClient";
import { logger } from "./logger";

const app = express();
app.use(express.json());

// Initialize corporate client (mock URL)
const corporateClient = new CorporateSystemClient("https://corporate-api.example.com");
const orderService = new OrderService(corporateClient);

// Middleware for error handling
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  logger.error(err.message);
  res.status(500).json({ error: "Internal Server Error" });
});

// API Endpoint
app.post("/api/orders", async (req: Request, res: Response) => {
  try {
    const order = await orderService.processOrder(req.body);
    res.status(201).json(order);
  } catch (error) {
    logger.error(`Order processing failed: ${(error as Error).message}`);
    res.status(400).json({ error: (error as Error).message });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});
