```typescript
import { Request, Response, NextFunction } from 'express';

type ValidationSchema = Record<string, 'string' | 'number' | 'boolean'>;

export function validateRequest<T>(schema: ValidationSchema) {
  return (req: Request<{}, {}, T>, res: Response, next: NextFunction) => {
    const errors: string[] = [];

    for (const [key, type] of Object.entries(schema)) {
      if (!req.body || typeof req.body[key] !== type) {
        errors.push(`Invalid or missing field: ${key} (expected ${type})`);
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    next();
  };
}
```

