import axios from "axios";
import { CorporateSystemResponse, Order } from "../types";

const ERP_API_BASE_URL = process.env.ERP_API_URL || "https://corporate-erp.example.com/api";

export class CorporateIntegrationService {
  async fetchOrder(orderId: string): Promise<CorporateSystemResponse<Order>> {
    try {
      const response = await axios.get<Order>(`${ERP_API_BASE_URL}/orders/${orderId}`);
      return { status: "success", data: response.data };
    } catch (error) {
      return { status: "error", data: null, error: error.message };
