import { Request, Response } from "express";
import { CorporateIntegrationService } from "../services/corporateIntegration";
import { Order } from "../types";

export class OrderController {
  private corporateService: CorporateIntegrationService;

  constructor() {
    this.corporateService = new CorporateIntegrationService();
  }

  async getOrder(req: Request, res: Response) {
    const { orderId } = req.params;

    if (!orderId) {
      return res.status(400).json({ error: "Order ID is required" });
    }

    const result = await this.corporateService.fetchOrder(orderId);

    if (result.status === "error") {
      return res.status(500).json({ error: result.error });
    }

    return res.status(200).json(result.data);
  }
}
