import { Pool } from 'pg'; // Example: PostgreSQL

const pool = new Pool({
  connectionString: process.env.DB_URL,
});

export const db = {
  query: async <T>(sql: string, params?: any[]): Promise<T[]> => {
    const res = await pool.query(sql, params);
    return res.rows as T[];
  },
  insert: async <T>(table: string, data: Partial<T>): Promise<T> => {
    const keys = Object.keys(data);
    const values = Object.values(data);
    const sql = `INSERT INTO ${table} (${keys.join(', ')}) VALUES (${values.map((_, i) => `$${i + 1}`).join(', ')}) RETURNING *`;
    const res = await pool.query(sql, values);
    return res.rows[0] as T;
  },
};

export async function connectDB() {
  await pool.connect();
  console.log('Connected to corporate database');
}
```

