import { connect } from 'amqplib'; // Example: RabbitMQ

let channel: any;

export async function connectQueue() {
  const conn = await connect(process.env.RABBITMQ_URL || 'amqp://localhost');
  channel = await conn.createChannel();
  await channel.assertQueue('user.events');
  console.log('Connected to corporate message queue');
}

export async function publishEvent(event: string, data: any) {
  if (!channel) throw new Error('Message queue not connected');
  channel.sendToQueue('user.events', Buffer.from(JSON.stringify({ event, data })));
}
