using Azure.Data.Tables;
using EnterpriseBackendService.Models;
using Microsoft.Extensions.Logging;

namespace EnterpriseBackendService.Services
{
    public class OrderService : IOrderService
    {
        private readonly ILogger<OrderService> _logger;
        private readonly TableClient _tableClient;

        public OrderService(ILogger<OrderService> logger, TableClient tableClient)
        {
            _logger = logger;
            _tableClient = tableClient;
        }

        public async Task<Order> GetOrderByIdAsync(Guid id)
        {
            _logger.LogInformation("Fetching order with ID: {OrderId}", id);
            var order = await _tableClient.GetEntityAsync<Order>("Orders", id.ToString());
            return order.Value;
        }

        public async Task<List<Order>> GetAllOrdersAsync()
        {
            _logger.LogInformation("Fetching all orders");
            var orders = new List<Order>();
            await foreach (var order in _tableClient.QueryAsync<Order>())
            {
                orders.Add(order);
            }
            return orders;
        }

        public async Task<Order> CreateOrderAsync(Order order)
        {
            _logger.LogInformation("Creating new order for customer: {CustomerName}", order.CustomerName);
            order.Id = Guid.NewGuid();
            order.OrderDate = DateTime.UtcNow;
            await _tableClient.AddEntityAsync(order);
            return order;
        }
    }
}
```

