#### **`Controllers/EmployeesController.cs`**
```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Distributed;
using EnterpriseBackendService.Data;
using EnterpriseBackendService.Models;
using System.Text.Json;

namespace EnterpriseBackendService.Controllers
{
    [Authorize]
    [ApiController]
    [Route("api/[controller]")]
    public class EmployeesController : ControllerBase
    {
        private readonly AppDbContext _context;
        private readonly IDistributedCache _cache;

        public EmployeesController(AppDbContext context, IDistributedCache cache)
        {
            _context = context;
            _cache = cache;
        }

        [HttpGet]
        public async Task<IActionResult> GetAllEmployees()
        {
            const string cacheKey = "AllEmployees";
            var cachedData = await _cache.GetStringAsync(cacheKey);

            if (!string.IsNullOrEmpty(cachedData))
            {
                var employees = JsonSerializer.Deserialize<List<Employee>>(cachedData);
                return Ok(employees);
            }

            var employeesFromDb = await _context.Employees.ToListAsync();
            await _cache.SetStringAsync(cacheKey, JsonSerializer.Serialize(employeesFromDb), new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
            });

            return Ok(employeesFromDb);
        }

        [HttpPost]
        public async Task<IActionResult> AddEmployee([FromBody] Employee employee)
        {
            _context.Employees.Add(employee);
            await _context.SaveChangesAsync();
            await _cache.RemoveAsync("AllEmployees"); // Invalidate cache
            return CreatedAtAction(nameof(GetAllEmployees), new { id = employee.Id }, employee);
        }
    }
}
```

