```csharp
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.Extensions.Logging;
using System.Net;
using EnterpriseBackendService.Models;
using EnterpriseBackendService.Services;

namespace EnterpriseBackendService.Functions
{
    public class EmployeeFunctions
    {
        private readonly IEmployeeService _employeeService;
        private readonly ILogger<EmployeeFunctions> _logger;

        public EmployeeFunctions(IEmployeeService employeeService, ILogger<EmployeeFunctions> logger)
        {
            _employeeService = employeeService;
            _logger = logger;
        }

        [Function("GetAllEmployees")]
        public async Task<HttpResponseData> GetAllEmployees(
            [HttpTrigger(AuthorizationLevel.Function, "get", Route = "employees")] HttpRequestData req)
        {
            _logger.LogInformation("Fetching all employees.");
            var employees = await _employeeService.GetAllEmployeesAsync();

            var response = req.CreateResponse(HttpStatusCode.OK);
            await response.WriteAsJsonAsync(employees);
            return response;
        }

        [Function("GetEmployeeById")]
        public async Task<HttpResponseData> GetEmployeeById(
            [HttpTrigger(AuthorizationLevel.Function, "get", Route = "employees/{id}")] HttpRequestData req, int id)
        {
            _logger.LogInformation($"Fetching employee with ID: {id}");
            var employee = await _employeeService.GetEmployeeByIdAsync(id);

            if (employee == null)
            {
                var notFoundResponse = req.CreateResponse(HttpStatusCode.NotFound);
                await notFoundResponse.WriteStringAsync("Employee not found.");
                return notFoundResponse;
            }

            var response = req.CreateResponse(HttpStatusCode.OK);
            await response.WriteAsJsonAsync(employee);
            return response;
        }

        [Function("AddEmployee")]
        public async Task<HttpResponseData> AddEmployee(
            [HttpTrigger(AuthorizationLevel.Function, "post", Route = "employees")] HttpRequestData req)
        {
            _logger.LogInformation("Adding a new employee.");
            var employee = await req.ReadFromJsonAsync<Employee>();

            if (employee == null)
            {
                var badRequest = req.CreateResponse(HttpStatusCode.BadRequest);
                await badRequest.WriteStringAsync("Invalid employee data.");
                return badRequest;
            }

            var createdEmployee = await _employeeService.AddEmployeeAsync(employee);
            var response = req.CreateResponse(HttpStatusCode.Created);
            await response.WriteAsJsonAsync(createdEmployee);
            return response;
        }

        [Function("UpdateEmployee")]
        public async Task<HttpResponseData> UpdateEmployee(
            [HttpTrigger(AuthorizationLevel.Function, "put", Route = "employees/{id}")] HttpRequestData req, int id)
        {
            _logger.LogInformation($"Updating employee with ID: {id}");
            var employee = await req.ReadFromJsonAsync<Employee>();

            if (employee == null)
            {
                var badRequest = req.CreateResponse(HttpStatusCode.BadRequest);
                await badRequest.WriteStringAsync("Invalid employee data.");
                return badRequest;
            }

            var updatedEmployee = await _employeeService.UpdateEmployeeAsync(id, employee);

            if (updatedEmployee == null)
            {
                var notFoundResponse = req.CreateResponse(HttpStatusCode.NotFound);
                await notFoundResponse.WriteStringAsync("Employee not found.");
                return notFoundResponse;
            }

            var response = req.CreateResponse(HttpStatusCode.OK);
            await response.WriteAsJsonAsync(updatedEmployee);
            return response;
        }

        [Function("DeleteEmployee")]
        public async Task<HttpResponseData> DeleteEmployee(
            [HttpTrigger(AuthorizationLevel.Function, "delete", Route = "employees/{id}")] HttpRequestData req, int id)
        {
            _logger.LogInformation($"Deleting employee with ID: {id}");
            var isDeleted = await _employeeService.DeleteEmployeeAsync(id);

            if (!isDeleted)
            {
                var notFoundResponse = req.CreateResponse(HttpStatusCode.NotFound);
                await notFoundResponse.WriteStringAsync("Employee not found.");
                return notFoundResponse;
            }

            var response = req.CreateResponse(HttpStatusCode.NoContent);
            return response;
        }
    }
}
```

