using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.Azure.Functions.Worker.Middleware;
using Microsoft.Extensions.DependencyInjection;
using Swashbuckle.AspNetCore.SwaggerUI;

namespace EnterpriseBackendService.Middleware
{
    public class SwaggerMiddleware : IFunctionsWorkerMiddleware
    {
        public async Task Invoke(FunctionContext context, FunctionExecutionDelegate next)
        {
            var req = await context.GetHttpRequestDataAsync();
            if (req != null && req.Url.Path.StartsWith("/swagger"))
            {
                var swaggerUI = new SwaggerUIOptions
                {
                    SwaggerEndpoint("/swagger/v1/swagger.json", "Enterprise Backend API v1")
                };

                var response = req.CreateResponse();
                await response.WriteAsJsonAsync(swaggerUI);
                context.GetInvocationResult().Value = response;
                return;
            }

            await next(context);
        }
    }
}
