```rust
use axum::{
    routing::get,
    Router,
    response::Html,
};
use std::net::SocketAddr;

// Simple handler for the root path
async fn root() -> Html<&'static str> {
    Html("<h1>Hello, Concurrent World!</h1>")
}

// Handler for a dynamic path
async fn greet(name: String) -> Html<String> {
    Html(format!("<h1>Hello, {}!</h1>", name))
}

#[tokio::main]
