### **High-Performance Web Server in Rust**
```rust
use hyper::{
    service::{make_service_fn, service_fn},
    Body, Request, Response, Server,
};
use std::{convert::Infallible, net::SocketAddr};
use tokio::sync::Semaphore;

#[tokio::main]
async fn main() {
    // Define the server address
    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));

    // Create a semaphore to limit concurrency (optional)
    let semaphore = Semaphore::new(1000); // Max 1000 concurrent requests

    // Build the HTTP service
    let make_svc = make_service_fn(move |_conn| {
        let semaphore = semaphore.clone();
        async move {
            Ok::<_, Infallible>(service_fn(move |req: Request<Body>| {
                let semaphore = semaphore.clone();
                async move {
                    // Acquire a permit (optional concurrency limit)
                    let _permit = semaphore.acquire().await.unwrap();

                    // Handle the request
                    let response = handle_request(req).await;
                    Ok::<_, Infallible>(response)
                }
            }))
        }
    });

    // Start the server
    let server = Server::bind(&addr).serve(make_svc);

    println!("Server running on http://{}", addr);

    // Run the server
    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}

// Handle HTTP requests
async fn handle_request(req: Request<Body>) -> Response<Body> {
    match (req.method(), req.uri().path()) {
        (&hyper::Method::GET, "/") => {
            Response::builder()
                .status(200)
                .header("Content-Type", "text/plain")
                .body(Body::from("Hello, World!"))
                .unwrap()
        }
        (&hyper::Method::GET, "/health") => {
            Response::builder()
                .status(200)
                .header("Content-Type", "application/json")
                .body(Body::from(r#"{"status": "healthy"}"#))
                .unwrap()
        }
        _ => {
            Response::builder()
                .status(404)
                .body(Body::from("Not Found"))
                .unwrap()
        }
    }
}
```

