```rust
use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use sqlx::postgres::PgPoolOptions;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::signal;
use tower_http::trace::TraceLayer;
use tracing::{info, Level};

// Database connection pool (shared state)
#[derive(Clone)]
struct AppState {
    db_pool: Arc<sqlx::PgPool>,
}

// Example JSON response
#[derive(Serialize, Deserialize)]
struct ApiResponse {
    message: String,
    status: u16,
}

// Health check endpoint
async fn health_check() -> impl IntoResponse {
    Json(ApiResponse {
        message: "Server is healthy".to_string(),
        status: StatusCode::OK.as_u16(),
    })
}

// Example DB query endpoint
async fn get_user(
    State(state): State<AppState>,
    Json(payload): Json<serde_json::Value>,
) -> impl IntoResponse {
    let user_id: i32 = payload["user_id"].as_i64().unwrap_or(0) as i32;

    let result = sqlx::query!("SELECT id, name FROM users WHERE id = $1", user_id)
        .fetch_one(&*state.db_pool)
        .await;

    match result {
        Ok(user) => Json(ApiResponse {
            message: format!("User found: {} (ID: {})", user.name, user.id),
            status: StatusCode::OK.as_u16(),
        }),
        Err(_) => (
            StatusCode::NOT_FOUND,
            Json(ApiResponse {
                message: "User not found".to_string(),
                status: StatusCode::NOT_FOUND.as_u16(),
            }),
        ),
    }
}

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .init();

    // Database connection pool
    let db_pool = PgPoolOptions::new()
        .max_connections(100) // Adjust based on load
        .connect("postgres://user:password@localhost/db_name")
        .await
        .expect("Failed to connect to database");

    // Shared state
    let shared_state = AppState {
        db_pool: Arc::new(db_pool),
    };

    // Build the router
    let app = Router::new()
        .route("/health", get(health_check))
        .route("/user", post(get_user))
        .layer(TraceLayer::new_for_http()) // Logging middleware
        .with_state(shared_state);

    // Start the server
    let addr = SocketAddr::from(([0, 0, 0, 0], 3000));
    info!("Server listening on {}", addr);

    let server = axum::Server::bind(&addr)
        .serve(app.into_make_service())
        .with_graceful_shutdown(shutdown_signal());

    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}

// Graceful shutdown handler
async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("Failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        signal::unix::signal(signal::unix::SignalKind::terminate())
            .expect("Failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("Shutting down gracefully...");
}
```

